INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('regle', 'equipement', 'economie', 'Économie de Réalité', 'Seuil d''achat avancé, remboursement de l''enveloppe, styles de vie.', '{"nature":"equipement","economy":{"advancedPurchaseThreshold":20000,"unusedEnvelopeRefundRate":0.5,"styleAugAccess":{"manucorpo":{"text":"Gen1 : Neural, Optique/Audio, membres utilitaires. 1 système Gen2 Optique/Audio ou utilitaire.","gen1":["neural","optical","audio","utility"],"gen2":["optical","audio","utility"]},"biocorpo":{"text":"Biogénétique ≤15k + Gen1 médical/interne. 1 système Gen2 médical ou dermique.","gen1":["medical","internal"],"gen2":["medical","dermal"],"bio":["medical","civil","sensorial"],"bioCap":15000},"cybercorpo":{"text":"Gen1 Neural et Optique/Audio. 1 système Gen2 Neural ou Optique/Audio.","gen1":["neural","optical","audio"],"gen2":["neural","optical","audio"]},"armacorpo":{"text":"Gen1 combat : Neural, Optique, membres. 1 système Gen2 combat ou sensoriel.","gen1":["combat","neural","optical","member"],"gen2":["combat","sensorial"]},"servicorpo":{"text":"Bio civile, esthétique et sensoriel. 1 système Gen2 civil/sensoriel ; pas de combatware Gen2.","gen1":["aesthetic","civil","sensorial"],"gen2":["civil","sensorial"],"bio":["civil","aesthetic","sensorial"]},"forces_armees":{"text":"Gen1 combat, membres, optiques. 1 système Gen2 militaire ou sensoriel.","gen1":["combat","member","optical"],"gen2":["combat","defensive","sensorial","member"]},"agent_gouvernemental":{"text":"Gen1 Neural, Optique/Audio, infiltration. 1 système Gen2 Neural ou sensoriel.","gen1":["neural","optical","audio","infiltration"],"gen2":["neural","sensorial"]},"net_corps":{"text":"Gen1 Neural/Optique. 1 système Gen2 Neural.","gen1":["neural","optical"],"gen2":["neural"]},"service_public":{"text":"Médical, assistif, sensoriel, Bio ≤10k. 1 système Gen2 non offensif.","gen1":["medical","utility","sensorial","defensive"],"gen2":["medical","utility","sensorial","defensive","civil"],"bio":["medical","civil","sensorial"],"bioCap":10000},"diplomate_administrateur":{"text":"Esthétique, bio civile, sensoriel. 1 système Gen2 civil.","gen1":["aesthetic","civil","sensorial"],"gen2":["civil"],"bio":["civil","aesthetic","sensorial"]},"soldato":{"text":"Gen1 combat et membres. Pas de Gen2 par défaut.","gen1":["combat","member"],"gen2":[]},"tueur_a_gages":{"text":"Gen1 combat/infiltration. 1 système Gen2 dissimulé ou sensoriel.","gen1":["combat","infiltration"],"gen2":["infiltration","sensorial"]},"hacker":{"text":"Gen1 Neural. 1 système Gen2 Neural.","gen1":["neural"],"gen2":["neural"]},"charcudoc":{"text":"Gen1 très large, Bio ≤15k. 1 système Gen2 médical ou utilitaire.","gen1":["all"],"gen2":["medical","utility"],"bio":["all"],"bioCap":15000},"affairiste_bookmaker":{"text":"Bio civile, esthétique, sensoriel. Gen2 civil uniquement.","gen1":["aesthetic","civil","sensorial"],"gen2":["civil"],"bio":["civil","aesthetic","sensorial"]},"deathrunner_merc":{"text":"Gen1 combat très large. Pas de Gen2 par défaut.","gen1":["combat","member","neural","optical","audio","internal","dermal"],"gen2":[]},"neurodiver":{"text":"Gen1 Neural. 1 système Gen2 Neural.","gen1":["neural"],"gen2":["neural"]},"meditech":{"text":"Gen1 médical, membres, interne ; Bio ≤10k. 1 système Gen2 médical/utilitaire.","gen1":["medical","member","internal","utility"],"gen2":["medical","utility"],"bio":["medical","civil"],"bioCap":10000},"gundriver":{"text":"Gen1 membres/sensoriel/utilitaire ; pas de Gen2. +10 000 $ de Capital véhicule.","gen1":["member","sensorial","utility"],"gen2":[]},"neopunk":{"text":"Esthétique, Neural/Audio Gen1. 1 système Gen2 Neural ou sensoriel.","gen1":["aesthetic","neural","audio"],"gen2":["neural","sensorial"]},"ordre_arme":{"text":"Gen1 combat. 1 système Gen2 défensif ou sensoriel.","gen1":["combat"],"gen2":["defensive","sensorial"]},"clerc_holonet":{"text":"Gen1 Neural/Optique-Audio. 1 système Gen2 Neural ou sensoriel.","gen1":["neural","optical","audio"],"gen2":["neural","sensorial"]},"ministeriel":{"text":"Médical/interne, Bio ≤15k. 1 système Gen2 médical ou utilitaire.","gen1":["medical","internal"],"gen2":["medical","utility"],"bio":["medical","civil"],"bioCap":15000},"clerc_administrateur":{"text":"Bio civile, esthétique, sensoriel ; Gen2 civil.","gen1":["aesthetic","civil","sensorial"],"gen2":["civil"],"bio":["civil","aesthetic","sensorial"]},"missionnaire":{"text":"Médical/utilitaire Gen1, Bio ≤10k. Pas de Gen2 par défaut.","gen1":["medical","utility"],"gen2":[],"bio":["medical","civil"],"bioCap":10000}},"lifestyle":{"order":["Survie","Modeste","Standard","Confortable","Aisé","Luxe"],"monthlyReference":{"Survie":200,"Modeste":400,"Standard":650,"Confortable":1200,"Aisé":2500,"Luxe":5000},"lore":{"Survie":"Le personnage vit au jour le jour. Logement instable, alimentation minimale et mobilité choisie par nécessité ; un imprévu financier peut suffire à déstabiliser le mois.","Modeste":"Le quotidien est tenu mais serré : petit logement ou colocation, dépenses surveillées et peu de marge pour les extras.","Standard":"Un niveau de vie urbain courant : logement correct, alimentation régulière, services usuels et quelques loisirs sans que l’argent disparaisse du jeu.","Confortable":"Le personnage dispose d’une vraie marge : meilleur logement, mobilité plus souple, abonnements utiles et dépenses ordinaires rarement problématiques.","Aisé":"Le niveau de vie devient un marqueur social : beaux quartiers, services premium, mobilité haut de gamme et capacité à absorber la plupart des dépenses communes.","Luxe":"Le quotidien relève du privilège : logement exceptionnel, services personnels, vraie production, déplacements coûteux et accès à des prestations que la majorité ne considère pas ordinaires."}}},"source":{"equipment":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","version":"2026-09-11-rebuilt","mergedLoreFiles":24}}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-couteau-de-combat', 'Couteau de combat', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de mêlée","sourceCategory":"Armes — Mêlée","price":150,"priceMin":null,"priceMax":null,"priceLabel":"150 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Couteau de combat reste l’une des rares armes dont l’usage ne dépend d’aucune batterie, interface ou munition propriétaire. Sa valeur vient d’une géométrie robuste, d’un étui correct et d’un entretien simple, ce qui en fait autant un outil de terrain qu’une arme de dernier recours.\n\nDans la Grande Californie saturée d’électronique, cette simplicité a presque quelque chose de volontairement archaïque. Militaires, agents de sécurité, techniciens et survivalistes peuvent employer des modèles très différents, mais tous recherchent la même chose : une lame disponible immédiatement et compréhensible par n’importe quel utilisateur formé.","data":{"Type":"Melee","DGT":"3","Portee":"Contact","Proprietes":"-"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-owl-ka-73-last-encounter', 'Owl KA-73 Last Encounter', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de mêlée","sourceCategory":"Armes — Mêlée","price":750,"priceMin":null,"priceMax":null,"priceLabel":"750 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le KA-73 Last Encounter illustre le goût d’Owl pour les solutions de terrain sobres et endurantes. C’est une arme de contact conçue pour supporter les manipulations brutales, les chocs et le manque d’entretien mieux qu’un modèle plus sophistiqué dont l’électronique deviendrait son premier point faible.\n\nSon nom de Last Encounter vise clairement le moment où la distance et les options ont disparu. On le retrouve donc naturellement auprès d’utilisateurs qui veulent une arme de secours crédible plutôt qu’un objet de prestige : sécurité privée, opérateurs isolés ou professionnels pour qui la continuité de service compte davantage que l’effet spectaculaire.","data":{"Type":"Melee","DGT":"7","Portee":"Contact","Proprietes":"Fiable/Robuste en fiction"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-phoenix-pck-08-feather', 'Phoenix PCK-08 Feather', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de mêlée","sourceCategory":"Armes — Mêlée","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le PCK-08 Feather appartient à la face la plus technologique de Phoenix : une arme de contact compacte dont le tranchant assisté cherche à conserver une coupe nette malgré un format léger. La silhouette et le nom vendent la finesse, mais l’objet reste un véritable outil offensif qui demande entretien et alimentation adaptés.\n\nLe Feather trouve sa place auprès d’utilisateurs qui veulent une lame moderne sans porter une arme longue ou ouvertement militaire. Sa technologie améliore le comportement du tranchant contre la matière et limite certaines conséquences physiques de la coupe, mais elle ne transforme ni le geste ni le porteur en combattant surnaturel.","data":{"Type":"Melee","DGT":"4","Portee":"Contact","Proprietes":"Perforant 1 ; cauterise"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-phoenix-ba-037-sun-axe', 'Phoenix BA-037 Sun Axe', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de mêlée","sourceCategory":"Armes — Mêlée","price":900,"priceMin":null,"priceMax":null,"priceLabel":"900 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"La BA-037 Sun Axe transpose la philosophie Phoenix dans une arme plus lourde : une tête de hache assistée technologiquement, faite pour concentrer l’effort sur une zone de matière réduite. Là où le Feather mise sur la finesse, la Sun Axe assume une silhouette de brèche et une présence impossible à confondre avec un simple outil domestique.\n\nCe type d’arme attire autant les amateurs de matériel spectaculaire que les professionnels qui ont réellement besoin de frapper une protection, une porte ou un obstacle à courte distance. Son assistance énergétique reste toutefois une technologie matérielle : elle ne confère aucune propriété mystique au coup porté.","data":{"Type":"Melee","DGT":"7","Portee":"Contact","Proprietes":"Perforant 1 ; cauterise"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-raven-cl-038-claymore', 'Raven CL-038 Claymore', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de mêlée","sourceCategory":"Armes — Mêlée","price":750,"priceMin":null,"priceMax":null,"priceLabel":"750 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"La CL-038 Claymore reprend la silhouette volontairement intimidante d’une grande lame et y ajoute la spécialité électronique que Raven décline sur une partie de son matériel d’intervention. Le résultat est une arme de contact pensée autant pour menacer un adversaire que pour rester pertinente face à de l’équipement moderne exposé.\n\nDans la gamme Raven, la Claymore évoque moins le duel élégant que l’outil de force destiné à une équipe lourde, un agent de sécurité ou un opérateur qui sait qu’il peut devoir combattre au milieu de drones, capteurs et interfaces. Son caractère EMP reste strictement technologique et ne vaut jamais comme propriété anti-magique.","data":{"Type":"Melee","DGT":"8","Portee":"Contact","Proprietes":"EMP"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-raven-sp-016-raven-spear', 'Raven SP-016 Raven Spear', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de mêlée","sourceCategory":"Armes — Mêlée","price":1100,"priceMin":null,"priceMax":null,"priceLabel":"1 100 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"La SP-016 Raven Spear exploite l’allonge d’une arme d’hast tout en conservant la logique Raven de perturbation des équipements modernes. Son format tient l’adversaire à distance et donne à la tête de l’arme assez de masse et de structure pour travailler contre des protections ou des dispositifs accessibles.\n\nC’est une pièce encombrante pour la vie civile mais cohérente dans une unité préparée, un périmètre de sécurité ou une opération où l’on peut assumer le port d’une arme longue. Sa combinaison de pénétration matérielle et d’effet EMP la rend spécialisée contre le monde technique, pas contre toutes les menaces indistinctement.","data":{"Type":"Melee","DGT":"6","Portee":"1,5 m","Proprietes":"EMP ; Perforant 1"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-raven-tm-028-riot-control', 'Raven TM-028 Riot Control', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de mêlée","sourceCategory":"Armes — Mêlée","price":600,"priceMin":null,"priceMax":null,"priceLabel":"600 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le TM-028 Riot Control porte dans son nom sa vocation : un outil Raven destiné aux interventions où la maîtrise d’une personne et de son équipement compte davantage qu’une mise à mort immédiate. Sa conception robuste et sa composante électrique le rapprochent des matériels de police et de sécurité lourde plutôt que des armes de duel.\n\nDans une mégapole où un suspect peut porter implants, capteurs et interfaces, une arme de contrôle moderne doit pouvoir perturber plus qu’un corps. Cela explique la place du TM-028 dans la gamme Raven, sans pour autant lui donner une autorité particulière sur un phénomène non électronique ou surnaturel.","data":{"Type":"Melee","DGT":"4","Portee":"Contact","Proprietes":"EMP"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-owl-ts-009-sun-wukong', 'Owl TS-009 Sun Wukong', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de mêlée","sourceCategory":"Armes — Mêlée","price":600,"priceMin":null,"priceMax":null,"priceLabel":"600 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le TS-009 Sun Wukong est une arme longue d’Owl qui mise sur l’allonge et la fiabilité plutôt que sur un empilement d’assistances électroniques. Sa présence renvoie à une famille de matériels où la mécanique doit rester lisible, réparable et suffisamment robuste pour supporter un usage physique répété.\n\nCette sobriété en fait une arme appréciable dans les environnements où une panne logicielle ou une batterie vide serait plus dangereuse qu’un manque de sophistication. Le nom et la forme donnent au modèle une identité très marquée, mais son efficacité reste celle d’un bon outil de mêlée manié par quelqu’un qui sait l’utiliser.","data":{"Type":"Melee","DGT":"6","Portee":"1,5 m","Proprietes":"Fiable/Robuste"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-phoenix-pw-026-vampire-killer', 'Phoenix PW-026 Vampire Killer', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de mêlée","sourceCategory":"Armes — Mêlée","price":1300,"priceMin":null,"priceMax":null,"priceLabel":"1 300 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"La PW-026 Vampire Killer est l’un des meilleurs exemples du marketing agressif de Phoenix : le nom promet une arme presque mythologique, alors que le modèle de Réalité demeure une arme matérielle à tranchant assisté, conçue pour attaquer durement une protection et conserver une coupe propre.\n\nLe surnom fait vendre auprès d’une clientèle fascinée par les légendes urbaines autant qu’il construit une image de gamme. Sans préparation, matériau ou propriété de Vérité ajoutée ailleurs, une Vampire Killer n’est pas davantage anti-Vampire qu’un autre outil moderne ; son avantage vient de sa conception physique et de sa technologie, pas de son nom.","data":{"Type":"Melee","DGT":"7","Portee":"3,5 m","Proprietes":"Perforant 1 ; cauterise"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-raven-mc-025-hitman', 'Raven MC-025 Hitman', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de mêlée","sourceCategory":"Armes — Mêlée","price":1100,"priceMin":null,"priceMax":null,"priceLabel":"1 100 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le MC-025 Hitman est une arme Raven de proximité qui privilégie une attaque concentrée contre la matière plutôt qu’un volume ou un effet de zone. Son format allongé laisse davantage d’espace au geste et au contrôle qu’une simple lame de poche, tout en restant plus portable qu’une arme d’hast complète.\n\nLe nom vise clairement les professionnels et les acheteurs attirés par une esthétique d’efficacité froide. Dans la pratique, le Hitman reste un outil spécialisé dont l’intérêt tient à sa capacité à travailler une protection matérielle ; il n’accorde ni discrétion automatique ni compétence d’assassin à celui qui le porte.","data":{"Type":"Melee","DGT":"5","Portee":"1,5 m","Proprietes":"Perforant 2"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-owl-lc-014-chasseur', 'Owl LC-014 Chasseur', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de jet & trait","sourceCategory":"Armes — Mêlée","price":750,"priceMin":null,"priceMax":null,"priceLabel":"750 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le LC-014 Chasseur est un lanceur de trait Owl à tir choisi, conçu pour délivrer un projectile avec peu de complexité électronique. Son architecture intéresse les utilisateurs qui veulent une arme silencieuse par nature mécanique, capable de travailler une protection matérielle sans la signature d’une arme à feu classique.\n\nLe mot Chasseur appartient ici au nom commercial et à l’imaginaire du modèle. Dans la Réalité, l’arme ne reçoit aucune efficacité surnaturelle intrinsèque ; les usages de Chasse véritables dépendent de projectiles, préparations ou doctrines spécifiques décrites ailleurs, pas du simple fait de posséder ce LC-014.","data":{"Type":"Trait","DGT":"7","Portee":"25 m","Proprietes":"Perforant 1 ; 1 coup"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-seawares-hl-02-poseidon', 'SeaWares HL-02 Poseidon', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de jet & trait","sourceCategory":"Armes — Mêlée","price":950,"priceMin":null,"priceMax":null,"priceLabel":"950 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le HL-02 Poseidon est un lanceur de trait SeaWares pensé dès l’origine pour rester utilisable dans l’eau. Étanchéité, prise en main et fonctionnement mécanique privilégient un milieu où une arme terrestre ordinaire devient vite encombrante, imprécise ou simplement inutilisable.\n\nLe Poseidon évoque naturellement un lanceur de harpon moderne destiné aux plongeurs, équipes portuaires ou opérations aquatiques spécialisées. Sa capacité à fonctionner sous l’eau ne lui donne aucune supériorité universelle à terre : elle reflète surtout le savoir-faire SeaWares dans un environnement que d’autres fabricants traitent comme une exception.","data":{"Type":"Trait","DGT":"8","Portee":"25 m","Proprietes":"Aquatique ; 1 coup"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-raven-jl-014-cuchulainn', 'Raven JL-014 Cuchulainn', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de jet & trait","sourceCategory":"Armes — Mêlée","price":850,"priceMin":null,"priceMax":null,"priceLabel":"850 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le JL-014 Cuchulainn est une arme de jet Raven qui associe une forme simple et immédiatement compréhensible à des effets techniques dirigés contre la matière et l’électronique. Cette combinaison en fait un objet inhabituel dans une gamme moderne : le projectile doit être physiquement lancé avant que sa technologie ait la moindre utilité.\n\nLe choix d’un nom héroïque contraste avec une conception très pragmatique. L’arme intéresse surtout les opérateurs qui acceptent l’entraînement nécessaire à un projectile réutilisable ou spécialisé ; son effet EMP reste lié à ce qu’elle atteint réellement et ne remplace ni une arme à distance classique ni un pouvoir surnaturel.","data":{"Type":"Jet","DGT":"7","Portee":"15 m","Proprietes":"Perforant 1 ; EMP"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-tala-th-029-tomahawk', 'Tala TH-029 Tomahawk', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de jet & trait","sourceCategory":"Armes — Mêlée","price":850,"priceMin":null,"priceMax":null,"priceLabel":"850 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le TH-029 Tomahawk de Tala assume une double identité d’arme de main et de jet. Sa conception robuste lui permet de rester utile après le lancer et de conserver une vraie fonction au contact, ce qui correspond bien à un outil que l’on emporte pour sa polyvalence plutôt que pour une seule séquence idéale.\n\nTala mise ici sur une forme culturelle immédiatement reconnaissable sans sacrifier la fabrication moderne. Le modèle attire les utilisateurs qui veulent un projectile récupérable et une arme de mêlée dans le même objet ; sa pénétration reste toutefois une propriété matérielle, non une permission d’ignorer n’importe quelle protection.","data":{"Type":"Jet/Melee","DGT":"6","Portee":"15 m","Proprietes":"Perforant 1 ; Fiable/Robuste"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-owl-mb-014-bolas-monofilament', 'Owl MB-014 Bolas monofilament', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de jet & trait","sourceCategory":"Armes — Mêlée","price":1500,"priceMin":null,"priceMax":null,"priceLabel":"1 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le MB-014 d’Owl reprend le principe ancien des bolas en remplaçant la simple corde par une liaison monofilament beaucoup plus dangereuse. Le projectile cherche d’abord à envelopper ou couper ce qu’il rencontre, ce qui exige une maîtrise réelle du lancer et une conscience aiguë de l’espace autour de la cible.\n\nC’est une arme spécialisée, difficile à confondre avec un accessoire de maintien de l’ordre ordinaire. Son intérêt vient de la combinaison entre géométrie de lancer et matériau de coupe ; le monofilament n’est pas magique, reste physiquement présent et peut être aussi problématique pour un utilisateur maladroit que pour sa cible.","data":{"Type":"Jet","DGT":"6","Portee":"15 m","Proprietes":"Perforant 1"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-owl-lt-015-incapaciteur', 'Owl LT-015 Incapaciteur', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Tasers","sourceCategory":"Armes — Poing & Tasers","price":250,"priceMin":null,"priceMax":null,"priceLabel":"250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le LT-015 Incapaciteur représente l’approche Owl de la neutralisation compacte : une arme électrique assez petite pour accompagner un agent, un vigile ou un civil autorisé sans donner l’impression de porter un pistolet lourd. La réserve relativement confortable favorise un usage répété plutôt qu’un unique choc de dernier recours.\n\nSon rôle social est important : l’Incapaciteur existe pour les situations où l’on veut arrêter, repousser ou maîtriser avant de tuer. La décharge reste pourtant une attaque réelle, sensible aux protections et à la physiologie ; l’étiquette de neutralisation ne garantit jamais une intervention sans risque.","data":{"Classe":"Taser léger","DGT":"3","Portee":"15 m","Cap.":"10","Proprietes":"Électrique"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-raven-ht-014-immobilisateur', 'Raven HT-014 Immobilisateur', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Tasers","sourceCategory":"Armes — Poing & Tasers","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le HT-014 Immobilisateur est la réponse Raven au taser léger : plus massif, moins discret et clairement destiné à une intervention où l’on préfère une décharge lourde à une longue autonomie. Sa silhouette et son nom le rapprochent des équipements professionnels de sécurité et de maintien de l’ordre.\n\nRaven traite ici la neutralisation comme un problème opérationnel plutôt que comme un gadget civil. Le porteur gagne un outil spécialisé contre une personne ou un équipement sensible à l’électricité, mais doit accepter une arme plus encombrante et une réserve plus limitée que les solutions Owl plus compactes.","data":{"Classe":"Taser lourd","DGT":"6","Portee":"15 m","Cap.":"5","Proprietes":"Électrique"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-owl-pp-014-old-colt', 'Owl PP-014 Old Colt', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets de poche","sourceCategory":"Armes — Poing & Tasers","price":300,"priceMin":null,"priceMax":null,"priceLabel":"300 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le PP-014 Old Colt joue volontairement avec l’image du petit pistolet traditionnel. Owl conserve un format de poche, une mécanique lisible et une esthétique rassurante pour les acheteurs qui préfèrent un objet familier à une plateforme saturée de capteurs et de liaisons numériques.\n\nSon faible encombrement en fait surtout une arme de secours ou de défense personnelle. La contrepartie est évidente : un petit magasin et une prise en main compacte imposent de considérer chaque coup, ce qui correspond mieux à une arme que l’on porte beaucoup et utilise rarement qu’à un outil de combat prolongé.","data":{"Classe":"Poche","DGT":"6","Portee":"20 m","Cap.":"5","Proprietes":"-"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-raven-pp-012-defender', 'Raven PP-012 Defender', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets de poche","sourceCategory":"Armes — Poing & Tasers","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le PP-012 Defender est le pistolet de poche selon Raven : peu de sophistication visible, un format réduit et une philosophie centrée sur la disponibilité immédiate. Il vise l’utilisateur qui veut une arme secondaire robuste sous une veste, dans une sacoche ou comme dernier recours professionnel.\n\nLe nom Defender le place naturellement du côté de la protection personnelle et des gardes rapprochées, mais il ne change pas sa nature de petite arme à feu. Sa réserve modeste et son gabarit rappellent qu’il s’agit d’un compromis de port quotidien, pas d’un substitut discret à un pistolet de service complet.","data":{"Classe":"Poche","DGT":"7","Portee":"20 m","Cap.":"4","Proprietes":"-"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-owl-lp-019-acceptable', 'Owl LP-019 Acceptable', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets légers","sourceCategory":"Armes — Poing & Tasers","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"L’Owl LP-019 Acceptable porte un nom presque ironique pour un pistolet léger de service. Cette modestie correspond bien à un produit conçu pour faire correctement le travail demandé sans promettre une technologie de prestige : ergonomie conventionnelle, entretien simple et comportement prévisible.\n\nC’est le genre d’arme que l’on peut imaginer dans les holsters de sociétés de sécurité, de personnels autorisés ou de propriétaires qui privilégient la familiarité. L’Acceptable n’essaie pas de résoudre le tir par logiciel ; sa valeur repose sur une plateforme ordinaire que l’entraînement et la maintenance rendent fiable.","data":{"Classe":"Pistolet léger","DGT":"7","Portee":"35 m","Cap.":"10","Proprietes":"-"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-raven-lp-004-sturdy', 'Raven LP-004 Sturdy', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets légers","sourceCategory":"Armes — Poing & Tasers","price":800,"priceMin":null,"priceMax":null,"priceLabel":"800 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Raven LP-004 Sturdy est un pistolet léger de service construit autour d’une promesse simple : continuer à fonctionner. Sa mécanique privilégie la robustesse à la multiplication des options, ce qui l’inscrit naturellement dans les usages de sécurité, d’intervention ou de dotation professionnelle.\n\nLe Sturdy parle à une clientèle qui préfère une arme légèrement austère mais connue à une plateforme plus brillante dont chaque fonction dépend d’une interface. Chez Raven, cette sobriété participe à l’identité de gamme : du matériel que l’on peut malmener, entretenir et remettre rapidement en service.","data":{"Classe":"Pistolet léger","DGT":"8","Portee":"35 m","Cap.":"8","Proprietes":"Fiable"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-phoenix-lp-028-sun-blast', 'Phoenix LP-028 Sun Blast', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets légers","sourceCategory":"Armes — Poing & Tasers","price":950,"priceMin":null,"priceMax":null,"priceLabel":"950 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Phoenix LP-028 Sun Blast est un pistolet léger de service qui montre la préférence du fabricant pour une arme déjà pensée comme élément d’un écosystème de ciblage. Son interface Smartlink lui permet de communiquer avec l’équipement compatible du porteur au lieu de rester un mécanisme isolé.\n\nCette sophistication le destine aux utilisateurs équipés pour exploiter réellement la liaison : sécurité haut de gamme, professionnels augmentés ou tireurs qui acceptent de maintenir plusieurs composants ensemble. Sans interface correspondante, il reste un pistolet moderne correct, mais une partie de ce qui justifie son identité Phoenix disparaît.","data":{"Classe":"Pistolet léger","DGT":"7","Portee":"35 m","Cap.":"10","Proprietes":"Smartlink"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-owl-hp-104-deputy', 'Owl HP-104 Deputy', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets lourds","sourceCategory":"Armes — Poing & Tasers","price":950,"priceMin":null,"priceMax":null,"priceLabel":"950 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le HP-104 Deputy est le pistolet lourd Owl dans sa forme la plus traditionnelle : une arme de poing puissante, robuste et volontairement peu dépendante de systèmes annexes. Son nom évoque une autorité de terrain plus qu’un arsenal militaire, ce qui correspond à une arme que l’on porte pour imposer une présence autant que pour tirer.\n\nSa conception fiable intéresse les agents qui veulent conserver une arme lourde opérationnelle malgré poussière, chocs et entretien imparfait. Le Deputy reste néanmoins une arme de poing : son prestige et sa puissance apparente ne lui donnent ni la stabilité ni la portée pratique d’une véritable arme d’épaule.","data":{"Classe":"Pistolet lourd","DGT":"10","Portee":"45 m","Cap.":"7","Proprietes":"Fiable"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-raven-hp-014-pacificateur', 'Raven HP-014 Pacificateur', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets lourds","sourceCategory":"Armes — Poing & Tasers","price":1250,"priceMin":null,"priceMax":null,"priceLabel":"1 250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le HP-014 Pacificateur associe le gabarit d’un pistolet lourd à l’intégration électronique devenue courante dans les gammes professionnelles Raven. Le Smartlink permet à l’arme de rejoindre une chaîne de ciblage moderne, ce qui en fait un choix cohérent pour les personnels déjà équipés d’interfaces compatibles.\n\nLe nom Pacificateur relève d’un vocabulaire institutionnel assez transparent : il vend l’idée d’un outil qui termine rapidement un affrontement. Dans les faits, il reste une arme lourde exigeante dont l’assistance numérique accompagne le tireur sans remplacer ni son jugement ni sa maîtrise du recul et de la situation.","data":{"Classe":"Pistolet lourd","DGT":"11","Portee":"45 m","Cap.":"7","Proprietes":"Smartlink"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-raven-hp-067-gardien', 'Raven HP-067 Gardien', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets lourds","sourceCategory":"Armes — Poing & Tasers","price":1650,"priceMin":null,"priceMax":null,"priceLabel":"1 650 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le HP-067 Gardien pousse le concept Raven du pistolet lourd de service vers une arme destinée à rester longtemps disponible avant rechargement. Son Smartlink l’inscrit dans les dispositifs de protection moderne où arme, viseur et interface personnelle fonctionnent comme plusieurs éléments d’une même chaîne.\n\nLe Gardien paraît particulièrement cohérent pour la sécurité de site, les escortes et les utilisateurs qui veulent une arme de poing principale plutôt qu’un simple secours. Sa capacité et son électronique n’effacent toutefois pas les contraintes d’un pistolet lourd : masse, recul, entretien et port visible restent des réalités quotidiennes.","data":{"Classe":"Pistolet lourd","DGT":"11","Portee":"45 m","Cap.":"12","Proprietes":"Smartlink"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-phoenix-hp-028-violator', 'Phoenix HP-028 Violator', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets lourds","sourceCategory":"Armes — Poing & Tasers","price":1250,"priceMin":null,"priceMax":null,"priceLabel":"1 250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Phoenix HP-028 Violator est une arme de poing lourde dont le nom et la présentation assument une image agressive. Comme d’autres Phoenix modernes, il intègre le Smartlink dès la conception et vise les utilisateurs qui considèrent l’arme comme un périphérique de leur équipement numérique autant que comme un mécanisme balistique.\n\nLe modèle attire naturellement une clientèle professionnelle ou fortunée sensible aux solutions de tir assisté. Cette intégration ne le rend pas autonome : sans interface compatible, le Violator perd son avantage de réseau et redevient essentiellement un gros pistolet dont la puissance doit encore être contrôlée par la personne qui le tient.","data":{"Classe":"Pistolet lourd","DGT":"10","Portee":"45 m","Cap.":"10","Proprietes":"Smartlink"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-phoenix-hp-092-depliant', 'Phoenix HP-092 Depliant', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets lourds","sourceCategory":"Armes — Poing & Tasers","price":1250,"priceMin":null,"priceMax":null,"priceLabel":"1 250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le HP-092 Dépliant cherche à résoudre un problème très concret : transporter une arme de poing lourde sans conserver en permanence tout son volume prêt au tir. Son architecture pliante compresse le profil au rangement, tandis que Phoenix conserve l’intégration Smartlink attendue d’un modèle aussi technologique.\n\nCette logique intéresse les gardes du corps, voyageurs et professionnels qui doivent concilier puissance disponible et encombrement de transport. Le mécanisme ajoute cependant des pièces et des articulations à surveiller ; le Dépliant est un produit d’ingénierie sophistiqué, pas une manière gratuite de rendre une arme lourde invisible.","data":{"Classe":"Pistolet lourd","DGT":"10","Portee":"45 m","Cap.":"9","Proprietes":"Smartlink ; pliant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-owl-mgp-062-suppressor', 'Owl MGP-062 Suppressor', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets-mitrailleurs (PM)","sourceCategory":"Armes — Automatiques","price":750,"priceMin":null,"priceMax":null,"priceLabel":"750 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"L’Owl MGP-062 Suppressor est un pistolet-mitrailleur conçu pour les espaces où une arme d’épaule longue devient davantage une gêne qu’un avantage. Owl reste fidèle à une approche pragmatique : une plateforme compacte, une réserve généreuse et peu de fonctions qui exigeraient un écosystème électronique spécifique.\n\nOn l’imagine facilement auprès d’équipes de sécurité, de convoyeurs ou d’opérateurs urbains qui travaillent dans des couloirs, parkings et véhicules. Le nom Suppressor renvoie au volume de feu qu’il peut imposer, pas à un silencieux intégré ni à une capacité spéciale de neutralisation discrète.","data":{"Classe":"PM","DGT":"7","Portee":"30 m","Cap.":"30","Proprietes":"Rafale, Automatique"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-raven-mgp-072-military', 'Raven MGP-072 Military', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets-mitrailleurs (PM)","sourceCategory":"Armes — Automatiques","price":1050,"priceMin":null,"priceMax":null,"priceLabel":"1 050 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Raven MGP-072 Military annonce sans détour son marché : une arme compacte conçue comme matériel professionnel plutôt que comme produit civil élégant. Sa mécanique robuste correspond à la tendance Raven à privilégier continuité de service, simplicité d’entretien et comportement prévisible sous contrainte.\n\nSa réserve moins généreuse que certains concurrents n’est pas nécessairement un défaut de conception ; elle accompagne une plateforme qui mise sur la fiabilité et un port raisonnable dans un environnement militaire ou de sécurité. Le Military sert d’abord à rester disponible au moment critique, pas à empiler les accessoires.","data":{"Classe":"PM","DGT":"8","Portee":"30 m","Cap.":"20","Proprietes":"Rafale, Automatique, Fiable"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-phoenix-mgp-042-equalizer', 'Phoenix MGP-042 Equalizer', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets-mitrailleurs (PM)","sourceCategory":"Armes — Automatiques","price":1250,"priceMin":null,"priceMax":null,"priceLabel":"1 250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Phoenix MGP-042 Equalizer est un pistolet-mitrailleur compact déjà pensé pour dialoguer avec une interface de ciblage. Phoenix traite ici l’arme comme un nœud d’un équipement personnel connecté : la mécanique de tir reste conventionnelle, mais le Smartlink lui permet de partager suivi et solution de tir avec le porteur.\n\nLe modèle intéresse surtout les professionnels équipés pour exploiter cette couche numérique, là où un utilisateur sans interface paierait une sophistication qu’il utilise peu. L’Equalizer ne transforme donc pas un mauvais tireur en expert ; il récompense une chaîne de matériel cohérente et correctement entretenue.","data":{"Classe":"PM","DGT":"7","Portee":"30 m","Cap.":"30","Proprietes":"Rafale, Automatique, Smartlink"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-owl-lmg-092-gladius', 'Owl LMG-092 Gladius', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — SMG","sourceCategory":"Armes — Automatiques","price":950,"priceMin":null,"priceMax":null,"priceLabel":"950 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"L’Owl LMG-092 Gladius occupe la zone intermédiaire entre arme compacte et véritable fusil d’assaut. Son identité tient à une formule simple : assez de volume de feu pour soutenir un déplacement, mais sans les dimensions et la logistique d’une arme lourde ou d’une plateforme bardée d’électronique.\n\nCette sobriété correspond aux utilisateurs qui veulent une arme d’épaule mobile pour la sécurité, l’autodéfense organisée ou des interventions urbaines courtes. Owl vend ici une continuité d’emploi plus qu’une fonction vedette : le Gladius n’a pas besoin d’un réseau de ciblage pour remplir son rôle.","data":{"Classe":"SMG","DGT":"9","Portee":"45 m","Cap.":"30","Proprietes":"Rafale, Automatique"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-phoenix-lmg-018-urban', 'Phoenix LMG-018 Urban', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — SMG","sourceCategory":"Armes — Automatiques","price":1550,"priceMin":null,"priceMax":null,"priceLabel":"1 550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Phoenix LMG-018 Urban a été nommé pour son environnement naturel : rues courtes, intérieurs vastes, parkings et structures où le tireur change constamment d’angle et de distance. Sa compacité se combine à un Smartlink qui permet de conserver le bénéfice d’un équipement connecté sans passer au format d’un fusil plus long.\n\nPhoenix vise ainsi les unités et professionnels qui veulent une arme de mobilité moderne plutôt qu’un simple tuyau à balles. Le ciblage assisté reste un outil : il dépend d’une interface compatible, n’efface pas les couverts et ne rend pas les rafales plus sûres pour les personnes autour de la cible.","data":{"Classe":"SMG","DGT":"9","Portee":"30 m","Cap.":"30","Proprietes":"Rafale, Automatique, Smartlink"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-raven-lmg-027-executionner', 'Raven LMG-027 Executionner', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — SMG","sourceCategory":"Armes — Automatiques","price":1350,"priceMin":null,"priceMax":null,"priceLabel":"1 350 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Raven LMG-027 Executionner est une mitraillette compacte qui privilégie la robustesse et la simplicité. Son nom brutal est presque plus démonstratif que sa technologie : derrière l’image commerciale, Raven propose surtout une arme courte conçue pour supporter les chocs, les manipulations rapides et les conditions de service difficiles.\n\nL’Executionner paraît particulièrement à sa place dans des mains professionnelles qui préfèrent connaître parfaitement une plateforme dépouillée plutôt que dépendre de multiples aides numériques. Sa réserve impose de gérer les séquences de feu, mais cette contrainte participe à une arme pensée pour des engagements rapprochés et contrôlés.","data":{"Classe":"SMG","DGT":"10","Portee":"30 m","Cap.":"20","Proprietes":"Rafale, Automatique, Fiable"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-raven-lmg-072-neo-executionner', 'Raven LMG-072 Neo-Executionner', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — SMG","sourceCategory":"Armes — Automatiques","price":2150,"priceMin":null,"priceMax":null,"priceLabel":"2 150 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le LMG-072 Neo-Executionner reprend la base robuste de la famille Executionner et lui ajoute la couche électronique que Raven réserve à ses versions modernisées. Le résultat conserve une mécanique destinée au service intensif tout en permettant au tireur équipé d’intégrer l’arme à une solution Smartlink.\n\nLe préfixe Neo ne signifie donc pas que Raven a abandonné sa philosophie de fiabilité ; il indique plutôt une évolution de plateforme. Pour les unités déjà dotées d’interfaces, c’est un moyen de conserver les habitudes de l’Executionner tout en entrant dans une chaîne de ciblage contemporaine.","data":{"Classe":"SMG","DGT":"10","Portee":"30 m","Cap.":"20","Proprietes":"Rafale, Automatique, Fiable, Smartlink"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-phoenix-ar-124-mutilator', 'Phoenix AR-124 Mutilator', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Fusils d’assaut","sourceCategory":"Armes — Automatiques","price":950,"priceMin":null,"priceMax":null,"priceLabel":"950 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Phoenix AR-124 Mutilator est le fusil d’assaut généraliste de ceux qui veulent une grande réserve et une arme capable d’accompagner une progression sans spécialisation excessive. Contrairement à plusieurs modèles Phoenix plus électroniques, son identité repose surtout sur une plateforme balistique moderne et agressivement nommée.\n\nLe Mutilator se prête aux unités mobiles, mercenaires et agents de sécurité lourdement équipés qui veulent une arme d’épaule unique pour l’essentiel d’un engagement. Son nom promet la violence, pas une propriété cachée : sa valeur vient du compromis entre autonomie, portée et cadence d’un vrai fusil de service.","data":{"Classe":"Assaut","DGT":"11","Portee":"60 m","Cap.":"36","Proprietes":"Rafale, Automatique"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-raven-ar-027-rampager', 'Raven AR-027 Rampager', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Fusils d’assaut","sourceCategory":"Armes — Automatiques","price":2100,"priceMin":null,"priceMax":null,"priceLabel":"2 100 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Raven AR-027 Rampager combine deux tendances fortes du fabricant : une mécanique pensée pour continuer à fonctionner et une capacité à rester pertinente dans un environnement saturé d’électronique. C’est un fusil d’assaut de terrain, moins intéressé par l’élégance que par la possibilité de traiter combattant, capteurs et équipements dans le même engagement.\n\nCette orientation explique son intérêt pour les unités d’intervention ou de sécurité qui affrontent drones, augmentations et systèmes intelligents aussi souvent que des armes ordinaires. L’EMP ne change pourtant pas la nature du fusil : ce qui n’est pas électronique ne devient pas vulnérable par simple présence du logo Raven.","data":{"Classe":"Assaut","DGT":"12","Portee":"60 m","Cap.":"24","Proprietes":"Rafale, Automatique, Fiable, EMP"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-owl-ar-071-howling', 'Owl AR-071 Howling', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Fusils d’assaut","sourceCategory":"Armes — Automatiques","price":1550,"priceMin":null,"priceMax":null,"priceLabel":"1 550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"L’Owl AR-071 Howling est un fusil d’assaut orienté vers les cibles protégées, tout en conservant la simplicité d’une arme d’épaule conventionnelle. Owl privilégie ici une réponse matérielle à un problème matériel : si les protections deviennent plus courantes, la munition et la plateforme doivent être capables de les travailler proprement.\n\nLe Howling trouve donc sa place chez les professionnels qui attendent davantage qu’un pistolet-mitrailleur sans vouloir une arme lourde spécialisée. Sa capacité de pénétration n’est pas une autorisation d’ignorer les armures ; elle fait du modèle un choix cohérent lorsqu’on sait que la cible risque d’être équipée.","data":{"Classe":"Assaut","DGT":"11","Portee":"45 m","Cap.":"36","Proprietes":"Rafale, Automatique, Perforant 1"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-phoenix-ar-124-sunlight', 'Phoenix AR-124 Sunlight', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Fusils d’assaut","sourceCategory":"Armes — Automatiques","price":2550,"priceMin":null,"priceMax":null,"priceLabel":"2 550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Phoenix AR-124 Sunlight transforme le fusil d’assaut en plateforme de contrôle autant que de tir. Smartlink et technologie Flash correspondent à la tendance Phoenix à ajouter une couche de capteurs et d’effets spécialisés à une arme qui doit pourtant rester utilisable comme fusil de service ordinaire.\n\nLe nom Sunlight entretient une esthétique lumineuse cohérente avec la gamme sans lui donner de vertu solaire surnaturelle. Son effet de désorientation reste une technologie de Réalité : utile contre des sens exposés dans les bonnes conditions, mais sans rapport automatique avec les faiblesses occultes décrites en Vérité.","data":{"Classe":"Assaut","DGT":"11","Portee":"45 m","Cap.":"36","Proprietes":"Rafale, Automatique, Smartlink, Flash"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-precision-owl-sr-017-big-game-hunter', 'Owl SR-017 Big Game Hunter', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Fusils de précision","sourceCategory":"Armes — Précision","price":950,"priceMin":null,"priceMax":null,"priceLabel":"950 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"L’Owl SR-017 Big Game Hunter est un fusil de précision volontairement dépouillé. Il s’adresse à ceux qui préfèrent une bonne mécanique, une position correcte et une solution de tir patiente plutôt qu’un système qui promet de compenser chaque erreur par des capteurs supplémentaires.\n\nSon nom emprunte à la chasse sportive et au tir sur cible difficile, ce qui lui donne une image plus civile que certains fusils militaires. Dans les faits, la plateforme reste une arme longue sérieuse dont la faible cadence favorise la préparation, l’observation et le choix d’un coup plutôt que l’échange soutenu.","data":{"Classe":"Précision","DGT":"12","Portee":"120 m","Cap.":"5","Proprietes":"-"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-precision-owl-sr-029-hoot', 'Owl SR-029 Hoot', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Fusils de précision","sourceCategory":"Armes — Précision","price":2550,"priceMin":null,"priceMax":null,"priceLabel":"2 550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"L’Owl SR-029 Hoot représente une montée en gamme vers le tir de précision contre des protections plus sérieuses. Owl conserve sa recherche de fiabilité, mais la plateforme est clairement destinée au tireur qui prépare un poste et attend d’un petit nombre de coups qu’ils restent efficaces sur une cible difficile.\n\nLe Hoot parle donc davantage aux professionnels, chasseurs de matériel ou tireurs de sécurité qu’au propriétaire occasionnel. Sa capacité de pénétration récompense une cible correctement identifiée et atteinte ; elle ne remplace ni l’observation, ni la connaissance de ce qui se trouve derrière une protection.","data":{"Classe":"Précision","DGT":"13","Portee":"200 m","Cap.":"6","Proprietes":"Fiable, Perforant 1"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-precision-raven-sr-029-deathbringer', 'Raven SR-029 Deathbringer', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Fusils de précision","sourceCategory":"Armes — Précision","price":4550,"priceMin":null,"priceMax":null,"priceLabel":"4 550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Raven SR-029 Deathbringer est un fusil de précision lourd dans son intention : longue distance, peu de coups disponibles et une conception qui privilégie la fiabilité lorsque le tireur ne peut pas se permettre une panne après s’être installé. Son nom commercial assume pleinement la réputation intimidante recherchée par Raven.\n\nLa présence d’une composante EMP lui donne une seconde lecture dans le monde de 2035 : un tir peut viser un opérateur, mais aussi l’électronique exposée d’un équipement important. Cette polyvalence reste ciblée ; le Deathbringer n’est ni une arme de suppression ni un détecteur de vulnérabilités technologiques.","data":{"Classe":"Précision","DGT":"14","Portee":"300 m","Cap.":"4","Proprietes":"Fiable, EMP"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-precision-phoenix-sr-034-phantom', 'Phoenix SR-034 Phantom', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Fusils de précision","sourceCategory":"Armes — Précision","price":4050,"priceMin":null,"priceMax":null,"priceLabel":"4 050 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Phoenix SR-034 Phantom est un fusil de précision construit autour de la discrétion relative et de l’assistance numérique. Un modérateur acoustique et un Smartlink s’intègrent à une plateforme longue pour réduire les indices laissés par le tireur et faciliter le suivi d’une cible compatible.\n\nLe nom Phantom décrit une ambition, pas une invisibilité. Le coup reste audible dans les bonnes conditions, le tireur reste visible s’il se place mal et l’électronique peut elle-même devenir une signature. Le modèle récompense donc surtout une doctrine où position, masque et information sont préparés ensemble.","data":{"Classe":"Précision","DGT":"13","Portee":"250 m","Cap.":"5","Proprietes":"Smartlink, silencieux"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-precision-raven-sg-025-riot-control', 'Raven SG-025 Riot Control', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Shotguns","sourceCategory":"Armes — Précision","price":1250,"priceMin":null,"priceMax":null,"priceLabel":"1 250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Raven SG-025 Riot Control est un shotgun d’intervention dont la vocation dépasse l’impact balistique ordinaire. Sa composante électrique le place naturellement dans les équipements de police et de sécurité qui doivent pouvoir neutraliser rapidement une personne ou perturber du matériel à quelques mètres.\n\nSon nom institutionnel ne rend pas son usage bénin : à courte distance, un shotgun reste une arme dangereuse et la décharge n’annule pas les conséquences physiques du tir. Raven vend ici un outil de contrôle lourd pour des équipes formées, pas un substitut sans risque au taser compact.","data":{"Classe":"Shotgun","DGT":"12","Portee":"15 m","Cap.":"8","Proprietes":"Dispersion 3 ; électrique"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-precision-raven-sg-039-croaker', 'Raven SG-039 Croaker', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Shotguns","sourceCategory":"Armes — Précision","price":5550,"priceMin":null,"priceMax":null,"priceLabel":"5 550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Raven SG-039 Croaker est la réponse de la marque aux cibles que l’on veut arrêter brutalement à courte distance. Fiabilité, pénétration matérielle et capacité à perturber l’électronique en font une plateforme d’assaut spécialisée, beaucoup plus proche d’un outil de brèche que d’un fusil de chasse civil.\n\nLe Croaker paraît destiné aux équipes qui savent pourquoi elles acceptent son poids et sa violence : intervention lourde, sécurité de site ou opérations dans un environnement très équipé. Sa polyvalence disparaît vite avec la distance, et ses effets techniques ne remplacent jamais le choix de la bonne munition ou du bon angle.","data":{"Classe":"Shotgun","DGT":"15","Portee":"15 m","Cap.":"6","Proprietes":"Dispersion 4 ; Fiable ; EMP ; Perforant 1"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-precision-owl-sg-016-boss', 'Owl SG-016 Boss', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Shotguns","sourceCategory":"Armes — Précision","price":1550,"priceMin":null,"priceMax":null,"priceLabel":"1 550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"L’Owl SG-016 Boss est un shotgun de proximité qui mise surtout sur l’autonomie et la robustesse. Owl évite les effets annexes spectaculaires pour proposer une arme capable de rester longtemps disponible dans un environnement resserré où chaque rechargement peut coûter cher.\n\nLe Boss convient aux utilisateurs qui veulent une présence immédiate derrière une porte, dans un couloir ou autour d’un véhicule. Sa grande réserve n’en fait pas une arme de moyenne portée : la philosophie du modèle reste celle d’un shotgun fiable, efficace tant qu’on accepte son domaine d’emploi très rapproché.","data":{"Classe":"Shotgun","DGT":"13","Portee":"15 m","Cap.":"12","Proprietes":"Dispersion 3 ; Fiable"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-precision-phoenix-sg-042-fire-rain', 'Phoenix SG-042 Fire Rain', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Shotguns","sourceCategory":"Armes — Précision","price":2050,"priceMin":null,"priceMax":null,"priceLabel":"2 050 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Phoenix SG-042 Fire Rain pousse le shotgun vers une fonction incendiaire assumée. La gerbe ne cherche pas seulement à frapper une cible : elle peut faire de l’environnement combustible une seconde menace, ce qui explique autant l’attrait du modèle que les réticences à l’employer dans un espace urbain mal contrôlé.\n\nPhoenix vend ici une arme spectaculaire dont l’usage exige pourtant beaucoup de discipline. Le feu n’obéit pas au propriétaire de l’arme et ne connaît pas la différence entre un couvert ennemi, une canalisation ou un appartement voisin ; le Fire Rain est donc un outil spécialisé, pas une amélioration universelle du shotgun.","data":{"Classe":"Shotgun","DGT":"13","Portee":"15 m","Cap.":"5","Proprietes":"Dispersion 4 ; [Feu]"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-lourdes-bastion', 'Bastion', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Mitrailleuses lourdes & Gatlings","sourceCategory":"Armes — Lourdes","price":5500,"priceMin":null,"priceMax":null,"priceLabel":"5 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Bastion est une mitrailleuse lourde d’appui conçue pour transformer une position en point d’ancrage. Bande volumineuse, masse importante et cadence soutenue la placent dans une logique de groupe : on prépare son transport, son emplacement et son alimentation avant de profiter réellement de ce que l’arme peut fournir.\n\nDans une équipe professionnelle, Bastion sert à tenir un axe, couvrir un déplacement ou interdire une zone plutôt qu’à suivre discrètement son porteur toute la journée. Son nom résume bien sa fonction sociale et tactique : ce n’est pas une arme personnelle prestigieuse, c’est une infrastructure de feu portable.","data":{"DGT":"13","Portee":"80 m","Cap.":"60","Role":"Mitrailleuse lourde / appui","Proprietes":"Rafale, Automatique, Encombrant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-lourdes-manticore', 'Manticore', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Neutralisation lourde","sourceCategory":"Armes — Lourdes","price":8500,"priceMin":null,"priceMax":null,"priceLabel":"8 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Manticore est une arme lourde de neutralisation qui applique la logique EMP à l’échelle d’un matériel d’appui. Là où un fusil Raven peut opportunément perturber un système, Manticore est choisie précisément parce que drones, capteurs, interfaces ou machines constituent une partie centrale du problème.\n\nSon encombrement et ses munitions spécialisées en font un outil d’équipe que l’on sort pour une mission connue, pas une arme polyvalente portée par habitude. Une Manticore peut bouleverser un dispositif électronique exposé, mais elle ne résout rien contre une menace dont la nature n’est pas technologique.","data":{"DGT":"14","Portee":"80 m","Cap.":"6","Role":"Neutralisation lourde","Proprietes":"EMP, Encombrant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-lourdes-hellstorm', 'Hellstorm', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Mitrailleuses lourdes & Gatlings","sourceCategory":"Armes — Lourdes","price":12000,"priceMin":null,"priceMax":null,"priceLabel":"12 000 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Hellstorm est une Gatling lourde alimentée par une bande de 200 coups. Sa cadence et son volume de feu lui permettent de saturer durablement un secteur à moyenne portée plutôt que de rechercher la discrétion ou la mobilité légère.\n\nRafale, tir automatique et mécanique Fiable en font une arme d’appui et de suppression conçue pour maintenir un feu soutenu sous pression. Sa bande dédiée fournit l’autonomie nécessaire à ce rôle, tandis que son gabarit Encombrant impose un portage adapté.","data":{"DGT":"13","Portee":"70 m","Cap.":"200","Role":"Gatling","Proprietes":"Rafale, Automatique, Fiable, Encombrant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-lourdes-doorbell', 'Doorbell', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Lanceurs & missiles","sourceCategory":"Armes — Lourdes","price":3500,"priceMin":null,"priceMax":null,"priceLabel":"3 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Doorbell est un lance-grenades lourd à barillet dont l’identité dépend moins du tube que de ce que l’équipe décide d’y charger. Fragmentation, EMP, flash ou fumigène transforment la même plateforme en outil de destruction, de perturbation, de désorientation ou de couverture.\n\nCette polyvalence favorise les unités qui préparent réellement leur mission et savent identifier les effets qu’elles veulent produire avant d’ouvrir le feu. Le surnom Doorbell reflète l’idée d’annoncer brutalement son arrivée ; la plateforme reste toutefois aussi bonne ou mauvaise que la sélection de grenades emportée.","data":{"DGT":"variable","Portee":"60 m","Cap.":"6","Role":"Lance-grenades lourd","Proprietes":"Zone selon grenade, Encombrant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-lourdes-breacher', 'Breacher', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Lanceurs & missiles","sourceCategory":"Armes — Lourdes","price":5500,"priceMin":null,"priceMax":null,"priceLabel":"5 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Breacher est un lance-roquette monocoup conçu autour d’une tâche simple : faire céder un point dur. Porte renforcée, couverture, mur léger ou position préparée justifient une arme dont la munition est trop encombrante et trop coûteuse pour être gaspillée comme projectile généraliste.\n\nSon emploi impose donc une petite logistique de brèche : transporter les roquettes, choisir l’angle, protéger le tireur pendant la préparation et accepter les conséquences autour du point d’impact. Breacher appartient à l’outillage violent d’une équipe d’assaut davantage qu’à l’armement personnel.","data":{"DGT":"18","Portee":"90 m","Cap.":"1","Role":"Lance-roquette de breche","Proprietes":"Perforant 2, Zone 3 m, Encombrant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-lourdes-wasp', 'Wasp', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Lanceurs & missiles","sourceCategory":"Armes — Lourdes","price":14000,"priceMin":null,"priceMax":null,"priceLabel":"14 000 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Wasp est un lance-missile guidé destiné aux situations où atteindre la cible compte autant que la puissance de la charge. Son électronique peut exploiter une désignation compatible et une trajectoire plausible, ce qui transforme le lancement en opération coordonnée plutôt qu’en simple tir d’un projectile lourd.\n\nUne équipe qui emploie Wasp doit donc penser en termes de capteurs, de verrouillage, d’espace de vol et de munitions dédiées. Le guidage ne rend rien inévitable : brouillage, défense, mauvais repérage ou trajectoire impossible restent des problèmes que le missile ne peut pas corriger par magie.","data":{"DGT":"20","Portee":"150 m","Cap.":"1","Role":"Missile guide","Proprietes":"Autoguide, Smartlink, Zone 4 m, Encombrant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-lourdes-wallbreaker', 'Wallbreaker', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Anti-matériel & fortifications","sourceCategory":"Armes — Lourdes","price":12500,"priceMin":null,"priceMax":null,"priceLabel":"12 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Wallbreaker est une arme lourde anti-matériel qui privilégie la pénétration et le tir préparé plutôt que la zone ou la cadence. Son rôle naturel est de traiter une couverture, une structure, un équipement protégé ou une cible dont l’armure justifie un projectile spécialisé.\n\nLe modèle intéresse les équipes de sécurité lourde, mercenaires et intervenants capables d’assumer son encombrement et la visibilité de son emploi. Son nom ne doit pas faire oublier que toute structure a sa propre résistance : Wallbreaker est un outil puissant, pas une permission narrative de traverser n’importe quel mur.","data":{"DGT":"16","Portee":"200 m","Cap.":"3","Role":"Anti-matériel / fortification","Proprietes":"Perforant 3, Encombrant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-lourdes-salamander', 'Salamander', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Projecteurs lourds","sourceCategory":"Armes — Lourdes","price":3500,"priceMin":null,"priceMax":null,"priceLabel":"3 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Salamander est un projecteur incendiaire lourd conçu pour imposer le feu comme problème de terrain. Son intérêt apparaît surtout dans les espaces où combustible, couvert et circulation des personnes peuvent être bouleversés par une projection à courte portée plutôt que par un simple impact ponctuel.\n\nC’est aussi une arme politiquement et pratiquement difficile à employer proprement en ville : le porteur transporte son propre consommable inflammable et le décor peut continuer à brûler après son action. Les utilisateurs professionnels le traitent donc comme matériel spécialisé, rarement comme arme de routine.","data":{"DGT":"9","Portee":"15 m","Cap.":"6 usages","Role":"Projecteur incendiaire","Proprietes":"[Feu], Zone 3 m (cone), Encombrant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-lourdes-purifier', 'Purifier', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Projecteurs lourds","sourceCategory":"Armes — Lourdes","price":6500,"priceMin":null,"priceMax":null,"priceLabel":"6 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Purifier est un projecteur chimique lourd issu d’une logique industrielle de décontamination et de corrosion détournée vers le terrain. Plutôt que de compter sur une balle, il répand un agent dont l’intérêt dépend directement des matériaux, des protections et de l’environnement qu’il rencontre.\n\nLe nom Purifier possède évidemment une ironie sinistre lorsque l’appareil est utilisé comme arme. Masques, étanchéité et procédures de manipulation comptent autant que le projecteur lui-même, car une fuite, un mauvais vent ou une surface incompatible peut transformer le dispositif en problème pour sa propre équipe.","data":{"DGT":"11","Portee":"12 m","Cap.":"5 usages","Role":"Projecteur chimique lourd","Proprietes":"[Chimique], Zone 3 m (cone), Encombrant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'accessoires-d-armes-silencieux', 'Silencieux', NULL, '{"nature":"equipement","kind":"equipment","category":"Accessoires d''armes","sourceCategory":"Accessoires d''armes","price":250,"priceMin":null,"priceMax":null,"priceLabel":"250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Perception pour entendre/localiser le tir : -3 lorsque le silencieux est efficace. Le tir n''est jamais absolument silencieux.","lore":"Le Silencieux moderne est avant tout un modérateur de signature : il réduit le bruit et rend l’origine d’un tir plus difficile à localiser, mais ne transforme jamais une détonation en geste inaudible. Munition, longueur de canon, environnement et distance continuent de compter autant que l’accessoire lui-même.\n\nDans une ville saturée de micros, capteurs et témoins, sa valeur tient souvent à quelques secondes d’incertitude supplémentaires plutôt qu’à une disparition miraculeuse. Professionnels et criminels l’emploient donc comme une couche de discrétion parmi d’autres, avec l’entretien et l’encombrement que son montage impose.","data":{"Effet":"Perception pour entendre/localiser le tir : -3 lorsque le silencieux est efficace. Le tir n''est jamais absolument silencieux."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'accessoires-d-armes-optique-de-precision', 'Optique de précision', NULL, '{"nature":"equipement","kind":"equipment","category":"Accessoires d''armes","sourceCategory":"Accessoires d''armes","price":400,"priceMin":null,"priceMax":null,"priceLabel":"400 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"En utilisant Viser, ignore le -3 de longue portée jusqu''à 2 x la portée nominale.","lore":"L’Optique de précision regroupe les systèmes de visée conçus pour tirer parti d’une arme au-delà de la distance où l’œil nu suffit confortablement. Grossissement, repères et stabilisation visuelle servent surtout à identifier correctement une cible et à conserver une solution de tir préparée.\n\nCe type d’optique équipe chasseurs, tireurs professionnels et unités de sécurité sans transformer pour autant une arme courte en fusil de précision. Il aide à exploiter une plateforme adaptée ; qualité du canon, position, atmosphère et compétence du tireur restent les limites réelles de l’ensemble.","data":{"Effet":"En utilisant Viser, ignore le -3 de longue portée jusqu''à 2 x la portée nominale."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'accessoires-d-armes-chargeur-etendu', 'Chargeur étendu', NULL, '{"nature":"equipement","kind":"equipment","category":"Accessoires d''armes","sourceCategory":"Accessoires d''armes","price":75,"priceMin":null,"priceMax":null,"priceLabel":"75 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+50 % capacité, arrondi au supérieur ; plus difficile à dissimuler.","lore":"Le Chargeur étendu est l’une des modifications les plus simples à comprendre : davantage de munitions dans l’arme avant de devoir interrompre l’action. Cette réserve supplémentaire implique un magasin plus long ou plus volumineux, donc une modification immédiatement perceptible de la silhouette et de l’équilibre.\n\nLes unités qui anticipent un échange prolongé apprécient ce compromis, tandis que les utilisateurs cherchant la discrétion ou le port sous vêtement préfèrent souvent le magasin standard. Un chargeur étendu ne rend pas l’arme plus puissante ; il déplace seulement le problème du rechargement vers celui du volume et du poids.","data":{"Effet":"+50 % capacité, arrondi au supérieur ; plus difficile à dissimuler."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'accessoires-d-armes-bipied', 'Bipied', NULL, '{"nature":"equipement","kind":"equipment","category":"Accessoires d''armes","sourceCategory":"Accessoires d''armes","price":150,"priceMin":null,"priceMax":null,"priceLabel":"150 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Stationnaire et appuyé : ignore les contraintes directement dues à Encombrant/poids pour le tir.","lore":"Le Bipied transforme une surface stable en troisième point d’appui pour l’arme. Sur une mitrailleuse, un fusil lourd ou une plateforme anti-matériel, ce simple dispositif permet au tireur de laisser le sol reprendre une partie de la masse et des efforts qui pèseraient autrement sur ses bras et ses épaules.\n\nSon intérêt explique aussi sa limite : un bipied n’aide réellement que lorsqu’on peut s’installer. Les équipes d’appui choisissent donc leurs positions en pensant à la hauteur, au champ de tir et à la stabilité du support ; dans un déplacement précipité, les deux pieds repliés deviennent surtout du métal supplémentaire.","data":{"Effet":"Stationnaire et appuyé : ignore les contraintes directement dues à Encombrant/poids pour le tir."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'accessoires-d-armes-smartlink', 'Smartlink', NULL, '{"nature":"equipement","kind":"equipment","category":"Accessoires d''armes","sourceCategory":"Accessoires d''armes","price":1000,"priceMin":null,"priceMax":null,"priceLabel":"1 000 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Donne Smartlink ; avec interface compatible, permet le Verrouillage. Un Unsinkable ne peut pas bénéficier de cette liaison neuroassistée.","lore":"Le Smartlink est moins un viseur qu’un langage commun entre l’arme et l’équipement de ciblage de son porteur. Il transmet position, orientation et données de tir à une interface compatible, ce qui permet à plusieurs éléments techniques de fonctionner comme un ensemble plutôt que comme des accessoires indépendants.\n\nCette intégration explique pourquoi le Smartlink est particulièrement présent sur les gammes Phoenix et certains Raven modernes. Sans interface capable de recevoir la liaison, l’accessoire perd une grande partie de son intérêt ; un Unsinkable peut utiliser l’arme elle-même, mais pas la couche neuroassistée qui fait la spécificité du système.","data":{"Effet":"Donne Smartlink ; avec interface compatible, permet le Verrouillage. Un Unsinkable ne peut pas bénéficier de cette liaison neuroassistée."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'accessoires-d-armes-facecaster-dfl', 'FaceCaster DFL', NULL, '{"nature":"equipement","kind":"equipment","category":"Accessoires d''armes","sourceCategory":"Accessoires d''armes","price":750,"priceMin":null,"priceMax":null,"priceLabel":"750 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Projecteur porté. Seul : apparence de surface, vêtements/visage ; avec Holo''Rmor : simulation corps complet.","lore":"Le FaceCaster DFL est un projecteur porté qui falsifie l’apparence visible du visage et des vêtements plutôt que le corps lui-même. Il appartient à la même culture technique que les dispositifs holographiques de consommation, mais pousse leur précision vers l’infiltration, le spectacle ou la protection d’identité.\n\nEmployé seul, le DFL doit composer avec la silhouette réelle, le toucher, les capteurs non visuels et les erreurs de perspective. Couplé à une Holo’Rmor, il peut contribuer à un déguisement beaucoup plus complet ; même alors, il produit une apparence cohérente, jamais une transformation physique du porteur.","data":{"Effet":"Projecteur porté. Seul : apparence de surface, vêtements/visage ; avec Holo''Rmor : simulation corps complet."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-speciales-raven-flash', 'Raven Flash', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions spéciales","sourceCategory":"Munitions spéciales","price":null,"priceMin":null,"priceMax":null,"priceLabel":"x2 le prix normal / 20","generation":null,"charge":null,"stress":null,"slots":null,"effect":"À l''Altération, peut aveugler/éblouir une cible exposée pour son activation suivante si le vecteur visuel fonctionne.","lore":"La Raven Flash est une munition de contrôle qui transforme l''impact en agression visuelle plutôt qu''en simple supplément de puissance. Elle s''inscrit bien dans la logique Raven des outils d''intervention : neutraliser un avantage adverse, casser une réaction et ouvrir une fenêtre d''action sans prétendre remplacer une arme spécialisée.\n\nSon effet dépend toutefois d''une exposition visuelle réelle. Sur une Altération, elle peut aveugler ou éblouir la cible pour son activation suivante si le vecteur fonctionne ; un adversaire protégé de la lumière, privé de vision ou hors de l''effet pertinent ne subit pas artificiellement cette conséquence.","data":{"Effet actuel":"À l''Altération, peut aveugler/éblouir une cible exposée pour son activation suivante si le vecteur visuel fonctionne."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-speciales-raven-volto', 'Raven Volto', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions spéciales","sourceCategory":"Munitions spéciales","price":null,"priceMin":null,"priceMax":null,"priceLabel":"x3 / 10","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Munition électrique ; à l''Altération, peut provoquer immobilisation ou perte de passe future selon cible et fiction.","lore":"La Raven Volto est une munition électrique pensée pour faire de l''impact un outil de neutralisation momentanée. Plutôt que d''ajouter une seconde arme au paquetage, elle permet à une plateforme balistique compatible de menacer aussi la motricité, les muscles et certains systèmes sensibles à une décharge.\n\nL''électricité ne signifie pas immobilisation automatique. Sur une Altération, la Volto peut provoquer une immobilisation ou la perte d''une passe future lorsque la cible et la situation le permettent ; la conséquence reste liée à ce que la décharge peut réellement perturber.","data":{"Effet actuel":"Munition électrique ; à l''Altération, peut provoquer immobilisation ou perte de passe future selon cible et fiction."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-speciales-raven-drill', 'Raven Drill', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions spéciales","sourceCategory":"Munitions spéciales","price":null,"priceMin":null,"priceMax":null,"priceLabel":"x1 / 5","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Perforant 1.","lore":"La Raven Drill est la réponse la plus directe de la gamme aux protections matérielles : une munition construite pour privilégier la pénétration plutôt qu''un effet secondaire spectaculaire. Elle convient aux situations où le problème n''est pas de désorienter la cible mais de faire travailler le projectile à travers ce qui la protège.\n\nSon identité tient précisément à cette simplicité. La Drill apporte Perforant 1 et rien de plus : pas de décharge, pas de zone, pas de contrôle additionnel. C''est une cartouche spécialisée dont la valeur vient d''un comportement prévisible face aux protections.","data":{"Effet actuel":"Perforant 1."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-speciales-raven-night', 'Raven Night', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions spéciales","sourceCategory":"Munitions spéciales","price":null,"priceMin":null,"priceMax":null,"priceLabel":"x4 / 1","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+5 dégâts après le calcul normal des dégâts du tir ; ce +5 n''est jamais double. Tir unitaire uniquement ; incompatible Rafale/Suppression. Un échec narratif peut endommager ou désactiver sévèrement l''arme.","lore":"La Raven Night est une cartouche extrême de la gamme Raven, pensée pour un tir unique où l''arme et la munition sont poussées à leur limite. Elle sacrifie la souplesse d''emploi à un choc initial exceptionnel : ce n''est ni une munition de rafale ni une solution destinée à arroser une zone.\n\nAprès le calcul normal des dégâts du tir, la Night ajoute 5 dégâts qui ne sont jamais doublés. Elle s''emploie uniquement en tir unitaire et reste incompatible avec Rafale ou Suppression ; un échec narratif peut en outre endommager ou désactiver sévèrement l''arme, ce qui matérialise le prix technique de cette surcharge.","data":{"Effet actuel":"+5 dégâts après le calcul normal des dégâts du tir ; ce +5 n''est jamais double. Tir unitaire uniquement ; incompatible Rafale/Suppression. Un échec narratif peut endommager ou désactiver sévèrement l''arme."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-speciales-phoenix-pyro', 'Phoenix Pyro', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions spéciales","sourceCategory":"Munitions spéciales","price":null,"priceMin":null,"priceMax":null,"priceLabel":"x2 / 20","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Dégâts [Feu]. N''ajoute pas de DoT générique ; les conséquences de feu passent par Altération/environnement.","lore":"La Phoenix Pyro transpose dans une cartouche la fascination de Phoenix pour les effets énergétiques visibles et immédiatement exploitables. Le projectile ne cherche pas seulement à blesser : il apporte un vecteur de feu capable de faire entrer matériaux, vêtements, carburants ou décor combustible dans les conséquences de l''impact lorsque la scène s''y prête.\n\nLa Pyro inflige des dégâts de type Feu, mais n''ajoute pas un incendie continu automatique. Les brûlures persistantes, départs de feu ou embrasements restent des conséquences d''Altération et d''environnement ; la munition fournit le vecteur thermique, pas une règle universelle de dégâts dans le temps.","data":{"Effet actuel":"Dégâts [Feu]. N''ajoute pas de DoT générique ; les conséquences de feu passent par Altération/environnement."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-speciales-phoenix-hack', 'Phoenix Hack', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions spéciales","sourceCategory":"Munitions spéciales","price":null,"priceMin":null,"priceMax":null,"priceLabel":"x3 / 2","generation":null,"charge":null,"stress":null,"slots":null,"effect":"[Électricité]. À l''Altération contre cible connectée/augmentée : -3 Défense Neuro jusqu''à la fin de sa prochaine activation.","lore":"La Phoenix Hack vise les cibles dont le corps, l''armure ou l''équipement forment déjà une surface numérique attaquable. Sa charge électrique transforme le projectile en point d''entrée temporaire : l''intérêt n''est pas de pirater magiquement une cible à distance, mais de profiter d''un impact pour fragiliser une architecture connectée.\n\nElle inflige des dégâts d''Électricité. Sur une Altération contre une cible connectée ou augmentée, elle peut imposer -3 en Défense Neuro jusqu''à la fin de la prochaine activation de cette cible ; sans système pertinent à perturber, la munition ne crée pas artificiellement une vulnérabilité numérique.","data":{"Effet actuel":"[Électricité]. À l''Altération contre cible connectée/augmentée : -3 Défense Neuro jusqu''à la fin de sa prochaine activation."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-speciales-phoenix-blast', 'Phoenix Blast', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions spéciales","sourceCategory":"Munitions spéciales","price":null,"priceMin":null,"priceMax":null,"priceLabel":"x3 / 2","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Onde de choc ; à l''Altération, projection/renversement significatif.","lore":"La Phoenix Blast privilégie l''impulsion mécanique : l''impact libère une onde de choc conçue pour déplacer, déstabiliser ou casser un appui plutôt que pour ajouter une perforation classique. Elle est particulièrement utile lorsque faire perdre sa position à une cible compte davantage que simplement traverser sa protection.\n\nSur une Altération, la Blast peut provoquer une projection ou un renversement significatif si la masse de la cible, son appui et l''environnement rendent cette conséquence crédible. Elle n''ignore donc ni l''échelle ni la fiction : une onde de choc reste une force appliquée, pas une télékinésie garantie.","data":{"Effet actuel":"Onde de choc ; à l''Altération, projection/renversement significatif."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-speciales-owl-venom', 'Owl Venom', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions spéciales","sourceCategory":"Munitions spéciales","price":null,"priceMin":null,"priceMax":null,"priceLabel":"x2 / 10","generation":null,"charge":null,"stress":null,"slots":null,"effect":"DGT -3. Si au moins un projectile de la même action inflige 1 PV ou plus à une cible biologique : Vigueur + Constitution vs 15. Échec : +2 PV de poison ignorant l''Armure. Un seul test par action de tir.","lore":"L''Owl Venom est une munition biologique à effet retardé : le projectile accepte de perdre une part de son pouvoir d''impact pour déposer un toxique dans une blessure réelle. Cette logique correspond bien à Owl, qui multiplie les réponses spécialisées plutôt que de chercher systématiquement la plus grosse énergie à la bouche.\n\nLa cartouche subit -3 dégâts. Si au moins un projectile de la même action inflige 1 PV ou plus à une cible biologique, celle-ci teste Vigueur + Constitution contre 15 ; en cas d''échec, elle subit 2 PV de poison ignorant l''Armure. Un seul test est effectué par action de tir.","data":{"Effet actuel":"DGT -3. Si au moins un projectile de la même action inflige 1 PV ou plus à une cible biologique : Vigueur + Constitution vs 15. Échec : +2 PV de poison ignorant l''Armure. Un seul test par action de tir."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-speciales-owl-liquid', 'Owl Liquid', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions spéciales","sourceCategory":"Munitions spéciales","price":null,"priceMin":null,"priceMax":null,"priceLabel":"x4 / 2","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Projectile se liquéfiant dans la blessure ; peut créer une conséquence localisée persistante exigeant extraction/soin adapté.","lore":"L''Owl Liquid est une munition conçue pour compliquer la blessure elle-même. Après pénétration, le projectile se liquéfie et laisse dans les tissus une matière qui ne se traite pas comme un fragment balistique ordinaire ; sa dangerosité vient autant de ce qu''il reste dans la plaie que de l''impact initial.\n\nLorsqu''une Altération ou la fiction le justifie, cette présence peut créer une conséquence localisée persistante qui exige extraction ou soin adapté. La Liquid ne donne pas automatiquement une hémorragie ou un malus universel : elle fournit une complication médicale concrète que la blessure doit rendre pertinente.","data":{"Effet actuel":"Projectile se liquéfiant dans la blessure ; peut créer une conséquence localisée persistante exigeant extraction/soin adapté."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-speciales-owl-rust', 'Owl Rust', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions spéciales","sourceCategory":"Munitions spéciales","price":null,"priceMin":null,"priceMax":null,"priceLabel":"x4 / 1","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Munition électrique anti-cyber ; à l''Altération, peut désactiver une fonction augmentique accessible jusqu''à maintenance/fin d''effet.","lore":"L''Owl Rust est une munition anti-cyber destinée à transformer un impact électrique en panne ciblée. Plutôt que de chercher à neutraliser toute l''électronique environnante comme une impulsion large, elle exploite le contact avec une fonction augmentique accessible pour la perturber directement.\n\nLa Rust est une munition électrique. Sur une Altération, elle peut désactiver une fonction augmentique accessible jusqu''à maintenance ou fin de l''effet prévu ; elle ne permet pas de choisir arbitrairement un implant inaccessible à l''impact ni d''éteindre l''ensemble d''un organisme augmenté d''un seul coup.","data":{"Effet actuel":"Munition électrique anti-cyber ; à l''Altération, peut désactiver une fonction augmentique accessible jusqu''à maintenance/fin d''effet."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-lourdes-consommables-bande-bastion', 'Bande Bastion', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions lourdes & consommables","sourceCategory":"Munitions lourdes & consommables","price":250,"priceMin":null,"priceMax":null,"priceLabel":"250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Munition lourde conventionnelle.","lore":"La Bande Bastion est une alimentation lourde pensée pour accompagner une mitrailleuse d’appui pendant une vraie séquence de feu. Sa longueur, son conditionnement et son poids rappellent que l’autonomie d’une arme comme Bastion n’existe jamais gratuitement : quelqu’un doit transporter, protéger et présenter correctement les munitions.\n\nDans une équipe organisée, les bandes deviennent donc une ressource logistique presque aussi importante que l’arme. Les charger, les répartir entre porteurs et éviter leur contamination par poussière ou débris font partie du travail invisible qui sépare une mitrailleuse opérationnelle d’un gros morceau de métal inutilisable.","data":{"Quantite":"60 coups","Profil / effet":"Munition lourde conventionnelle."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-lourdes-consommables-charge-manticore', 'Charge Manticore', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions lourdes & consommables","sourceCategory":"Munitions lourdes & consommables","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Munition EMP lourde.","lore":"La Charge Manticore rassemble les munitions spécialisées nécessaires à l’arme lourde EMP du même nom. Leur fabrication privilégie la décharge et la perturbation de systèmes plutôt qu’un simple effet balistique, ce qui les rend plus coûteuses et plus dépendantes d’un stockage correct qu’une munition conventionnelle.\n\nUne équipe qui emporte Manticore choisit donc ses cibles avant même de choisir son nombre de charges : drones, capteurs, interfaces ou véhicules peuvent justifier ce consommable, là où une menace purement organique en exploite mal la valeur. La munition reste un outil ciblé, pas une cartouche universelle.","data":{"Quantite":"6 coups","Profil / effet":"Munition EMP lourde."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-lourdes-consommables-bande-hellstorm', 'Bande Hellstorm', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions lourdes & consommables","sourceCategory":"Munitions lourdes & consommables","price":650,"priceMin":null,"priceMax":null,"priceLabel":"650 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Alimentation haute cadence.","lore":"La Bande Hellstorm existe pour nourrir une arme dont la raison d’être est la cadence. Son volume et sa masse font immédiatement comprendre pourquoi une Gatling lourde ne se résume jamais au porteur : alimentation, transport et remplacement des bandes deviennent une petite chaîne logistique à eux seuls.\n\nLes équipes qui utilisent Hellstorm prévoient donc généralement plusieurs porteurs, un véhicule ou une position préparée. Une bande complète donne du temps de saturation ; plusieurs bandes changent le poids de la mission. Cette réalité matérielle est précisément ce qui empêche l’arme de devenir une source de feu illimitée.","data":{"Quantite":"200 coups","Profil / effet":"Alimentation haute cadence."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-lourdes-consommables-grenade-fragmentation-doorbell', 'Grenade fragmentation Doorbell', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions lourdes & consommables","sourceCategory":"Munitions lourdes & consommables","price":75,"priceMin":null,"priceMax":null,"priceLabel":"75 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"DGT 12, Zone 4 m.","lore":"La grenade à fragmentation Doorbell est la charge conventionnelle du lance-grenades lourd : une munition de zone destinée à saturer l''espace autour du point d''impact par des éclats. Elle donne au Doorbell sa fonction la plus directe d''appui, contre un groupe exposé ou une position que l''on ne peut pas traiter efficacement par un seul projectile.\n\nElle inflige 12 dégâts dans une zone de 4 mètres. Cette zone représente la dispersion dangereuse de la charge, pas la destruction automatique de tout ce qu''elle contient ; couvert, obstacles et circonstances continuent de déterminer ce que l''explosion peut réellement atteindre.","data":{"Quantite":"1","Profil / effet":"DGT 12, Zone 4 m."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-lourdes-consommables-grenade-emp-doorbell', 'Grenade EMP Doorbell', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions lourdes & consommables","sourceCategory":"Munitions lourdes & consommables","price":200,"priceMin":null,"priceMax":null,"priceLabel":"200 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"DGT 8, Zone 4 m, EMP.","lore":"La grenade EMP Doorbell remplace la fragmentation par une impulsion pensée pour saturer l''électronique dans une zone. Elle sert lorsque le lance-grenades doit traiter drones, capteurs, armures ou systèmes connectés sans confondre cette mission avec celle d''une charge purement antipersonnel.\n\nElle inflige 8 dégâts dans une zone de 4 mètres et applique l''effet EMP. Les équipements durcis ou protégés conservent leurs protections prévues, et l''impulsion ne devient pas une panne narrative illimitée : elle agit sur les systèmes réellement exposés à l''EMP.","data":{"Quantite":"1","Profil / effet":"DGT 8, Zone 4 m, EMP."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-lourdes-consommables-grenade-flash-doorbell', 'Grenade Flash Doorbell', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions lourdes & consommables","sourceCategory":"Munitions lourdes & consommables","price":150,"priceMin":null,"priceMax":null,"priceLabel":"150 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"DGT 3, Zone 5 m ; sur Altération, -3 aux tests surtout visuels jusqu''à la fin de la prochaine activation.","lore":"La grenade Flash Doorbell est une charge de contrôle de zone destinée à saturer brutalement la perception visuelle d''un secteur. Elle permet au lance-grenades de préparer une entrée, casser une ligne de tir ou désorganiser plusieurs personnes sans demander à la charge de produire les dégâts d''une fragmentation lourde.\n\nElle inflige 3 dégâts dans une zone de 5 mètres. Sur une Altération, les cibles réellement exposées peuvent subir -3 aux tests principalement visuels jusqu''à la fin de leur prochaine activation ; protections adaptées, absence de vision ou obstacle pertinent continuent de compter.","data":{"Quantite":"1","Profil / effet":"DGT 3, Zone 5 m ; sur Altération, -3 aux tests surtout visuels jusqu''à la fin de la prochaine activation."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-lourdes-consommables-grenade-fumigene-doorbell', 'Grenade fumigene Doorbell', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions lourdes & consommables","sourceCategory":"Munitions lourdes & consommables","price":100,"priceMin":null,"priceMax":null,"priceLabel":"100 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Zone 5 m ; écran opaque pour la vision ordinaire, sans couvert physique.","lore":"La grenade fumigène Doorbell transforme le lance-grenades en outil de masquage et de mouvement. Sa charge n''est pas destinée à vaincre une armure : elle crée rapidement un volume opaque qui coupe les lignes de vue ordinaires, protège une traversée ou oblige un adversaire à changer de position.\n\nLe nuage couvre une zone de 5 mètres et bloque la vision ordinaire, mais il ne constitue pas un couvert physique. Balles, éclats et personnes peuvent toujours traverser la fumée ; capteurs capables de travailler dans ce milieu restent pertinents selon leurs fonctions réelles.","data":{"Quantite":"1","Profil / effet":"Zone 5 m ; écran opaque pour la vision ordinaire, sans couvert physique."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-lourdes-consommables-roquette-breacher', 'Roquette Breacher', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions lourdes & consommables","sourceCategory":"Munitions lourdes & consommables","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"DGT 18, Perforant 2, Zone 3 m.","lore":"La Roquette Breacher est un projectile de brèche spécialisé, conçu pour concentrer une énergie importante sur une structure ou une position durcie. Son emballage, sa sécurité et son transport reflètent une munition que l’on ne manipule pas comme une boîte de cartouches de service ordinaires.\n\nChaque roquette représente un choix de mission : ouvrir ce point précis, neutraliser cette couverture ou frapper cette position. Les équipes compétentes résistent donc à la tentation de l’utiliser sur la première cible visible ; la valeur du Breacher vient autant du bon diagnostic du problème que de la violence du projectile.","data":{"Quantite":"1","Profil / effet":"DGT 18, Perforant 2, Zone 3 m."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-lourdes-consommables-missile-wasp', 'Missile Wasp', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions lourdes & consommables","sourceCategory":"Munitions lourdes & consommables","price":2500,"priceMin":null,"priceMax":null,"priceLabel":"2 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"DGT 20, Autoguide, Zone 4 m.","lore":"Le Missile Wasp est un consommable guidé qui embarque une part importante de la sophistication du système d’arme. Capteurs, guidage et charge doivent survivre au stockage puis fonctionner ensemble au moment du lancement, ce qui rend chaque projectile nettement plus précieux qu’une munition lourde purement balistique.\n\nCette valeur explique pourquoi les opérateurs sérieux préparent désignation et trajectoire avant le tir. Perdre un Wasp sur une cible mal identifiée coûte autant en capacité future qu’en argent ; le missile est donc traité comme une ressource d’appui rare, pas comme une roquette que l’on peut gaspiller pour intimider.","data":{"Quantite":"1","Profil / effet":"DGT 20, Autoguide, Zone 4 m."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-lourdes-consommables-munition-wallbreaker', 'Munition Wallbreaker', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions lourdes & consommables","sourceCategory":"Munitions lourdes & consommables","price":250,"priceMin":null,"priceMax":null,"priceLabel":"250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"DGT 16, Perforant 3.","lore":"La Munition Wallbreaker est un projectile anti-matériel conçu autour de la pénétration d’une cible dure. Sa place n’est pas dans les chargeurs d’infanterie ordinaire : elle accompagne une arme lourde dont le canon, la chambre et le tireur sont préparés à encaisser une munition destinée aux protections et aux structures.\n\nLes professionnels l’emploient lorsque la couverture elle-même fait partie de la cible. Cette spécialisation impose aussi de savoir ce qui se trouve derrière : une munition capable de traverser davantage de matière augmente la responsabilité du tireur autant que son efficacité contre une position fortifiée.","data":{"Quantite":"1","Profil / effet":"DGT 16, Perforant 3."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-lourdes-consommables-reservoir-salamander', 'Reservoir Salamander', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions lourdes & consommables","sourceCategory":"Munitions lourdes & consommables","price":150,"priceMin":null,"priceMax":null,"priceLabel":"150 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Projecteur [Feu].","lore":"Le Réservoir Salamander contient le consommable inflammable qui donne au projecteur son autonomie de terrain. Plus qu’une simple recharge, c’est un contenant pressurisé ou protégé que l’équipe doit transporter sans fuite, choc majeur ni exposition inutile à la chaleur.\n\nCette contrainte fait du porteur de Salamander quelqu’un que ses alliés protègent autant qu’ils exploitent sa puissance. Un réservoir de rechange augmente la durée d’emploi du projecteur, mais aussi la quantité de produit dangereux présente dans l’équipe ; stockage et sécurité deviennent donc une partie du choix tactique.","data":{"Quantite":"6 usages","Profil / effet":"Projecteur [Feu]."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-lourdes-consommables-reservoir-purifier', 'Reservoir Purifier', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions lourdes & consommables","sourceCategory":"Munitions lourdes & consommables","price":250,"priceMin":null,"priceMax":null,"priceLabel":"250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Projecteur [Chimique].","lore":"Le Réservoir Purifier contient l’agent chimique utilisé par le projecteur lourd du même nom. Le conditionnement doit rester compatible avec un produit suffisamment agressif pour corroder ou contaminer, ce qui fait de la recharge un matériel technique plutôt qu’un simple bidon interchangeable.\n\nTransport, étanchéité et procédure de remplacement comptent autant que le contenu. Les équipes qui travaillent avec Purifier traitent ses réservoirs comme des produits dangereux : une fuite dans un véhicule ou une planque peut créer un incident bien avant que l’arme ne soit utilisée contre qui que ce soit.","data":{"Quantite":"5 usages","Profil / effet":"Projecteur [Chimique]."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-basiques-raven-black-feathers', 'Raven Black Feathers', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Basiques","sourceCategory":"Armures — Basiques","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Gilet fin, dissimulable.","lore":"Le Raven Black Feathers est la réponse discrète de Raven au besoin de porter une protection sans ressembler immédiatement à un agent d’intervention. Sa coupe fine et dissimulable suggère un gilet pensé pour disparaître sous une veste, un manteau ou une tenue de ville, au prix d’une couverture moins massive que les équipements de combat de la marque.\n\nIl convient naturellement aux gardes rapprochés, enquêteurs, cadres exposés ou criminels qui préfèrent ne pas annoncer qu’ils sont protégés. La philosophie reste très Raven : une pièce sobre, utilitaire et suffisamment robuste pour être portée longtemps, mais dont l’intérêt principal est précisément de ne pas transformer son porteur en silhouette militaire.","data":{"Protection":"Balistique 1 (Ablatif 4)","Notes":"Gilet fin, dissimulable."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-basiques-owl-bullets-fear', 'Owl Bullets Fear', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Basiques","sourceCategory":"Armures — Basiques","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Gilet epais.","lore":"L’Owl Bullets Fear assume au contraire l’épaisseur d’un véritable gilet de protection. Son volume le rend difficile à confondre avec un vêtement ordinaire : c’est le genre d’équipement que l’on enfile parce qu’on s’attend raisonnablement à recevoir des coups ou des tirs, pas parce qu’on veut conserver une silhouette élégante.\n\nCette franchise correspond bien au positionnement pragmatique d’Owl : davantage de matière protectrice, une construction simple à comprendre et peu d’efforts consacrés à la dissimulation. On l’imagine facilement chez des vigiles, des équipes de sécurité modestes ou des professionnels qui privilégient la protection visible au confort d’un gilet fin.","data":{"Protection":"Balistique 2 (Ablatif 2)","Notes":"Gilet epais."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-basiques-phoenix-sun-shield', 'Phoenix Sun Shield', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Basiques","sourceCategory":"Armures — Basiques","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Anti-tranchant léger.","lore":"Le Phoenix Sun Shield est une protection légère destinée aux violences de proximité, en particulier aux coupures et aux attaques tranchantes. Plutôt qu’un gilet épais, il s’inscrit dans la logique Phoenix d’une protection moderne intégrée à une tenue relativement mobile, adaptée à quelqu’un qui doit rester présentable ou actif en environnement urbain.\n\nSon nom et sa place dans la gamme suggèrent une pièce pensée autant pour être portée au quotidien que pour rassurer son utilisateur face aux agressions ordinaires. Il ne cherche pas à imiter une armure militaire : c’est une couche de sécurité légère pour agents, personnels exposés ou citadins fortunés qui veulent conserver leur mobilité.","data":{"Protection":"Melee 1 (Ablatif 4)","Notes":"Anti-tranchant léger."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-basiques-byron-punk-life', 'Byron Punk Life', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Basiques","sourceCategory":"Armures — Basiques","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Voyant, style neopunk.","lore":"Le Byron Punk Life ne tente pas de cacher ce qu’il est. Sa protection est intégrée à une tenue volontairement voyante qui reprend les codes Neopunk : pièces renforcées, silhouette agressive, éléments graphiques et goût assumé pour un vêtement qui sert autant à afficher une appartenance culturelle qu’à encaisser la brutalité de la rue.\n\nChez Byron, la fonction ne gomme donc pas le style. Le Punk Life peut convenir à un musicien, un Crawler, un habitué des clubs ou simplement à quelqu’un qui veut porter sa protection comme une déclaration publique. Cette visibilité a évidemment une contrepartie sociale : là où un Black Feathers se cache, le Punk Life annonce immédiatement une attitude et un milieu.","data":{"Protection":"Melee 1 (Ablatif 4), Antichoc 1","Notes":"Voyant, style neopunk."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-basiques-raven-black-dog', 'Raven Black Dog', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Basiques","sourceCategory":"Armures — Basiques","price":1000,"priceMin":null,"priceMax":null,"priceLabel":"1 000 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Tenue de sécurité/police.","lore":"Le Raven Black Dog est une tenue de sécurité ou de police conçue pour être identifiée comme telle. Elle appartient à la partie institutionnelle de la gamme Raven : protection répartie sur une tenue complète, emplacement prévu pour l’équipement de service et silhouette suffisamment standardisée pour fonctionner au sein d’une équipe plutôt que comme pièce individuelle de mode.\n\nSon apparence participe autant à son rôle que sa résistance. Dans un hall, une manifestation ou un contrôle, le Black Dog signale immédiatement qu’une autorité ou un service de sécurité est présent. Il est donc courant d’imaginer des variantes de marquage selon l’employeur, mais la base reste celle d’un uniforme opérationnel robuste plutôt que d’une armure clandestine.","data":{"Protection":"Balistique 3, Melee 2, Antichoc 2","Notes":"Tenue de sécurité/police."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-basiques-phoenix-silver-knight', 'Phoenix Silver Knight', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Basiques","sourceCategory":"Armures — Basiques","price":1000,"priceMin":null,"priceMax":null,"priceLabel":"1 000 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Tenue renforcée.","lore":"Le Phoenix Silver Knight est une tenue renforcée qui monte clairement en gamme par rapport au Sun Shield. Le nom évoque une protection plus assumée et une finition plus valorisante : une armure urbaine capable d’être montrée, avec une silhouette propre et technologique qui convient mieux à une sécurité privée haut de gamme qu’à un simple gilet porté sous les vêtements.\n\nOn peut facilement l’associer aux gardes de cadres, aux équipes corporatistes ou aux professionnels qui doivent combiner protection et image de marque. Phoenix ne cherche pas seulement à arrêter un coup : la gamme donne l’impression d’un équipement récent, entretenu et coûteux, suffisamment élégant pour accompagner une présence officielle ou prestigieuse.","data":{"Protection":"Balistique 2, Melee 3, Antichoc 2","Notes":"Tenue renforcée."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-basiques-owl-new-guard', 'Owl New Guard', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Basiques","sourceCategory":"Armures — Basiques","price":850,"priceMin":null,"priceMax":null,"priceLabel":"850 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Protection polyvalente.","lore":"L’Owl New Guard est une protection polyvalente destinée à ceux qui ne savent pas exactement quelle forme prendra le prochain problème. Elle n’affiche ni la discrétion d’un gilet caché ni la spécialisation d’une armure technique : sa vocation est d’offrir une base protectrice crédible pour du gardiennage, de l’escorte ou du travail armé régulier.\n\nCette absence d’exotisme constitue précisément son intérêt. Owl peut la vendre à des sociétés de sécurité, des indépendants ou des mercenaires qui veulent un équipement facile à comprendre, à entretenir et à compléter. Le New Guard ressemble moins à un prototype spectaculaire qu’à une tenue que l’on peut réellement voir portée chaque jour par des professionnels.","data":{"Protection":"Balistique 2, Melee 2, Antichoc 2","Notes":"Protection polyvalente."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-basiques-byron-king-worker-vii', 'Byron King Worker VII', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Basiques","sourceCategory":"Armures — Basiques","price":750,"priceMin":null,"priceMax":null,"priceLabel":"750 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Harnais de chantier ; compatible outils/augmentations industrielles.","lore":"Le Byron King Worker VII est moins une armure de guerre qu’un harnais industriel renforcé. Il est conçu pour vivre au milieu des outils, charges, câbles et augmentations professionnelles : points d’accroche, renforts aux zones exposées et structure compatible avec l’équipement que portent déjà les ouvriers du bâtiment ou de la maintenance lourde.\n\nLa septième génération suggère un produit anciennement installé dans les usages plutôt qu’une nouveauté de vitrine. Sur un chantier, le King Worker peut se couvrir de poches, d’attaches et de modules personnels jusqu’à devenir presque méconnaissable ; sa valeur vient justement de cette capacité à rester un vêtement de travail protecteur autour d’un corps parfois fortement augmenté.","data":{"Protection":"Antichoc 4","Notes":"Harnais de chantier ; compatible outils/augmentations industrielles."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-combat-raven-gallowglass-ii-legere', 'Raven Gallowglass II légère', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Combat","sourceCategory":"Armures — Combat","price":1450,"priceMin":null,"priceMax":null,"priceLabel":"1 450 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Anti-EMP","lore":"La Raven Gallowglass II légère appartient déjà au monde des véritables armures de combat. Sa version allégée cherche à conserver une mobilité acceptable pour l’infanterie, la sécurité lourde ou les équipes d’intervention tout en intégrant la résistance aux perturbations EMP caractéristique de cette famille Raven.\n\nLe nom Gallowglass renvoie à une gamme faite pour les utilisateurs qui doivent continuer leur mission au milieu d’équipements électroniques endommagés ou d’attaques contre les systèmes. Plutôt qu’une armure de parade, c’est une tenue opérationnelle modulable que l’on imagine marquée, réparée et personnalisée au fil des déploiements.","data":{"Bal.":"Balistique 5","Mel.":"Melee 3","Ant.":"Antichoc 4","Notes":"Anti-EMP"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-combat-phoenix-skylord-iii', 'Phoenix Skylord III', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Combat","sourceCategory":"Armures — Combat","price":1450,"priceMin":null,"priceMax":null,"priceLabel":"1 450 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Protection thermique reactive en pugilat selon fiction","lore":"La Phoenix Skylord III est une armure de combat dont la protection thermique réactive révèle une approche plus technologique que purement passive. Ses couches protectrices sont pensées pour gérer brutalement la chaleur au contact et dans les affrontements rapprochés, ce qui donne à la tenue une identité très différente d’un simple empilement de plaques.\n\nUne troisième génération suggère une technologie déjà affinée par plusieurs itérations. La Skylord convient à des opérateurs mobiles qui acceptent une maintenance plus exigeante en échange d’une armure capable de participer activement à la gestion des agressions thermiques ; elle a donc davantage sa place chez des unités bien financées que dans un vestiaire de sécurité ordinaire.","data":{"Bal.":"Balistique 4","Mel.":"Melee 4","Ant.":"Antichoc 4","Notes":"Protection thermique reactive en pugilat selon fiction"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-combat-owl-night-guard', 'Owl Night Guard', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Combat","sourceCategory":"Armures — Combat","price":1450,"priceMin":null,"priceMax":null,"priceLabel":"1 450 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Faible signature en obscurite","lore":"L’Owl Night Guard est une armure de combat pensée pour être moins facile à distinguer dans l’obscurité. Plutôt que de promettre une invisibilité technologique, elle travaille vraisemblablement sur la silhouette, les surfaces mates, la suppression des reflets et les détails visibles qui trahissent normalement un porteur sous un éclairage faible.\n\nCette sobriété en fait une tenue crédible pour surveillance nocturne, patrouilles discrètes ou embuscades urbaines. Sa faible signature reste liée aux conditions sombres : sous un projecteur, en plein jour ou face à un capteur qui ne dépend pas simplement de la vision ordinaire, le Night Guard redevient une armure identifiable.","data":{"Bal.":"Balistique 3","Mel.":"Melee 6","Ant.":"Antichoc 3","Notes":"Faible signature en obscurite"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-combat-raven-gallowglass-ii-lourde', 'Raven Gallowglass II lourde', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Combat","sourceCategory":"Armures — Combat","price":5500,"priceMin":null,"priceMax":null,"priceLabel":"5 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Anti-EMP ; militaire lourd","lore":"La Raven Gallowglass II lourde pousse la même philosophie que la version légère vers la protection militaire assumée. Plus massive, elle se destine aux brèches, aux positions exposées et aux opérateurs pour lesquels encaisser compte davantage que se fondre dans la circulation d’une rue ; sa résistance EMP protège en outre l’électronique de la tenue contre une menace devenue banale sur un champ de bataille moderne.\n\nUne telle armure n’est pas discrète et ne prétend pas l’être. Elle évoque les unités tactiques, les mercenaires bien équipés et les forces corporatistes capables de supporter son coût logistique. Chez Raven, la lourdeur devient ici un choix doctrinal : continuer à avancer quand l’environnement devient hostile plutôt que miser sur l’élégance ou la furtivité.","data":{"Bal.":"Balistique 9","Mel.":"Melee 4","Ant.":"Antichoc 6","Notes":"Anti-EMP ; militaire lourd"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-combat-phoenix-sun-king', 'Phoenix Sun King', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Combat","sourceCategory":"Armures — Combat","price":5000,"priceMin":null,"priceMax":null,"priceLabel":"5 000 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Protection thermique reactive","lore":"Le Phoenix Sun King représente le versant lourd et prestigieux de la protection thermique réactive de la marque. Là où les modèles plus légers cherchent à préserver la mobilité, le Sun King donne l’image d’une armure qui accepte une présence beaucoup plus imposante pour entourer son porteur d’une enveloppe protectrice sophistiquée.\n\nSon nom de gamme n’a rien de discret : cette armure est faite pour être reconnue comme un équipement haut de gamme. On l’imagine chez des unités corporatistes, des gardes d’élite ou des opérateurs spécialisés qui disposent de l’entretien nécessaire à ses systèmes thermiques, et pour lesquels l’effet psychologique d’une silhouette lourdement équipée n’est pas un défaut.","data":{"Bal.":"Balistique 5","Mel.":"Melee 5","Ant.":"Antichoc 5","Notes":"Protection thermique reactive"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-combat-owl-moon-guard', 'Owl Moon Guard', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Combat","sourceCategory":"Armures — Combat","price":4550,"priceMin":null,"priceMax":null,"priceLabel":"4 550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Faible signature en obscurite","lore":"L’Owl Moon Guard prolonge la logique du Night Guard avec une protection plus ambitieuse destinée aux opérations menées dans l’obscurité. Les surfaces et volumes sont pensés pour casser la lecture de la silhouette et limiter les détails qui accrochent la lumière, afin qu’une armure complète reste moins évidente à repérer lors d’une progression nocturne.\n\nCette spécialisation en fait naturellement une tenue de patrouille discrète, de chasse ou d’intervention après extinction des lumières. Elle ne doit pas être confondue avec un camouflage universel : l’avantage disparaît dès que l’environnement ou les moyens de détection ne reposent plus sur la faible luminosité qui fonde toute la conception Moon Guard.","data":{"Bal.":"Balistique 4","Mel.":"Melee 7","Ant.":"Antichoc 4","Notes":"Faible signature en obscurite"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-specialisees-bridgeelectrics-no-fire', 'BridgeElectrics No-Fire', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Spécialisées","sourceCategory":"Armures — Spécialisées","price":1000,"priceMin":null,"priceMax":null,"priceLabel":"1 000 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Tenue pompier/technicien, chaleur et électricité.","lore":"La BridgeElectrics No-Fire est une tenue professionnelle pour pompiers, techniciens de réseau et intervenants qui travaillent là où chaleur et électricité se combinent dangereusement. Elle privilégie l’isolation, la fermeture des zones exposées et la possibilité de manipuler du matériel technique sans transformer son porteur en soldat lourd.\n\nSa place dans un catalogue de protections vient du fait que l’industrie moderne est elle-même un environnement hostile. Arc électrique, incendie de batteries, câbles sous tension ou locaux techniques surchauffés justifient un équipement dédié ; le No-Fire appartient donc autant aux casernes et équipes de maintenance qu’aux situations de crise.","data":{"Profil":"Bal.1 / Mel.1 / Ant.3 ; Réduction 3 [Feu/Électricité]","Fonction":"Tenue pompier/technicien, chaleur et électricité."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-specialisees-ocean-master-free-fly', 'Ocean Master Free Fly', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Spécialisées","sourceCategory":"Armures — Spécialisées","price":1500,"priceMin":null,"priceMax":null,"priceLabel":"1 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Respirateur/compensateur G ; circonstances favorables (+3) contre désorientation, vent violent ou perte d''équilibre liée au vol.","lore":"L’Ocean Master Free Fly est une tenue spécialisée pour les situations où le corps cesse de pouvoir compter sur un environnement stable : vol, fortes accélérations, vents violents ou travail en hauteur. Respirateur, maintien du corps et compensation des contraintes d’accélération en font davantage un équipement de pilote ou de sauveteur aérien qu’une armure de fantassin.\n\nSa protection prend surtout la forme d’une meilleure tolérance aux conditions qui désorientent normalement un humain. Harnais, maintien et assistance respiratoire permettent de conserver plus facilement ses repères lorsqu’un véhicule bouge brutalement ou que l’air devient difficile à exploiter ; la tenue ne rend évidemment pas son porteur indépendant de tout appareil de vol.","data":{"Profil":"Antichoc 1","Fonction":"Respirateur/compensateur G ; circonstances favorables (+3) contre désorientation, vent violent ou perte d''équilibre liée au vol."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-specialisees-icecorps-santa-clothes', 'Icecorps Santa Clothes', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Spécialisées","sourceCategory":"Armures — Spécialisées","price":900,"priceMin":null,"priceMax":null,"priceLabel":"900 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Très épaisse ; peut être défavorable pour actions demandant finesse/mobilité.","lore":"L’Icecorps Santa Clothes est une tenue de froid extrême dont le surnom presque jovial masque un équipement très épais. Elle est faite pour les personnels qui passent de longues périodes dans des environnements glacés : logistique polaire, maintenance extérieure, recherche ou exploitation de sites où une veste urbaine isolante ne suffit plus.\n\nToute cette matière a un prix ergonomique. Les couches isolantes, gants, capuche et protections périphériques transforment le porteur en silhouette volumineuse et peuvent gêner les gestes fins ou la mobilité lorsqu’ils deviennent prioritaires. C’est une tenue que l’on accepte parce que le froid constitue le danger principal, pas parce qu’elle est agréable à porter partout.","data":{"Profil":"Mel.2 / Ant.4 ; Réduction 3 [Froid]","Fonction":"Très épaisse ; peut être défavorable pour actions demandant finesse/mobilité."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-specialisees-biosun-medicarmor', 'BioSun MedicArmor', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Spécialisées","sourceCategory":"Armures — Spécialisées","price":1500,"priceMin":null,"priceMax":null,"priceLabel":"1 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Permet de travailler dans environnement chimique/viral ordinaire ; une perforation grave peut rompre l''étanchéité.","lore":"La Biosun Medicarmor est une tenue médicale étanche destinée aux environnements contaminés ordinaires : intervention biologique, chimique ou sanitaire là où le soignant doit s’approcher du patient sans partager immédiatement son exposition. Sa conception associe donc protection du corps, surface décontaminable et liberté suffisante pour continuer à examiner ou manipuler du matériel médical.\n\nL’étanchéité reste celle d’une combinaison portée sur le terrain, pas celle d’un bunker. Une perforation sévère peut rompre la barrière protectrice et transformer un vêtement intact en équipement compromis ; les équipes qui l’utilisent ont donc de bonnes raisons de contrôler l’état de la tenue après chaque intervention et de traiter une déchirure comme un incident sérieux.","data":{"Profil":"Étanche ; filtres ; protection contamination","Fonction":"Permet de travailler dans environnement chimique/viral ordinaire ; une perforation grave peut rompre l''étanchéité."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-specialisees-sunways-desert-survivor', 'Sunways Desert Survivor', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Spécialisées","sourceCategory":"Armures — Spécialisées","price":2500,"priceMin":null,"priceMax":null,"priceLabel":"2 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Recyclage fluides, charge solaire lente, signature thermique reduite, survie desertique.","lore":"La Sunways Desert Survivor est une combinaison d’autonomie pensée pour les zones arides où la chaleur et l’eau comptent davantage que les tirs. Recyclage des fluides, recharge solaire lente et réduction de la signature thermique répondent à la même logique : prolonger le temps pendant lequel un opérateur peut rester loin d’une infrastructure confortable.\n\nOn l’imagine sur les équipes de prospection, de maintenance énergétique, les convoyeurs ou les expéditions qui doivent traverser des secteurs désertiques. Sa technologie ne crée pas des ressources à partir de rien : elle économise, recycle et récupère lentement ce que l’environnement offre, ce qui en fait une assurance de survie plutôt qu’une autonomie illimitée.","data":{"Profil":"Mel.2 / Ant.2 ; Réduction 3 [Chaud/Froid]","Fonction":"Recyclage fluides, charge solaire lente, signature thermique reduite, survie desertique."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-specialisees-seawares-scaph-iv', 'Seawares Scaph IV', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Spécialisées","sourceCategory":"Armures — Spécialisées","price":3500,"priceMin":null,"priceMax":null,"priceLabel":"3 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Étanche, air, isolation ; très encombrant et défavorable hors milieu adapté.","lore":"Le SeaWares Scaph IV est un scaphandre fermé conçu autour de trois priorités : conserver une atmosphère respirable, isoler le porteur et maintenir une enveloppe étanche dans un environnement où l’extérieur n’est pas directement supportable. Il appartient clairement au matériel professionnel de plongée, d’inspection et d’intervention plutôt qu’à l’équipement quotidien.\n\nCette fermeture explique aussi son encombrement. Hors de l’eau ou du milieu pour lequel il est préparé, le Scaph IV devient une tenue lourde et maladroite dont les articulations, réserves et épaisseurs gênent les gestes ordinaires. Son excellente utilité spécialisée vient précisément de compromis qui le rendent peu désirable comme armure généraliste.","data":{"Profil":"Bal.4 / Mel.4 / Ant.4 (6 sous l''eau)","Fonction":"Étanche, air, isolation ; très encombrant et défavorable hors milieu adapté."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-specialisees-arcanetwork-neuromaster', 'ArcaNetwork Neuromaster', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Spécialisées","sourceCategory":"Armures — Spécialisées","price":3550,"priceMin":null,"priceMax":null,"priceLabel":"3 550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Permet l''immersion profonde ; réduit de 3 les pertes de PV neuronales. Aucun bonus de Rang, slots ou PA. Un Unsinkable ne peut pas utiliser son mode d''immersion.","lore":"L’ArcaNetwork Neuromaster est une protection conçue pour le Neurodive profond plutôt que pour arrêter des balles. Autour du Neurodiver, elle forme un environnement d’immersion : interfaces, maintien et sécurité neuronale travaillent ensemble pour limiter les dommages qu’une session violente peut infliger au système nerveux pendant que le corps reste physiquement vulnérable dans le monde réel.\n\nLe nom peut donner l’impression d’un équipement qui rend meilleur dans la Matrice, mais ce n’est pas sa fonction. Le Neuromaster ne fournit ni Rang, ni emplacement supplémentaire, ni action de plus ; il protège seulement mieux l’utilisateur pendant l’immersion compatible. Un Unsinkable peut manipuler l’équipement comme du matériel ordinaire, mais ne peut pas exploiter le mode d’immersion neuronale qui en constitue le cœur.","data":{"Profil":"Réduction 3 [Neuro] ; interface Neurodive complète","Fonction":"Permet l''immersion profonde ; réduit de 3 les pertes de PV neuronales. Aucun bonus de Rang, slots ou PA. Un Unsinkable ne peut pas utiliser son mode d''immersion."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-camouflage-byron-ghillie-basic', 'Byron Ghillie Basic', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Camouflage","sourceCategory":"Armures — Camouflage","price":550,"priceMin":null,"priceMax":null,"priceLabel":"550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Visuel/textile.","lore":"Le Byron Ghillie Basic applique une solution volontairement ancienne à un monde saturé d’électronique : casser la silhouette avec du textile, des volumes irréguliers et des éléments adaptés au terrain. Il ne cherche pas à tromper un réseau de capteurs sophistiqués, seulement à rendre un humain beaucoup moins évident pour un observateur qui regarde réellement le décor.\n\nSon intérêt est aussi logistique. Une ghillie textile peut être salie, retaillée, complétée avec des matériaux locaux et réparée sans atelier spécialisé ; chasseurs, tireurs embusqués et éclaireurs peuvent donc l’adapter au terrain. Le revers est évident : une mauvaise préparation ou un changement d’environnement peut transformer le camouflage en masse parfaitement reconnaissable.","data":{"Profil":"Camo 1","Notes":"Visuel/textile."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-camouflage-raven-squid-skin', 'Raven Squid Skin', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Camouflage","sourceCategory":"Armures — Camouflage","price":4950,"priceMin":null,"priceMax":null,"priceLabel":"4 950 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Réflexion visuelle active ; dépend du contraste.","lore":"La Raven Squid Skin remplace la simple dissimulation textile par une surface active capable de réfléchir et réorganiser visuellement ce qui l’entoure. Le nom évoque naturellement la peau changeante d’un céphalopode : l’armure cherche moins à devenir transparente qu’à rendre ses contours et ses couleurs difficiles à séparer du fond immédiat.\n\nCe principe explique sa dépendance au contraste et aux conditions. Un décor très homogène lui facilite la tâche ; une lumière brutale, un mouvement évident ou un arrière-plan qu’elle reproduit mal peuvent au contraire révéler le porteur. Raven en fait donc un outil d’approche et de dissimulation visuelle, pas une cape d’invisibilité absolue.","data":{"Profil":"Melee 1, Antichoc 1, Camo 2","Notes":"Réflexion visuelle active ; dépend du contraste."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-camouflage-phoenix-dirty-sniper', 'Phoenix Dirty Sniper', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Camouflage","sourceCategory":"Armures — Camouflage","price":4550,"priceMin":null,"priceMax":null,"priceLabel":"4 550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Texture adaptative ; profil visuel/thermique selon environnement.","lore":"La Phoenix Dirty Sniper est une tenue de tireur embusqué qui combine adaptation de texture et travail sur le profil visuel ou thermique selon l’environnement. Plutôt que de miser sur une seule couleur de camouflage, elle cherche à maintenir une signature cohérente avec le poste de tir préparé autour d’elle.\n\nLe qualificatif Dirty résume assez bien sa philosophie : cette technologie n’est réellement efficace qu’intégrée au terrain, couverte de poussière, de végétation ou des irrégularités du lieu. Un sniper qui change brutalement de décor emporte avec lui une tenue sophistiquée, mais pas automatiquement le contexte auquel elle était en train de s’accorder.","data":{"Profil":"Melee 2, Antichoc 2, Camo 2","Notes":"Texture adaptative ; profil visuel/thermique selon environnement."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-camouflage-owl-zero-guard', 'Owl Zero Guard', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Camouflage","sourceCategory":"Armures — Camouflage","price":3550,"priceMin":null,"priceMax":null,"priceLabel":"3 550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Brouillage électronique ; moins efficace contre capteurs biologiques directs.","lore":"L’Owl Zero Guard attaque la détection par un autre angle : le brouillage électronique. Plutôt que de modifier seulement l’apparence du porteur, la tenue cherche à compliquer le travail des capteurs et systèmes qui s’appuient sur une lecture électronique de leur environnement, ce qui la destine naturellement aux infiltrations dans des sites fortement instrumentés.\n\nCette spécialisation laisse une faiblesse logique aux moyens qui ne dépendent pas de la même chaîne de détection. Un regard humain, un animal, certains sens biologiques ou un capteur directement adapté à une signature que la tenue ne brouille pas peuvent encore repérer le porteur. Le Zero Guard est donc un outil contre les réseaux de surveillance, pas une disparition physique.","data":{"Profil":"Camo 1, Electro-trompeur","Notes":"Brouillage électronique ; moins efficace contre capteurs biologiques directs."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-camouflage-arcanetwork-holo-rmor-v2', 'ArcaNetwork Holo''Rmor V2', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Camouflage","sourceCategory":"Armures — Camouflage","price":3550,"priceMin":null,"priceMax":null,"priceLabel":"3 550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Holo-tissage identitaire, pas de Camo générique.","lore":"L’ArcaNetwork Holo’Rmor V2 utilise une trame holographique pour travailler sur l’identité visible du porteur plutôt que sur une invisibilité générique. Sa surface peut donner à une silhouette une autre lecture vestimentaire ou visuelle, suffisamment crédible pour brouiller une reconnaissance rapide lorsque les conditions permettent à l’holographie de tenir.\n\nCette fonction explique pourquoi la Holo’Rmor appartient davantage au déguisement technologique qu’au camouflage classique. Elle peut aider quelqu’un à paraître différent, à masquer certains détails ou à présenter une autre tenue, mais elle ne supprime ni la masse du corps ni les autres signatures physiques qu’un observateur ou un système attentif peut contrôler.","data":{"Profil":"Melee 1, Antichoc 2","Notes":"Holo-tissage identitaire, pas de Camo générique."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armures-camouflage-sba-ninja', 'SBA Ninja', NULL, '{"nature":"equipement","kind":"equipment","category":"Armures — Camouflage","sourceCategory":"Armures — Camouflage","price":6500,"priceMin":null,"priceMax":null,"priceLabel":"6 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Mode spectral haut de gamme ; Camo 3 ne bloque pas un radar/senseur que la combinaison ne masque pas.","lore":"La SBA Ninja est une tenue de camouflage haut de gamme destinée aux opérations où plusieurs bandes du spectre doivent être prises en compte simultanément. Son nom commercial assume l’imaginaire d’infiltration : surfaces, gestion des émissions et systèmes actifs cherchent ensemble à rendre un opérateur beaucoup plus difficile à isoler dans un environnement préparé.\n\nMême à ce niveau, la furtivité reste une discipline et non un pouvoir magique. Le mode spectral ne bloque pas automatiquement un radar ou un capteur dont la signature n’est pas réellement masquée par la tenue, et les déplacements, traces ou erreurs du porteur continuent d’exister. La Ninja réduit fortement certaines voies de détection ; elle ne garantit jamais qu’aucun système ne puisse voir.","data":{"Profil":"Camo 3","Notes":"Mode spectral haut de gamme ; Camo 3 ne bloque pas un radar/senseur que la combinaison ne masque pas."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'modules-d-armure-renfort-balistique', 'Renfort balistique', NULL, '{"nature":"equipement","kind":"equipment","category":"Modules d''armure","sourceCategory":"Modules d''armure","price":1000,"priceMin":null,"priceMax":null,"priceLabel":"1 000 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+1 contre Tir.","lore":"Le renfort balistique ajoute à une armure des couches ou inserts destinés spécifiquement aux projectiles : fibres supplémentaires, plaques locales ou panneaux interchangeables selon la structure de départ. C''est un retrofit courant pour une tenue qui doit rester en service tout en étant adaptée à un environnement où les armes à feu deviennent une menace plus probable.\n\nLe module augmente de +1 la protection contre le Tir, sans transformer pour autant toute l''armure en modèle lourd. Son intérêt tient à cette spécialisation : on renforce les zones les plus exposées aux impacts balistiques, mais le même ajout n''est pas automatiquement une meilleure réponse aux coups de mêlée ou aux autres formes de dommage.","data":{"Slots":"1 slot","Effet":"+1 contre Tir."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'modules-d-armure-renfort-melee', 'Renfort melee', NULL, '{"nature":"equipement","kind":"equipment","category":"Modules d''armure","sourceCategory":"Modules d''armure","price":600,"priceMin":null,"priceMax":null,"priceLabel":"600 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+1 contre Melee.","lore":"Le renfort mêlée protège les parties d''une tenue qui souffrent particulièrement dans un corps-à-corps : avant-bras, épaules, flancs, articulations et zones où une lame ou une arme contondante peut trouver prise. Sur une armure de sécurité ou d''intervention, ces pièces donnent souvent une silhouette plus segmentée et plus apte à encaisser les contacts rapprochés.\n\nIl apporte +1 de protection contre la Mêlée et reste volontairement spécialisé. Les matériaux, formes et zones renforcées sont choisis pour dévier, amortir ou répartir un coup porté à courte distance ; cela ne lui confère pas par défaut l''efficacité d''un renfort balistique contre un projectile lancé à grande vitesse.","data":{"Slots":"1","Effet":"+1 contre Melee."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'modules-d-armure-renfort-antichoc', 'Renfort antichoc', NULL, '{"nature":"equipement","kind":"equipment","category":"Modules d''armure","sourceCategory":"Modules d''armure","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+1 contre Antichoc.","lore":"Le renfort antichoc travaille moins sur la pénétration que sur la manière dont une violence brutale se transmet au corps. Mousses techniques, structures déformables et couches de répartition peuvent être placées sous les parties rigides de l''armure afin d''éviter qu''un choc, une chute ou un impact contondant concentre toute son énergie au même endroit.\n\nLe module fournit +1 de protection contre l''Antichoc. On le retrouve logiquement sur du matériel d''intervention, de maintien de l''ordre, de travail en hauteur ou toute tenue destinée à subir des collisions ; sa fonction n''est pas de rendre l''armure universellement plus résistante, mais de mieux gérer cette famille précise de traumatismes.","data":{"Slots":"1","Effet":"+1 contre Antichoc."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'modules-d-armure-plaques-ablatives', 'Plaques ablatives', NULL, '{"nature":"equipement","kind":"equipment","category":"Modules d''armure","sourceCategory":"Modules d''armure","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $ / recharge 250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Ablatif 2 : +1 protection sur les 2 premiers impacts applicables.","lore":"Les plaques ablatives sont des éléments sacrificiels montés à l''extérieur d''une armure pour prendre les premiers impacts à la place de la structure principale. Leur apparence peut aller de petits carreaux superposés à de larges panneaux remplaçables, mais leur logique reste la même : accepter d''être fissurées, arrachées ou déformées afin de préserver ce qu''elles recouvrent.\n\nLe système est Ablatif 2 : il ajoute +1 de protection sur les deux premiers impacts applicables, après quoi les éléments utiles sont considérés comme consommés ou trop endommagés. Une armure revenue d''une mission peut donc rester parfaitement fonctionnelle tout en portant très visiblement les logements vides ou les restes des plaques qui ont fait leur travail.","data":{"Slots":"1","Effet":"Ablatif 2 : +1 protection sur les 2 premiers impacts applicables."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'modules-d-armure-anti-emp', 'Anti-EMP', NULL, '{"nature":"equipement","kind":"equipment","category":"Modules d''armure","sourceCategory":"Modules d''armure","price":750,"priceMin":null,"priceMax":null,"priceLabel":"750 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Protège l''électronique de l''armure contre EMP standard.","lore":"Un module Anti-EMP durcit l''électronique propre de l''armure contre les impulsions électromagnétiques ordinaires. Blindage de câbles, isolation de circuits, composants moins sensibles et chemins électriques protégés permettent aux fonctions intégrées de continuer à répondre là où une tenue connectée non préparée risquerait de perdre capteurs, assistance ou contrôle local.\n\nCette protection concerne l''électronique de l''armure contre un EMP standard ; elle n''étend pas automatiquement son bénéfice à tous les implants, armes ou appareils que porte l''utilisateur. Dans une tenue moderne très dépendante de ses systèmes, l''Anti-EMP ressemble donc moins à un luxe qu''à une assurance contre la perte soudaine de fonctions essentielles.","data":{"Slots":"1","Effet":"Protège l''électronique de l''armure contre EMP standard."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'modules-d-armure-anti-hack', 'Anti-hack', NULL, '{"nature":"equipement","kind":"equipment","category":"Modules d''armure","sourceCategory":"Modules d''armure","price":1000,"priceMin":null,"priceMax":null,"priceLabel":"1 000 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+3 Défense Neuro contre attaque directe de l''électronique de l''armure.","lore":"L''Anti-hack traite l''armure comme ce qu''elle est devenue : un petit réseau informatique porté sur le corps. Contrôleurs séparés, authentification renforcée, segmentation des fonctions et surveillance des accès compliquent la prise de contrôle directe d''un casque, d''un servomoteur, d''une suite de capteurs ou d''un autre élément connecté de la tenue.\n\nLe module apporte +3 en Défense Neuro contre une attaque dirigée directement contre l''électronique de l''armure. Il ne constitue pas un pare-feu universel pour le porteur ou son matériel extérieur : il durcit précisément les systèmes intégrés à la tenue, ceux dont une compromission pourrait rendre l''équipement lui-même dangereux ou inutilisable.","data":{"Slots":"1","Effet":"+3 Défense Neuro contre attaque directe de l''électronique de l''armure."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'modules-d-armure-etanche', 'Étanche', NULL, '{"nature":"equipement","kind":"equipment","category":"Modules d''armure","sourceCategory":"Modules d''armure","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Rend le profil étanche quand la structure le permet.","lore":"Le module Étanche transforme les ouvertures d''une armure compatible en véritable enveloppe fermée : joints aux articulations, fermetures protégées, raccords de casque et passages de câbles sont revus afin que l''eau ou les contaminants ne disposent plus d''un chemin évident vers l''intérieur. Sur une tenue déjà presque close, la différence tient souvent à ces détails invisibles.\n\nLe profil ne devient étanche que lorsque sa structure permet réellement d''être fermée. Un gilet ouvert ou une tenue qui laisse volontairement le visage et les membres exposés ne se change donc pas par magie en scaphandre ; ce module est surtout la dernière étape qui fait d''une armure compatible une enveloppe continue.","data":{"Slots":"1","Effet":"Rend le profil étanche quand la structure le permet."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'modules-d-armure-respirateur', 'Respirateur', NULL, '{"nature":"equipement","kind":"equipment","category":"Modules d''armure","sourceCategory":"Modules d''armure","price":800,"priceMin":null,"priceMax":null,"priceLabel":"800 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Environ 2 h d''air ; exige armure fermée.","lore":"Le respirateur ajoute à une armure fermée une réserve et une circulation d''air indépendantes de l''atmosphère immédiate. Masque ou casque, régulation, filtres et petite alimentation respiratoire forment un ensemble destiné aux fumées, atmosphères dangereuses ou passages temporaires dans un milieu où respirer directement serait une mauvaise idée.\n\nL''autonomie est d''environ deux heures et exige une armure close pour être réellement exploitable. Ce n''est donc pas un système de survie indéfini : son utilisateur dispose d''une fenêtre opérationnelle mesurable, suffisante pour intervenir ou traverser une zone contaminée, mais qui impose ensuite recharge, remplacement ou retour à une atmosphère sûre.","data":{"Slots":"1","Effet":"Environ 2 h d''air ; exige armure fermée."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'modules-d-armure-thermique', 'Thermique', NULL, '{"nature":"equipement","kind":"equipment","category":"Modules d''armure","sourceCategory":"Modules d''armure","price":750,"priceMin":null,"priceMax":null,"priceLabel":"750 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Réduction 3 [Feu/Froid].","lore":"Le module thermique combine isolation et gestion des échanges de chaleur afin que l''armure protège mieux son occupant aussi bien d''un froid agressif que d''une exposition au feu. Selon le support, cela peut prendre la forme de couches isolantes, de matériaux réfractaires ou de circuits répartissant une partie de la chaleur loin des zones les plus vulnérables.\n\nIl fournit une Réduction 3 contre le Feu et le Froid. Cette spécialisation explique qu''on le retrouve aussi bien sur des tenues industrielles que sur des équipements de terrain extrême ; elle ne doit pas être confondue avec une protection électrique ou EMP, qui répond à des contraintes physiques complètement différentes.","data":{"Slots":"1","Effet":"Réduction 3 [Feu/Froid]."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'modules-d-armure-electrique', 'Électrique', NULL, '{"nature":"equipement","kind":"equipment","category":"Modules d''armure","sourceCategory":"Modules d''armure","price":750,"priceMin":null,"priceMax":null,"priceLabel":"750 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Réduction 3 [Électricité] ; ne vaut pas Anti-EMP.","lore":"Le module électrique vise les décharges qui traverseraient normalement la tenue et le corps : matériaux diélectriques, chemins de dérivation et isolation des zones conductrices limitent la quantité d''énergie qui atteint directement l''occupant. Il est particulièrement logique sur des armures de technicien, d''intervention industrielle ou destinées à affronter des armes électriques.\n\nIl apporte une Réduction 3 contre l''Électricité, mais ne vaut pas Anti-EMP. Protéger un humain d''une décharge et préserver des circuits d''une impulsion électromagnétique sont deux problèmes distincts ; une armure très bien isolée électriquement peut donc encore voir ses propres systèmes électroniques perturbés si elle n''est pas durcie pour cela.","data":{"Slots":"1","Effet":"Réduction 3 [Électricité] ; ne vaut pas Anti-EMP."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'modules-d-armure-suite-capteurs', 'Suite capteurs', NULL, '{"nature":"equipement","kind":"equipment","category":"Modules d''armure","sourceCategory":"Modules d''armure","price":1250,"priceMin":null,"priceMax":null,"priceLabel":"1 250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+2 Perception quand les capteurs integres sont precisement pertinents.","lore":"Une suite capteurs transforme casque et armure en plateforme d''observation : optiques spécialisées, télémétrie, capteurs environnementaux ou autres instruments peuvent être combinés selon la mission. L''intérêt n''est pas d''afficher davantage d''informations en permanence, mais de fournir au porteur une mesure qu''un œil ou une oreille seuls ne pourraient pas obtenir aussi proprement.\n\nLe module accorde +2 en Perception lorsque les capteurs intégrés sont précisément pertinents pour ce que l''utilisateur cherche à détecter. Cette condition est essentielle : une caméra thermique aide si la chaleur est l''indice utile, un autre capteur dans une autre situation, mais aucune suite ne remplace automatiquement tous les sens ni toute forme d''enquête.","data":{"Slots":"1","Effet":"+2 Perception quand les capteurs integres sont precisement pertinents."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'modules-d-armure-interface-de-ciblage', 'Interface de ciblage', NULL, '{"nature":"equipement","kind":"equipment","category":"Modules d''armure","sourceCategory":"Modules d''armure","price":750,"priceMin":null,"priceMax":null,"priceLabel":"750 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Interface compatible Smartlink/Verrouillage ; aucun +3 propre. Inutilisable comme guidage neural par un Unsinkable.","lore":"L''interface de ciblage relie l''armure aux armes et systèmes compatibles afin que données de visée, identification et Verrouillage puissent être affichés là où le porteur en a besoin. Viseur de casque, liaison de données et contrôleur local forment ainsi une couche commune entre la tenue et un Smartlink sans obliger chaque arme à fournir sa propre interface visuelle complète.\n\nLe module est compatible Smartlink et Verrouillage, mais n''accorde aucun +3 par lui-même. Pour un Unsinkable, il peut toujours servir d''affichage ou d''électronique ordinaire, mais pas de guidage neural : l''interface transmet les informations disponibles sans créer une connexion cérébrale que l''utilisateur ne possède pas.","data":{"Slots":"1","Effet":"Interface compatible Smartlink/Verrouillage ; aucun +3 propre. Inutilisable comme guidage neural par un Unsinkable."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'modules-d-armure-exosquelette-leger', 'Exosquelette léger', NULL, '{"nature":"equipement","kind":"equipment","category":"Modules d''armure","sourceCategory":"Modules d''armure","price":2500,"priceMin":null,"priceMax":null,"priceLabel":"2 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Exo 1 : portage, effort, équipement lourd et prérequis de force explicitement concernés.","lore":"L''exosquelette léger ajoute une ossature motorisée ou assistée le long des principaux segments de l''armure. Il ne transforme pas son porteur en machine de guerre : sa vocation est de reprendre une partie du poids, soutenir les efforts répétés et permettre à une tenue chargée d''équipement de rester exploitable pendant un travail physique exigeant.\n\nLe module fournit Exo 1 pour le portage, l''effort, l''équipement lourd et les prérequis de force explicitement concernés. Sur le terrain, cela correspond à une assistance de manutention et de maintien plutôt qu''à une augmentation générale de toutes les actions physiques ; l''exosquelette aide là où sa structure peut réellement reprendre la charge.","data":{"Slots":"2","Effet":"Exo 1 : portage, effort, équipement lourd et prérequis de force explicitement concernés."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'modules-d-armure-compensation-mobilite', 'Compensation mobilité', NULL, '{"nature":"equipement","kind":"equipment","category":"Modules d''armure","sourceCategory":"Modules d''armure","price":1500,"priceMin":null,"priceMax":null,"priceLabel":"1 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Annule les pénalités de mobilité explicitement causées par l''armure.","lore":"La compensation de mobilité équipe une armure encombrante de servos, articulations assistées ou mécanismes de rappel calibrés sur son propre poids. Le but est simple : empêcher la protection elle-même de lutter contre son utilisateur à chaque pas, rotation du torse ou changement de position, surtout lorsque plusieurs couches rigides doivent se déplacer ensemble.\n\nLe module annule les pénalités de mobilité explicitement causées par l''armure. Il ne rend donc pas le porteur plus rapide ou plus agile qu''il ne le serait sans cette charge ; il compense le handicap créé par la tenue afin qu''une protection lourde puisse être manipulée avec une liberté de mouvement plus proche de la normale.","data":{"Slots":"1","Effet":"Annule les pénalités de mobilité explicitement causées par l''armure."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'modules-d-armure-camo-adaptatif', 'Camo adaptatif', NULL, '{"nature":"equipement","kind":"equipment","category":"Modules d''armure","sourceCategory":"Modules d''armure","price":2500,"priceMin":null,"priceMax":null,"priceLabel":"2 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Camo 1 ; impossible si l''armure possède déjà Camo.","lore":"Le camouflage adaptatif applique à une armure ordinaire une surface capable de modifier partiellement son apparence en fonction du décor. Ce retrofit reste plus simple que les systèmes conçus dès l''origine autour de la furtivité : il travaille surtout les couleurs, motifs et ruptures de silhouette accessibles depuis la couche extérieure de la tenue.\n\nLe module fournit Camo 1 et ne peut pas être installé sur une armure qui possède déjà Camo. Cette impossibilité reflète bien sa nature : c''est une couche de camouflage ajoutée à une plateforme qui n''en avait pas, pas un multiplicateur que l''on empile sur une Squid Skin, une Ninja ou une autre architecture de furtivité déjà spécialisée.","data":{"Slots":"2","Effet":"Camo 1 ; impossible si l''armure possède déjà Camo."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'applications-holonet-navia', 'NavIA', NULL, '{"nature":"equipement","kind":"equipment","category":"Applications Holonet","sourceCategory":"Applications Holonet","price":0,"priceMin":null,"priceMax":null,"priceLabel":"Incluse / gratuite","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Navigation, profil, achats, GPS, OS Holonet.","lore":"NavIA est le socle logiciel courant de l’accès personnel au Holonet. Elle réunit la navigation, le GPS, le profil utilisateur et les fonctions d’achat dans l’environnement qui sert d’interface générale au terminal de son propriétaire.\n\nSon rôle est d’orchestrer ces services de base plutôt que de remplacer les applications spécialisées. Lorsqu’un usage réclame une communication dédiée, une place de marché, un service bancaire ou un canal sécurisé, NavIA sert surtout de point d’entrée vers l’outil concerné.","data":{"Fonction":"Navigation, profil, achats, GPS, OS Holonet."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'applications-holonet-celtx', 'CeltX', NULL, '{"nature":"equipement","kind":"equipment","category":"Applications Holonet","sourceCategory":"Applications Holonet","price":75,"priceMin":null,"priceMax":null,"priceLabel":"75 $/an","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Communication textuelle, vocale et neuronale.","lore":"CeltX est une application de communication qui rassemble échanges textuels, vocaux et neuronaux. Elle permet donc de conserver un même canal de conversation entre plusieurs modes d’interface, du message classique à la communication exploitant un accès neural compatible.\n\nLe mode employé dépend du matériel disponible chez les interlocuteurs : l’application fournit le service de communication, mais ne crée pas à elle seule une interface neuronale chez quelqu’un qui n’en possède pas et ne transforme pas un échange ordinaire en canal sécurisé.","data":{"Fonction":"Communication textuelle, vocale et neuronale."},"vehicle":false,"neuro":false,"recurring":"annual","monthlyCost":6.25,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'applications-holonet-securio', 'Securio', NULL, '{"nature":"equipement","kind":"equipment","category":"Applications Holonet","sourceCategory":"Applications Holonet","price":500,"priceMin":500,"priceMax":2500,"priceLabel":"500 - 2 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Canal securise diff. 12/15/18/21/25.","lore":"Securio fournit des canaux de communication sécurisés dont la résistance existe en plusieurs niveaux. Le choix du service correspond donc directement au niveau de protection recherché lorsqu’un échange doit être plus difficile à intercepter ou à compromettre qu’une communication courante.\n\nCette sécurité reste mesurable et attaquable : les différents paliers de Securio correspondent à des difficultés croissantes plutôt qu’à une inviolabilité absolue. Un canal plus robuste augmente l’obstacle à franchir, sans rendre son contenu impossible à atteindre par principe.","data":{"Fonction":"Canal securise diff. 12/15/18/21/25."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'applications-holonet-shelov', 'Shelov', NULL, '{"nature":"equipement","kind":"equipment","category":"Applications Holonet","sourceCategory":"Applications Holonet","price":150,"priceMin":null,"priceMax":null,"priceLabel":"150 $/an","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Musique Tuatha.","lore":"Shelov est une application musicale consacrée à la musique Tuatha. Elle constitue un point d’accès spécialisé à cette scène plutôt qu’un service Holonet généraliste, et sa raison d’être est précisément de rassembler ce contenu musical sous une même offre.\n\nL’application n’ajoute aucune fonction technique particulière au terminal qui l’exécute : sa valeur vient de son catalogue et de son orientation culturelle. Pour un utilisateur qui cherche spécifiquement la musique Tuatha, Shelov est l’outil dédié prévu pour cet usage.","data":{"Fonction":"Musique Tuatha."},"vehicle":false,"neuro":false,"recurring":"annual","monthlyCost":12.5,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'applications-holonet-blackflag', 'BlackFlag', NULL, '{"nature":"equipement","kind":"equipment","category":"Applications Holonet","sourceCategory":"Applications Holonet","price":0,"priceMin":null,"priceMax":null,"priceLabel":"Gratuit","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Réseau musical Neopunk.","lore":"BlackFlag est le réseau musical associé à la scène Neopunk. Contrairement à une application de musique généraliste, son identité est liée à ce milieu et à la circulation de ses contenus, ce qui en fait un espace numérique identifiable de cette culture underground.\n\nSon intérêt est donc autant dans le réseau auquel il donne accès que dans la musique elle-même. BlackFlag ne confère aucun statut automatique au sein de la scène : l’application ouvre le réseau musical Neopunk, mais la place d’un utilisateur dans ce milieu reste une affaire de relations et de réputation.","data":{"Fonction":"Réseau musical Neopunk."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'applications-holonet-allbrains', 'AllBrains', NULL, '{"nature":"equipement","kind":"equipment","category":"Applications Holonet","sourceCategory":"Applications Holonet","price":300,"priceMin":null,"priceMax":null,"priceLabel":"300 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Modelisation holo / impression 3D.","lore":"AllBrains est un outil de modélisation holographique destiné à préparer des formes et modèles exploitables en fabrication 3D. Il fournit l’environnement logiciel nécessaire pour concevoir, visualiser ou ajuster une pièce avant de passer à sa production physique.\n\nLe logiciel ne remplace pas l’équipement de fabrication : un modèle AllBrains doit encore être compatible avec la machine, les matériaux et les capacités disponibles. Il intervient donc en amont de l’impression, là où se construit et se vérifie la géométrie du projet.","data":{"Fonction":"Modelisation holo / impression 3D."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'applications-holonet-ladydolla', 'LadyDolla', NULL, '{"nature":"equipement","kind":"equipment","category":"Applications Holonet","sourceCategory":"Applications Holonet","price":250,"priceMin":null,"priceMax":null,"priceLabel":"250 $/an","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Gestion/alertes bancaires.","lore":"LadyDolla est une application de gestion bancaire centrée sur le suivi de l’activité financière et les alertes. Elle permet à son utilisateur de surveiller plus facilement les opérations qui concernent ses services bancaires depuis son environnement Holonet personnel.\n\nLes alertes servent à signaler une opération ou une situation financière détectée par le service ; elles ne remplacent ni l’autorisation de la banque ni les contrôles qui encadrent réellement une transaction. LadyDolla facilite le suivi, pas le contournement du système bancaire.","data":{"Fonction":"Gestion/alertes bancaires."},"vehicle":false,"neuro":false,"recurring":"annual","monthlyCost":20.833333333333332,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'applications-holonet-redwish', 'Redwish', NULL, '{"nature":"equipement","kind":"equipment","category":"Applications Holonet","sourceCategory":"Applications Holonet","price":0,"priceMin":null,"priceMax":null,"priceLabel":"Gratuit","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Réseau social/rencontre/services associes.","lore":"Redwish combine réseau social, rencontres et services associés au sein d’une même application. Un profil peut donc servir à nouer des contacts personnels, chercher une rencontre ou accéder aux prestations que la plateforme rattache à cet écosystème social.\n\nLa mise en relation reste une mise en relation : Redwish ne garantit ni l’identité réelle, ni les intentions, ni la compatibilité des personnes rencontrées. Les conséquences sociales dépendent toujours des utilisateurs et du contexte derrière les profils affichés par le réseau.","data":{"Fonction":"Réseau social/rencontre/services associes."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'applications-holonet-boudicca', 'Boudicca', NULL, '{"nature":"equipement","kind":"equipment","category":"Applications Holonet","sourceCategory":"Applications Holonet","price":0,"priceMin":null,"priceMax":null,"priceLabel":"Gratuit","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Marketplace grand public.","lore":"Boudicca est la grande place de marché grand public du Holonet. Elle sert à chercher, présenter et mettre en relation l’offre courante accessible aux consommateurs, plutôt qu’à fournir elle-même une catégorie unique de biens ou de services.\n\nLa plateforme organise l’accès au marché, mais la nature d’un achat reste celle de ce qui est effectivement proposé. Disponibilité, qualité, livraison et légalité dépendent donc de l’offre concernée ; être référencé sur Boudicca ne transforme pas tous les vendeurs en source équivalente.","data":{"Fonction":"Marketplace grand public."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'applications-holonet-call-infornia', 'Call''infornia', NULL, '{"nature":"equipement","kind":"equipment","category":"Applications Holonet","sourceCategory":"Applications Holonet","price":0,"priceMin":null,"priceMax":null,"priceLabel":"Gratuit / obligatoire","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Identite civique, vote, services publics.","lore":"Call''infornia est l’interface civique reliant l’identité du citoyen aux services publics numériques. Elle centralise notamment les fonctions d’identité civique, l’accès au vote et les démarches administratives disponibles par le Holonet.\n\nSon caractère civique la distingue des réseaux sociaux ou marchands : l’application sert d’interface avec les institutions et les services publics. Elle ne remplace pas les droits ou autorisations eux-mêmes, mais fournit le canal numérique par lequel ils sont présentés ou exercés.","data":{"Fonction":"Identite civique, vote, services publics."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'applications-holonet-vatican', 'Vatican+', NULL, '{"nature":"equipement","kind":"equipment","category":"Applications Holonet","sourceCategory":"Applications Holonet","price":0,"priceMin":null,"priceMax":null,"priceLabel":"Gratuit","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Réseau chretien.","lore":"Vatican+ est un réseau Holonet chrétien, distinct des services civiques et des réseaux généralistes. Sa fonction documentée est de fournir un espace numérique identifié à cette communauté religieuse plutôt qu’un outil technique universel.\n\nL’accès au réseau ne constitue pas en lui-même une autorité religieuse, un statut ecclésiastique ou un effet surnaturel. Vatican+ reste un service numérique de Réalité ; les rôles, croyances et institutions auxquels il peut donner accès existent indépendamment de l’application.","data":{"Fonction":"Réseau chretien."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'applications-holonet-islamaster', 'Islamaster', NULL, '{"nature":"equipement","kind":"equipment","category":"Applications Holonet","sourceCategory":"Applications Holonet","price":0,"priceMin":null,"priceMax":null,"priceLabel":"Gratuit","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Réseau musulman.","lore":"Islamaster est un réseau Holonet musulman, organisé comme un espace numérique identifié à cette communauté religieuse plutôt qu’à un usage marchand, bancaire ou administratif généraliste.\n\nUtiliser Islamaster ne confère par lui-même ni autorité religieuse ni effet particulier au personnage. Le réseau appartient au quotidien numérique de Réalité ; les pratiques, responsabilités et relations religieuses auxquelles il peut servir de support restent celles des personnes et institutions concernées.","data":{"Fonction":"Réseau musulman."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'applications-holonet-rampage-x', 'Rampage X', NULL, '{"nature":"equipement","kind":"equipment","category":"Applications Holonet","sourceCategory":"Applications Holonet","price":0,"priceMin":null,"priceMax":null,"priceLabel":"Gratuit","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Crawler/Abyss ; contrats/BBM ; +3 aux Intrusions hostiles contre le systeme tant que l''app tourne.","lore":"Rampage X est une application liée aux réseaux Crawler et à l’Abyss, utilisée notamment pour les contrats et les échanges BBM. Elle appartient donc à un environnement opérationnel bien plus exposé que les applications Holonet grand public ordinaires.\n\nLorsqu’elle fonctionne, Rampage X durcit le système qui l’héberge contre les Intrusions hostiles : celles-ci subissent une difficulté accrue de 3. Cette protection ne rend pas la machine inviolable et ne s’applique qu’aussi longtemps que l’application est effectivement active.","data":{"Fonction":"Crawler/Abyss ; contrats/BBM ; +3 aux Intrusions hostiles contre le systeme tant que l''app tourne."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'objets-usuels-neurodive-n-sta', 'N-Sta', NULL, '{"nature":"equipement","kind":"equipment","category":"Objets usuels & Neurodive","sourceCategory":"Objets usuels & Neurodive","price":25,"priceMin":null,"priceMax":null,"priceLabel":"25 $ / 20","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Environ 1 h : Stress augmentique effectif -1 et +2 Maîtrise contre Stress/Surcharge augmentique. Limite 1/h ; abus -> test Constitution.","lore":"N-Sta est un consommable destiné à amortir temporairement la pression que les augmentations font peser sur leur utilisateur. Pendant environ une heure, il réduit d’un cran le Stress augmentique effectif et aide à conserver le contrôle face au Stress ou à la Surcharge liés aux implants.\n\nL’effet reste ponctuel : N-Sta accorde aussi +2 en Maîtrise contre le Stress ou la Surcharge augmentique, mais son usage est limité à une prise par heure. Dépasser ce rythme expose l’organisme et appelle un test de Constitution plutôt qu’un cumul libre des bénéfices.","data":{"Usage":"Environ 1 h : Stress augmentique effectif -1 et +2 Maîtrise contre Stress/Surcharge augmentique. Limite 1/h ; abus -> test Constitution."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'objets-usuels-neurodive-holophone', 'Holophone', NULL, '{"nature":"equipement","kind":"equipment","category":"Objets usuels & Neurodive","sourceCategory":"Objets usuels & Neurodive","price":250,"priceMin":null,"priceMax":null,"priceLabel":"250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Holonet, applications, communication, NavIA.","lore":"Le Holophone est le terminal personnel courant d’accès au Holonet. Il concentre communications, applications et services usuels autour de NavIA, ce qui en fait à la fois un téléphone, un portefeuille de services et une porte d’entrée vers l’environnement numérique quotidien.\n\nSon intérêt vient surtout de cette centralisation : un même appareil sert à communiquer, consulter le réseau, utiliser ses applications et exploiter les fonctions de navigation associées. Il reste néanmoins un équipement connecté, donc dépendant de l’accès au réseau et exposé aux risques propres aux systèmes numériques.","data":{"Usage":"Holonet, applications, communication, NavIA."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'objets-usuels-neurodive-hololentilles', 'Hololentilles', NULL, '{"nature":"equipement","kind":"equipment","category":"Objets usuels & Neurodive","sourceCategory":"Objets usuels & Neurodive","price":350,"priceMin":null,"priceMax":null,"priceLabel":"350 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"RA/affichage optique temporaire ; risques en usage intensif/hack.","lore":"Les Hololentilles projettent directement des informations et éléments de réalité augmentée dans le champ de vision de l’utilisateur. Elles offrent un affichage optique temporaire sans exiger d’implant permanent et servent autant à consulter des données qu’à superposer une interface à l’environnement réel.\n\nCette proximité avec la perception a un revers : usage intensif, surcharge d’informations ou compromission du système peuvent devenir particulièrement gênants. Elles ne remplacent pas les sens naturels ; elles ajoutent une couche visuelle dont la fiabilité dépend du dispositif, de son alimentation et de sa sécurité.","data":{"Usage":"RA/affichage optique temporaire ; risques en usage intensif/hack."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'objets-usuels-neurodive-idpass', 'IDpass', NULL, '{"nature":"equipement","kind":"equipment","category":"Objets usuels & Neurodive","sourceCategory":"Objets usuels & Neurodive","price":100,"priceMin":null,"priceMax":null,"priceLabel":"100 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Identite/autorisation de presence sans Holophone.","lore":"L’IDpass est un support d’identité et d’autorisation autonome destiné aux situations où un Holophone n’est pas utilisé ou ne doit pas servir de justificatif. Il permet de présenter les informations nécessaires à un contrôle de présence, d’accès ou d’identité sans dépendre du terminal personnel principal.\n\nSon utilité est donc administrative et pratique plutôt que technique : il matérialise une identité exploitable par les systèmes qui l’acceptent. La possession de l’IDpass ne garantit pas qu’une autorisation soit valide ; elle fournit seulement le support prévu pour la présenter et la vérifier.","data":{"Usage":"Identite/autorisation de presence sans Holophone."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'objets-usuels-neurodive-byron-zippo', 'Byron Zippo', NULL, '{"nature":"equipement","kind":"equipment","category":"Objets usuels & Neurodive","sourceCategory":"Objets usuels & Neurodive","price":200,"priceMin":null,"priceMax":null,"priceLabel":"200 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Briquet autoregenerant ; petit outil de flamme.","lore":"Le Byron Zippo est un briquet autorégénérant conçu pour conserver durablement sa fonction de petite source de flamme. Son intérêt tient moins à la puissance qu’à la disponibilité : allumer, chauffer ponctuellement ou amorcer un matériau combustible reste possible sans dépendre d’un consommable ordinaire immédiatement disponible.\n\nIl demeure un outil de poche, pas un dispositif incendiaire. Sa flamme sert aux usages qu’un briquet peut réellement accomplir et sa technologie autorégénérante améliore surtout l’endurance de l’objet, sans lui donner la portée ou la puissance d’un équipement spécialisé.","data":{"Usage":"Briquet autoregenerant ; petit outil de flamme."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'objets-usuels-neurodive-projecteur-holographique', 'Projecteur holographique', NULL, '{"nature":"equipement","kind":"equipment","category":"Objets usuels & Neurodive","sourceCategory":"Objets usuels & Neurodive","price":250,"priceMin":null,"priceMax":null,"priceLabel":"250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Projection locale et support DFL.","lore":"Un projecteur holographique crée une projection locale utilisable pour présenter des informations, des modèles ou d’autres contenus visuels dans l’espace proche. Il sert notamment de support aux fichiers et contenus DFL lorsqu’un affichage partagé est préférable à une consultation individuelle.\n\nLa projection reste liée au volume et aux capacités physiques de l’appareil : elle affiche, elle ne transforme pas matériellement l’environnement. Sa valeur vient donc de la visualisation collective, de la préparation et de la lecture de contenus plutôt que d’un effet de dissimulation ou d’illusion universel.","data":{"Usage":"Projection locale et support DFL."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'objets-usuels-neurodive-facecaster-dfl', 'FaceCaster DFL', NULL, '{"nature":"equipement","kind":"equipment","category":"Objets usuels & Neurodive","sourceCategory":"Objets usuels & Neurodive","price":750,"priceMin":null,"priceMax":null,"priceLabel":"750 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Projection apparence porte ; complet avec Holo''Rmor.","lore":"Le FaceCaster DFL est un projecteur porté qui falsifie l’apparence visible du visage et des vêtements plutôt que le corps lui-même. Il appartient à la même culture technique que les dispositifs holographiques de consommation, mais pousse leur précision vers l’infiltration, le spectacle ou la protection d’identité.\n\nEmployé seul, le DFL doit composer avec la silhouette réelle, le toucher, les capteurs non visuels et les erreurs de perspective. Couplé à une Holo’Rmor, il peut contribuer à un déguisement beaucoup plus complet ; même alors, il produit une apparence cohérente, jamais une transformation physique du porteur.","data":{"Usage":"Projection apparence porte ; complet avec Holo''Rmor."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'objets-usuels-neurodive-essaim-de-microbots', 'Essaim de microbots', NULL, '{"nature":"equipement","kind":"equipment","category":"Objets usuels & Neurodive","sourceCategory":"Objets usuels & Neurodive","price":600,"priceMin":null,"priceMax":null,"priceLabel":"600 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Inspection, petites manipulations et maintenance de précision selon outils.","lore":"Un essaim de microbots rassemble de très petites unités capables d’inspecter des zones difficiles d’accès et d’effectuer des manipulations fines. Selon l’outillage embarqué, il peut soutenir une opération de maintenance, examiner un mécanisme ou intervenir là où des mains ou des outils classiques seraient trop encombrants.\n\nL’essaim n’est pas un atelier autonome : ses possibilités dépendent directement des outils dont les microbots disposent et de la tâche demandée. Il excelle dans la précision et l’accès, mais ne remplace ni les pièces nécessaires, ni les compétences de diagnostic, ni l’équipement lourd lorsqu’une réparation l’exige.","data":{"Usage":"Inspection, petites manipulations et maintenance de précision selon outils."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'objets-usuels-neurodive-drone-civil', 'Drone civil', NULL, '{"nature":"equipement","kind":"equipment","category":"Objets usuels & Neurodive","sourceCategory":"Objets usuels & Neurodive","price":1000,"priceMin":null,"priceMax":null,"priceLabel":"1 000 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Observation, transport léger ou assistance selon modèle ; pas de PA gratuits.","lore":"Le drone civil couvre une famille d’appareils autonomes ou téléopérés destinés à l’observation, au transport léger ou à l’assistance. Le rôle exact dépend du modèle : certains privilégient les capteurs, d’autres la manutention ou une présence mobile capable d’accompagner une activité courante.\n\nDisposer d’un drone ajoute un outil mobile, pas du temps d’action supplémentaire au personnage. Il agit dans les limites de son équipement, de son autonomie et de ses commandes ; lorsqu’une tâche dépasse ses capteurs, sa charge utile ou sa programmation, il ne peut pas la résoudre par simple présence.","data":{"Usage":"Observation, transport léger ou assistance selon modèle ; pas de PA gratuits."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'objets-usuels-neurodive-serrure-intelligente', 'Serrure intelligente', NULL, '{"nature":"equipement","kind":"equipment","category":"Objets usuels & Neurodive","sourceCategory":"Objets usuels & Neurodive","price":250,"priceMin":null,"priceMax":null,"priceLabel":"250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Contrôle d''accès connecté ; sécurité selon installation.","lore":"Une serrure intelligente contrôle l’accès à une porte ou un compartiment au moyen d’un système connecté. Elle peut reconnaître les autorisations prévues par l’installation et s’intégrer à la sécurité d’un logement, d’un local ou d’un équipement plutôt que de fonctionner comme une simple clé mécanique.\n\nSon niveau de protection dépend pourtant de l’ensemble dans lequel elle est installée : qualité du verrouillage, alimentation, réseau, configuration et sécurité du système comptent tous. Une serrure sophistiquée montée sur un accès faible ou mal administré ne transforme pas à elle seule le lieu en zone sécurisée.","data":{"Usage":"Contrôle d''accès connecté ; sécurité selon installation."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'objets-usuels-neurodive-relais-holonet-portable', 'Relais Holonet portable', NULL, '{"nature":"equipement","kind":"equipment","category":"Objets usuels & Neurodive","sourceCategory":"Objets usuels & Neurodive","price":750,"priceMin":null,"priceMax":null,"priceLabel":"750 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Etend/etablit un accès local au réseau.","lore":"Le relais Holonet portable sert à étendre ou à établir localement un accès au réseau lorsqu’une connexion directe est insuffisante ou mal placée. Il fournit un point de relais transportable autour duquel plusieurs équipements peuvent retrouver une connectivité exploitable.\n\nIl améliore la couverture locale, pas l’existence d’une infrastructure amont. Si aucun réseau utilisable n’est accessible au relais, celui-ci ne crée pas magiquement une liaison vers le Holonet ; son intérêt est de transporter, redistribuer ou rapprocher une connexion réellement disponible.","data":{"Usage":"Etend/etablit un accès local au réseau."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'objets-usuels-neurodive-scanner-portable', 'Scanner portable', NULL, '{"nature":"equipement","kind":"equipment","category":"Objets usuels & Neurodive","sourceCategory":"Objets usuels & Neurodive","price":750,"priceMin":null,"priceMax":null,"priceLabel":"750 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Capteurs multi-usages ; permet les tests qu''il peut physiquement mesurer.","lore":"Le scanner portable rassemble plusieurs capteurs dans un appareil transportable afin d’examiner un objet, un lieu ou un phénomène. Il fournit des mesures exploitables lorsque ses capteurs correspondent réellement à ce qui doit être observé et permet d’appuyer un diagnostic sur autre chose qu’une simple inspection visuelle.\n\nSa polyvalence ne signifie pas qu’il détecte tout. Un test n’est possible que si l’appareil peut physiquement mesurer l’information recherchée et si les conditions permettent une lecture correcte ; l’interprétation des données reste ensuite liée aux compétences et connaissances de l’utilisateur.","data":{"Usage":"Capteurs multi-usages ; permet les tests qu''il peut physiquement mesurer."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'objets-usuels-neurodive-imprimante-polymere', 'Imprimante polymere', NULL, '{"nature":"equipement","kind":"equipment","category":"Objets usuels & Neurodive","sourceCategory":"Objets usuels & Neurodive","price":2500,"priceMin":null,"priceMax":null,"priceLabel":"2 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Fabrication de pièces simples avec matière/plan approprié.","lore":"L’imprimante polymère fabrique des pièces simples à partir d’une matière compatible et d’un plan approprié. Elle est utile pour produire sur place des composants courants, des formes de remplacement ou de petits éléments techniques sans dépendre immédiatement d’une chaîne logistique extérieure.\n\nElle ne peut toutefois imprimer que ce que son procédé, sa matière et le plan fourni permettent réellement de fabriquer. Une pièce complexe, un matériau absent ou un mécanisme dépassant ses capacités exige toujours un équipement adapté ; l’imprimante accélère la fabrication simple, elle ne remplace pas un atelier complet.","data":{"Usage":"Fabrication de pièces simples avec matière/plan approprié."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'objets-usuels-neurodive-scanner-3d', 'Scanner 3D', NULL, '{"nature":"equipement","kind":"equipment","category":"Objets usuels & Neurodive","sourceCategory":"Objets usuels & Neurodive","price":1200,"priceMin":null,"priceMax":null,"priceLabel":"1 200 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Acquisition de forme pour modelisation/fabrication.","lore":"Le scanner 3D acquiert la forme d’un objet afin d’en produire une représentation exploitable pour la modélisation ou la fabrication. Il sert à relever des volumes, préparer un modèle ou fournir une base de travail lorsqu’une reproduction ou une adaptation doit partir d’un objet existant.\n\nIl capture une géométrie, pas automatiquement la fonction complète de ce qu’il observe. Les matériaux, mécanismes internes, tolérances et propriétés invisibles doivent encore être connus ou étudiés séparément avant qu’un modèle puisse devenir une pièce réellement fonctionnelle.","data":{"Usage":"Acquisition de forme pour modelisation/fabrication."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'objets-usuels-neurodive-kit-medical', 'Kit médical', NULL, '{"nature":"equipement","kind":"equipment","category":"Objets usuels & Neurodive","sourceCategory":"Objets usuels & Neurodive","price":150,"priceMin":null,"priceMax":null,"priceLabel":"150 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Matériel adapté pour Premiers soins et Stabilisation.","lore":"Le kit médical regroupe le matériel nécessaire aux gestes de premiers soins et à la stabilisation d’un blessé. Il fournit les consommables et outils adaptés pour traiter une urgence immédiate lorsque la compétence médicale de l’intervenant permet d’agir correctement.\n\nIl est conçu pour maintenir, protéger et préparer une prise en charge, pas pour remplacer une clinique ou une chirurgie. Les blessures qui demandent une intervention lourde, un suivi ou un matériel spécialisé dépassent ses capacités même si les premiers gestes ont été correctement réalisés.","data":{"Usage":"Matériel adapté pour Premiers soins et Stabilisation."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'objets-usuels-neurodive-kit-technique', 'Kit technique', NULL, '{"nature":"equipement","kind":"equipment","category":"Objets usuels & Neurodive","sourceCategory":"Objets usuels & Neurodive","price":250,"priceMin":null,"priceMax":null,"priceLabel":"250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Outils de maintenance/réparation courante.","lore":"Le kit technique rassemble les outils nécessaires à la maintenance et aux réparations courantes. Il permet d’ouvrir, tester, ajuster ou remettre en état un équipement standard lorsque la panne reste dans le domaine d’un entretien de terrain ou d’atelier léger.\n\nLe kit ne fournit ni les pièces rares ni les machines spécialisées qu’exige une réparation lourde. Il donne les moyens matériels d’intervenir sur un problème accessible, mais le diagnostic, la qualité de la réparation et les limites de l’équipement restent déterminés par la situation et la compétence du technicien.","data":{"Usage":"Outils de maintenance/réparation courante."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'objets-usuels-neurodive-cyberconsole-neurodive', 'Cyberconsole Neurodive', NULL, '{"nature":"equipement","kind":"equipment","category":"Objets usuels & Neurodive","sourceCategory":"Objets usuels & Neurodive","price":1000,"priceMin":null,"priceMax":null,"priceLabel":"1 000 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Interface externe portable permettant de charger et employer des Neuroprogrammes sans implant neural ; aucun bonus de Rang. Un Unsinkable peut l''utiliser comme terminal ordinaire, jamais pour plonger.","lore":"La Cyberconsole Neurodive est une interface externe portable permettant de charger et d’employer des Neuroprogrammes sans disposer d’un implant neural dédié. Elle sert de poste de travail pour accéder aux outils logiciels du Neurodive depuis un équipement distinct du corps de l’utilisateur.\n\nElle ne confère aucun Rang supplémentaire et ne contourne pas les limites propres à celui qui l’utilise. Un Unsinkable peut s’en servir comme terminal informatique ordinaire, mais son incompatibilité avec l’immersion demeure : la console ne lui permet pas de plonger dans le Neurodive.","data":{"Usage":"Interface externe portable permettant de charger et employer des Neuroprogrammes sans implant neural ; aucun bonus de Rang. Un Unsinkable peut l''utiliser comme terminal ordinaire, jamais pour plonger."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'objets-usuels-neurodive-kit-hardline', 'Kit hardline', NULL, '{"nature":"equipement","kind":"equipment","category":"Objets usuels & Neurodive","sourceCategory":"Objets usuels & Neurodive","price":150,"priceMin":null,"priceMax":null,"priceLabel":"150 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Câbles/adaptateurs ; permet la Connexion physique directe lorsque l’accès matériel compatible existe réellement.","lore":"Le kit hardline réunit les câbles et adaptateurs nécessaires à une connexion physique directe avec un système compatible. Il devient utile lorsqu’un accès matériel existe réellement et qu’une liaison filaire est préférable ou nécessaire à une connexion sans fil.\n\nIl ne crée pas un port là où aucun accès matériel n’existe et ne neutralise pas à lui seul la sécurité du système. Son rôle est de rendre possible la liaison physique ; ce qui peut ensuite être fait avec cette connexion dépend de la machine, de ses protections et des compétences de l’utilisateur.","data":{"Usage":"Câbles/adaptateurs ; permet la Connexion physique directe lorsque l’accès matériel compatible existe réellement."},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'equipement-civique-puce-de-sante-citoyenne', 'Puce de santé citoyenne', NULL, '{"nature":"equipement","kind":"equipment","category":"Équipement civique","sourceCategory":"Équipement civique","price":0,"priceMin":null,"priceMax":null,"priceLabel":"Incluse avec l’identité civique","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Localisation et données vitales selon le modèle ; peut déclencher une alerte médicale et être lue par les portails sanitaires. Sa précision et la qualité de l’intervention dépendent du réseau/assurance.","lore":"La puce de santé citoyenne relie, selon le modèle, des données de localisation et des constantes vitales à l’écosystème sanitaire civique. Elle peut être lue par les portails de santé compatibles et fournir les informations prévues lorsqu’une prise en charge médicale devient nécessaire.\n\nElle peut également déclencher une alerte médicale, mais elle ne garantit ni une localisation parfaite ni une intervention immédiate. La précision disponible et la qualité de la réponse dépendent du réseau accessible et de la couverture médicale dont bénéficie réellement le citoyen.","data":{"Fonction":"Localisation et données vitales selon le modèle ; peut déclencher une alerte médicale et être lue par les portails sanitaires. Sa précision et la qualité de l’intervention dépendent du réseau/assurance."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'equipement-civique-ia-personnelle-du-holophone', 'IA personnelle du Holophone', NULL, '{"nature":"equipement","kind":"equipment","category":"Équipement civique","sourceCategory":"Équipement civique","price":0,"priceMin":null,"priceMax":null,"priceLabel":"Incluse avec Holophone/NavIA","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Gère agenda, achats usuels, banque, informations, maison connectée et habitudes de consommation. Fonction de confort : aucun bonus numérique universel.","lore":"L’IA personnelle du Holophone accompagne les usages civiques courants de son propriétaire. Elle gère l’agenda, les achats usuels, les opérations bancaires, la recherche d’informations et les habitudes de consommation depuis l’écosystème Holophone/NavIA.\n\nElle peut également coordonner les fonctions de la maison connectée lorsque le logement le permet. Cette automatisation relève du confort quotidien et de l’organisation personnelle : elle ne confère aucun bonus numérique universel aux actions de son utilisateur.","data":{"Fonction":"Gère agenda, achats usuels, banque, informations, maison connectée et habitudes de consommation. Fonction de confort : aucun bonus numérique universel."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'equipement-civique-pack-domotique-robots-domestiques', 'Pack domotique & robots domestiques', NULL, '{"nature":"equipement","kind":"equipment","category":"Équipement civique","sourceCategory":"Équipement civique","price":500,"priceMin":500,"priceMax":2500,"priceLabel":"Souvent inclus Standard+ ; sinon 500–2 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Ménage, cuisine, ravitaillement, petites réparations, surveillance domestique et coordination des appareils connectés selon le logement.","lore":"Un pack domotique et robots domestiques regroupe les automatismes d’un logement avec les petites unités qui assurent les tâches courantes. Selon l’installation, l’ensemble prend en charge ménage, cuisine, ravitaillement, petites réparations, surveillance domestique et coordination des appareils connectés.\n\nIl ne s’agit pas d’un robot unique aux capacités universelles : le contenu du pack dépend du logement et des équipements effectivement installés. Une fonction absente du système domestique ne peut pas être improvisée simplement parce que le logement possède une domotique générale.","data":{"Fonction":"Ménage, cuisine, ravitaillement, petites réparations, surveillance domestique et coordination des appareils connectés selon le logement."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'equipement-civique-robot-drone-de-securite', 'Robot / drone de sécurité', NULL, '{"nature":"equipement","kind":"equipment","category":"Équipement civique","sourceCategory":"Équipement civique","price":1500,"priceMin":1500,"priceMax":null,"priceLabel":"1 500 $+ civil ; professionnel selon profil","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Utilise Structure + Blindage comme un véhicule et peut être Neurohacké s’il est connecté. Les modèles armés détaillés appartiennent au bestiaire.","lore":"Un robot ou drone de sécurité est une unité mobile de protection dont la résistance physique se traite avec Structure et Blindage, comme pour un véhicule. Les versions civiles et professionnelles peuvent varier fortement ; les modèles armés disposant de profils complets relèvent du Bestiaire.\n\nDès qu’il est connecté, l’appareil devient aussi une cible possible de Neurohack. Sa présence n’accorde donc pas une sécurité abstraite au lieu : ce qu’il peut détecter, encaisser ou accomplir dépend de son profil réel, de son équipement et de l’intégrité de sa connexion.","data":{"Fonction":"Utilise Structure + Blindage comme un véhicule et peut être Neurohacké s’il est connecté. Les modèles armés détaillés appartiennent au bestiaire."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'vetements-recuperation-sans-abri', 'Récupération / sans-abri', NULL, '{"nature":"equipement","kind":"equipment","category":"Vêtements","sourceCategory":"Vêtements","price":25,"priceMin":null,"priceMax":null,"priceLabel":"25 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Chaleur minimale, faible standing.","lore":"Les vêtements de récupération ou de sans-abri répondent d’abord à une nécessité immédiate : conserver un minimum de chaleur avec ce qui peut être trouvé, récupéré ou maintenu en état. Leur qualité, leur coupe et leur homogénéité varient donc fortement d’un ensemble à l’autre.\n\nDans l’espace social, cette tenue signale un faible standing bien avant de constituer un choix esthétique neutre. Elle peut suffire pour se couvrir et traverser le quotidien, mais elle n’offre ni les codes de présentation ni les garanties pratiques d’un équipement professionnel ou spécialisé.","data":{"Exemples d''usage":"Chaleur minimale, faible standing."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'vetements-provocante-rue', 'Provocante / rue', NULL, '{"nature":"equipement","kind":"equipment","category":"Vêtements","sourceCategory":"Vêtements","price":50,"priceMin":null,"priceMax":null,"priceLabel":"50 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Code social spécifique.","lore":"Une tenue provocante ou de rue s’appuie sur des codes sociaux précis : manière de se présenter, degré d’exposition, références de quartier ou de scène et façon d’assumer sa présence dans l’espace public. Son sens dépend donc fortement du milieu dans lequel elle est portée.\n\nElle peut aider quelqu’un à être immédiatement identifié comme familier d’un certain registre social, mais elle ne produit aucun bonus universel. Dans un autre contexte, les mêmes codes peuvent attirer l’attention, être mal compris ou simplement ne rien signifier pour les personnes présentes.","data":{"Exemples d''usage":"Code social spécifique."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'vetements-neopunk', 'Neopunk', NULL, '{"nature":"equipement","kind":"equipment","category":"Vêtements","sourceCategory":"Vêtements","price":150,"priceMin":null,"priceMax":null,"priceLabel":"150 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Scene underground.","lore":"La tenue Neopunk appartient à une scène underground dont l’habillement fait partie de l’identité visible. Porter ce style revient à afficher une proximité culturelle avec ce milieu plutôt qu’à choisir une simple variante de vêtements urbains ordinaires.\n\nCette reconnaissance reste sociale, pas mécanique. Une apparence Neopunk peut rendre l’appartenance supposée plus lisible dans les lieux où ces codes sont connus, mais elle ne remplace ni les relations, ni la réputation, ni la connaissance réelle de la scène.","data":{"Exemples d''usage":"Scene underground."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'vetements-citoyen', 'Citoyen', NULL, '{"nature":"equipement","kind":"equipment","category":"Vêtements","sourceCategory":"Vêtements","price":150,"priceMin":null,"priceMax":null,"priceLabel":"150 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Tenue courante connectée.","lore":"La tenue citoyenne représente l’habillement urbain courant d’une population habituée aux services connectés. Elle est pensée pour s’intégrer sans difficulté au quotidien moderne plutôt que pour répondre à un métier, une scène culturelle ou une activité à risque particulière.\n\nSon caractère connecté reste celui d’un vêtement de tous les jours : il accompagne l’environnement numérique ordinaire sans devenir une interface spécialisée. Pour travailler sous contrainte, plonger dans le Neurodive ou affronter des conditions dangereuses, un équipement dédié reste nécessaire.","data":{"Exemples d''usage":"Tenue courante connectée."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'vetements-ouvrier', 'Ouvrier', NULL, '{"nature":"equipement","kind":"equipment","category":"Vêtements","sourceCategory":"Vêtements","price":250,"priceMin":null,"priceMax":null,"priceLabel":"250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Travail et sécurité de base.","lore":"La tenue d’ouvrier privilégie le travail et la sécurité de base. Elle est conçue pour supporter un usage professionnel régulier et pour fournir les protections ordinaires attendues sur un poste de travail, sans prétendre remplacer les équipements spécialisés d’un environnement réellement dangereux.\n\nElle reste donc distincte d’une armure ou d’une combinaison technique lourde. Sa fonction est de rendre le travail quotidien plus sûr et plus praticable ; dès qu’une tâche implique chaleur extrême, produits dangereux, combat ou exposition spécialisée, il faut un équipement adapté à ce risque.","data":{"Exemples d''usage":"Travail et sécurité de base."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'vetements-lingerie', 'Lingerie', NULL, '{"nature":"equipement","kind":"equipment","category":"Vêtements","sourceCategory":"Vêtements","price":200,"priceMin":null,"priceMax":null,"priceLabel":"200 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Qualite courante.","lore":"La lingerie courante désigne des pièces de qualité ordinaire destinées au confort, à l’intimité et à la présentation personnelle. Elle appartient au marché quotidien et n’implique ni fabrication exceptionnelle ni statut particulier par sa seule présence.\n\nSon rôle reste celui d’un vêtement : coupe, goût et contexte peuvent compter socialement, mais aucune propriété spéciale ne lui est attachée. Les différences avec les gammes plus prestigieuses tiennent surtout à la qualité, au travail de fabrication et au niveau de finition.","data":{"Exemples d''usage":"Qualite courante."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'vetements-detective-rue', 'Détective / rue', NULL, '{"nature":"equipement","kind":"equipment","category":"Vêtements","sourceCategory":"Vêtements","price":250,"priceMin":null,"priceMax":null,"priceLabel":"250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Codes et outils pratiques.","lore":"La tenue détective ou de rue combine une présentation capable de passer dans l’environnement urbain avec les besoins pratiques d’un travail de terrain. Elle privilégie l’accès aux petits outils et aux effets utiles plutôt qu’une apparence purement formelle ou représentative.\n\nElle ne fournit pas un équipement d’enquête complet par elle-même : elle est surtout pensée pour porter et utiliser ce que son propriétaire a réellement avec lui. Son intérêt tient à cette praticité discrète, adaptée à quelqu’un qui doit circuler, observer et travailler sans uniforme spécialisé.","data":{"Exemples d''usage":"Codes et outils pratiques."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'vetements-neurodiver', 'Neurodiver', NULL, '{"nature":"equipement","kind":"equipment","category":"Vêtements","sourceCategory":"Vêtements","price":350,"priceMin":null,"priceMax":null,"priceLabel":"350 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Vêtements connectés ; ne remplace pas Neuromaster.","lore":"Les vêtements de Neurodiver sont conçus pour accompagner un utilisateur dont l’activité quotidienne implique des équipements connectés et des interfaces numériques. Ils facilitent cette coexistence matérielle sans transformer le vêtement lui-même en système d’immersion profonde.\n\nIls ne remplacent donc jamais un Neuromaster. Porter cette tenue peut être pratique autour d’un poste de Neurodive, d’une cyberconsole ou d’autres périphériques, mais les capacités d’immersion, de protection neuronale et de Rang restent celles du matériel et de l’utilisateur.","data":{"Exemples d''usage":"Vêtements connectés ; ne remplace pas Neuromaster."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'vetements-techfighter-biker', 'Techfighter / biker', NULL, '{"nature":"equipement","kind":"equipment","category":"Vêtements","sourceCategory":"Vêtements","price":250,"priceMin":null,"priceMax":null,"priceLabel":"250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Tenue robuste.","lore":"La tenue Techfighter ou biker est d’abord robuste. Elle est choisie pour supporter les déplacements, les manipulations répétées et un usage plus rude qu’un vêtement urbain ordinaire, ce qui en fait un choix naturel autour des motos, ateliers et activités physiques de terrain.\n\nCette robustesse ne doit pas être confondue avec une protection d’armure. Le vêtement encaisse mieux l’usure quotidienne et accompagne une activité exigeante, mais les impacts de combat, les risques spécialisés et les protections techniques relèvent toujours d’un équipement prévu pour cela.","data":{"Exemples d''usage":"Tenue robuste."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'vetements-meditech', 'Meditech', NULL, '{"nature":"equipement","kind":"equipment","category":"Vêtements","sourceCategory":"Vêtements","price":350,"priceMin":null,"priceMax":null,"priceLabel":"350 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Matériel de soin/atelier léger.","lore":"La tenue Meditech est organisée autour des besoins d’un soignant ou d’un technicien médical travaillant avec du matériel léger. Elle permet de garder à portée les petits instruments et consommables adaptés à une intervention ordinaire sans transformer son porteur en unité médicale autonome.\n\nElle complète donc un environnement de soin ou un kit approprié plutôt qu’elle ne le remplace. Les actes qui réclament un équipement lourd, une chirurgie, une protection biologique ou un véritable atelier médical dépassent ce que peut fournir une simple tenue professionnelle.","data":{"Exemples d''usage":"Matériel de soin/atelier léger."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'vetements-cadre', 'Cadre', NULL, '{"nature":"equipement","kind":"equipment","category":"Vêtements","sourceCategory":"Vêtements","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Formel de qualite.","lore":"La tenue de cadre est un habillement formel de qualité destiné aux environnements professionnels où présentation et crédibilité sociale comptent. Elle marque une attention réelle à la coupe, à l’état du vêtement et aux conventions du milieu corporatiste ou administratif.\n\nElle aide surtout à ne pas détonner dans ces espaces. Une bonne tenue peut rendre une présence cohérente avec le rôle affiché, mais elle ne crée ni fonction, ni autorité, ni accès : les personnes qui connaissent le milieu peuvent toujours distinguer l’apparence de la position réelle.","data":{"Exemples d''usage":"Formel de qualite."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'vetements-grande-lingerie', 'Grande lingerie', NULL, '{"nature":"equipement","kind":"equipment","category":"Vêtements","sourceCategory":"Vêtements","price":400,"priceMin":null,"priceMax":null,"priceLabel":"400 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Haut de gamme.","lore":"La grande lingerie se situe dans le haut de gamme : qualité des matières, coupe et finition sont traitées comme des éléments de luxe plutôt que comme de simples nécessités vestimentaires. Le produit vise autant le plaisir personnel que la présentation dans un cadre intime.\n\nCette catégorie reste cependant un vêtement, pas un marqueur social automatique. La qualité se voit surtout dans la confection et l’attention portée au détail ; son importance en scène dépend de la personne qui la porte, de celle qui la voit et du contexte où elle devient pertinente.","data":{"Exemples d''usage":"Haut de gamme."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'vetements-cyber-expert', 'Cyber expert', NULL, '{"nature":"equipement","kind":"equipment","category":"Vêtements","sourceCategory":"Vêtements","price":600,"priceMin":null,"priceMax":null,"priceLabel":"600 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Tenue technique connectée.","lore":"La tenue de Cyber expert combine vêtements techniques et intégration à un environnement connecté. Elle est pensée pour quelqu’un qui manipule régulièrement systèmes, périphériques et outils numériques, avec une organisation adaptée à ce travail plutôt qu’à la représentation formelle.\n\nElle ne fournit pas de compétence informatique ni de capacité de Neurodive supplémentaire. Sa fonction est matérielle : rendre le travail avec des équipements connectés plus pratique et cohérent, tandis que les interfaces, logiciels et protections réellement utilisés restent des objets distincts.","data":{"Exemples d''usage":"Tenue technique connectée."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'vetements-haut-cadre', 'Haut cadre', NULL, '{"nature":"equipement","kind":"equipment","category":"Vêtements","sourceCategory":"Vêtements","price":1500,"priceMin":1500,"priceMax":null,"priceLabel":"1 500 $+","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Sur mesure / haute representation.","lore":"La tenue de haut cadre relève du sur-mesure et de la haute représentation. Elle est conçue pour des environnements où l’apparence participe directement à la lecture du rang social, du sérieux professionnel et du niveau de ressources de la personne qui la porte.\n\nSa force tient à l’ajustement et à la qualité de présentation, pas à un pouvoir social automatique. Elle peut rendre crédible l’image d’une personne habituée aux cercles dirigeants, mais titre, réputation, relations et autorité restent indépendants du vêtement.","data":{"Exemples d''usage":"Sur mesure / haute representation."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'nourriture-ration-synthetique', 'Ration / synthetique', NULL, '{"nature":"equipement","kind":"equipment","category":"Nourriture","sourceCategory":"Nourriture","price":2,"priceMin":2,"priceMax":3,"priceLabel":"2 - 3 $ / jour","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Survie et grande production.","lore":"La ration ou nourriture synthétique est pensée pour nourrir de manière fiable avec une production de masse. Elle répond aux besoins de survie et d’alimentation quotidienne avant de rechercher le plaisir, la variété ou l’origine prestigieuse des ingrédients.\n\nSa banalité vient précisément de cette efficacité industrielle : conservation, disponibilité et régularité comptent davantage que le terroir ou l’expérience du repas. On peut vivre avec ce type d’alimentation, mais il se situe à l’opposé des produits rares ou réellement traditionnels.","data":{"Lecture":"Survie et grande production."},"vehicle":false,"neuro":false,"recurring":"per_use","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'nourriture-mick-go-alternative', 'Mick&Go / alternative', NULL, '{"nature":"equipement","kind":"equipment","category":"Nourriture","sourceCategory":"Nourriture","price":5,"priceMin":null,"priceMax":null,"priceLabel":"5 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Bas de gamme ; qualite douteuse possible.","lore":"Mick&Go et les alternatives comparables occupent le bas de gamme de la restauration rapide. Le repas est accessible et immédiatement disponible, mais la qualité des ingrédients et de la préparation peut être très variable, jusqu’à devenir franchement douteuse selon l’établissement ou le produit.\n\nCe niveau répond surtout à la faim et au manque de temps. Il ne signifie pas qu’un repas sera forcément dangereux, mais l’économie réalisée se retrouve dans la régularité, la qualité perçue et le soin accordé à ce qui est servi.","data":{"Lecture":"Bas de gamme ; qualite douteuse possible."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'nourriture-mac-yellow', 'Mac''Yellow', NULL, '{"nature":"equipement","kind":"equipment","category":"Nourriture","sourceCategory":"Nourriture","price":10,"priceMin":null,"priceMax":null,"priceLabel":"10 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Fast-food populaire.","lore":"Mac''Yellow représente le fast-food populaire : une restauration standardisée, connue et suffisamment répandue pour constituer un choix ordinaire plutôt qu’une expérience particulière. L’intérêt tient à la facilité d’accès et à la prévisibilité du repas.\n\nLa chaîne se situe au-dessus de l’alimentation de survie sans chercher la cuisine de qualité. On y mange normalement et rapidement, dans un cadre familier à une large partie de la population urbaine, mais sans les attentes d’un restaurant artisanal ou haut de gamme.","data":{"Lecture":"Fast-food populaire."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'nourriture-famileat', 'Famileat', NULL, '{"nature":"equipement","kind":"equipment","category":"Nourriture","sourceCategory":"Nourriture","price":20,"priceMin":20,"priceMax":30,"priceLabel":"20 - 30 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Repas normal.","lore":"Famileat correspond au repas normal du quotidien : suffisamment complet et correct pour constituer une vraie alimentation courante, sans être défini par la rareté, le prestige ou la restauration d’exception. C’est le niveau où manger cesse d’être seulement une contrainte de survie.\n\nCe type de repas peut être partagé, commandé ou consommé dans un cadre familial ordinaire. Sa valeur vient de sa normalité même : qualité acceptable, diversité suffisante et place sociale du repas, sans prétendre à l’expérience d’un bon restaurant.","data":{"Lecture":"Repas normal."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'nourriture-artisan-bon-restaurant', 'Artisan / bon restaurant', NULL, '{"nature":"equipement","kind":"equipment","category":"Nourriture","sourceCategory":"Nourriture","price":30,"priceMin":30,"priceMax":60,"priceLabel":"30 - 60 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Qualite et social.","lore":"Un produit artisanal ou un bon restaurant met la qualité et la préparation au centre du repas. Les ingrédients, le savoir-faire et le cadre comptent davantage que dans la restauration standardisée, ce qui en fait aussi un choix pertinent pour recevoir ou marquer une occasion.\n\nLa dimension sociale devient donc partie intégrante de l’expérience. On ne paie pas seulement pour être nourri, mais pour mieux manger et pour disposer d’un cadre où le repas peut avoir du poids dans une rencontre, sans atteindre encore les codes de la cuisine d’élite.","data":{"Lecture":"Qualite et social."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'nourriture-oldo', 'Oldo''', NULL, '{"nature":"equipement","kind":"equipment","category":"Nourriture","sourceCategory":"Nourriture","price":100,"priceMin":100,"priceMax":150,"priceLabel":"100 - 150 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Cuisine elite / aliments rares.","lore":"Oldo'' appartient à la cuisine d’élite et travaille avec des aliments rares. Le repas n’est plus seulement jugé sur sa qualité immédiate : disponibilité des produits, sélection et caractère exceptionnel de ce qui est servi participent directement à l’expérience.\n\nFréquenter ce niveau de restauration signifie entrer dans un univers où la rareté elle-même a de la valeur. Le cadre convient aux occasions où prestige et qualité doivent être perceptibles, mais la table ne confère évidemment aucun statut durable à quelqu’un qui y est simplement invité.","data":{"Lecture":"Cuisine elite / aliments rares."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'nourriture-luxe-vraie-production', 'Luxe / vraie production', NULL, '{"nature":"equipement","kind":"equipment","category":"Nourriture","sourceCategory":"Nourriture","price":250,"priceMin":250,"priceMax":null,"priceLabel":"250 $+","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Produits traditionnels, terroir, service haut de gamme.","lore":"La catégorie Luxe / vraie production regroupe les aliments issus d’une production traditionnelle réelle, avec origine, terroir et méthodes de fabrication qui comptent autant que le produit final. Dans une économie largement capable de fournir du synthétique, cette authenticité devient une forme de rareté.\n\nLe service qui accompagne ces produits appartient lui aussi au haut de gamme. Provenance, fraîcheur, saison, préparation et présentation deviennent des critères distinctifs : on ne cherche plus simplement à reproduire un goût, mais à consommer quelque chose dont l’origine matérielle fait partie de la valeur.","data":{"Lecture":"Produits traditionnels, terroir, service haut de gamme."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'boissons-eau-reconditionnee', 'Eau reconditionnee', NULL, '{"nature":"equipement","kind":"equipment","category":"Boissons","sourceCategory":"Boissons","price":1,"priceMin":null,"priceMax":null,"priceLabel":"1 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"L’Eau reconditionnée est l’un des produits les plus banals de la Grande Californie : eau récupérée, traitée, contrôlée puis réinjectée dans les circuits de consommation. Dans une mégapole qui ne peut pas se permettre de perdre continuellement ses ressources, le recyclage relève de l’infrastructure quotidienne plutôt que d’un signe de pénurie exceptionnelle.\n\nSon absence de prestige est précisément ce qui la rend socialement importante. On la trouve partout où l’approvisionnement ordinaire fonctionne, et personne n’attend d’elle une histoire de terroir ou une expérience gustative ; choisir autre chose relève du goût, du confort ou du statut, pas d’un besoin élémentaire différent.","data":{},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'boissons-soda', 'Soda', NULL, '{"nature":"equipement","kind":"equipment","category":"Boissons","sourceCategory":"Boissons","price":2,"priceMin":2,"priceMax":4,"priceLabel":"2 - 4 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Soda est un produit industriel parfaitement adapté à l’économie alimentaire de 2035 : eau, sucre ou substitut, arômes et marque suffisent à créer des dizaines d’identités commerciales à partir d’une chaîne de production très standardisée. Distributeurs, fast-foods et lieux de passage en font un réflexe de consommation ordinaire.\n\nSa force tient moins à sa qualité qu’à sa disponibilité et à son langage publicitaire. Chaque quartier peut avoir ses marques dominantes ou ses parfums à la mode, mais le produit reste associé au repas rapide, au trajet et au loisir accessible ; personne ne le confond avec une boisson de prestige.","data":{},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'boissons-biere-fermentation-d-algues', 'Biere/fermentation d''algues', NULL, '{"nature":"equipement","kind":"equipment","category":"Boissons","sourceCategory":"Boissons","price":4,"priceMin":4,"priceMax":8,"priceLabel":"4 - 8 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"La bière ou boisson de fermentation d’algues remplit le rôle social qu’occupait autrefois une grande partie de la bière de céréales. Une biomasse abondante et facile à cultiver fournit une base fermentescible stable, que l’industrie peut ensuite travailler pour obtenir des profils plus ou moins convaincants selon la gamme.\n\nDans les bars populaires, l’origine algale ne constitue plus un sujet d’étonnement ; c’est simplement l’alcool courant de ceux qui veulent boire ensemble sans payer le coût agricole d’un produit traditionnel. Les puristes peuvent la mépriser, mais cette attitude en dit souvent plus sur leur statut que sur la fonction réelle de la boisson.","data":{},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'boissons-alcool-industriel', 'Alcool industriel', NULL, '{"nature":"equipement","kind":"equipment","category":"Boissons","sourceCategory":"Boissons","price":5,"priceMin":5,"priceMax":20,"priceLabel":"5 - 20 $ / verre","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"L’Alcool industriel regroupe les spiritueux et mélanges produits à grande échelle à partir de bases fermentaires ou synthétiques standardisées. Arômes, coloration et assemblage permettent de reproduire une grande partie des attentes du consommateur sans dépendre d’une récolte, d’un terroir ou d’un vieillissement long.\n\nLa catégorie couvre aussi bien la bouteille médiocre que le produit correctement maîtrisé vendu sous une marque respectable. Ce qui la distingue de l’alcool traditionnel n’est donc pas nécessairement le goût, mais la chaîne de production : reproductible, massive et relativement indépendante des matières premières historiques.","data":{},"vehicle":false,"neuro":false,"recurring":"per_use","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'boissons-alcool-traditionnel', 'Alcool traditionnel', NULL, '{"nature":"equipement","kind":"equipment","category":"Boissons","sourceCategory":"Boissons","price":20,"priceMin":20,"priceMax":null,"priceLabel":"20 $ à plusieurs centaines","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"L’Alcool traditionnel vient encore de matières agricoles réelles, de fermentations et de distillations liées à un lieu, une récolte ou un savoir-faire identifiable. Dans un monde où l’industrie sait fabriquer une ivresse et un arôme crédibles à moindre coût, cette origine devient elle-même une partie de la valeur du produit.\n\nUne bouteille peut donc être achetée pour son goût, son histoire ou ce qu’elle dit de celui qui la sert. Les établissements aisés mettent en avant provenance et méthode comme autrefois on aurait mis en avant une marque ; à très haut niveau, boire traditionnel revient presque à consommer du temps, de la terre et de la rareté.","data":{},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'boissons-cafe-synthetique', 'Cafe synthetique', NULL, '{"nature":"equipement","kind":"equipment","category":"Boissons","sourceCategory":"Boissons","price":2,"priceMin":2,"priceMax":5,"priceLabel":"2 - 5 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Café synthétique fournit caféine, amertume et arômes attendus sans utiliser de grains cultivés. C’est le café des bureaux, distributeurs, stations et nuits de travail : un produit conçu d’abord pour être constant, bon marché et disponible quelle que soit la santé des anciennes régions productrices.\n\nLes consommateurs savent généralement ce qu’ils boivent et n’y voient aucune tromperie particulière. Le synthétique est devenu la référence fonctionnelle ; ce sont les cafés cellulaires ou issus de vrais grains qui doivent désormais justifier leur supplément par une expérience, une origine ou un statut particulier.","data":{},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'boissons-cafe-clone-cellulaire', 'Cafe clone/cellulaire', NULL, '{"nature":"equipement","kind":"equipment","category":"Boissons","sourceCategory":"Boissons","price":10,"priceMin":10,"priceMax":20,"priceLabel":"10 - 20 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Café clone ou cellulaire cultive en environnement contrôlé des tissus ou composés issus du café afin de retrouver davantage de complexité qu’une simple imitation synthétique. Il occupe un compromis industriel intéressant : se rapprocher du produit agricole sans devoir reproduire toute la plantation qui l’a historiquement rendu possible.\n\nCette position intermédiaire lui donne une clientèle régulière chez ceux qui trouvent le synthétique trop plat mais refusent le prix ou le cérémonial du vrai grain. Les cafés qui veulent paraître soignés sans se positionner dans le luxe peuvent en faire un marqueur discret de qualité.","data":{},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'boissons-vrai-cafe', 'Vrai cafe', NULL, '{"nature":"equipement","kind":"equipment","category":"Boissons","sourceCategory":"Boissons","price":30,"priceMin":30,"priceMax":100,"priceLabel":"30 - 100 $ / tasse","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Vrai café est préparé à partir de grains réellement cultivés, récoltés puis torréfiés. Cette continuité agricole en fait un produit rare dans une économie où synthèse et culture cellulaire suffisent à l’essentiel de la demande ; origine, millésime et chaîne logistique deviennent donc visibles dans ce qui était autrefois une boisson quotidienne.\n\nLe servir peut être un plaisir sincère autant qu’un signe de statut. Dans les lieux aisés, on discute provenance, fraîcheur et méthode comme d’un vin ; dans les cercles très riches, la simple garantie qu’un grain vient réellement d’une plantation identifiable peut valoir autant que son profil aromatique.","data":{},"vehicle":false,"neuro":false,"recurring":"per_use","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'drogues-kick', 'Kick', NULL, '{"nature":"equipement","kind":"equipment","category":"Drogues","sourceCategory":"Drogues","price":15,"priceMin":15,"priceMax":25,"priceLabel":"15 - 25 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+2 Initiative si pris avant le jet. N''accorde jamais de PA en cours de round ; crash/fatigue possibles.","lore":"Kick se prend avant une situation où la vitesse de réaction compte. Son effet est immédiat sur l’entrée en action : lorsqu’il est consommé avant le jet, il accorde +2 en Initiative et aide l’utilisateur à partir plus vite lorsque la scène bascule sous pression.\n\nCe coup d’accélérateur ne crée jamais de PA supplémentaires une fois le round commencé. Le contrecoup peut au contraire se traduire par un crash ou de la fatigue, ce qui fait de Kick un outil de préparation ponctuel plutôt qu’un moyen de maintenir artificiellement un rythme sans conséquence.","data":{"Type":"Stimulant","Profil":"+2 Initiative si pris avant le jet. N''accorde jamais de PA en cours de round ; crash/fatigue possibles."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'drogues-velvet', 'Velvet', NULL, '{"nature":"equipement","kind":"equipment","category":"Drogues","sourceCategory":"Drogues","price":20,"priceMin":20,"priceMax":40,"priceLabel":"20 - 40 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Le Stress psychologique compte un cran plus bas pour explosif/échec narratif (Paniqué->Tendu, Tendu->Normal), sans masquer les états dus aux blessures. -3 Initiative/Perception.","lore":"Velvet atténue la manière dont le Stress psychologique pèse sur les emballements les plus graves. Pour déterminer les conséquences d’un explosif ou d’un échec narratif lié à ce Stress, Paniqué compte comme Tendu et Tendu comme Normal tant que l’effet est pertinent.\n\nCette distance émotionnelle a un coût : Velvet impose -3 en Initiative et en Perception. Elle ne masque jamais les états provoqués par les blessures physiques, de sorte qu’un corps réellement Tendu ou Paniqué par ses blessures reste soumis à ces états malgré la drogue.","data":{"Type":"Anxiolytique/recreatif","Profil":"Le Stress psychologique compte un cran plus bas pour explosif/échec narratif (Paniqué->Tendu, Tendu->Normal), sans masquer les états dus aux blessures. -3 Initiative/Perception."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'drogues-prism', 'Prism', NULL, '{"nature":"equipement","kind":"equipment","category":"Drogues","sourceCategory":"Drogues","price":50,"priceMin":50,"priceMax":100,"priceLabel":"50 - 100 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Altération forte des sens/perceptions ; outils sociaux ou artistiques seulement si la scene le justifie ; échec peut devenir Stress/désorientation.","lore":"Prism provoque une altération forte des sens et de la perception. Dans une scène où cette modification est réellement utile, elle peut ouvrir des possibilités sociales ou artistiques particulières en changeant la façon dont l’utilisateur reçoit et interprète ce qui l’entoure.\n\nCe potentiel n’est pas un bonus universel : il n’existe que si la scène justifie l’usage de cette perception altérée. Une mauvaise réaction ou un échec peut au contraire faire basculer l’expérience vers le Stress ou la désorientation et rendre la situation plus difficile à maîtriser.","data":{"Type":"Hallucinogene sensoriel","Profil":"Altération forte des sens/perceptions ; outils sociaux ou artistiques seulement si la scene le justifie ; échec peut devenir Stress/désorientation."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'drogues-redline', 'Redline', NULL, '{"nature":"equipement","kind":"equipment","category":"Drogues","sourceCategory":"Drogues","price":100,"priceMin":100,"priceMax":200,"priceLabel":"100 - 200 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Effort physique exceptionnel mais forte fatigue/risque physiologique ; utiliser circonstances favorables seulement dans l''usage precis prepare.","lore":"Redline est un stimulant de performance destiné aux situations où l’utilisateur cherche à soutenir un effort physique exceptionnel. Son intérêt se situe dans cet usage précis et préparé, plutôt que dans l’octroi d’un avantage permanent ou polyvalent.\n\nLa contrepartie est une forte fatigue accompagnée d’un risque physiologique réel. Les conséquences de Redline se traitent donc selon la scène et l’effort demandé : les circonstances favorables éventuelles ne valent que lorsque l’usage concret du stimulant les justifie.","data":{"Type":"Stimulant de performance","Profil":"Effort physique exceptionnel mais forte fatigue/risque physiologique ; utiliser circonstances favorables seulement dans l''usage precis prepare."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'drogues-bloom', 'Bloom', NULL, '{"nature":"equipement","kind":"equipment","category":"Drogues","sourceCategory":"Drogues","price":75,"priceMin":75,"priceMax":150,"priceLabel":"75 - 150 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Facilite chaleur sociale/intimite quand le contexte s''y prête ; expose à manipulation, dépendance et perte de jugement.","lore":"Bloom facilite la chaleur sociale et l’intimité lorsque le contexte s’y prête. Son intérêt apparaît donc dans les échanges où proximité, confiance et relâchement ont déjà un sens, plutôt que comme une manière automatique de rendre n’importe quel interlocuteur favorable.\n\nCette ouverture rend aussi l’utilisateur plus vulnérable. Manipulation, dépendance et perte de jugement font partie des risques associés à Bloom : ce qui rapproche les personnes dans un moment choisi peut devenir dangereux lorsque quelqu’un exploite cet état ou que l’usage cesse d’être maîtrisé.","data":{"Type":"Empathogene","Profil":"Facilite chaleur sociale/intimite quand le contexte s''y prête ; expose à manipulation, dépendance et perte de jugement."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'drogues-fleshfire', 'Fleshfire', NULL, '{"nature":"equipement","kind":"equipment","category":"Drogues","sourceCategory":"Drogues","price":150,"priceMin":150,"priceMax":300,"priceLabel":"150 - 300 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Surcharge volontaire des sensations/implants organiques ; effet dependant de l''augmentation ; risque Constitution/Stress.","lore":"Fleshfire pousse volontairement les sensations et les implants organiques vers la surcharge. L’expérience dépend directement des augmentations présentes chez l’utilisateur : la drogue ne produit donc pas un effet identique chez tous les corps ni avec tous les équipements biologiques.\n\nCette recherche d’intensité expose l’organisme à un véritable risque de Constitution ou de Stress. Plus l’effet sollicite fortement les sensations ou une augmentation organique, plus la scène doit tenir compte de ce que le corps est réellement capable d’encaisser au lieu de traiter Fleshfire comme un simple amplificateur sans limite.","data":{"Type":"Augmentique/sensoriel","Profil":"Surcharge volontaire des sensations/implants organiques ; effet dependant de l''augmentation ; risque Constitution/Stress."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'drogues-dreamrush', 'Dreamrush', NULL, '{"nature":"equipement","kind":"equipment","category":"Drogues","sourceCategory":"Drogues","price":30,"priceMin":30,"priceMax":75,"priceLabel":"30 - 75 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"En cas d''échec au test d''usage/retour : au minimum Tendu ou +1 cran ; échec narratif : Paniqué.","lore":"Dreamrush est une expérience dont le danger se révèle notamment au test d’usage ou de retour. Une mauvaise sortie n’est pas neutre : en cas d’échec, l’utilisateur devient au minimum Tendu ou voit son état de Stress augmenter d’un cran selon sa situation actuelle.\n\nUn échec narratif rend le retour beaucoup plus brutal et mène à Paniqué. La prise de Dreamrush doit donc être envisagée avec la phase de retour autant qu’avec l’expérience elle-même, car perdre pied au mauvais moment peut laisser l’utilisateur dans un état psychologique immédiatement exploitable par la scène.","data":{"Type":"Virtuelle","Profil":"En cas d''échec au test d''usage/retour : au minimum Tendu ou +1 cran ; échec narratif : Paniqué."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'drogues-crashware', 'Crashware', NULL, '{"nature":"equipement","kind":"equipment","category":"Drogues","sourceCategory":"Drogues","price":100,"priceMin":100,"priceMax":250,"priceLabel":"100 - 250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Overclock neuronal ; ajoute 1 Stress augmentique temporaire pendant l''effet et peut interagir dangereusement avec Neurodive.","lore":"Crashware fonctionne comme un overclock neuronal : pendant son effet, le système nerveux est poussé au-delà de son fonctionnement ordinaire afin de soutenir cette accélération artificielle. Cette sollicitation ajoute immédiatement 1 point de Stress augmentique temporaire tant que l’effet dure.\n\nLe risque devient particulièrement important lorsqu’il se combine au Neurodive, qui sollicite déjà directement l’interface neuronale. Crashware et immersion ne doivent donc pas être considérés comme deux avantages indépendants : leur interaction peut devenir dangereuse précisément parce qu’ils chargent le même système.","data":{"Type":"Logiciel-drogue Neuro","Profil":"Overclock neuronal ; ajoute 1 Stress augmentique temporaire pendant l''effet et peut interagir dangereusement avec Neurodive."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'services-medicaux-flashmergencies', 'Flashmergencies', NULL, '{"nature":"equipement","kind":"equipment","category":"Services médicaux","sourceCategory":"Services médicaux","price":0,"priceMin":null,"priceMax":null,"priceLabel":"Gratuit pour citoyen","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Urgences publiques ; disponibilite et delai dependent de la zone et de la situation.","lore":"Flashmergencies désigne le dispositif d’urgences publiques accessible aux citoyens. Il fournit une prise en charge réelle plutôt qu’un bonus abstrait : son rôle est de faire intervenir les secours lorsqu’une urgence médicale exige effectivement leur présence.\n\nLa disponibilité du service et son délai d’intervention dépendent directement de la zone et de la situation. Deux appels identiques peuvent donc recevoir des réponses très différentes selon l’endroit, la saturation locale et les circonstances de l’urgence.","data":{"Fonction":"Urgences publiques ; disponibilite et delai dependent de la zone et de la situation."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'services-medicaux-careforce-bronze', 'CareForce Bronze', NULL, '{"nature":"equipement","kind":"equipment","category":"Services médicaux","sourceCategory":"Services médicaux","price":800,"priceMin":null,"priceMax":null,"priceLabel":"800 $ / an","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Urgences privees niveau Bronze.","lore":"CareForce Bronze est le niveau Bronze des urgences privées CareForce. Il donne accès à cette filière médicale privée lorsqu’une urgence doit être prise en charge, en complément ou à la place des circuits publics auxquels un patient pourrait autrement devoir recourir.\n\nBronze reste le niveau d’entrée de cette couverture : il fournit le service prévu par la formule, mais pas la forte priorité des offres supérieures. Son intérêt concret est l’accès réel à une chaîne d’urgence privée, avec les moyens correspondant au niveau de couverture possédé.","data":{"Fonction":"Urgences privees niveau Bronze."},"vehicle":false,"neuro":false,"recurring":"annual","monthlyCost":66.66666666666667,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'services-medicaux-careforce-silver', 'CareForce Silver', NULL, '{"nature":"equipement","kind":"equipment","category":"Services médicaux","sourceCategory":"Services médicaux","price":1500,"priceMin":null,"priceMax":null,"priceLabel":"1 500 $ / an","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Priorite et couverture superieures ; correspond au Talent Crawler Assurance Silver.","lore":"CareForce Silver est un niveau de couverture médicale CareForce offrant une priorité et une couverture supérieures aux formules d’entrée de gamme. Il représente une prise en charge organisée et durable, et non un bonus automatique appliqué à chaque problème de santé.\n\nPour les Crawlers, cette couverture correspond directement au Talent Assurance Silver. Son intérêt concret est donc l’accès au niveau de service prévu par cette assurance lorsque des soins ou une intervention doivent réellement être obtenus.","data":{"Fonction":"Priorite et couverture superieures ; correspond au Talent Crawler Assurance Silver."},"vehicle":false,"neuro":false,"recurring":"annual","monthlyCost":125,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'services-medicaux-careforce-golden', 'CareForce Golden', NULL, '{"nature":"equipement","kind":"equipment","category":"Services médicaux","sourceCategory":"Services médicaux","price":5500,"priceMin":null,"priceMax":null,"priceLabel":"5 500 $ / an","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Couverture premium et priorite forte.","lore":"CareForce Golden est la couverture haut de gamme du réseau CareForce. Elle associe une prise en charge premium à une priorité forte lorsqu’une intervention médicale relevant du service doit être organisée, ce qui la distingue nettement des niveaux inférieurs.\n\nCette priorité ne remplace pas la médecine elle-même : gravité de la blessure, moyens nécessaires et disponibilité locale restent des réalités de la scène. Golden améliore surtout la position du patient dans la chaîne privée de prise en charge et l’accès au niveau de service prévu par cette couverture.","data":{"Fonction":"Couverture premium et priorite forte."},"vehicle":false,"neuro":false,"recurring":"annual","monthlyCost":458.3333333333333,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'services-medicaux-clinique-courante', 'Clinique courante', NULL, '{"nature":"equipement","kind":"equipment","category":"Services médicaux","sourceCategory":"Services médicaux","price":50,"priceMin":50,"priceMax":300,"priceLabel":"50 - 300 $+","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Consultation/soin banal hors urgence publique, selon acte.","lore":"Une clinique courante assure les consultations et les soins ordinaires qui ne relèvent pas d’une urgence publique. Elle couvre les actes médicaux banals dont la nature dépend du problème présenté, plutôt qu’une prestation unique identique pour tous les patients.\n\nLe service médical acheté correspond à une prise en charge réelle par la clinique. Il n’accorde pas de bonus abstrait par lui-même : ce qui compte est l’acte effectivement pratiqué, avec ses besoins, son suivi et les moyens médicaux mobilisés.","data":{"Fonction":"Consultation/soin banal hors urgence publique, selon acte."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'services-medicaux-chirurgie-hospitalisation', 'Chirurgie / hospitalisation', NULL, '{"nature":"equipement","kind":"equipment","category":"Services médicaux","sourceCategory":"Services médicaux","price":500,"priceMin":500,"priceMax":null,"priceLabel":"500 $ à plusieurs milliers","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Selon gravite, technologie et assurance.","lore":"Une chirurgie ou une hospitalisation recouvre des prises en charge dont l’ampleur varie énormément avec la gravité du cas et la technologie nécessaire. Une intervention simple, un séjour prolongé et une opération lourde ne mobilisent ni les mêmes équipes ni les mêmes moyens.\n\nL’assurance du patient compte également dans la manière dont cette prise en charge est accessible. Le service doit donc être évalué d’après l’acte médical réellement nécessaire, les installations requises et la couverture disponible, plutôt que comme une prestation médicale uniforme.","data":{"Fonction":"Selon gravite, technologie et assurance."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'services-medicaux-black-clinic', 'Black Clinic', NULL, '{"nature":"equipement","kind":"equipment","category":"Services médicaux","sourceCategory":"Services médicaux","price":null,"priceMin":null,"priceMax":null,"priceLabel":"Variable","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Accès clandestin. Le prix dépend surtout du risque, de la provenance des pièces et de l''anonymat.","lore":"Une Black Clinic fournit un accès médical clandestin lorsque la filière officielle n’est pas adaptée ou souhaitée. L’accès lui-même suppose un réseau crédible : le Talent Crawler Black Clinic représente précisément une entrée auprès d’au moins une clinique noire ou d’un réseau Meditech.\n\nLes conditions varient surtout avec le risque, la provenance des pièces nécessaires et le niveau d’anonymat recherché. La clandestinité est donc au cœur de la prestation : disponibilité et conditions dépendent du réseau mobilisé plutôt que d’un service public standardisé.","data":{"Fonction":"Accès clandestin. Le prix dépend surtout du risque, de la provenance des pièces et de l''anonymat."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'services-professionnels-formation-courte-adulte', 'Formation courte / adulte', NULL, '{"nature":"equipement","kind":"equipment","category":"Services professionnels","sourceCategory":"Services professionnels","price":100,"priceMin":100,"priceMax":500,"priceLabel":"100 - 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Mise à niveau, certification, module professionnel.","lore":"Une formation courte pour adulte sert à remettre à niveau une pratique, obtenir une certification ou suivre un module professionnel ciblé. Elle répond à un besoin défini et limité, sans prétendre remplacer un cursus long ou l’expérience accumulée dans un métier.\n\nLe résultat dépend du contenu effectivement suivi : certaines formations valident une procédure, d’autres actualisent des connaissances ou ouvrent l’accès à une certification précise. S’inscrire à une session ne transforme donc pas instantanément le participant en expert du domaine entier.","data":{"Usage":"Mise à niveau, certification, module professionnel."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'services-professionnels-expertise-technique-medicale', 'Expertise technique/medicale', NULL, '{"nature":"equipement","kind":"equipment","category":"Services professionnels","sourceCategory":"Services professionnels","price":100,"priceMin":100,"priceMax":500,"priceLabel":"100 - 500 $ / intervention","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Diagnostic, analyse, rapport, procedure specialisee.","lore":"Une expertise technique ou médicale mobilise un spécialiste pour produire un diagnostic, une analyse, un rapport ou une procédure adaptée à un problème précis. Elle permet d’obtenir un regard professionnel lorsque la situation dépasse une simple inspection ou un entretien courant.\n\nL’expertise reste limitée à son objet et aux moyens disponibles. Un rapport peut identifier une cause sans fournir les pièces nécessaires pour la réparer, comme un diagnostic médical peut déterminer un traitement sans remplacer l’intervention qui devra ensuite être pratiquée.","data":{"Usage":"Diagnostic, analyse, rapport, procedure specialisee."},"vehicle":false,"neuro":false,"recurring":"per_use","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'services-professionnels-reparation-courante', 'Réparation courante', NULL, '{"nature":"equipement","kind":"equipment","category":"Services professionnels","sourceCategory":"Services professionnels","price":50,"priceMin":50,"priceMax":250,"priceLabel":"50 - 250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Matériel standard hors pièces rares.","lore":"Une réparation courante concerne du matériel standard dont la panne peut être traitée avec un atelier et des pièces ordinaires. Elle couvre l’entretien, le remplacement d’éléments accessibles et la remise en état lorsque l’intervention ne réclame ni composant rare ni procédure exceptionnelle.\n\nLe service dépend donc autant de la nature de la panne que du matériel concerné. Si le diagnostic révèle une pièce introuvable, une calibration spécialisée ou des dommages structurels importants, l’intervention sort du cadre d’une réparation courante et exige une prise en charge plus lourde.","data":{"Usage":"Matériel standard hors pièces rares."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'services-professionnels-reparation-lourde-augmentique', 'Réparation lourde / augmentique', NULL, '{"nature":"equipement","kind":"equipment","category":"Services professionnels","sourceCategory":"Services professionnels","price":250,"priceMin":250,"priceMax":2000,"priceLabel":"250 - 2 000 $+","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Atelier, calibration, chirurgie ou piece spécifique.","lore":"Une réparation lourde ou augmentique intervient lorsque la remise en état réclame un véritable atelier, une calibration précise, une chirurgie ou une pièce spécifique. Elle peut concerner aussi bien un système technique complexe qu’une augmentation intégrée au corps de son utilisateur.\n\nCe niveau d’intervention ne se résume pas à disposer d’un tournevis ou d’un kit de terrain. Il faut réunir le lieu, la compétence et les composants adaptés au problème ; dans le cas d’un implant, les contraintes médicales s’ajoutent directement aux exigences purement techniques.","data":{"Usage":"Atelier, calibration, chirurgie ou piece spécifique."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'services-professionnels-faux-document-identite', 'Faux document / identite', NULL, '{"nature":"equipement","kind":"equipment","category":"Services professionnels","sourceCategory":"Services professionnels","price":500,"priceMin":500,"priceMax":5000,"priceLabel":"500 - 5 000 $+","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Dépend fortement du niveau de contrôle attendu et du réseau.","lore":"Un faux document ou une fausse identité est une prestation dont la crédibilité dépend du niveau de contrôle auquel elle doit résister. La même couverture n’a donc pas la même valeur selon qu’elle doit seulement passer un examen ordinaire ou affronter une vérification plus exigeante.\n\nLe réseau disponible compte autant que le document lui-même. La qualité de la filière, l’accès aux bonnes ressources et le contrôle attendu déterminent ce que le service peut réellement fournir ; il ne crée pas à lui seul une réussite automatique face à n’importe quelle vérification.","data":{"Usage":"Dépend fortement du niveau de contrôle attendu et du réseau."},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'services-professionnels-service-juridique', 'Service juridique', NULL, '{"nature":"equipement","kind":"equipment","category":"Services professionnels","sourceCategory":"Services professionnels","price":100,"priceMin":100,"priceMax":500,"priceLabel":"100 - 500 $ / h ou forfait","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Conseil/representation ; souvent fourni par une institution.","lore":"Un service juridique fournit du conseil et de la représentation dans une affaire réelle. Il s’agit d’une compétence professionnelle mobilisée pour une situation précise, souvent fournie ou organisée par une institution plutôt que d’un avantage générique attaché au personnage.\n\nDans un cadre corporatiste, l’avantage Service juridique donne une assistance légale pour les affaires relevant réellement du travail. L’étendue de l’aide dépend donc du dossier, du cadre institutionnel et du domaine dans lequel la représentation est effectivement assurée.","data":{"Usage":"Conseil/representation ; souvent fourni par une institution."},"vehicle":false,"neuro":false,"recurring":"per_use","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'services-professionnels-securite-privee', 'Sécurité privée', NULL, '{"nature":"equipement","kind":"equipment","category":"Services professionnels","sourceCategory":"Services professionnels","price":250,"priceMin":250,"priceMax":null,"priceLabel":"250 $ / jour à plusieurs milliers","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Garde, escorte, evenement, intervention selon armement.","lore":"La sécurité privée peut prendre la forme d’un garde, d’une escorte, d’un dispositif pour un événement ou d’une équipe d’intervention. La prestation doit être définie par la mission demandée : protéger une personne en déplacement n’implique pas les mêmes moyens que tenir un site ou répondre à une alerte.\n\nL’armement et le niveau d’engagement des agents font partie de cette définition. Engager de la sécurité n’accorde donc pas une protection abstraite : cela met de vraies personnes et de vrais moyens sur une mission, avec les capacités, limites et règles d’intervention correspondant au contrat retenu.","data":{"Usage":"Garde, escorte, evenement, intervention selon armement."},"vehicle":false,"neuro":false,"recurring":"per_use","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'services-professionnels-stockage-box-atelier', 'Stockage / box / atelier', NULL, '{"nature":"equipement","kind":"equipment","category":"Services professionnels","sourceCategory":"Services professionnels","price":50,"priceMin":50,"priceMax":500,"priceLabel":"50 - 500 $ / mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Petit local, espace technique ou stockage.","lore":"Un stockage, un box ou un petit atelier fournit un local distinct du logement pour entreposer du matériel ou disposer d’un espace technique. La fonction réelle dépend du lieu loué : un simple volume fermé, un espace de travail et un atelier équipé ne répondent pas aux mêmes besoins.\n\nIl ne faut donc pas supposer automatiquement alimentation renforcée, outils, sécurité élevée ou anonymat. Le service garantit l’espace correspondant à la formule choisie ; équipements, accès, discrétion et possibilités de travail dépendent ensuite des caractéristiques concrètes du local.","data":{"Usage":"Petit local, espace technique ou stockage."},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":50,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'loisirs-media-holonet-reseaux', 'Média Holonet / réseaux', NULL, '{"nature":"equipement","kind":"equipment","category":"Applications Holonet","sourceCategory":"Applications Holonet","price":0,"priceMin":0,"priceMax":20,"priceLabel":"Gratuit à 20 $/mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Les médias Holonet et réseaux forment la couche continue de la vie connectée : information, divertissement, communauté, musique, vidéo et conversations se mélangent dans des interfaces que chacun personnalise autour de son profil. Pour beaucoup d’habitants, consulter le réseau ne constitue plus une activité séparée mais l’arrière-plan permanent de la journée.\n\nL’accès de base peut être extrêmement large, tandis que visibilité, archives, flux premium ou communautés fermées créent les véritables différences. Le Holonet ne remplace pas tous les services spécialisés : il est surtout l’espace dans lequel applications, identités et publics se rencontrent, avec les mêmes problèmes de réputation et de traçage que toute vie sociale.","data":{},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'loisirs-bar-club-sortie-populaire', 'Bar, club, sortie populaire', NULL, '{"nature":"equipement","kind":"equipment","category":"Loisirs","sourceCategory":"Loisirs","price":10,"priceMin":10,"priceMax":50,"priceLabel":"10 - 50 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Une sortie populaire en bar ou en club reste l’une des manières les plus simples de rencontrer physiquement d’autres personnes dans une société pourtant très connectée. Quartier, musique, clientèle et sécurité donnent au lieu son identité bien plus que la sophistication technique de ses installations.\n\nCes établissements forment aussi une géographie sociale très concrète : on sait où sortent les ouvriers d’un secteur, les étudiants, les Neopunks ou les employés d’une corporation voisine. Fréquenter le bon bar peut donc renseigner sur un quartier et ses réseaux, sans pour autant accorder automatiquement contacts ou réputation.","data":{},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'loisirs-concert-spectacle-sport', 'Concert, spectacle, sport', NULL, '{"nature":"equipement","kind":"equipment","category":"Loisirs","sourceCategory":"Loisirs","price":25,"priceMin":25,"priceMax":150,"priceLabel":"25 - 150 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Concerts, spectacles et compétitions sportives conservent une valeur particulière parce qu’ils rassemblent un public réel autour d’un événement qui n’existe qu’à un moment donné. Le Holonet peut diffuser une performance parfaitement, mais il ne reproduit pas complètement la foule, le déplacement ni la présence partagée dans un même lieu.\n\nLe prix et l’expérience varient alors surtout avec la place, l’accès et l’importance de l’événement. Pour certains habitants, ces sorties sont des plaisirs occasionnels ; pour d’autres elles constituent un rituel social où l’on retrouve les mêmes groupes, soutient une scène locale ou se montre dans un milieu précis.","data":{},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'loisirs-immersion-experience-premium', 'Immersion / experience premium', NULL, '{"nature":"equipement","kind":"equipment","category":"Loisirs","sourceCategory":"Loisirs","price":100,"priceMin":100,"priceMax":500,"priceLabel":"100 - 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Une immersion ou expérience premium vend davantage qu’un contenu : environnement sensoriel, mise en scène, encadrement et matériel sont arrangés pour donner au client l’impression d’entrer temporairement dans une autre situation. C’est le segment du loisir où le décor et la technologie deviennent eux-mêmes une prestation.\n\nLa clientèle paie pour la qualité de la simulation, le confort et le soin apporté à l’expérience autant que pour son thème. Ces offres peuvent côtoyer le Neurodive sans s’y confondre : une immersion commerciale n’accorde aucune capacité de Crawler et ne suppose pas nécessairement une connexion neurale profonde.","data":{},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'loisirs-evenement-luxe-vip', 'Evenement luxe / VIP', NULL, '{"nature":"equipement","kind":"equipment","category":"Loisirs","sourceCategory":"Loisirs","price":500,"priceMin":500,"priceMax":null,"priceLabel":"500 $+","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Un événement luxe ou VIP repose autant sur le filtrage de l’accès que sur le spectacle proposé. Espace réservé, service individualisé, proximité avec certaines personnes et contrôle de la clientèle créent un environnement où l’on paie pour ne pas vivre l’événement comme tout le monde.\n\nDans les milieux aisés, ces espaces servent aussi de lieux de représentation : inviter quelqu’un, être reconnu à l’entrée ou être vu dans une zone réservée peut compter autant que la programmation. Cette valeur sociale reste contextuelle ; posséder un billet VIP ne donne pas à lui seul du statut hors du cercle qui s’y intéresse.","data":{},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'loisirs-compagnie-sociale-courte', 'Compagnie sociale courte', NULL, '{"nature":"equipement","kind":"equipment","category":"Loisirs","sourceCategory":"Loisirs","price":10,"priceMin":10,"priceMax":50,"priceLabel":"10 - 50 $/h","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"La Compagnie sociale courte est une prestation de présence : accompagner un dîner, tenir une conversation, servir de partenaire lors d’une sortie ou aider quelqu’un à ne pas arriver seul à un événement. Elle professionnalise un besoin social sans impliquer par défaut de relation intime ou sexuelle.\n\nLe métier demande surtout adaptation, écoute et compréhension du cadre demandé par le client. Selon le milieu, l’accompagnateur peut se rapprocher d’un hôte, d’un partenaire mondain ou d’une présence rassurante ; la prestation reste un contrat de temps et de comportement, pas l’achat d’une relation personnelle authentique.","data":{},"vehicle":false,"neuro":false,"recurring":"per_use","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'loisirs-compagnie-intime-prostitution-legale', 'Compagnie intime/prostitution legale', NULL, '{"nature":"equipement","kind":"equipment","category":"Loisirs","sourceCategory":"Loisirs","price":50,"priceMin":50,"priceMax":150,"priceLabel":"50 - 150 $/h+","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"La compagnie intime légale appartient au secteur adulte réglementé et peut inclure une relation sexuelle consentie dans les limites du contrat établi. Elle se distingue de la compagnie sociale par la nature explicite de la prestation, mais reste un service professionnel avec ses règles, intermédiaires et conditions de sécurité.\n\nÉtablissement, indépendance, contrôle sanitaire, discrétion et standing produisent des expériences très différentes derrière une même catégorie. Dans une grande métropole, la clientèle va du rendez-vous banal au service très haut de gamme ; le prix ne dit jamais à lui seul comment le travail est organisé ni qui le protège.","data":{},"vehicle":false,"neuro":false,"recurring":"per_use","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'logements-squat-zone-abandonnee', 'Squat / zone abandonnee', NULL, '{"nature":"equipement","kind":"equipment","category":"Logements","sourceCategory":"Logements","price":0,"priceMin":null,"priceMax":null,"priceLabel":"0 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Aucune connectivite fiable.","lore":"Un squat ou une zone abandonnée offre un abri parce que le lieu est délaissé, pas parce qu’il fournit un véritable service de logement. L’occupation dépend de l’état du bâtiment et de la possibilité d’y rester sans disposer des garanties d’un habitat entretenu.\n\nLa connectivité y est explicitement peu fiable. Holonet, services domestiques et sécurisation ne peuvent donc pas être présumés : confort, accès et protection dépendent de ce qui fonctionne encore réellement sur place.","data":{"Securite typique":"12 ou aucun systeme","Notes":"Aucune connectivite fiable."},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'logements-dortoir-ouvrier', 'Dortoir ouvrier', NULL, '{"nature":"equipement","kind":"equipment","category":"Logements","sourceCategory":"Logements","price":150,"priceMin":150,"priceMax":300,"priceLabel":"150 - 300 $/mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Basique, dense.","lore":"Le dortoir ouvrier est un logement collectif basique conçu autour de la densité d’occupation. Il fournit un hébergement stable sans rechercher l’espace individuel ou le standing, et représente une solution fonctionnelle avant d’être confortable.\n\nSa logique collective implique que le lieu se partage avec de nombreux autres occupants et que l’intimité y reste limitée. Le dortoir donne un toit et une place identifiable, mais pas les avantages d’un logement autonome ou fortement sécurisé.","data":{"Securite typique":"12-15","Notes":"Basique, dense."},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":150,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'logements-vladic-micro-logement', 'Vladic micro-logement', NULL, '{"nature":"equipement","kind":"equipment","category":"Logements","sourceCategory":"Logements","price":150,"priceMin":150,"priceMax":250,"priceLabel":"150 - 250 $/mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Bon marche ; forte dépendance sociale/turf.","lore":"Le micro-logement Vladic constitue le premier échelon du parc immobilier gravitant autour de Vladic et de son réseau mafieux russe. Il faut l’imaginer comme une chambre autonome ou un très petit studio récupéré dans un immeuble du territoire, parfois issu d’un ancien logement subdivisé : peu d’espace, peu de prestige, mais une adresse stable accessible à quelqu’un que le réseau accepte de loger.\n\nSon faible coût apparent se paie surtout en dépendance sociale. Le propriétaire, le gardien, un voisin ou un commerce proche peut connaître le visage de l’occupant et savoir par qui il est arrivé là ; on n’habite donc pas vraiment anonymement chez Vladic. Le même tissu humain qui facilite l’accès au logement peut rendre rapidement compte d’un loyer en retard, d’un visiteur inhabituel ou d’un locataire qui commence à poser problème.","data":{"Securite typique":"15","Notes":"Bon marche ; forte dépendance sociale/turf."},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":150,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'logements-vladic-studio', 'Vladic studio', NULL, '{"nature":"equipement","kind":"equipment","category":"Logements","sourceCategory":"Logements","price":250,"priceMin":250,"priceMax":400,"priceLabel":"250 - 400 $/mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Réseau Vladic, suivi social implicite.","lore":"Le studio Vladic marque un cran d’autonomie supplémentaire dans la même économie immobilière de territoire. C’est vraisemblablement un véritable petit appartement plutôt qu’une simple chambre : assez d’espace pour vivre seul sans promiscuité immédiate, dans un bâtiment où plusieurs lots, commerces ou intermédiaires peuvent appartenir directement ou indirectement à la sphère de Vladic.\n\nLe réseau reste cependant présent en arrière-plan. Un occupant régulier devient un visage connu de l’immeuble et du quartier, et cette familiarité fonctionne dans les deux sens : elle donne accès à un environnement moins indifférent qu’une location anonyme, mais signifie aussi que les habitudes, les visiteurs et les absences se remarquent. La protection éventuelle vient de cette implantation sociale, pas d’une fortification du studio.","data":{"Securite typique":"15","Notes":"Réseau Vladic, suivi social implicite."},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":250,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'logements-studio-urbain-ancien', 'Studio urbain ancien', NULL, '{"nature":"equipement","kind":"equipment","category":"Logements","sourceCategory":"Logements","price":350,"priceMin":350,"priceMax":600,"priceLabel":"350 - 600 $/mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Ancien bâti, sécurité connectée variable.","lore":"Le studio urbain ancien appartient au bâti vieillissant de la ville : un logement individuel ordinaire dont les infrastructures ont été adaptées, entretenues ou remplacées de manière très variable au fil du temps.\n\nLa sécurité connectée y est donc inégale. Avant de compter sur une serrure intelligente, une alerte ou une domotique fiable, il faut regarder ce que le logement possède réellement plutôt que supposer qu’un vieux studio dispose du niveau numérique d’une construction récente.","data":{"Securite typique":"15","Notes":"Ancien bâti, sécurité connectée variable."},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":350,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'logements-vladic-familial', 'Vladic familial', NULL, '{"nature":"equipement","kind":"equipment","category":"Logements","sourceCategory":"Logements","price":450,"priceMin":450,"priceMax":700,"priceLabel":"450 - 700 $/mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Familial/protégé par le territoire.","lore":"Le logement familial Vladic correspond à un appartement capable d’accueillir durablement plusieurs personnes : plusieurs pièces, davantage de rangements et une vraie vie domestique, probablement dans les barres ou ensembles où le réseau dispose déjà d’une implantation solide. Dans la gamme Vladic, ce n’est plus seulement un toit de dépannage mais un logement que l’on peut occuper des années et autour duquel se construit une vie de quartier.\n\nCette stabilité renforce aussi l’inscription dans le territoire. Les voisins connaissent les enfants, les commerces connaissent les habitudes et certaines figures locales savent quelles familles relèvent de qui ; pour un officier mafieux, ce maillage vaut souvent mieux qu’une caméra isolée. Il peut rendre une présence étrangère rapidement visible et susciter une réaction locale, sans jamais constituer un bonus de combat pour les habitants eux-mêmes.","data":{"Securite typique":"15-18","Notes":"Familial/protégé par le territoire."},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":450,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'logements-appartement-connecte', 'Appartement connecté', NULL, '{"nature":"equipement","kind":"equipment","category":"Logements","sourceCategory":"Logements","price":650,"priceMin":650,"priceMax":1000,"priceLabel":"650 - 1 000 $/mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Domotique, alerte, services.","lore":"L’appartement connecté intègre directement domotique, systèmes d’alerte et services numériques au fonctionnement du logement. Les tâches domestiques et la gestion quotidienne peuvent ainsi s’appuyer sur un ensemble d’équipements reliés plutôt que sur des appareils isolés.\n\nLe niveau réel de confort ou de sécurité dépend toutefois des fonctions effectivement installées. Un appartement connecté fournit l’infrastructure pour automatiser et surveiller le domicile ; il ne suppose pas que chaque service possible soit présent dans tous les logements de cette catégorie.","data":{"Securite typique":"18","Notes":"Domotique, alerte, services."},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":650,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'logements-vladic-grand-protege', 'Vladic grand/protégé', NULL, '{"nature":"equipement","kind":"equipment","category":"Logements","sourceCategory":"Logements","price":800,"priceMin":800,"priceMax":1200,"priceLabel":"800 - 1 200 $/mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Protection de quartier, pas bonus de combat.","lore":"Le qualificatif « grand/protégé » place ce logement au sommet de la gamme Vladic ordinaire. Il évoque vraisemblablement un T4, un T5 ou un appartement encore plus vaste, autour de la centaine de mètres carrés lorsque le bâti le permet, parfois obtenu en rénovant ou réunissant plusieurs lots d’une barre déjà tenue par le réseau. Ce type d’adresse convient à une famille installée, à un lieutenant utile ou à quelqu’un que Vladic a intérêt à loger correctement plutôt qu’à un locataire de passage.\n\nSa véritable protection vient du territoire autant que de la porte d’entrée : gardien qui connaît les résidents, voisins qui remarquent les inconnus, commerces qui voient les véhicules inhabituels et petites mains capables de faire remonter une information vers le réseau. Un intrus qui rôde peut donc devenir un problème collectif avant d’atteindre l’appartement. Cela reste une protection de quartier, sociale et mafieuse, pas un bonus de combat une fois la violence entrée dans le logement.","data":{"Securite typique":"18","Notes":"Protection de quartier, pas bonus de combat."},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":800,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'logements-residence-de-cadre-securisee', 'Résidence de cadre sécurisée', NULL, '{"nature":"equipement","kind":"equipment","category":"Logements","sourceCategory":"Logements","price":2000,"priceMin":2000,"priceMax":5000,"priceLabel":"2 000 - 5 000 $/mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Sécurité, services et quartier.","lore":"La résidence de cadre sécurisée combine un logement de bon standing avec un environnement où sécurité, services et qualité du quartier font partie de la prestation. Elle vise une vie quotidienne plus encadrée qu’un simple appartement urbain.\n\nLa protection ne se résume donc pas à une serrure plus solide : elle repose sur l’ensemble formé par le bâtiment, les services disponibles et le secteur où se trouve la résidence. Les moyens précis restent ceux réellement présents sur le site.","data":{"Securite typique":"18-21","Notes":"Sécurité, services et quartier."},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":2000,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'logements-penthouse-villa', 'Penthouse / villa', NULL, '{"nature":"equipement","kind":"equipment","category":"Logements","sourceCategory":"Logements","price":5000,"priceMin":5000,"priceMax":20000,"priceLabel":"5 000 - 20 000 $+/mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Standing, sécurité et services premium.","lore":"Le penthouse ou la villa représente le sommet du logement privé courant : espace, standing, sécurité et services premium sont réunis dans un habitat pensé autant pour le confort que pour la représentation sociale.\n\nCette catégorie décrit un niveau de prestation, pas un plan de sécurité unique. Personnel, contrôle d’accès, domotique ou surveillance peuvent varier d’une propriété à l’autre ; ce qui est garanti est le niveau élevé de standing et de services attendu du lieu.","data":{"Securite typique":"21+","Notes":"Standing, sécurité et services premium."},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":5000,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'planques-cache-improvisee', 'Cache improvisee', NULL, '{"nature":"equipement","kind":"equipment","category":"Planques","sourceCategory":"Planques","price":0,"priceMin":0,"priceMax":100,"priceLabel":"0 - 100 $/mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Dissimulation par abandon/oubli ; peu de sécurité.","lore":"Une cache improvisée se dissimule surtout par abandon ou par oubli : un recoin, local ou espace que personne ne regarde vraiment et qui peut servir tant qu’il reste hors de l’attention ordinaire. Sa discrétion vient davantage de son insignifiance apparente que d’un dispositif sophistiqué.\n\nElle offre peu de sécurité. Il ne faut présumer ni contre-surveillance, ni accès renforcé, ni réseau fiable ; si quelqu’un identifie la cache et vient la chercher, le lieu dispose rarement de moyens propres pour résister à cette découverte.","data":{"Securite":"12","Usage":"Dissimulation par abandon/oubli ; peu de sécurité."},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'planques-piece-box-squat-discret', 'Piece/box/squat discret', NULL, '{"nature":"equipement","kind":"equipment","category":"Planques","sourceCategory":"Planques","price":150,"priceMin":150,"priceMax":400,"priceLabel":"150 - 400 $/mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Usage court, faible empreinte.","lore":"Une pièce, un box ou un squat discret sert de planque de courte durée en recherchant avant tout une faible empreinte. Le lieu est choisi pour rester banal et peu remarqué plutôt que pour devenir une installation permanente et fortement équipée.\n\nCette discrétion fonctionne tant que l’usage reste contenu. Plus on y accumule de matériel, de passages ou de connexions, plus on s’éloigne de ce qui fait sa force : un espace temporaire dont la présence attire peu l’attention.","data":{"Securite":"12-15","Usage":"Usage court, faible empreinte."},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":150,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'planques-studio-garage-anonyme', 'Studio/garage anonyme', NULL, '{"nature":"equipement","kind":"equipment","category":"Planques","sourceCategory":"Planques","price":400,"priceMin":400,"priceMax":800,"priceLabel":"400 - 800 $/mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Identite/location choisie, stockage.","lore":"Le studio ou garage anonyme est une planque stable dont l’identité associée et l’emplacement sont choisis pour ne pas renvoyer directement vers la vie ordinaire de son utilisateur. Le lieu fournit également un espace de stockage exploitable.\n\nL’anonymat constitue ici la première couche de protection. Il sépare une activité ou du matériel de l’adresse habituelle, mais n’implique pas automatiquement une sécurité physique élevée : celle-ci dépend encore des équipements réellement ajoutés au site.","data":{"Securite":"15","Usage":"Identite/location choisie, stockage."},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":400,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'planques-planque-dediee', 'Planque dediee', NULL, '{"nature":"equipement","kind":"equipment","category":"Planques","sourceCategory":"Planques","price":800,"priceMin":800,"priceMax":2000,"priceLabel":"800 - 2 000 $/mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Serrures, cameras, connectivite choisie ou isolement.","lore":"Une planque dédiée est préparée spécifiquement pour cet usage. Serrures, caméras et organisation des accès peuvent y être choisis dès l’installation, avec une connectivité volontairement mise en place ou au contraire un isolement réseau recherché.\n\nCette maîtrise de la connectivité compte autant que la fermeture des portes : selon le besoin, la planque peut privilégier l’accès au Holonet ou réduire sa surface numérique. Elle devient ainsi un lieu configuré pour une fonction clandestine précise plutôt qu’un logement détourné.","data":{"Securite":"18","Usage":"Serrures, cameras, connectivite choisie ou isolement."},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":800,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'planques-planque-securisee', 'Planque sécurisée', NULL, '{"nature":"equipement","kind":"equipment","category":"Planques","sourceCategory":"Planques","price":2000,"priceMin":2000,"priceMax":5000,"priceLabel":"2 000 - 5 000 $/mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Anonymat, contre-surveillance, plusieurs accès.","lore":"Une planque sécurisée ajoute à l’anonymat des moyens de contre-surveillance et plusieurs accès possibles. Elle est pensée pour limiter la capacité d’un observateur à confirmer qui utilise le lieu et pour éviter qu’une seule entrée ne conditionne tous les déplacements.\n\nLa sécurité repose donc sur la préparation du site autant que sur ses protections physiques. Surveillance adverse, accès compromis ou identité découverte restent des menaces possibles, mais la planque fournit des moyens dédiés pour les détecter, les compliquer ou s’en dégager.","data":{"Securite":"18-21","Usage":"Anonymat, contre-surveillance, plusieurs accès."},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":2000,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'planques-reseau-de-planques-premium', 'Réseau de planques premium', NULL, '{"nature":"equipement","kind":"equipment","category":"Planques","sourceCategory":"Planques","price":5000,"priceMin":5000,"priceMax":15000,"priceLabel":"5 000 - 15 000 $+/mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Plusieurs sites, identités, logistique et sécurité.","lore":"Un réseau de planques premium ne repose plus sur une adresse unique : plusieurs sites, identités de couverture, moyens logistiques et dispositifs de sécurité sont maintenus comme un ensemble cohérent. La clandestinité devient une infrastructure plutôt qu’un simple lieu de repli.\n\nSa force tient à cette redondance. Un site compromis n’épuise pas nécessairement toutes les solutions disponibles, et la logistique du réseau permet de déplacer personnes ou matériel entre plusieurs points préparés au lieu de dépendre d’une seule cache.","data":{"Securite":"21+","Usage":"Plusieurs sites, identités, logistique et sécurité."},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":5000,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'transports-metro-tram', 'Metro / tram', NULL, '{"nature":"equipement","kind":"equipment","category":"Transports","sourceCategory":"Transports","price":2,"priceMin":2,"priceMax":5,"priceLabel":"2 - 5 $ / trajet","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Métro et tram constituent l’ossature visible de la mobilité collective dans les zones denses. Leur force n’est pas la personnalisation mais la capacité à déplacer continuellement de grandes quantités de personnes le long d’axes connus, indépendamment de la possession d’un véhicule ou de la disponibilité d’un service individuel.\n\nLe réseau dessine aussi la ville sociale : vivre près d’une station change les temps de trajet, certains quartiers respirent au rythme des correspondances et les heures de pointe imposent leurs propres contraintes. Pour les revenus modestes, le transport collectif reste souvent ce qui rend possible un emploi éloigné du logement.","data":{},"vehicle":false,"neuro":false,"recurring":"per_use","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'transports-pass-metro-tram', 'Pass metro/tram', NULL, '{"nature":"equipement","kind":"equipment","category":"Transports","sourceCategory":"Transports","price":60,"priceMin":60,"priceMax":100,"priceLabel":"60 - 100 $ / mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le Pass métro/tram transforme le réseau collectif en service continu plutôt qu’en suite de décisions à chaque trajet. Il correspond à la vie de quelqu’un qui se déplace assez régulièrement pour intégrer le transport public à son budget mensuel, au même titre que la connexion ou le logement.\n\nCette logique en fait une charge fixe typique des travailleurs et étudiants qui organisent leur quotidien autour du réseau. Le pass achète une facilité d’accès, pas une priorité de circulation ni un confort supérieur ; les mêmes quais, retards et foules restent partagés avec les autres usagers.","data":{},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":60,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'transports-mas-court-trajet', 'MAS - court trajet', NULL, '{"nature":"equipement","kind":"equipment","category":"Transports","sourceCategory":"Transports","price":5,"priceMin":5,"priceMax":10,"priceLabel":"5 - 10 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Un MAS de court trajet est un déplacement motorisé à la demande pour les portions de ville que la marche ou le réseau collectif desservent mal. Dans la Grande Californie, ces services ont repris une grande partie du rôle autrefois partagé entre taxi, bus flexible et navette privée.\n\nLe passager achète le trajet plutôt que le véhicule : conduite, navigation, entretien et stationnement restent à la charge de l’opérateur. C’est particulièrement pratique pour une course ponctuelle, un retour tardif ou le dernier segment entre une station et une destination peu accessible.","data":{},"vehicle":false,"neuro":false,"recurring":"per_use","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'transports-mas-trajet-long-urbain', 'MAS - trajet long urbain', NULL, '{"nature":"equipement","kind":"equipment","category":"Transports","sourceCategory":"Transports","price":10,"priceMin":10,"priceMax":25,"priceLabel":"10 - 25 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Le MAS longue distance urbaine applique le même principe à une traversée plus importante de la mégapole. Il offre une continuité porte-à-porte que le métro exige souvent de reconstruire par plusieurs correspondances, sans obliger le passager à posséder ou conduire son propre véhicule.\n\nCe confort devient vite coûteux lorsqu’il est répété quotidiennement, ce qui explique l’existence des abonnements de mobilité plus structurés. Le MAS reste donc très courant pour les déplacements occasionnels ou contraints, mais moins rationnel comme unique solution permanente pour qui traverse la ville chaque jour.","data":{},"vehicle":false,"neuro":false,"recurring":"per_use","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'transports-bull-basic', 'Bull Basic', NULL, '{"nature":"equipement","kind":"equipment","category":"Transports","sourceCategory":"Transports","price":150,"priceMin":null,"priceMax":null,"priceLabel":"150 $ / mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Bull Basic est l’entrée de gamme d’un abonnement de mobilité pensé pour ceux qui veulent une disponibilité régulière sans posséder de voiture. La marque vend moins un véhicule précis qu’une place permanente dans son infrastructure de déplacement, cohérente avec un Train de vie Standard.\n\nPour un citadin, l’intérêt est de transformer une succession de courses et de problèmes d’entretien en une dépense prévisible. Basic reste une formule fonctionnelle : elle répond au besoin de se déplacer, sans prétendre offrir le standing ou les garanties de service que Bull réserve à ses niveaux supérieurs.","data":{},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":150,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'transports-bull-standard', 'Bull Standard', NULL, '{"nature":"equipement","kind":"equipment","category":"Transports","sourceCategory":"Transports","price":300,"priceMin":null,"priceMax":null,"priceLabel":"300 $ / mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Bull Standard constitue le cœur de la gamme d’abonnements de mobilité de la marque. Il vise la clientèle qui utilise suffisamment souvent le service pour vouloir en faire sa solution normale de déplacement, tout en restant dans les habitudes budgétaires d’un Train de vie Standard.\n\nLa différence avec l’entrée Basic tient à la place plus confortable que le service prend dans le quotidien, pas à la possession d’un véhicule. Le client reste utilisateur d’un réseau : il achète simplicité et disponibilité, tandis que Bull conserve l’entretien, la flotte et l’organisation des trajets.","data":{},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":300,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'transports-bull-premium', 'Bull Premium', NULL, '{"nature":"equipement","kind":"equipment","category":"Transports","sourceCategory":"Transports","price":750,"priceMin":null,"priceMax":null,"priceLabel":"750 $ / mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Bull Premium fait passer l’abonnement de mobilité dans le registre Confortable. À ce niveau, le client ne cherche plus seulement à éviter l’achat d’une voiture ; il veut que le service soit suffisamment présent et agréable pour devenir une alternative assumée à un véhicule personnel de bonne qualité.\n\nCette position place Premium en concurrence avec d’autres choix de confort comme un VAP familial ou une moto haut de gamme. Le choix devient autant une question de mode de vie que de coût : préférer déléguer conduite et entretien, ou préférer garder un véhicule disponible sous son propre contrôle.","data":{},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":750,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'transports-bull-executive', 'Bull Executive', NULL, '{"nature":"equipement","kind":"equipment","category":"Transports","sourceCategory":"Transports","price":1500,"priceMin":null,"priceMax":null,"priceLabel":"1 500 $ / mois","generation":null,"charge":null,"stress":null,"slots":null,"effect":"","lore":"Bull Executive est la formule haute de la gamme, destinée à une clientèle Aisée pour laquelle la mobilité doit fonctionner comme un service permanent plutôt qu’une contrainte. L’abonnement se rapproche d’une prestation de déplacement haut de gamme sans transférer au client la propriété ni la maintenance d’un véhicule.\n\nChez un cadre, un indépendant prospère ou quelqu’un dont l’image professionnelle dépend de sa ponctualité, cette délégation peut être plus intéressante qu’une voiture personnelle. Executive est donc aussi un choix social : payer pour que le transport disparaisse du champ des problèmes ordinaires, tout en restant dépendant du réseau Bull.","data":{},"vehicle":false,"neuro":false,"recurring":"monthly","monthlyCost":1500,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-standard-pistolet-leger-pm-raven', 'Pistolet léger / PM — Raven', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions standard","sourceCategory":"Munitions standard","price":50,"priceMin":null,"priceMax":null,"priceLabel":"50 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Prix du lot standard indiqué par fabricant/calibre.","lore":"Les lots Raven pour pistolets légers et pistolets-mitrailleurs représentent la munition de service ordinaire de la marque dans les petits calibres de combat. Ils sont pensés pour alimenter sans particularité exotique les armes compactes Raven et les plateformes compatibles, avec la logique de standardisation attendue d''un fabricant très présent sur les gammes de sécurité et d''intervention.\n\nIl s''agit bien de munitions standard : aucune propriété EMP, perforante ou de contrôle n''est incluse par défaut. Le nom Raven renseigne surtout sur la filière d''approvisionnement, le conditionnement et la compatibilité du lot ; les effets spéciaux appartiennent aux cartouches dédiées comme Flash, Volto, Drill ou Night.","data":{"Famille":"Pistolet léger / PM","Fabricant":"Raven"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-standard-pistolet-leger-pm-phoenix', 'Pistolet léger / PM — Phoenix', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions standard","sourceCategory":"Munitions standard","price":80,"priceMin":null,"priceMax":null,"priceLabel":"80 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Prix du lot standard indiqué par fabricant/calibre.","lore":"Les munitions Phoenix pour pistolets légers et PM constituent l''alimentation conventionnelle des armes compactes de la marque. Dans un catalogue où Phoenix associe volontiers ses plateformes à des interfaces Smartlink et à des effets spécialisés, ces cartouches rappellent qu''une grande partie de l''usage quotidien reste fondée sur une munition balistique ordinaire.\n\nLe lot n''apporte donc ni ciblage électronique ni effet énergétique à lui seul. Les fonctions particulières viennent de l''arme ou d''une munition spéciale distincte ; ici, Phoenix fournit simplement la cartouche courante nécessaire à l''entraînement, au port quotidien et aux échanges où aucun effet spécialisé n''est recherché.","data":{"Famille":"Pistolet léger / PM","Fabricant":"Phoenix"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-standard-pistolet-leger-pm-owl', 'Pistolet léger / PM — Owl', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions standard","sourceCategory":"Munitions standard","price":30,"priceMin":null,"priceMax":null,"priceLabel":"30 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Prix du lot standard indiqué par fabricant/calibre.","lore":"Les lots Owl pour pistolets légers et PM occupent le versant le plus simple de l''offre de la marque : des cartouches conventionnelles pour armes compactes, destinées à être consommées en quantité sans transformer chaque chargeur en dépense spécialisée. Elles correspondent au caractère pratique et direct de nombreuses armes Owl.\n\nAucun poison, effet anti-cyber ou projectile exotique n''est présent dans ce lot standard. Les familles Venom, Liquid ou Rust sont des choix séparés ; cette munition sert au tir courant, à l''entraînement et au ravitaillement de base d''une arme compatible.","data":{"Famille":"Pistolet léger / PM","Fabricant":"Owl"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-standard-pistolet-lourd-raven', 'Pistolet lourd — Raven', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions standard","sourceCategory":"Munitions standard","price":70,"priceMin":null,"priceMax":null,"priceLabel":"70 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Prix du lot standard indiqué par fabricant/calibre.","lore":"Pistolet lourd — Raven désigne le conditionnement Raven de munitions classiques destiné à la famille des pistolets lourds. Le lot contient 40 cartouches, soit la quantité standard retenue pour cette gamme de consommables.\n\nIl s’agit de munitions conventionnelles sans effet spécial ajouté : leur rôle est d’alimenter les armes compatibles de cette famille. La réserve de quarante coups en fait un achat d’approvisionnement courant plutôt qu’une munition spécialisée à usage ponctuel.","data":{"Famille":"Pistolet lourd","Fabricant":"Raven"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-standard-pistolet-lourd-phoenix', 'Pistolet lourd — Phoenix', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions standard","sourceCategory":"Munitions standard","price":110,"priceMin":null,"priceMax":null,"priceLabel":"110 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Prix du lot standard indiqué par fabricant/calibre.","lore":"Le lot Phoenix pour pistolet lourd fournit la cartouche conventionnelle des armes de poing les plus puissantes de la marque. Le calibre supérieur impose déjà une munition plus volumineuse que celle des armes légères, mais le produit reste une alimentation ordinaire et ne doit pas être confondu avec une charge Phoenix spécialisée.\n\nSmartlink, Flash, Feu ou autres propriétés éventuelles appartiennent à l''arme ou à une munition dédiée, pas à cette boîte de cartouches. Le lot sert donc de référence logistique : celui que l''on achète pour maintenir des chargeurs disponibles sans rechercher un comportement particulier à l''impact.","data":{"Famille":"Pistolet lourd","Fabricant":"Phoenix"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-standard-pistolet-lourd-owl', 'Pistolet lourd — Owl', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions standard","sourceCategory":"Munitions standard","price":40,"priceMin":null,"priceMax":null,"priceLabel":"40 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Prix du lot standard indiqué par fabricant/calibre.","lore":"Les cartouches Owl pour pistolet lourd sont la munition courante des armes de poing de gros calibre compatibles. Elles fournissent l''impact attendu de la classe d''arme sans ajouter la chimie, l''électricité ou les projectiles transformables qui caractérisent les familles spéciales de la marque.\n\nCette distinction est importante dans l''approvisionnement : un chargeur rempli de munitions standard reste prévisible et simple à remplacer. Venom, Liquid et Rust doivent être choisis explicitement lorsqu''on veut leurs contraintes et leurs effets particuliers.","data":{"Famille":"Pistolet lourd","Fabricant":"Owl"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-standard-mitraillette-raven', 'Mitraillette — Raven', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions standard","sourceCategory":"Munitions standard","price":75,"priceMin":null,"priceMax":null,"priceLabel":"75 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Prix du lot standard indiqué par fabricant/calibre.","lore":"La munition Raven pour mitraillettes est conditionnée pour les armes automatiques compactes qui consomment rapidement leurs réserves en rafale ou en tir soutenu. Dans ce rôle, la valeur du lot tient moins à un effet particulier qu''à la disponibilité d''une alimentation homogène adaptée à un usage répété.\n\nChaque cartouche reste conventionnelle et n''hérite pas automatiquement des technologies EMP ou perforantes visibles ailleurs dans le catalogue Raven. L''utilisateur choisit séparément une munition spéciale lorsqu''il accepte son coût, ses contraintes et son comportement spécifique.","data":{"Famille":"Mitraillette","Fabricant":"Raven"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-standard-mitraillette-phoenix', 'Mitraillette — Phoenix', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions standard","sourceCategory":"Munitions standard","price":118,"priceMin":null,"priceMax":null,"priceLabel":"118 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Prix du lot standard indiqué par fabricant/calibre.","lore":"Le lot Phoenix pour mitraillette alimente les armes automatiques de proximité de la marque sans leur ajouter une fonction supplémentaire. C''est la munition que l''on emporte lorsque cadence, réserve de chargeurs et continuité du ravitaillement comptent davantage qu''un effet énergétique ou électronique particulier.\n\nLes systèmes Smartlink des armes compatibles fonctionnent avec cette munition comme avec toute cartouche adaptée, mais le projectile lui-même n''est ni guidé ni intelligent. Phoenix sépare ainsi l''électronique de la plateforme et les effets réellement portés par une munition spécialisée.","data":{"Famille":"Mitraillette","Fabricant":"Phoenix"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-standard-mitraillette-owl', 'Mitraillette — Owl', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions standard","sourceCategory":"Munitions standard","price":30,"priceMin":null,"priceMax":null,"priceLabel":"30 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Prix du lot standard indiqué par fabricant/calibre.","lore":"Les munitions Owl pour mitraillette sont des cartouches de consommation courante destinées aux armes qui privilégient volume de feu et proximité. Leur intérêt logistique est évident : une arme automatique vide ses chargeurs vite, et le lot standard reste la solution normale lorsqu''aucun effet spécialisé n''est nécessaire.\n\nLe projectile n''intègre ni poison ni charge anti-cyber. Les munitions Owl exotiques forment une couche de spécialisation distincte ; ce lot constitue au contraire le fond de stock simple que l''on peut réserver à l''entraînement, à la suppression ou au combat ordinaire.","data":{"Famille":"Mitraillette","Fabricant":"Owl"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-standard-fusil-d-assaut-raven', 'Fusil d''assaut — Raven', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions standard","sourceCategory":"Munitions standard","price":85,"priceMin":null,"priceMax":null,"priceLabel":"85 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Prix du lot standard indiqué par fabricant/calibre.","lore":"Le lot Raven pour fusil d''assaut est l''alimentation conventionnelle des armes d''épaule de la marque et des plateformes compatibles de même calibre. Il correspond au cœur logistique d''une arme de service : des cartouches destinées à remplir des chargeurs complets pour les engagements où la polyvalence du fusil suffit.\n\nLa cartouche standard ne possède pas par défaut l''EMP du Rampager ni le pouvoir perforant de la Drill. Ces propriétés doivent provenir de l''arme ou d''une munition identifiée comme telle ; le lot Raven ordinaire reste volontairement neutre afin de servir de référence stable.","data":{"Famille":"Fusil d''assaut","Fabricant":"Raven"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-standard-fusil-d-assaut-phoenix', 'Fusil d''assaut — Phoenix', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions standard","sourceCategory":"Munitions standard","price":135,"priceMin":null,"priceMax":null,"priceLabel":"135 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Prix du lot standard indiqué par fabricant/calibre.","lore":"Les cartouches Phoenix pour fusil d''assaut forment le ravitaillement de base des armes d''épaule automatiques de la marque. Elles sont destinées aux chargeurs que l''on consomme dans les échanges prolongés, sans transformer chaque tir en usage d''une technologie particulière ou d''une charge coûteuse.\n\nLe fait qu''un fusil Phoenix puisse disposer d''un Smartlink ou d''un effet Flash ne modifie pas la nature de cette munition. Le lot standard reste balistique et conventionnel ; Pyro, Hack ou Blast sont des choix distincts lorsque l''effet de la cartouche elle-même devient important.","data":{"Famille":"Fusil d''assaut","Fabricant":"Phoenix"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-standard-fusil-d-assaut-owl', 'Fusil d''assaut — Owl', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions standard","sourceCategory":"Munitions standard","price":50,"priceMin":null,"priceMax":null,"priceLabel":"50 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Prix du lot standard indiqué par fabricant/calibre.","lore":"Le lot Owl pour fusil d''assaut fournit les cartouches ordinaires nécessaires aux armes d''épaule de la marque. Il s''inscrit dans une logique de ravitaillement pragmatique : suffisamment de munitions pour soutenir des chargeurs de combat sans dépendre d''un consommable spécialisé à chaque échange.\n\nAucune propriété Perforante, toxique ou anti-cyber n''est attachée au lot simplement parce qu''il porte le nom Owl. Le comportement spécial d''un Howling, d''une Venom ou d''une Rust vient de la plateforme ou du type de munition choisi, pas de la marque imprimée sur une boîte standard.","data":{"Famille":"Fusil d''assaut","Fabricant":"Owl"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-standard-precision-raven', 'Précision — Raven', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions standard","sourceCategory":"Munitions standard","price":90,"priceMin":null,"priceMax":null,"priceLabel":"90 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Prix du lot standard indiqué par fabricant/calibre.","lore":"Les munitions Raven de précision sont les cartouches standard prévues pour les fusils à longue portée compatibles. Elles servent aux tirs préparés et au ravitaillement normal d''une arme de précision, sans supposer que chaque projectile reproduise les effets particuliers d''un Deathbringer ou d''une cartouche spécialisée.\n\nLe lot ne reçoit donc pas automatiquement Fiable, EMP ou Perforant. Ces propriétés restent celles de l''arme ou d''une munition explicitement conçue pour les porter ; la catégorie « précision » indique ici le type d''arme et de calibre auquel le ravitaillement est destiné.","data":{"Famille":"Précision","Fabricant":"Raven"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-standard-precision-phoenix', 'Précision — Phoenix', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions standard","sourceCategory":"Munitions standard","price":140,"priceMin":null,"priceMax":null,"priceLabel":"140 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Prix du lot standard indiqué par fabricant/calibre.","lore":"Le lot Phoenix de précision alimente les fusils longue distance de la marque avec une cartouche conventionnelle. Il permet de dissocier l''approvisionnement courant des fonctions plus sophistiquées de certaines plateformes Phoenix, notamment les interfaces de ciblage ou les dispositifs destinés à réduire la signature du tir.\n\nLa cartouche standard n''est ni silencieuse ni guidée par elle-même : ces qualités dépendent de l''arme et de ses équipements. Le lot fournit simplement la munition adaptée à la classe de précision, tandis que les effets particuliers doivent rester explicitement identifiés ailleurs.","data":{"Famille":"Précision","Fabricant":"Phoenix"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-standard-precision-owl', 'Précision — Owl', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions standard","sourceCategory":"Munitions standard","price":60,"priceMin":null,"priceMax":null,"priceLabel":"60 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Prix du lot standard indiqué par fabricant/calibre.","lore":"Precision — Owl désigne le conditionnement Owl de munitions classiques pour les armes de précision. Le lot contient 25 cartouches, un format plus resserré que les conditionnements Raven ou Phoenix de la même section.\n\nCes cartouches n’apportent aucun effet spécial par elles-mêmes : elles constituent l’alimentation conventionnelle d’une arme compatible. Le conditionnement de vingt-cinq coups correspond donc à une réserve dédiée au tir de précision plutôt qu’à un volume de saturation.","data":{"Famille":"Précision","Fabricant":"Owl"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-standard-shotgun-raven', 'Shotgun — Raven', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions standard","sourceCategory":"Munitions standard","price":75,"priceMin":null,"priceMax":null,"priceLabel":"75 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Prix du lot standard indiqué par fabricant/calibre.","lore":"Les cartouches Raven pour shotgun constituent l''alimentation conventionnelle des armes à dispersion de la marque. Elles sont faites pour être chargées et remplacées rapidement dans une arme de proximité, sans présumer l''effet électrique, EMP ou perforant de certains modèles Raven plus spécialisés.\n\nLe type de dispersion et les propriétés de l''arme restent ceux de la plateforme utilisée. Ce lot ne transforme pas un shotgun ordinaire en Riot Control ou en Croaker ; il représente simplement la réserve de cartouches standard sur laquelle repose l''usage quotidien de cette famille d''armes.","data":{"Famille":"Shotgun","Fabricant":"Raven"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-standard-shotgun-phoenix', 'Shotgun — Phoenix', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions standard","sourceCategory":"Munitions standard","price":120,"priceMin":null,"priceMax":null,"priceLabel":"120 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Prix du lot standard indiqué par fabricant/calibre.","lore":"Le lot Phoenix pour shotgun fournit des cartouches conventionnelles aux armes à dispersion compatibles. Il est destiné aux usages où l''on veut conserver la puissance et la couverture naturelles d''un shotgun sans engager une charge incendiaire ou un autre consommable spécialisé.\n\nUn Fire Rain doit son effet Feu à son système ou à sa munition identifiée comme telle, pas à n''importe quelle cartouche Phoenix. Le lot standard reste donc la solution de ravitaillement neutre pour entraînement, réserve ou combat de proximité ordinaire.","data":{"Famille":"Shotgun","Fabricant":"Phoenix"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'munitions-standard-shotgun-owl', 'Shotgun — Owl', NULL, '{"nature":"equipement","kind":"equipment","category":"Munitions standard","sourceCategory":"Munitions standard","price":35,"priceMin":null,"priceMax":null,"priceLabel":"35 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Prix du lot standard indiqué par fabricant/calibre.","lore":"Les munitions Owl pour shotgun forment la réserve ordinaire des armes à dispersion de la marque. Elles privilégient la simplicité d''approvisionnement et la disponibilité de nombreux coups de proximité plutôt qu''une fonction toxique, électrique ou technologique ajoutée au projectile.\n\nLe lot n''accorde aucune propriété spéciale par lui-même. La fiabilité éventuelle d''un Boss appartient à l''arme, tandis que Venom, Liquid ou Rust restent des munitions distinctes ; ces cartouches représentent donc le choix de base lorsque la dispersion du shotgun suffit au besoin.","data":{"Famille":"Shotgun","Fabricant":"Owl"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-black-arrow', 'Black Arrow', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Arcs, arbalètes & harpons","sourceCategory":"Armes — Mêlée","price":800,"priceMin":null,"priceMax":null,"priceLabel":"800 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme de trait à un coup, fiable et capable de mieux travailler les protections qu’une arme de trait ordinaire","lore":"Black Arrow est une arbalète urbaine très diffusée, appréciée notamment parce que ses carreaux restent peu coûteux.\n\nDans son emploi prévu, arme de trait à un coup, fiable et capable de mieux travailler les protections qu’une arme de trait ordinaire.","data":{"Type":"Trait","DGT":"8","Portee":"45 m","Cap.":"1","Proprietes":"Perforant 1 ; Fiable ; 1 coup"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-nextar-championship', 'Nextar Championship', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Arcs, arbalètes & harpons","sourceCategory":"Armes — Mêlée","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"grand arc pliant à un coup dont les dégâts restent liés à la Vigueur du tireur","lore":"Nextar Championship est un arc à poulies Nextar puissant et précis, utilisé aussi bien pour la chasse que dans les compétitions où la marque dispose d’une forte présence.\n\nDans son emploi prévu, grand arc pliant à un coup dont les dégâts restent liés à la Vigueur du tireur.","data":{"Type":"Trait","DGT":"V+2","Portee":"65 m","Cap.":"1","Proprietes":"Pliant ; Fiable ; 1 coup"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-byron-tethyssette', 'Byron Tethyssette', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Arcs, arbalètes & harpons","sourceCategory":"Armes — Mêlée","price":900,"priceMin":null,"priceMax":null,"priceLabel":"900 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme aquatique de courte portée, spécialisée et moins efficace lorsque ses conditions d’emploi idéales ne sont pas réunies","lore":"Byron Tethyssette est un fusil-harpon Byron destiné au combat sous-marin, dont les mini-harpons exploitent des bulles de plasma autour de l’impact.\n\nDans son emploi prévu, arme aquatique de courte portée, spécialisée et moins efficace lorsque ses conditions d’emploi idéales ne sont pas réunies.","data":{"Type":"Trait","DGT":"6","Portee":"15 m","Cap.":"1","Proprietes":"Aquatique ; 1 coup ; Efficience minimale"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-lourdes-flak-cannon-prototype', 'Flak Cannon — Prototype', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes lourdes prototypes","sourceCategory":"Armes — Lourdes","price":null,"priceMin":null,"priceMax":null,"priceLabel":"Spécial","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme lourde expérimentale à volume de feu élevé ; son statut de prototype impose une disponibilité spéciale plutôt qu’un prix de marché","lore":"Flak Cannon — Prototype est un quadri-canon portable expérimental, compatible avec plusieurs munitions et entourant les projectiles d’un milieu ionisé qui accentue leur violence.\n\nDans son emploi prévu, arme lourde expérimentale à volume de feu élevé ; son statut de prototype impose une disponibilité spéciale plutôt qu’un prix de marché.","data":{"Role":"Quadri-canon portable","DGT":"14","Portee":"50 m","Cap.":"16","Proprietes":"Incendiaire ; munitions universelles ; prototype"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-lourdes-sheer-blueshell-a-prototype', 'Sheer BlueShell A. — Prototype', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Drones d’assaut & armes autonomes","sourceCategory":"Armes — Lourdes","price":null,"priceMin":null,"priceMax":null,"priceLabel":"Spécial","generation":null,"charge":null,"stress":null,"slots":null,"effect":"engin d’assaut autonome à usage unique ou très limité ; il doit être programmé avant emploi et n’est pas une arme personnelle conventionnelle","lore":"Sheer BlueShell A. — Prototype est un robot autonome programmable par Neurodive ou holophone, lancé vers une personne ou un lieu déterminé avant d’exécuter sa mission de façon inexorable.\n\nDans son emploi prévu, engin d’assaut autonome à usage unique ou très limité ; il doit être programmé avant emploi et n’est pas une arme personnelle conventionnelle.","data":{"Role":"Drone/robot d’assaut autonome","DGT":"20","Portee":"Contact","Cap.":"1","Proprietes":"Programmable ; charge explosive ; prototype"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-charm-prototype', 'Charm — Prototype', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Dispositifs expérimentaux","sourceCategory":"Armes — Poing & Tasers","price":null,"priceMin":null,"priceMax":null,"priceLabel":"Spécial","generation":null,"charge":null,"stress":null,"slots":null,"effect":"dispositif chimique expérimental dont l’effet principal n’est pas balistique et dépend du composé diffusé","lore":"Charm — Prototype est un petit cœur cristallin lévitant contenant un mélange expérimental de phéromones et de protéines diffusé comme agent de contrôle.\n\nDans son emploi prévu, dispositif chimique expérimental dont l’effet principal n’est pas balistique et dépend du composé diffusé.","data":{"Classe":"Dispositif chimique","DGT":"X","Portee":"20 m","Cap.":"12","Proprietes":"Phéromones ; gaz de combat ; prototype"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-lourdes-armcannon-prototype', 'Armcannon — Prototype', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes lourdes prototypes","sourceCategory":"Armes — Lourdes","price":null,"priceMin":null,"priceMax":null,"priceLabel":"Spécial","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme énergétique de bras à faible autonomie, alimentée par cellules et pensée pour des tirs puissants plutôt que soutenus","lore":"Armcannon — Prototype est un canon de bras expérimental qui ne nécessite pas d’opération et projette des décharges ioniques surchauffées sans munition solide.\n\nDans son emploi prévu, arme énergétique de bras à faible autonomie, alimentée par cellules et pensée pour des tirs puissants plutôt que soutenus.","data":{"Role":"Canon de bras ionique","DGT":"10","Portee":"55 m","Cap.":"2","Proprietes":"EMP ; énergétique ; prototype"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-lourdes-raven-sehdia-railway-to-hell-prototype', 'Raven-Sehdia Railway to Hell — Prototype', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Anti-matériel & fortifications","sourceCategory":"Armes — Lourdes","price":null,"priceMin":null,"priceMax":null,"priceLabel":"Spécial","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme anti-matériel expérimentale à très longue portée, extrêmement perforante et limitée par son cycle de charge énergétique","lore":"Raven-Sehdia Railway to Hell — Prototype est un railgun prototype Raven-Sehdia sans recul dont le projectile supersonique s’entoure d’un plasma ionisé après la charge.\n\nDans son emploi prévu, arme anti-matériel expérimentale à très longue portée, extrêmement perforante et limitée par son cycle de charge énergétique.","data":{"Role":"Railgun prototype","DGT":"19","Portee":"500 m","Cap.":"1","Proprietes":"Perforant 4 ; portée extrême ; énergétique ; prototype"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-phoenix-vader-prototype', 'Phoenix Vader — Prototype', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets prototypes","sourceCategory":"Armes — Poing & Tasers","price":null,"priceMin":null,"priceMax":null,"priceLabel":"Spécial","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme laser expérimentale à trois tirs par cellule ; sa pénétration est matérielle et son comportement dépend de la dissipation du faisceau","lore":"Phoenix Vader — Prototype est un pistolet-laser Phoenix alimenté par cellule, capable d’attaquer une couche de matière avant que le faisceau poursuive sa course.\n\nDans son emploi prévu, arme laser expérimentale à trois tirs par cellule ; sa pénétration est matérielle et son comportement dépend de la dissipation du faisceau.","data":{"Classe":"Pistolet laser","DGT":"8","Portee":"Spéciale","Cap.":"3","Proprietes":"Laser ; Perforant 3 ; prototype"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-raven-ravenegg', 'Raven Ravenegg', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Grenades & explosifs","sourceCategory":"Armes — Mêlée","price":1550,"priceMin":null,"priceMax":null,"priceLabel":"1 550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"grenade de zone qui mêle dégâts explosifs et perturbation EMP contre les systèmes électroniques","lore":"Raven Ravenegg est un lot de grenades Raven combinant charge explosive et décharge électromagnétique.\n\nDans son emploi prévu, grenade de zone qui mêle dégâts explosifs et perturbation EMP contre les systèmes électroniques.","data":{"Type":"Grenade","DGT":"10","Portee":"15 m","Cap.":"3","Proprietes":"Zone ; EMP"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-phoenix-inferno', 'Phoenix Inferno', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Grenades & explosifs","sourceCategory":"Armes — Mêlée","price":1050,"priceMin":null,"priceMax":null,"priceLabel":"1 050 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"grenade incendiaire de zone ; son intérêt vient de la chaleur et de l’embrasement plus que de la perforation","lore":"Phoenix Inferno est un lot de trois grenades Phoenix dont plusieurs liquides se mélangent au déclenchement pour produire une réaction exothermique.\n\nDans son emploi prévu, grenade incendiaire de zone ; son intérêt vient de la chaleur et de l’embrasement plus que de la perforation.","data":{"Type":"Grenade","DGT":"8","Portee":"15 m","Cap.":"3","Proprietes":"Zone ; Feu"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-owl-dripper', 'Owl Dripper', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Grenades & explosifs","sourceCategory":"Armes — Mêlée","price":1250,"priceMin":null,"priceMax":null,"priceLabel":"1 250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"grenade chimique de zone ; les protections étanches et adaptées aux agents corrosifs restent pertinentes","lore":"Owl Dripper est un lot de grenades Owl libérant un agent acide gazeux qui réagit notamment avec l’humidité des muqueuses et de la peau.\n\nDans son emploi prévu, grenade chimique de zone ; les protections étanches et adaptées aux agents corrosifs restent pertinentes.","data":{"Type":"Grenade","DGT":"8","Portee":"15 m","Cap.":"3","Proprietes":"Zone ; Chimique ; acide"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-phoenix-helios-ii', 'Phoenix Helios II', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Grenades & explosifs","sourceCategory":"Armes — Mêlée","price":950,"priceMin":null,"priceMax":null,"priceLabel":"950 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"grenade de désorientation et d’aveuglement plutôt que munition conçue pour infliger des dégâts lourds","lore":"Phoenix Helios II est des grenades flash Phoenix qui causent peu de dégâts directs mais saturent brutalement la vision et pénalisent particulièrement les cibles photosensibles.\n\nDans son emploi prévu, grenade de désorientation et d’aveuglement plutôt que munition conçue pour infliger des dégâts lourds.","data":{"Type":"Grenade","DGT":"3","Portee":"15 m","Cap.":"3","Proprietes":"Zone ; aveuglant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-owl-superchoc', 'Owl Superchoc', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Grenades & explosifs","sourceCategory":"Armes — Mêlée","price":2250,"priceMin":null,"priceMax":null,"priceLabel":"2 250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"grenade de choc lourde visant à neutraliser par la violence de l’onde de pression autant que par les dégâts","lore":"Owl Superchoc est un lot de grenades Owl produisant une onde de choc particulièrement brutale dans leur zone d’effet.\n\nDans son emploi prévu, grenade de choc lourde visant à neutraliser par la violence de l’onde de pression autant que par les dégâts.","data":{"Type":"Grenade","DGT":"14","Portee":"15 m","Cap.":"3","Proprietes":"Zone ; super choc"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-biosun-frog-egg', 'Biosun Frog Egg', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Grenades & explosifs","sourceCategory":"Armes — Mêlée","price":3000,"priceMin":null,"priceMax":null,"priceLabel":"3 000 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"munition de contrôle de zone et d’immobilisation ; sa charge adhésive compte davantage que son pouvoir destructeur","lore":"Biosun Frog Egg est six mini-grenades Biosun qui libèrent une colle extrêmement puissante et réagissent aux sources de chaleur.\n\nDans son emploi prévu, munition de contrôle de zone et d’immobilisation ; sa charge adhésive compte davantage que son pouvoir destructeur.","data":{"Type":"Grenade","DGT":"5","Portee":"15 m","Cap.":"6","Proprietes":"Zone ; adhésif ; thermosensible"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-byron-pokeball', 'Byron Pokeball', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Grenades & explosifs","sourceCategory":"Armes — Mêlée","price":850,"priceMin":null,"priceMax":null,"priceLabel":"850 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"grenade de neutralisation de zone dont la composante électrique vise surtout à interrompre l’action des personnes touchées","lore":"Byron Pokeball est trois grenades Byron à l’apparence volontairement ludique, diffusant un gaz électrique paralysant.\n\nDans son emploi prévu, grenade de neutralisation de zone dont la composante électrique vise surtout à interrompre l’action des personnes touchées.","data":{"Type":"Grenade","DGT":"3","Portee":"15 m","Cap.":"3","Proprietes":"Zone ; électrique ; paralysant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-lourdes-owl-vending-machine', 'Owl Vending Machine', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Lance-grenades","sourceCategory":"Armes — Lourdes","price":850,"priceMin":null,"priceMax":null,"priceLabel":"850 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"lanceur à un coup privilégiant la compatibilité des munitions plutôt qu’un chargeur volumineux","lore":"Owl Vending Machine est un lance-grenades Owl conçu pour accepter un très large éventail de grenades du marché.\n\nDans son emploi prévu, lanceur à un coup privilégiant la compatibilité des munitions plutôt qu’un chargeur volumineux.","data":{"Role":"Lance-grenades universel","DGT":"3","Portee":"120 m","Cap.":"1","Proprietes":"Compatible grenades ; 1 coup"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-jagi', 'Jagi', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Grenades & explosifs","sourceCategory":"Armes — Mêlée","price":450,"priceMin":null,"priceMax":null,"priceLabel":"450 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"grenade de zone à fixation magnétique ; le faible coût s’accompagne d’une fiabilité inférieure aux modèles corporatistes","lore":"Jagi est des grenades nord-coréennes bon marché dont la charge magnétique permet d’adhérer aux surfaces ferreuses.\n\nDans son emploi prévu, grenade de zone à fixation magnétique ; le faible coût s’accompagne d’une fiabilité inférieure aux modèles corporatistes.","data":{"Type":"Grenade","DGT":"6","Portee":"15 m","Cap.":"3","Proprietes":"Zone ; magnétique ; Défaillant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-shadow-gift', 'Shadow Gift', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Grenades & explosifs","sourceCategory":"Armes — Mêlée","price":3500,"priceMin":null,"priceMax":null,"priceLabel":"3 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"munition programmable lourde dont le mode bombe sacrifie la simplicité d’emploi au profit d’un effet préparé plus important","lore":"Shadow Gift est une grenade programmable par holophone ou Neurodive, utilisable aussi comme bombe à retardement.\n\nDans son emploi prévu, munition programmable lourde dont le mode bombe sacrifie la simplicité d’emploi au profit d’un effet préparé plus important.","data":{"Type":"Grenade programmable","DGT":"15","Portee":"15 m","Cap.":"1","Proprietes":"Zone ; programmable ; Perforant 3"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-lourdes-raven-bomberman', 'Raven Bomberman', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Lance-grenades","sourceCategory":"Armes — Lourdes","price":1050,"priceMin":null,"priceMax":null,"priceLabel":"1 050 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"lanceur à trois coups plus puissant et plus spécialisé que les modèles universels","lore":"Raven Bomberman est un lance-grenades Raven compatible avec les grenades et certains projectiles de la marque, conçu pour provoquer l’explosion dès l’impact.\n\nDans son emploi prévu, lanceur à trois coups plus puissant et plus spécialisé que les modèles universels.","data":{"Role":"Lance-grenades","DGT":"5","Portee":"100 m","Cap.":"3","Proprietes":"Compatible grenades Raven ; détonation à l’impact"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-lourdes-phoenix-easter-bunny', 'Phoenix Easter Bunny', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Lance-grenades","sourceCategory":"Armes — Lourdes","price":950,"priceMin":null,"priceMax":null,"priceLabel":"950 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"lanceur à trois coups simple, pensé comme plateforme de projection pour les grenades Phoenix","lore":"Phoenix Easter Bunny est un lance-grenades Phoenix plus abordable que le modèle Raven et destiné aux munitions de la marque.\n\nDans son emploi prévu, lanceur à trois coups simple, pensé comme plateforme de projection pour les grenades Phoenix.","data":{"Role":"Lance-grenades","DGT":"3","Portee":"100 m","Cap.":"3","Proprietes":"Compatible grenades Phoenix"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-phoenix-king-fist', 'Phoenix King Fist', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de contact & outils","sourceCategory":"Armes — Mêlée","price":80,"priceMin":null,"priceMax":null,"priceLabel":"80 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme de pugilat sans alimentation ni projectile, conçue pour concentrer la force d’un coup","lore":"Phoenix King Fist est un poing américain Phoenix très simple, dont l’efficacité dépend surtout du combattant qui le manie.\n\nDans son emploi prévu, arme de pugilat sans alimentation ni projectile, conçue pour concentrer la force d’un coup.","data":{"Type":"Melee","DGT":"2","Portee":"Contact","Proprietes":"Choc"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-byron-ginette', 'Byron Ginette', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de contact & outils","sourceCategory":"Armes — Mêlée","price":1500,"priceMin":null,"priceMax":null,"priceLabel":"1 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme de contact lourde combinant fort impact et capacité accrue contre les protections","lore":"Byron Ginette est une arme contondante Byron pensée pour écraser violemment la cible et briser les protections.\n\nDans son emploi prévu, arme de contact lourde combinant fort impact et capacité accrue contre les protections.","data":{"Type":"Melee","DGT":"7","Portee":"Contact","Proprietes":"Perforant 2 ; Choc"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-mary-antoinette', 'Mary-Antoinette', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de contact & outils","sourceCategory":"Armes — Mêlée","price":875,"priceMin":null,"priceMax":null,"priceLabel":"875 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"outil industriel détournable en arme de contact, très destructeur mais lourd et dépendant de ses cellules","lore":"Mary-Antoinette est un gantelet hydraulique équipé d’une pince de découpe dont la puissance évoque une petite guillotine.\n\nDans son emploi prévu, outil industriel détournable en arme de contact, très destructeur mais lourd et dépendant de ses cellules.","data":{"Type":"Outil/arme hydraulique","DGT":"12","Portee":"Contact","Cap.":"12","Proprietes":"Hydraulique ; Lourd 1"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-pierrette', 'Pierrette', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de contact & outils","sourceCategory":"Armes — Mêlée","price":675,"priceMin":null,"priceMax":null,"priceLabel":"675 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"outil industriel de contact à plusieurs modes ; il reste plus encombrant et spécialisé qu’une arme conventionnelle","lore":"Pierrette est un marteau hydraulique de chantier dont le manche rétractable et modulable permet d’alterner entre frappe et fonction de marteau-piqueur.\n\nDans son emploi prévu, outil industriel de contact à plusieurs modes ; il reste plus encombrant et spécialisé qu’une arme conventionnelle.","data":{"Type":"Outil/arme hydraulique","DGT":"5","Portee":"Contact","Cap.":"6","Proprietes":"Hydraulique ; mode marteau/piqueur"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-byron-melinette', 'Byron Melinette', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de contact & outils","sourceCategory":"Armes — Mêlée","price":675,"priceMin":null,"priceMax":null,"priceLabel":"675 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"outil thermique utilisable au contact ; les décharges offensives consomment sa réserve beaucoup plus vite que le soudage normal","lore":"Byron Melinette est un pistolet-soudeur Byron disposant de douze cellules et pouvant fonctionner longtemps comme outil ou délivrer des décharges de très haute température.\n\nDans son emploi prévu, outil thermique utilisable au contact ; les décharges offensives consomment sa réserve beaucoup plus vite que le soudage normal.","data":{"Type":"Outil thermique","DGT":"5","Portee":"Contact","Cap.":"12","Proprietes":"Feu ; soudage"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-stretchy', 'Stretchy', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de contact & outils","sourceCategory":"Armes — Mêlée","price":700,"priceMin":null,"priceMax":null,"priceLabel":"700 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme de contact modulable ; après épuisement de ses quatre décharges EMP elle reste utilisable mais perd sa capacité de repli électrique","lore":"Stretchy est un bâton de combat à longueur variable, capable de se déformer sous courant électrique et de délivrer plusieurs attaques EMP.\n\nDans son emploi prévu, arme de contact modulable ; après épuisement de ses quatre décharges EMP elle reste utilisable mais perd sa capacité de repli électrique.","data":{"Type":"Melee","DGT":"6","Portee":"1,5 m à 2,75 m","Cap.":"4","Proprietes":"EMP ; pliant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-sal-in', 'Sal-in', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Fusils d’assaut","sourceCategory":"Armes — Automatiques","price":875,"priceMin":null,"priceMax":null,"priceLabel":"875 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"fusil d’assaut automatique puissant mais peu fiable ; son prix bas ne supprime pas les risques de fonctionnement","lore":"Sal-in est un fusil d’assaut nord-coréen très bon marché, employé par des soldats puis des insurgés malgré une conception réputée défaillante et dangereuse.\n\nDans son emploi prévu, fusil d’assaut automatique puissant mais peu fiable ; son prix bas ne supprime pas les risques de fonctionnement.","data":{"Classe":"Assaut","DGT":"12","Portee":"45 m","Cap.":"24","Proprietes":"Rafale, Automatique, Défaillant, Dangereux"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-morissette', 'Morissette', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Fusils d’assaut","sourceCategory":"Armes — Automatiques","price":1000,"priceMin":null,"priceMax":null,"priceLabel":"1 000 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme automatique de grande capacité, assistée au ciblage sans atteindre les performances des modèles plus lourds","lore":"Morissette est un fusil d’assaut moderne souvent comparé à tort à un jouet, correct et doté d’une forte capacité mais moins puissant que les références haut de gamme.\n\nDans son emploi prévu, arme automatique de grande capacité, assistée au ciblage sans atteindre les performances des modèles plus lourds.","data":{"Classe":"Assaut","DGT":"10","Portee":"45 m","Cap.":"46","Proprietes":"Rafale, Automatique, Smartlink"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-biosun-aciditicteeth', 'Biosun Aciditicteeth', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Fusils d’assaut","sourceCategory":"Armes — Automatiques","price":2550,"priceMin":null,"priceMax":null,"priceLabel":"2 550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"fusil d’assaut organique à munitions régénérées ; son caractère vivant et visqueux implique des contraintes biologiques absentes des armes mécaniques","lore":"Biosun Aciditicteeth est l’unique incursion Biosun dans les armes à feu : un bio-objet qui régénère et produit ses propres projectiles, se rétracte et blesse par un agent acide.\n\nDans son emploi prévu, fusil d’assaut organique à munitions régénérées ; son caractère vivant et visqueux implique des contraintes biologiques absentes des armes mécaniques.","data":{"Classe":"Assaut bio-organique","DGT":"8","Portee":"30 m","Cap.":"8","Proprietes":"Rafale, Automatique, acide, régénératif, bio-objet"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-tortoise-blastard', 'Tortoise Blastard', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Fusils d’assaut","sourceCategory":"Armes — Automatiques","price":5250,"priceMin":null,"priceMax":null,"priceLabel":"5 250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme automatique lourde à courte portée, spécialisée contre les cibles protégées et technogmentées","lore":"Tortoise Blastard est un fusil d’assaut lourd conçu pour Tortoise Security avant le conflit mexicain, dont l’impact est décrit comme capable de déplacer violemment un véhicule léger.\n\nDans son emploi prévu, arme automatique lourde à courte portée, spécialisée contre les cibles protégées et technogmentées.","data":{"Classe":"Assaut lourd","DGT":"12","Portee":"20 m","Cap.":"8","Proprietes":"Rafale, Automatique, EMP, Perforant 1, Choc"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-precision-song-gos', 'Song-gos', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Fusils de précision","sourceCategory":"Armes — Précision","price":1550,"priceMin":null,"priceMax":null,"priceLabel":"1 550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"fusil de précision à deux coups privilégiant la pénétration au prix d’un fonctionnement moins sûr","lore":"Song-gos est un fusil de précision nord-coréen surnommé la perceuse, peu coûteux et efficace contre les blindages malgré une fiabilité médiocre.\n\nDans son emploi prévu, fusil de précision à deux coups privilégiant la pénétration au prix d’un fonctionnement moins sûr.","data":{"Classe":"Precision","DGT":"12","Portee":"250 m","Cap.":"2","Proprietes":"Perforant 2 ; Défaillant ; Dangereux"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-precision-byron-luzette', 'Byron Luzette', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Fusils de précision","sourceCategory":"Armes — Précision","price":3500,"priceMin":null,"priceMax":null,"priceLabel":"3 500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"fusil de précision à deux coups qui concentre ses performances sur la puissance et l’assistance au tir","lore":"Byron Luzette est une arme de précision de la gamme Byron 2035, étonnamment puissante malgré une réserve très faible.\n\nDans son emploi prévu, fusil de précision à deux coups qui concentre ses performances sur la puissance et l’assistance au tir.","data":{"Classe":"Precision","DGT":"14","Portee":"150 m","Cap.":"2","Proprietes":"Smartlink ; Perforant 1"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-precision-abraham-kennedy', 'Abraham Kennedy', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Fusils de précision","sourceCategory":"Armes — Précision","price":null,"priceMin":null,"priceMax":null,"priceLabel":"Mission","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme de mission distribuée comme modèle reproductible plutôt que produit commercial standard ; la fabrication locale rend la qualité plus variable","lore":"Abraham Kennedy est un fusil de précision de l’insurrection civile conçu pour être imprimé par frittage dans un meditech équipé.\n\nDans son emploi prévu, arme de mission distribuée comme modèle reproductible plutôt que produit commercial standard ; la fabrication locale rend la qualité plus variable.","data":{"Classe":"Precision imprimable","DGT":"12","Portee":"120 m","Cap.":"4","Proprietes":"Imprimable ; Aléatoire ; précision fine"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-precision-raven-sehdia-hellrails', 'Raven-Sehdia Hellrails', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Fusils de précision","sourceCategory":"Armes — Précision","price":45550,"priceMin":null,"priceMax":null,"priceLabel":"45 550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"railgun de précision à très longue portée, extrêmement perforant et dépendant d’une recharge énergétique","lore":"Raven-Sehdia Hellrails est un fusil à rampe issu d’une collaboration Sehdia-Raven, sans recul et conçu pour une trajectoire extrêmement rectiligne malgré les conditions extérieures.\n\nDans son emploi prévu, railgun de précision à très longue portée, extrêmement perforant et dépendant d’une recharge énergétique.","data":{"Classe":"Railgun de précision","DGT":"15","Portee":"550 m","Cap.":"5","Proprietes":"Perforant 5 ; Infaillible ; énergétique"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-precision-biosun-pandemic', 'Biosun Pandemic', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Fusils hypodermiques","sourceCategory":"Armes — Précision","price":650,"priceMin":null,"priceMax":null,"priceLabel":"650 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme hypodermique de précision ; le contenu de la seringue détermine l’essentiel de l’effet après impact","lore":"Biosun Pandemic est un fusil à seringues Biosun doté d’une grande réserve et conçu pour placer avec précision des munitions hypodermiques spécialisées.\n\nDans son emploi prévu, arme hypodermique de précision ; le contenu de la seringue détermine l’essentiel de l’effet après impact.","data":{"Classe":"Hypodermique","DGT":"3","Portee":"50 m","Cap.":"25","Proprietes":"Hypodermique ; Smartlink ; précision fine"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-precision-sunways-savior-dgr', 'Sunways Savior DGR', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Fusils hypodermiques","sourceCategory":"Armes — Précision","price":550,"priceMin":null,"priceMax":null,"priceLabel":"550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme hypodermique à longue portée et petite réserve ; la munition injectée reste séparée du dommage mécanique de l’impact","lore":"Sunways Savior DGR est un fusil hypodermique Sunways destiné à projeter des fléchettes à une distance inhabituelle pour ce type d’équipement.\n\nDans son emploi prévu, arme hypodermique à longue portée et petite réserve ; la munition injectée reste séparée du dommage mécanique de l’impact.","data":{"Classe":"Hypodermique","DGT":"3","Portee":"150 m","Cap.":"6","Proprietes":"Hypodermique ; précision fine"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-disease', 'Disease', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets hypodermiques","sourceCategory":"Armes — Poing & Tasers","price":450,"priceMin":null,"priceMax":null,"priceLabel":"450 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"pistolet hypodermique compact dont l’effet dépend de la substance chargée dans les seringues","lore":"Disease est un pistolet à seringues utilisable pour administrer de petites quantités de produit à une cible, qu’il s’agisse de soin ou de sédation.\n\nDans son emploi prévu, pistolet hypodermique compact dont l’effet dépend de la substance chargée dans les seringues.","data":{"Classe":"Hypodermique","DGT":"2","Portee":"25 m","Cap.":"6","Proprietes":"Hypodermique"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-raven-sunways-savior-dg', 'Raven-Sunways Savior DG', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets hypodermiques","sourceCategory":"Armes — Poing & Tasers","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"pistolet hypodermique précis à faible capacité, pensé pour l’administration ciblée","lore":"Raven-Sunways Savior DG est un pistolet hypodermique développé par Raven avec Sunways pour inoculer une substance à distance sans s’exposer inutilement.\n\nDans son emploi prévu, pistolet hypodermique précis à faible capacité, pensé pour l’administration ciblée.","data":{"Classe":"Hypodermique","DGT":"2","Portee":"50 m","Cap.":"4","Proprietes":"Hypodermique ; précision fine"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-lourdes-phoenix-redcrush', 'Phoenix RedCrush', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Lanceurs hypodermiques & chimiques","sourceCategory":"Armes — Lourdes","price":1050,"priceMin":null,"priceMax":null,"priceLabel":"1 050 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme polyvalente de projection chimique ou hypodermique ; le type de charge conditionne son effet de zone ou d’injection","lore":"Phoenix RedCrush est un lanceur Phoenix capable de projeter fioles d’acide, charges gazeuses ou seringues volumineuses.\n\nDans son emploi prévu, arme polyvalente de projection chimique ou hypodermique ; le type de charge conditionne son effet de zone ou d’injection.","data":{"Role":"Lanceur hypodermique/chimique","DGT":"5","Portee":"35 m","Cap.":"6","Proprietes":"Hypodermique ; chimique ; lance-grenades"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-raven-painkiller', 'Raven Painkiller', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets hypodermiques","sourceCategory":"Armes — Poing & Tasers","price":650,"priceMin":null,"priceMax":null,"priceLabel":"650 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"pistolet hypodermique fiable ; son intérêt médical dépend évidemment du produit injecté et du contexte de soin","lore":"Raven Painkiller est un pistolet à seringues Raven dont la précision et l’assistance de tir sont pensées pour faciliter les injections utiles à distance.\n\nDans son emploi prévu, pistolet hypodermique fiable ; son intérêt médical dépend évidemment du produit injecté et du contexte de soin.","data":{"Classe":"Hypodermique","DGT":"2","Portee":"45 m","Cap.":"7","Proprietes":"Hypodermique ; Fiable ; Smartlink ; soin assisté"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-sunways-hornetouch', 'Sunways Hornetouch', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de contact hypodermiques","sourceCategory":"Armes — Mêlée","price":100,"priceMin":null,"priceMax":null,"priceLabel":"100 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme de contact hypodermique limitée par ses quatre injections ; le produit chargé détermine l’effet secondaire","lore":"Sunways Hornetouch est un poing américain Sunways capable de déployer quatre seringues flexibles pour injecter une substance pendant une frappe.\n\nDans son emploi prévu, arme de contact hypodermique limitée par ses quatre injections ; le produit chargé détermine l’effet secondaire.","data":{"Type":"Melee hypodermique","DGT":"3","Portee":"Contact","Cap.":"4","Proprietes":"Hypodermique"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-biosun-blastard-injector', 'Biosun Blastard Injector', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de contact hypodermiques","sourceCategory":"Armes — Mêlée","price":250,"priceMin":null,"priceMax":null,"priceLabel":"250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme de contact légère avec deux injections optionnelles ; elle reste utilisable comme lame une fois les seringues consommées","lore":"Biosun Blastard Injector est un couteau de combat Biosun en titane intégrant deux seringues que l’utilisateur peut choisir de déclencher pendant le coup.\n\nDans son emploi prévu, arme de contact légère avec deux injections optionnelles ; elle reste utilisable comme lame une fois les seringues consommées.","data":{"Type":"Melee hypodermique","DGT":"3","Portee":"Contact","Cap.":"2","Proprietes":"Hypodermique ; lame titane"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-bi', 'Bi', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets-mitrailleurs (PM)","sourceCategory":"Armes — Automatiques","price":600,"priceMin":null,"priceMax":null,"priceLabel":"600 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"PM automatique économique dont la fiabilité est inférieure à celle des modèles corporatistes","lore":"Bi est un pistolet-mitrailleur nord-coréen très bon marché, surnommé pluie, mais réputé pour ses défauts de fonctionnement.\n\nDans son emploi prévu, PM automatique économique dont la fiabilité est inférieure à celle des modèles corporatistes.","data":{"Classe":"PM","DGT":"7","Portee":"20 m","Cap.":"20","Proprietes":"Rafale, Automatique, Défaillant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-sfu-nebullar', 'SFU Nebullar', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets-mitrailleurs (PM)","sourceCategory":"Armes — Automatiques","price":2000,"priceMin":null,"priceMax":null,"priceLabel":"2 000 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"PM automatique spécialisé dans la résistance environnementale plutôt que dans l’augmentation brute des dégâts","lore":"SFU Nebullar est un pistolet-mitrailleur de la SFU conçu pour continuer à fonctionner sous l’eau, dans le vide, dans la boue et sous des températures extrêmes.\n\nDans son emploi prévu, PM automatique spécialisé dans la résistance environnementale plutôt que dans l’augmentation brute des dégâts.","data":{"Classe":"PM","DGT":"8","Portee":"25 m","Cap.":"25","Proprietes":"Rafale, Automatique, Inaltérable"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-monarch-surge', 'Monarch Surge', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets-mitrailleurs (PM)","sourceCategory":"Armes — Automatiques","price":2000,"priceMin":null,"priceMax":null,"priceLabel":"2 000 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"PM automatique doté d’un ciblage spécialisé ; son avantage concerne les signatures et interfaces connectées, pas toutes les formes de dissimulation","lore":"Monarch Surge est une arme Monarch Systems spécialisée contre les Neurodivers, capable d’améliorer le ciblage d’individus Connectés même lorsqu’ils cherchent à se dissimuler.\n\nDans son emploi prévu, PM automatique doté d’un ciblage spécialisé ; son avantage concerne les signatures et interfaces connectées, pas toutes les formes de dissimulation.","data":{"Classe":"PM","DGT":"8","Portee":"25 m","Cap.":"25","Proprietes":"Rafale, Automatique, autociblage Connectés"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-bibal', 'Bibal', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — SMG","sourceCategory":"Armes — Automatiques","price":800,"priceMin":null,"priceMax":null,"priceLabel":"800 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"SMG automatique abordable mais défaillant, adapté à ceux qui privilégient coût et volume de feu","lore":"Bibal est une mitraillette nord-coréenne bon marché surnommée grêle, vendue au prix d’une fiabilité réduite.\n\nDans son emploi prévu, SMG automatique abordable mais défaillant, adapté à ceux qui privilégient coût et volume de feu.","data":{"Classe":"SMG","DGT":"9","Portee":"25 m","Cap.":"25","Proprietes":"Rafale, Automatique, Défaillant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-automatiques-byron-florette', 'Byron Florette', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — SMG","sourceCategory":"Armes — Automatiques","price":1950,"priceMin":null,"priceMax":null,"priceLabel":"1 950 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"SMG automatique dont l’intérêt particulier est son matériau de construction, pas une invisibilité universelle aux contrôles","lore":"Byron Florette est une mitraillette Byron construite en Biosteel afin de réduire sa détection par les portiques et détecteurs métalliques classiques.\n\nDans son emploi prévu, SMG automatique dont l’intérêt particulier est son matériau de construction, pas une invisibilité universelle aux contrôles.","data":{"Classe":"SMG","DGT":"9","Portee":"30 m","Cap.":"30","Proprietes":"Rafale, Automatique, Biosteel"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-owl-apex', 'Owl Apex', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets lourds","sourceCategory":"Armes — Poing & Tasers","price":1300,"priceMin":null,"priceMax":null,"priceLabel":"1 300 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"pistolet lourd de longue portée pour sa catégorie, privilégiant la précision plutôt que les dégâts maximaux","lore":"Owl Apex est un revolver lourd Owl haut de gamme conçu comme un véritable pistolet de précision à une main, avec un recul particulièrement faible.\n\nDans son emploi prévu, pistolet lourd de longue portée pour sa catégorie, privilégiant la précision plutôt que les dégâts maximaux.","data":{"Classe":"Pistolet lourd","DGT":"9","Portee":"75 m","Cap.":"9","Proprietes":"précision fine ; recul réduit"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-byron-jeanette', 'Byron Jeanette', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets légers","sourceCategory":"Armes — Poing & Tasers","price":750,"priceMin":null,"priceMax":null,"priceLabel":"750 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"pistolet léger à faible capacité combinant tir double et dispositif d’alerte au ciblage","lore":"Byron Jeanette est un revolver léger Byron dont le mécanisme permet un tir double et dont l’électronique avertit lorsque l’utilisateur est lui-même ciblé.\n\nDans son emploi prévu, pistolet léger à faible capacité combinant tir double et dispositif d’alerte au ciblage.","data":{"Classe":"Pistolet leger","DGT":"5","Portee":"25 m","Cap.":"6","Proprietes":"Double balle ; détection de ciblage"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-jotkka', 'Jotkka', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets lourds","sourceCategory":"Armes — Poing & Tasers","price":900,"priceMin":null,"priceMax":null,"priceLabel":"900 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"pistolet lourd économique dont le prix bas s’accompagne d’un risque de panne supérieur aux modèles industriels modernes","lore":"Jotkka est un revolver lourd nord-coréen très bon marché et réputé défaillant.\n\nDans son emploi prévu, pistolet lourd économique dont le prix bas s’accompagne d’un risque de panne supérieur aux modèles industriels modernes.","data":{"Classe":"Pistolet lourd","DGT":"10","Portee":"35 m","Cap.":"10","Proprietes":"Défaillant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-raven-sehdia-pacificateur-x', 'Raven-Sehdia Pacificateur X', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets lourds","sourceCategory":"Armes — Poing & Tasers","price":12050,"priceMin":null,"priceMax":null,"priceLabel":"12 050 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"pistolet lourd d’exception, nettement au-dessus du Pacificateur standard en puissance et en coût","lore":"Raven-Sehdia Pacificateur X est une évolution Raven-Sehdia du Pacificateur, extrêmement puissante et capable d’ioniser ses munitions pour produire une décharge EMP.\n\nDans son emploi prévu, pistolet lourd d’exception, nettement au-dessus du Pacificateur standard en puissance et en coût.","data":{"Classe":"Pistolet lourd","DGT":"15","Portee":"50 m","Cap.":"7","Proprietes":"Infaillible ; EMP"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-eolgul-e', 'Eolgul-e', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets de poche","sourceCategory":"Armes — Poing & Tasers","price":250,"priceMin":null,"priceMax":null,"priceLabel":"250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme de poche à faible puissance et faible coût, dont la défaillance constitue le principal compromis","lore":"Eolgul-e est un petit revolver nord-coréen extrêmement bon marché, conçu pour être accessible malgré une fiabilité médiocre.\n\nDans son emploi prévu, arme de poche à faible puissance et faible coût, dont la défaillance constitue le principal compromis.","data":{"Classe":"Poche","DGT":"4","Portee":"20 m","Cap.":"5","Proprietes":"Défaillant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-phoenix-sunnyroshima', 'Phoenix Sunnyroshima', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets de poche","sourceCategory":"Armes — Poing & Tasers","price":600,"priceMin":null,"priceMax":null,"priceLabel":"600 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme de poche à faible capacité et effet thermique de proximité, pensée pour les engagements très courts","lore":"Phoenix Sunnyroshima est un très petit pistolet Phoenix qui compense sa puissance limitée par un nuage de gaz ardent utile à courte distance.\n\nDans son emploi prévu, arme de poche à faible capacité et effet thermique de proximité, pensée pour les engagements très courts.","data":{"Classe":"Poche","DGT":"5","Portee":"20 m","Cap.":"4","Proprietes":"Feu ; nuage ardent à courte portée"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-reminiscer-prototype', 'Reminiscer — Prototype', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets prototypes","sourceCategory":"Armes — Poing & Tasers","price":null,"priceMin":null,"priceMax":null,"priceLabel":"Mission","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme de mission expérimentale dont la munition spéciale exige une programmation et ne se comporte pas comme un projectile conventionnel","lore":"Reminiscer — Prototype est un pistolet expérimental utilisant des munitions de matière noire qui traversent les obstacles avant de se matérialiser à la distance ou sur la cible programmée.\n\nDans son emploi prévu, arme de mission expérimentale dont la munition spéciale exige une programmation et ne se comporte pas comme un projectile conventionnel.","data":{"Classe":"Pistolet lourd expérimental","DGT":"12","Portee":"50 m","Cap.":"5","Proprietes":"Munitions noires ; Fiable 2 ; Smartlink"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-oblivion-prototype', 'Oblivion — Prototype', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets prototypes","sourceCategory":"Armes — Poing & Tasers","price":null,"priceMin":null,"priceMax":null,"priceLabel":"Mission","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme de mission spécialisée dans la surcharge neuro-sensorielle plutôt que dans la simple pénétration balistique","lore":"Oblivion — Prototype est un pistolet expérimental dont le neurochoc surcharge le cerveau biologique ou augmenté, avec un effet plus marqué sur les cibles sensibles.\n\nDans son emploi prévu, arme de mission spécialisée dans la surcharge neuro-sensorielle plutôt que dans la simple pénétration balistique.","data":{"Classe":"Pistolet lourd expérimental","DGT":"10","Portee":"25 m","Cap.":"10","Proprietes":"Neurochoc ; Fiable 2"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-zeus-prototype', 'Zeus — Prototype', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets prototypes","sourceCategory":"Armes — Poing & Tasers","price":null,"priceMin":null,"priceMax":null,"priceLabel":"Mission","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme de mission modulaire ; la valeur indiquée représente son profil de référence et la reconfiguration ne doit pas cumuler tous les avantages","lore":"Zeus — Prototype est un pistolet ionique expérimental dont la configuration peut arbitrer entre portée, puissance et nombre d’utilisations de la cellule.\n\nDans son emploi prévu, arme de mission modulaire ; la valeur indiquée représente son profil de référence et la reconfiguration ne doit pas cumuler tous les avantages.","data":{"Classe":"Pistolet ionique expérimental","DGT":"15","Portee":"20 m","Cap.":"5","Proprietes":"EMP ; modularité ; Fiable"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-poing-tasers-dracula-prototype', 'Dracula — Prototype', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Pistolets prototypes","sourceCategory":"Armes — Poing & Tasers","price":null,"priceMin":null,"priceMax":null,"priceLabel":"Mission","generation":null,"charge":null,"stress":null,"slots":null,"effect":"arme de mission spécialisée dans les traumatismes internes ; son effet particulier dépend d’un impact pertinent sur l’anatomie de la cible","lore":"Dracula — Prototype est un pistolet expérimental utilisant des projectiles vibratoires capables de provoquer de graves lésions vasculaires lorsqu’ils frappent un os.\n\nDans son emploi prévu, arme de mission spécialisée dans les traumatismes internes ; son effet particulier dépend d’un impact pertinent sur l’anatomie de la cible.","data":{"Classe":"Pistolet leger expérimental","DGT":"8","Portee":"35 m","Cap.":"6","Proprietes":"Bloody shock ; Fiable"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
