INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-owl-k-resonancer', 'Owl K Resonancer', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de mêlée","sourceCategory":"Armes — Mêlée","price":250,"priceMin":null,"priceMax":null,"priceLabel":"250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Le K Resonancer est un couteau technologique d’Owl équipé d’une lame vibrante. Ses vibrations s’adaptent progressivement à la cible pour détériorer sa structure.","lore":"Le K Resonancer est un couteau technologique d’Owl équipé d’une lame vibrante.\n\nSes vibrations s’adaptent progressivement à la cible pour détériorer sa structure.","data":{"Type":"Couteaux","DGT":"3","Portee":"Contact","Proprietes":"Vibratoire"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-raven-k-hellthorn', 'Raven K Hellthorn', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de mêlée","sourceCategory":"Armes — Mêlée","price":350,"priceMin":null,"priceMax":null,"priceLabel":"350 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Le K Hellthorn est un couteau de combat de Raven à filament photonique. Ce filament fonctionne de manière comparable à un laser de haute intensité et caractérise son tranchant Photoedge.","lore":"Le K Hellthorn est un couteau de combat de Raven à filament photonique.\n\nCe filament fonctionne de manière comparable à un laser de haute intensité et caractérise son tranchant Photoedge.","data":{"Type":"Couteaux","DGT":"4","Portee":"Contact","Proprietes":"Photoedge"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
