INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-raven-kb-karas', 'Raven KB Karas', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de mêlée","sourceCategory":"Armes — Mêlée","price":650,"priceMin":null,"priceMax":null,"priceLabel":"650 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Le KB Karas est le katana de Raven, présenté comme l’arme blanche la plus vendue. Solide et puissant, il se distingue par son équilibre, qui permet une précision fine dans son maniement.","lore":"Le KB Karas est le katana de Raven, présenté comme l’arme blanche la plus vendue.\n\nSolide et puissant, il se distingue par son équilibre, qui permet une précision fine dans son maniement.","data":{"Type":"Katanas","DGT":"8","Portee":"Contact","Proprietes":"Précision fine ; Visée Intégrée"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-k-golijagi', 'K Golijagi', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de mêlée","sourceCategory":"Armes — Mêlée","price":300,"priceMin":null,"priceMax":null,"priceLabel":"300 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Le K Golijagi est la lame des soldats nord-coréens. Sa fabrication en Biosteel le rend indétectable par les détecteurs conventionnels.","lore":"Le K Golijagi est la lame des soldats nord-coréens.\n\nSa fabrication en Biosteel le rend indétectable par les détecteurs conventionnels.","data":{"Type":"Couteaux","DGT":"4","Portee":"Contact","Proprietes":"Biosteel"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-owl-sb-nextcalibur', 'Owl SB Nextcalibur', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de mêlée","sourceCategory":"Armes — Mêlée","price":650,"priceMin":null,"priceMax":null,"priceLabel":"650 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"La SB Nextcalibur est une épée technologique d’Owl dont la dureté peut changer. Sa lame peut devenir flexible pour s’enrouler autour d’un bras ou se ranger dans un sac. Son Biosteel la rend indétectable aux détecteurs conventionnels.","lore":"La SB Nextcalibur est une épée technologique d’Owl dont la dureté peut changer.\n\nSa lame peut devenir flexible pour s’enrouler autour d’un bras ou se ranger dans un sac. Son Biosteel la rend indétectable aux détecteurs conventionnels.","data":{"Type":"Épées","DGT":"7","Portee":"Contact","Proprietes":"Biosteel ; Pliant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-phoenix-sb-khopesh', 'Phoenix SB Khopesh', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de mêlée","sourceCategory":"Armes — Mêlée","price":715,"priceMin":null,"priceMax":null,"priceLabel":"715 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"La SB Khopesh transpose chez Phoenix la silhouette du khépesh dans l’armement de 2035. Phoenix équipe cette lame irradiante d’un monofilament et la présente comme sa meilleure offre dans cette catégorie.","lore":"La SB Khopesh transpose chez Phoenix la silhouette du khépesh dans l’armement de 2035.\n\nPhoenix équipe cette lame irradiante d’un monofilament et la présente comme sa meilleure offre dans cette catégorie.","data":{"Type":"Épées","DGT":"6","Portee":"Contact","Proprietes":"Irradiant ; Photoedge"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-hache-circulaire-owl', 'Hache circulaire Owl', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de mêlée","sourceCategory":"Armes — Mêlée","price":850,"priceMin":null,"priceMax":null,"priceLabel":"850 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Cette hache de combat d’Owl est construite autour d’une scie circulaire résistante aux chocs. Elle peut s’utiliser avec sa lame bloquée comme une arme blanche ou avec le système rotatif en fonctionnement.","lore":"Cette hache de combat d’Owl est construite autour d’une scie circulaire résistante aux chocs.\n\nElle peut s’utiliser avec sa lame bloquée comme une arme blanche ou avec le système rotatif en fonctionnement.","data":{"Type":"Haches","DGT":"4","Portee":"Contact","Proprietes":"Dual mode (E) ; Système rotatif","Cap.":"8"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'armes-melee-insurrection-sp-new-partisan', 'Insurrection SP New Partisan', NULL, '{"nature":"equipement","kind":"equipment","category":"Armement — Armes de mêlée","sourceCategory":"Armes — Mêlée","price":null,"priceMin":null,"priceMax":null,"priceLabel":"Mission","generation":null,"charge":null,"stress":null,"slots":null,"effect":"La SP New Partisan est une arme de l’Insurrection produite par impression et frittage. Sa forme et sa taille peuvent varier : lance, épée ou hache conservent généralement la même efficacité. L’arme peut également se rétracter.","lore":"La SP New Partisan est une arme de l’Insurrection produite par impression et frittage.\n\nSa forme et sa taille peuvent varier : lance, épée ou hache conservent généralement la même efficacité. L’arme peut également se rétracter.","data":{"Type":"Armes d’hast","DGT":"5","Portee":"Contact","Proprietes":"Pliant"},"vehicle":false,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'd-fence', 'D-Fence', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+1 Defense active.","lore":"D-Fence est le pare-feu personnel d’entrée de gamme d’Aces : une défense volontairement lisible, représentée comme une barrière simple que le Neurodiver comprend immédiatement lorsqu’une attaque arrive. Cette clarté participe à son succès auprès des utilisateurs qui veulent une protection fiable sans apprendre une interface complexe.\n\nAces traite ici la sécurité comme un outil de réflexe plutôt que comme une forteresse autonome. D-Fence accompagne la défense active de son utilisateur et dépend donc toujours de son attention, de son Neurodive et du reste de son équipement ; il n’existe pas comme bouclier indépendant qui continuerait à combattre seul.","data":{"id":"d-fence","name":"D-Fence","category":"Defensif","priceMode":"exact","price":500,"priceLabel":"500 $","effect":"+1 Defense active.","data":{},"_path":"entries / 0"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'shieldic', 'Shieldic', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":550,"priceMin":null,"priceMax":null,"priceLabel":"550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+1 Defense active ; si des PV passent, 1 PV neural a l''assaillant.","lore":"Shieldic, signé ArcaNetwork, prend l’apparence d’un bouclier lumineux réactif dont la surface semble renvoyer une partie de l’agression vers son origine. L’esthétique traduit bien sa philosophie : protéger, mais faire comprendre à l’attaquant que franchir la défense possède un coût.\n\nCe comportement en fait un choix apprécié des Neurodivers qui veulent décourager les attaques répétées plutôt que seulement encaisser. La contre-réaction n’est toutefois pas une attaque autonome ni une immunité : Shieldic reste un programme défensif qui travaille au moment où son utilisateur tente réellement de bloquer une intrusion hostile.","data":{"id":"shieldic","name":"Shieldic","category":"Defensif","priceMode":"exact","price":550,"priceLabel":"550 $","effect":"+1 Defense active ; si des PV passent, 1 PV neural a l''assaillant.","data":{},"_path":"entries / 1"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'mywall', 'MyWall', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":550,"priceMin":null,"priceMax":null,"priceLabel":"550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+2 Defense active.","lore":"MyWall appartient à Monarch System et adopte sans surprise une imagerie monumentale : mur massif, architecture de données épaisse, impression que l’avatar se retranche derrière une structure plutôt que derrière un simple écran. Le programme privilégie la résistance directe à la subtilité.\n\nCette mise en scène correspond à la culture visuelle de Monarch, qui transforme volontiers la cybersécurité en forteresse, royaume ou siège. MyWall reste pourtant un outil personnel : le mur existe parce que le Neurodiver l’emploie activement, pas parce qu’il aurait créé une zone inviolable dans tout le système.","data":{"id":"mywall","name":"MyWall","category":"Defensif","priceMode":"exact","price":550,"priceLabel":"550 $","effect":"+2 Defense active.","data":{},"_path":"entries / 2"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', '2-fence', '2-Fence', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":1000,"priceMin":null,"priceMax":null,"priceLabel":"1000 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+1 et 2 Interceptions annulant chacune une Neuroattaque apres Defense ratee.","lore":"2-Fence est l’un des programmes Aces les plus immédiatement reconnaissables : deux agents humanoïdes accompagnent le Neurodiver et se placent tour à tour entre lui et l’attaque. Cette représentation donne au porteur une lecture intuitive de ses ressources défensives sans passer par une jauge abstraite.\n\nLa force du concept tient aussi à sa limite visible : chaque intervention d’un agent le retire temporairement de la paire. Le Neurodiver voit donc sa protection s’éroder à mesure qu’il demande aux deux figures d’absorber des erreurs, jusqu’à devoir leur laisser le temps de se reconstruire dans un environnement sûr.","data":{"id":"2-fence","name":"2-Fence","category":"Defensif","priceMode":"exact","price":1000,"priceLabel":"1 000 $","effect":"+1 et 2 Interceptions annulant chacune une Neuroattaque apres Defense ratee.","data":{},"_path":"entries / 3"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'omnithorns', 'Omnithorns', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":1250,"priceMin":null,"priceMax":null,"priceLabel":"1250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+1 Defense ; si des PV passent, 2 PV neuronaux a l''assaillant.","lore":"Omnithorns est une défense ArcaNetwork agressive, souvent figurée comme une couronne ou un réseau d’épines qui se referme sur toute intrusion ayant réellement franchi la périphérie. Le programme ne cherche pas seulement à bloquer : il rend l’idée même de forcer le passage désagréable pour l’assaillant.\n\nCette logique convient aux utilisateurs exposés à des attaques répétées et prêts à accepter une défense plus hostile. Les épines restent néanmoins une réaction liée à la défense du porteur ; elles ne parcourent pas le réseau à la recherche de cibles et ne transforment pas Omnithorns en programme offensif permanent.","data":{"id":"omnithorns","name":"Omnithorns","category":"Defensif","priceMode":"exact","price":1250,"priceLabel":"1 250 $","effect":"+1 Defense ; si des PV passent, 2 PV neuronaux a l''assaillant.","data":{},"_path":"entries / 4"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'castland', 'Castland', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":1250,"priceMin":null,"priceMax":null,"priceLabel":"1250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+3 Defense active.","lore":"Castland est la forteresse personnelle de Monarch System : tours, courtines et profondeur architecturale donnent à l’utilisateur l’impression de se retirer derrière plusieurs couches de défense. Là où MyWall montre une ligne, Castland met en scène tout un espace conçu pour absorber la pression.\n\nCe langage visuel sert une fonction très directe : aider le Neurodiver à tenir sa position face à une attaque frontale. Castland n’est ni un système de traçage ni un logiciel d’intrusion ; sa spécialisation assumée explique qu’il séduise surtout ceux qui préfèrent exceller dans la résistance plutôt que multiplier les fonctions annexes.","data":{"id":"castland","name":"Castland","category":"Defensif","priceMode":"exact","price":1250,"priceLabel":"1 250 $","effect":"+3 Defense active.","data":{},"_path":"entries / 5"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'datablast', 'Datablast', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":600,"priceMin":null,"priceMax":null,"priceLabel":"600 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"DGT neural = marge ; marge 6+ : -3 prochain Neurodive de la cible.","lore":"Datablast est une attaque ArcaNetwork qui se manifeste comme une nébuleuse dense d’informations contradictoires, de paquets parasites et de formes visuelles agressives. L’objectif n’est pas seulement de heurter la présence adverse : le programme cherche à laisser son rythme cognitif désorganisé juste après l’impact.\n\nCette philosophie en fait une ouverture de duel autant qu’une arme brute. Un Neurodiver peut employer Datablast pour créer un moment de flottement avant de poursuivre son action, mais l’effet reste une perturbation du combat numérique ; il ne réécrit pas durablement l’esprit de la cible et ne produit aucun contrôle hors connexion.","data":{"id":"datablast","name":"Datablast","category":"Offensif","priceMode":"exact","price":600,"priceLabel":"600 $","effect":"DGT neural = marge ; marge 6+ : -3 prochain Neurodive de la cible.","data":{},"_path":"entries / 6"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'dark-holes', 'Dark Holes', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":800,"priceMin":null,"priceMax":null,"priceLabel":"800 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Marge +1 PV.","lore":"Dark Holes porte la signature théâtrale de Monarch System : des singularités sombres s’ouvrent dans l’environnement numérique et donnent l’impression d’engloutir les structures de données proches. Derrière cette présentation, le programme assume une philosophie très simple : concentrer l’agression plutôt que chercher un effet secondaire subtil.\n\nC’est précisément cette franchise qui séduit ses utilisateurs. Dark Holes ne promet ni ouverture automatique, ni sabotage prolongé, ni manipulation de la connexion ; il occupe la place du marteau offensif dans un arsenal Neuro, utile lorsque la priorité est de faire céder la présence adverse plutôt que de préparer autre chose.","data":{"id":"dark-holes","name":"Dark Holes","category":"Offensif","priceMode":"exact","price":800,"priceLabel":"800 $","effect":"Marge +1 PV.","data":{},"_path":"entries / 7"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'darksword', 'Darksword', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":800,"priceMin":null,"priceMax":null,"priceLabel":"800 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Marge ; marge 6+ : Intrusion/Controle gratuit meme systeme, 1/round.","lore":"Darksword est une lame logique d’Aces : l’attaque est représentée comme une coupe qui ne cherche pas seulement à blesser la défense adverse mais à laisser une ouverture exploitable dans le système. L’image de l’épée rend immédiatement compréhensible l’idée d’un passage créé par la frappe elle-même.\n\nLes utilisateurs de Darksword le choisissent lorsqu’ils veulent enchaîner agression et exploitation plutôt que mener deux opérations totalement séparées. La brèche ne devient toutefois utile que si le Neurodiver sait quoi en faire ; le programme ne décide pas à sa place quel système contrôler ni quelle donnée extraire.","data":{"id":"darksword","name":"Darksword","category":"Offensif","priceMode":"exact","price":800,"priceLabel":"800 $","effect":"Marge ; marge 6+ : Intrusion/Controle gratuit meme systeme, 1/round.","data":{},"_path":"entries / 8"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'langoliers', 'Langoliers', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":2500,"priceMin":null,"priceMax":null,"priceLabel":"2500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Marge +1 ; peut extraire fragment de donnees d''une IA/programme detruit.","lore":"Langoliers, développé par ArcaNetwork, apparaît comme une nuée prédatrice qui dévore les structures logicielles de sa cible au lieu de simplement les repousser. Cette représentation souligne une particularité recherchée par les récupérateurs de données : ce qui est détruit peut parfois laisser derrière lui des fragments encore exploitables.\n\nLe programme est donc autant associé au pillage numérique qu’au duel. Il ne crée cependant aucune information inexistante : journaux, clés ou morceaux de mémoire doivent avoir été réellement accessibles à la cible détruite. Langoliers fouille les restes disponibles, il ne transforme pas chaque programme vaincu en coffre rempli de secrets.","data":{"id":"langoliers","name":"Langoliers","category":"Offensif","priceMode":"exact","price":2500,"priceLabel":"2 500 $","effect":"Marge +1 ; peut extraire fragment de donnees d''une IA/programme detruit.","data":{},"_path":"entries / 9"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'calamities-reign', 'Calamities Reign', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":2500,"priceMin":null,"priceMax":null,"priceLabel":"2500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Marge +3 ; en echec, prochain assaillant Neuro contre l''utilisateur +3.","lore":"Calamities Reign est l’une des offensives les plus démonstratives de Monarch System. L’environnement semble se briser sous une succession de catastrophes numériques, comme si le programme voulait submerger l’adversaire sous une violence impossible à traiter proprement plutôt que rechercher une faille élégante.\n\nCette puissance explique aussi sa réputation de programme exigeant : un assaut aussi engagé laisse peu de marge pour corriger une erreur ou masquer une ouverture. Les Neurodivers qui le chargent acceptent une philosophie de tout ou rien, où l’échec peut rendre leur propre position momentanément plus vulnérable.","data":{"id":"calamities-reign","name":"Calamities Reign","category":"Offensif","priceMode":"exact","price":2500,"priceLabel":"2 500 $","effect":"Marge +3 ; en echec, prochain assaillant Neuro contre l''utilisateur +3.","data":{},"_path":"entries / 10"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'darkalibur', 'Darkalibur', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":2500,"priceMin":null,"priceMax":null,"priceLabel":"2500 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Un jet contre jusqu''a 2 cibles distinctes ; jamais deux frappes sur la meme.","lore":"Darkalibur est la version Aces du mythe de la lame légendaire : une attaque représentée par une épée double capable de répartir une même séquence offensive vers deux présences distinctes. L’esthétique héroïque cache surtout un programme conçu pour gérer plusieurs menaces connectées au même instant.\n\nSa force vient de cette division de l’attention, pas d’une multiplication infinie des coups. Face à une seule cible, Darkalibur redevient une attaque unique ; face à plusieurs adversaires, il permet surtout au Neurodiver de ne pas choisir immédiatement lequel des deux doit rester entièrement hors de la séquence.","data":{"id":"darkalibur","name":"Darkalibur","category":"Offensif","priceMode":"exact","price":2500,"priceLabel":"2 500 $","effect":"Un jet contre jusqu''a 2 cibles distinctes ; jamais deux frappes sur la meme.","data":{},"_path":"entries / 11"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'overload-iv', 'OverLoad IV', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":750,"priceMin":null,"priceMax":null,"priceLabel":"750 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Hardlag : -3, perte de passe, puis blocage Neuro selon marge.","lore":"OverLoad IV est un programme ArcaNetwork de contrôle offensif qui cherche à saturer la capacité de traitement de la cible plutôt qu’à détruire directement sa présence numérique. Tâches parasites, interruptions et demandes contradictoires produisent un Hardlag qui donne l’impression que tout répond avec une fraction de seconde de retard.\n\nLe résultat est particulièrement pénible dans un affrontement où chaque fenêtre d’action compte. OverLoad ne détruit pourtant ni matériel ni identité : il encombre temporairement le fonctionnement de la cible et profite de la pression déjà présente, ce qui en fait un outil de tempo davantage qu’une arme de dégâts.","data":{"id":"overload-iv","name":"OverLoad IV","category":"Controle offensif","priceMode":"exact","price":750,"priceLabel":"750 $","effect":"Hardlag : -3, perte de passe, puis blocage Neuro selon marge.","data":{},"_path":"entries / 12"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'king-crash', 'King Crash', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":1250,"priceMin":null,"priceMax":null,"priceLabel":"1250 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Deconnexion forcee ; forte marge peut ajouter Stress augmentique temporaire.","lore":"King Crash est une attaque de Monarch System dirigée contre le lien lui-même. Plutôt que d’abattre l’avatar, le programme inverse, corrompt ou surcharge les protocoles qui maintiennent la présence connectée jusqu’à donner l’impression que le réseau rejette brutalement l’utilisateur.\n\nCette vocation en fait une menace très différente d’une Neuroattaque classique : le but est l’expulsion et la rupture de continuité. La déconnexion ne donne aucun contrôle sur l’appareil quitté et ne garantit pas que la cible restera dehors ; King Crash cherche surtout à gagner le temps créé par l’arrachement.","data":{"id":"king-crash","name":"King Crash","category":"Controle offensif","priceMode":"exact","price":1250,"priceLabel":"1 250 $","effect":"Deconnexion forcee ; forte marge peut ajouter Stress augmentique temporaire.","data":{},"_path":"entries / 13"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'ace-burnx', 'Ace-BurnX', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":750,"priceMin":null,"priceMax":null,"priceLabel":"750 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+1 ou +2 Stress augmentique temporaire sur augmentations accessibles, max +3.","lore":"Ace-BurnX est un programme Aces qui détourne l’accès numérique aux augmentations pour leur envoyer une succession de micro-commandes parasites. Plutôt que de casser immédiatement un implant, il pousse les systèmes corporels connectés à travailler de travers, chauffer et accumuler une charge que le porteur ressent physiquement.\n\nLe programme incarne la frontière inconfortable entre Neurodive et cybernétique : lorsqu’un corps accepte d’exposer ses augmentations au réseau, l’attaque peut passer par cette même porte. Ace-BurnX ne crée toutefois aucune connexion inexistante ; un implant réellement isolé ou inaccessible ne devient pas soudain une cible.","data":{"id":"ace-burnx","name":"Ace-BurnX","category":"Controle offensif","priceMode":"exact","price":750,"priceLabel":"750 $","effect":"+1 ou +2 Stress augmentique temporaire sur augmentations accessibles, max +3.","data":{},"_path":"entries / 14"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'zero-k', 'Zero K', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":1550,"priceMin":null,"priceMax":null,"priceLabel":"1550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+3 contre deconnexion forcee ; evacuation d''urgence.","lore":"Zero K est le programme d’évacuation d’ArcaNetwork, conçu pour maintenir assez de cohérence dans une connexion agressée pour permettre au Neurodiver de sortir proprement. Son interface évoque souvent un chemin froid, vide et stable au milieu d’un environnement qui se fragmente ou tente de retenir l’utilisateur.\n\nLes Crawler prudents le considèrent moins comme une défense de prestige que comme une assurance de survie numérique. Zero K n’annule pas les conséquences déjà subies et ne rend pas toute déconnexion impossible ; il fournit surtout un outil spécialisé quand rester connecté devient plus dangereux que renoncer à l’action en cours.","data":{"id":"zero-k","name":"Zero K","category":"Defensif / fuite","priceMode":"exact","price":1550,"priceLabel":"1 550 $","effect":"+3 contre deconnexion forcee ; evacuation d''urgence.","data":{},"_path":"entries / 15"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'icewall', 'Icewall', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":1050,"priceMin":null,"priceMax":null,"priceLabel":"1050 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Intercepte les attaques de connexion/augmentations d''un allie surveille.","lore":"Icewall est une défense Monarch System pensée pour protéger quelqu’un d’autre. Le programme se déploie comme une paroi froide entre l’attaque et la connexion surveillée, permettant à un Neurodiver de jouer réellement le rôle de garde du corps numérique au lieu de ne protéger que son propre avatar.\n\nCette philosophie en fait un outil d’équipe rare dans un domaine souvent très individuel. L’utilisateur doit cependant rester disponible pour intervenir et choisir qui il surveille ; Icewall ne crée pas une protection permanente sur tous les alliés connectés et ne remplace pas leur propre sécurité.","data":{"id":"icewall","name":"Icewall","category":"Defensif / garde","priceMode":"exact","price":1050,"priceLabel":"1 050 $","effect":"Intercepte les attaques de connexion/augmentations d''un allie surveille.","data":{},"_path":"entries / 16"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'data-shield', 'Data-Shield', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":650,"priceMin":null,"priceMax":null,"priceLabel":"650 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+2 Difficulté Intrusion max25 ; alerte et trace. Ne se cumule pas avec Sutr.","lore":"Data-Shield est une sentinelle Aces destinée à un ensemble de données ou à un environnement déterminé. Plutôt que de combattre comme un avatar, le programme renforce les contrôles existants, observe les tentatives de passage et aide le propriétaire à distinguer une activité normale d’une intrusion qui mérite son attention.\n\nSon intérêt se trouve donc dans la préparation d’un espace numérique privé : dossier sensible, petit serveur, environnement personnel. Data-Shield ne rend pas les données indestructibles et ne remplace pas les sauvegardes ; il ajoute une couche de vigilance à une architecture qui doit déjà exister.","data":{"id":"data-shield","name":"Data-Shield","category":"Sentinelle","priceMode":"exact","price":650,"priceLabel":"650 $","effect":"+2 Difficulté Intrusion max25 ; alerte et trace. Ne se cumule pas avec Sutr.","data":{},"_path":"entries / 17"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'stealthy-timmy', 'Stealthy Timmy', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":550,"priceMin":null,"priceMax":null,"priceLabel":"550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Efface/falsifie les traces ; marge 6+ fausse piste.","lore":"Stealthy Timmy est l’agent de masquage d’ArcaNetwork, souvent représenté comme un petit personnage affairé qui passe derrière le Neurodiver pour effacer, déplacer ou réécrire les traces de son passage. Cette apparence légère cache une fonction essentielle pour ceux qui veulent survivre à une intrusion après l’avoir réussie.\n\nLe programme travaille uniquement sur ce qu’il peut encore atteindre. Copies déjà exportées, sauvegardes isolées ou témoins extérieurs ne disparaissent pas parce que Timmy nettoie un nœud ; son véritable talent consiste à rendre l’enquête plus difficile, voire à laisser une origine plausible derrière lui lorsqu’il dispose d’assez de matière.","data":{"id":"stealthy-timmy","name":"Stealthy Timmy","category":"Masquage","priceMode":"exact","price":550,"priceLabel":"550 $","effect":"Efface/falsifie les traces ; marge 6+ fausse piste.","data":{},"_path":"entries / 18"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'jorgmunworm', 'Jorgmunworm', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":550,"priceMin":null,"priceMax":null,"priceLabel":"550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+2 Intrusion seulement.","lore":"Jorgmunworm est l’outil d’intrusion de Monarch System, figuré comme un ver gigantesque qui s’enroule autour d’une architecture et multiplie les petits points de pression jusqu’à trouver celui qui cédera. Le programme privilégie la recherche et l’entretien de micro-failles plutôt qu’une unique attaque spectaculaire.\n\nCette spécialisation explique pourquoi les Crawler le chargent lorsqu’ils savent que leur problème principal sera d’entrer. Une fois la frontière franchie, Jorgmunworm n’apporte pas soudain les compétences nécessaires pour contrôler, masquer ou combattre ; il aide à ouvrir la porte, pas à décider quoi faire dans la pièce.","data":{"id":"jorgmunworm","name":"Jorgmunworm","category":"Intrusion","priceMode":"exact","price":550,"priceLabel":"550 $","effect":"+2 Intrusion seulement.","data":{},"_path":"entries / 19"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'nanaruto', 'Nanaruto', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":650,"priceMin":null,"priceMax":null,"priceLabel":"650 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Defense contre IA automatisee avec Volonte + Neurodive.","lore":"Nanaruto est un leurre Aces qui multiplie l’avatar en copies visuellement crédibles pour saturer la décision d’une défense automatisée. L’interface transforme le Neurodiver en foule de doubles qui exécutent des mouvements similaires jusqu’à rendre le choix de la vraie cible coûteux pour une IA simple.\n\nLe procédé fonctionne surtout parce qu’une défense automatisée suit des critères que le programme peut exploiter. Un adversaire humain ou une IA sophistiquée peut chercher d’autres indices, recouper les comportements ou ignorer le théâtre visuel ; Nanaruto est un outil de tromperie ciblé, pas une invisibilité numérique.","data":{"id":"nanaruto","name":"Nanaruto","category":"Leurre","priceMode":"exact","price":650,"priceLabel":"650 $","effect":"Defense contre IA automatisee avec Volonte + Neurodive.","data":{},"_path":"entries / 20"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'swampro', 'Swampro', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":450,"priceMin":null,"priceMax":null,"priceLabel":"450 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"-2 actions Neuro hostiles contre l''environnement.","lore":"Swampro est une défense environnementale ArcaNetwork qui donne l’impression que les actions hostiles s’enfoncent dans une couche de données boueuse et résistante. Le programme ne construit pas une forteresse ; il rend surtout chaque manipulation agressive plus lente, plus pénible et plus coûteuse dans l’espace qu’il protège.\n\nCe type de logiciel convient aux propriétaires qui veulent défendre un environnement précis sans transformer tout leur loadout en arsenal de duel. Swampro doit toutefois être maintenu là où il agit et protège un lieu numérique déterminé ; il ne suit pas automatiquement le propriétaire partout dans le Holonet.","data":{"id":"swampro","name":"Swampro","category":"Defense environnement","priceMode":"exact","price":450,"priceLabel":"450 $","effect":"-2 actions Neuro hostiles contre l''environnement.","data":{},"_path":"entries / 21"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'sutr', 'Sutr', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":2550,"priceMin":null,"priceMax":null,"priceLabel":"2550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+1 niveau de securite, max25 ; echec narratif hostile = expulsion.","lore":"Sutr est le gardien monumental de Monarch System, souvent représenté comme un géant de feu occupant l’entrée d’un dossier ou d’un environnement sensible. Sa présence transforme la sécurité existante en obstacle plus intimidant et donne immédiatement au visiteur l’impression qu’il entre dans un territoire explicitement surveillé.\n\nLe programme est particulièrement adapté aux infrastructures qui veulent une sentinelle persistante plutôt qu’une défense de duel. Sutr renforce et surveille un environnement donné ; il ne rend pas toute intrusion impossible et ne remplace pas la conception correcte des droits, sauvegardes et couches de sécurité autour de ce qu’il garde.","data":{"id":"sutr","name":"Sutr","category":"Securite","priceMode":"exact","price":2550,"priceLabel":"2 550 $","effect":"+1 niveau de securite, max25 ; echec narratif hostile = expulsion.","data":{},"_path":"entries / 22"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'neurald', 'Neurald', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":450,"priceMin":null,"priceMax":null,"priceLabel":"450 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Poursuit une tache routiniere, sans PA de combat gratuits.","lore":"Neurald est une petite automatisation Aces constituée de plusieurs agents spécialisés capables de poursuivre une tâche routinière après que le Neurodiver l’a correctement lancée. Recherche simple, tri, copie ou surveillance répétitive sont exactement les travaux que l’on préfère déléguer plutôt que maintenir consciemment pendant toute leur durée.\n\nLa limite du concept est celle de toute automatisation : Neurald est bon tant que le problème reste celui qui lui a été confié. Une nouvelle sécurité, un choix ambigu ou une opposition intelligente exige de nouveau un opérateur ; le programme économise de l’attention, il ne crée pas un second Crawler autonome.","data":{"id":"neurald","name":"Neurald","category":"Automatisation","priceMode":"exact","price":450,"priceLabel":"450 $","effect":"Poursuit une tache routiniere, sans PA de combat gratuits.","data":{},"_path":"entries / 23"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'sicarius', 'Sicarius', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":1550,"priceMin":null,"priceMax":null,"priceLabel":"1550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Deconstruction autonome ; 1h/30m/10m/1m selon DR.","lore":"Sicarius est un agent ArcaNetwork de sabotage lent. Une fois introduit dans une cible logicielle, il ne cherche pas le spectacle d’une Neuroattaque mais la déconstruction méthodique des dépendances, fichiers et fonctions qui permettent au programme adverse de continuer à exister proprement.\n\nCette lenteur le rend particulièrement adapté au sabotage clandestin et aux objectifs différés. La difficulté est d’abord de l’insérer au bon endroit puis de lui laisser le temps de travailler ; une cible isolée, restaurée depuis une sauvegarde ou inspectée assez tôt peut encore interrompre la déconstruction avant son terme.","data":{"id":"sicarius","name":"Sicarius","category":"Sabotage","priceMode":"exact","price":1550,"priceLabel":"1 550 $","effect":"Deconstruction autonome ; 1h/30m/10m/1m selon DR.","data":{},"_path":"entries / 24"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'groundswell', 'Groundswell', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":3550,"priceMin":null,"priceMax":null,"priceLabel":"3550 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"+2 aux tests offensifs Neuro dans l''environnement, pour tous.","lore":"Groundswell est un programme de guerre de Monarch System qui modifie l’ambiance même d’un environnement numérique. Tout paraît plus agressif, plus réactif, comme si le terrain encourageait les attaques et réduisait la distance psychologique entre intention hostile et passage à l’acte.\n\nLa particularité la plus dangereuse du programme est son impartialité : il transforme le champ de bataille, pas seulement son propriétaire. Déployer Groundswell revient donc à parier que son équipe saura mieux exploiter l’escalade que l’adversaire ; dans un environnement mal contrôlé, le bonus offert à tous peut se retourner immédiatement contre celui qui l’a installé.","data":{"id":"groundswell","name":"Groundswell","category":"Guerre","priceMode":"exact","price":3550,"priceLabel":"3 550 $","effect":"+2 aux tests offensifs Neuro dans l''environnement, pour tous.","data":{},"_path":"entries / 25"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'duppli-cat', 'Duppli''cat', NULL, '{"nature":"equipement","kind":"equipment","category":"Neuroprogrammes","sourceCategory":"Neuroprogrammes","price":450,"priceMin":null,"priceMax":null,"priceLabel":"450 $","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Copie IA/donnees ; laisse un Cat donnant +3 prochaine Intrusion mais detecte.","lore":"Duppli’cat est le copieur d’Aces, représenté comme un petit félin qui se glisse dans les structures accessibles, en rapporte une réplique et laisse parfois derrière lui une marque presque moqueuse. Le programme vise les données complexes, IA et architectures qu’une simple copie de fichier ne suffit pas à reproduire correctement.\n\nLa copie reste prisonnière des dépendances de l’original : matériel particulier, licence, clé physique ou environnement incompatible ne disparaissent pas avec les données. Le fameux Cat laissé derrière lui peut devenir une opportunité de retour, mais aussi un indice très voyant pour l’administrateur qui découvre qu’on est passé par là.","data":{"id":"duppli-cat","name":"Duppli''cat","category":"Copie","priceMode":"exact","price":450,"priceLabel":"450 $","effect":"Copie IA/donnees ; laisse un Cat donnant +3 prochaine Intrusion mais detecte.","data":{},"_path":"entries / 26"},"vehicle":false,"neuro":true,"recurring":"one_off","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'moto-moderne', 'Moto moderne', NULL, '{"nature":"equipement","kind":"equipment","category":"Véhicules","sourceCategory":"Véhicules","price":null,"priceMin":null,"priceMax":null,"priceLabel":"","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Assistance/autopilote selon modele ; tres exposee","lore":"La moto moderne reste un véhicule où le conducteur est très exposé, même lorsque le modèle propose des aides de conduite ou un autopilote. Ces assistances peuvent faciliter certains déplacements, mais elles ne changent ni le faible volume du véhicule ni l’absence de carrosserie protectrice autour de son utilisateur.\n\nLe niveau d’automatisation dépend du modèle : toutes les motos modernes ne disposent donc pas du même degré d’assistance. Quel que soit l’équipement embarqué, elles conservent surtout les avantages et les contraintes d’un moyen de transport léger où la protection repose peu sur la structure du véhicule.","data":{"id":"moto-moderne","name":"Moto moderne","priceMode":"range","priceMin":5000,"priceMax":20000,"priceLabel":"5 000 - 20 000 $","effect":"Assistance/autopilote selon modele ; tres exposee","data":{"Places":"1-2","Str.":"8","Blind.":"0","Sec.":"12","Auto.":"15","Entretien/mois":"50 - 150 $","Notes":"Assistance/autopilote selon modele ; tres exposee"},"_path":"entries / 0"},"vehicle":true,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'vieille-voiture-manuelle', 'Vieille voiture manuelle', NULL, '{"nature":"equipement","kind":"equipment","category":"Véhicules","sourceCategory":"Véhicules","price":null,"priceMin":null,"priceMax":null,"priceLabel":"","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Taxee, permis, faible surface de hack","lore":"La vieille voiture manuelle appartient à une génération où la conduite reste directement entre les mains du conducteur. Son caractère ancien lui donne une faible surface de hack par rapport aux véhicules fortement connectés, puisque moins de fonctions essentielles dépendent d’un système autonome accessible à distance.\n\nCette simplicité numérique ne la rend pas avantageuse sur tous les plans : elle reste soumise au permis et à la taxation prévus pour ce type de véhicule. Sa faible exposition au piratage vient donc d’une technologie plus manuelle, pas d’un système de cybersécurité particulièrement sophistiqué.","data":{"id":"vieille-voiture-manuelle","name":"Vieille voiture manuelle","priceMode":"range","priceMin":500,"priceMax":5000,"priceLabel":"500 - 5 000 $","effect":"Taxee, permis, faible surface de hack","data":{"Places":"4-5","Str.":"15","Blind.":"0","Sec.":"-","Auto.":"-","Entretien/mois":"150 - 500 $+","Notes":"Taxee, permis, faible surface de hack"},"_path":"entries / 1"},"vehicle":true,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'citypod-bullmotors', 'CityPod Bullmotors', NULL, '{"nature":"equipement","kind":"equipment","category":"Véhicules","sourceCategory":"Véhicules","price":null,"priceMin":null,"priceMax":null,"priceLabel":"","generation":null,"charge":null,"stress":null,"slots":null,"effect":"VAP urbain, facile a hacker","lore":"Le CityPod Bullmotors est un VAP urbain conçu pour les déplacements quotidiens en ville. Son fonctionnement connecté et automatisé le rend pratique dans cet environnement, mais la contrepartie documentée est une sécurité numérique faible : le véhicule est facile à hacker.\n\nCette vulnérabilité concerne précisément sa dépendance aux systèmes connectés. Le CityPod reste un moyen de transport civil courant, mais quelqu’un qui compte sur lui dans une situation sensible doit considérer qu’un adversaire capable d’atteindre ses systèmes dispose d’une surface d’attaque bien plus intéressante que sur une vieille voiture manuelle.","data":{"id":"citypod-bullmotors","name":"CityPod Bullmotors","priceMode":"range","priceMin":8000,"priceMax":12000,"priceLabel":"8 000 - 12 000 $","effect":"VAP urbain, facile a hacker","data":{"Places":"2","Str.":"15","Blind.":"0","Sec.":"12","Auto.":"15","Entretien/mois":"50 - 100 $","Notes":"VAP urbain, facile a hacker"},"_path":"entries / 2"},"vehicle":true,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'vap-familial', 'VAP familial', NULL, '{"nature":"equipement","kind":"equipment","category":"Véhicules","sourceCategory":"Véhicules","price":null,"priceMin":null,"priceMax":null,"priceLabel":"","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Autonome civil courant","lore":"Le VAP familial représente le véhicule autonome civil courant destiné aux déplacements d’un foyer. Il privilégie l’usage quotidien et l’autonomie de conduite plutôt qu’une vocation professionnelle, tactique ou prestigieuse particulière.\n\nSon caractère banal est justement sa principale identité : il appartient au paysage normal de la mobilité civile. Les performances, la sécurité et les équipements précis dépendent du modèle réellement utilisé ; la catégorie garantit surtout un transport familial autonome, pas des capacités spécialisées.","data":{"id":"vap-familial","name":"VAP familial","priceMode":"range","priceMin":15000,"priceMax":25000,"priceLabel":"15 000 - 25 000 $","effect":"Autonome civil courant","data":{"Places":"4-6","Str.":"15","Blind.":"0","Sec.":"15","Auto.":"15","Entretien/mois":"75 - 150 $","Notes":"Autonome civil courant"},"_path":"entries / 3"},"vehicle":true,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'horntruck', 'Horntruck', NULL, '{"nature":"equipement","kind":"equipment","category":"Véhicules","sourceCategory":"Véhicules","price":null,"priceMin":null,"priceMax":null,"priceLabel":"","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Utilitaire Bullmotors","lore":"Le Horntruck est l’utilitaire de la gamme Bullmotors. Il est destiné aux usages où transporter du matériel ou disposer d’un véhicule de travail compte davantage que le confort premium ou la représentation sociale.\n\nSa désignation d’utilitaire décrit sa fonction générale sans lui donner automatiquement des équipements spécialisés. Atelier mobile, protections supplémentaires ou aménagements particuliers doivent exister réellement sur le véhicule concerné ; le Horntruck de base fournit avant tout une plateforme Bullmotors destinée au travail et au transport.","data":{"id":"horntruck","name":"Horntruck","priceMode":"range","priceMin":20000,"priceMax":35000,"priceLabel":"20 000 - 35 000 $","effect":"Utilitaire Bullmotors","data":{"Places":"2-3 + cargo","Str.":"20","Blind.":"1","Sec.":"15","Auto.":"15","Entretien/mois":"150 - 300 $","Notes":"Utilitaire Bullmotors"},"_path":"entries / 4"},"vehicle":true,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'gundriver-modifie', 'Gundriver modifié', NULL, '{"nature":"equipement","kind":"equipment","category":"Véhicules","sourceCategory":"Véhicules","price":null,"priceMin":null,"priceMax":null,"priceLabel":"","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Manuel, modifie, souvent peu tracable","lore":"Le Gundriver modifié est un véhicule manuel transformé par rapport à sa configuration d’origine. Ces modifications et son fonctionnement moins dépendant d’une conduite autonome en font un choix adapté à ceux qui veulent garder la main sur la machine plutôt que s’en remettre à un réseau de contrôle permanent.\n\nIl est aussi souvent peu traçable, sans que cette discrétion soit absolue. Elle dépend de l’histoire du véhicule, de ses identifiants, de ses modifications et de la manière dont il est utilisé ; le terme décrit une tendance de cette catégorie, pas une immunité automatique à toute enquête ou surveillance.","data":{"id":"gundriver-modifie","name":"Gundriver modifie","priceMode":"range","priceMin":10000,"priceMax":30000,"priceLabel":"10 000 - 30 000 $","effect":"Manuel, modifie, souvent peu tracable","data":{"Places":"2-5","Str.":"20","Blind.":"1","Sec.":"- ou 12","Auto.":"-","Entretien/mois":"200 - 500 $+","Notes":"Manuel, modifie, souvent peu tracable"},"_path":"entries / 5"},"vehicle":true,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'nymphrover-executive', 'Nymphrover Executive', NULL, '{"nature":"equipement","kind":"equipment","category":"Véhicules","sourceCategory":"Véhicules","price":null,"priceMin":null,"priceMax":null,"priceLabel":"","generation":null,"charge":null,"stress":null,"slots":null,"effect":"VAP premium, securite superieure","lore":"Le Nymphrover Executive est un VAP premium où confort de gamme et sécurité supérieure font partie de la proposition du véhicule. Il s’adresse à un usage civil haut de gamme plutôt qu’au simple déplacement fonctionnel d’un véhicule autonome ordinaire.\n\nSa sécurité renforcée le distingue notamment des VAP urbains plus faciles à compromettre, mais elle ne doit pas être comprise comme une invulnérabilité. Les protections réellement opposées à une intrusion restent celles du modèle et de sa configuration, simplement à un niveau supérieur à la moyenne civile.","data":{"id":"nymphrover-executive","name":"Nymphrover Executive","priceMode":"range","priceMin":40000,"priceMax":80000,"priceLabel":"40 000 - 80 000 $","effect":"VAP premium, securite superieure","data":{"Places":"4-6","Str.":"20","Blind.":"2","Sec.":"18","Auto.":"18","Entretien/mois":"200 - 400 $","Notes":"VAP premium, securite superieure"},"_path":"entries / 6"},"vehicle":true,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'nymphrover-security', 'Nymphrover Security', NULL, '{"nature":"equipement","kind":"equipment","category":"Véhicules","sourceCategory":"Véhicules","price":null,"priceMin":null,"priceMax":null,"priceLabel":"","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Transport protege corporatif","lore":"Le Nymphrover Security est un transport corporatif protégé. Sa conception répond à un besoin où déplacer des personnes sous une protection supérieure compte davantage que l’apparence d’un simple véhicule de fonction ou le confort d’un VAP familial.\n\nLe véhicule fournit donc une base de transport sécurisée, mais la protection d’un trajet dépend encore de son emploi réel. Escorte, itinéraire, équipage ou dispositifs supplémentaires ne sont pas inclus par principe dans le nom du modèle : ils doivent être présents dans la scène pour compter.","data":{"id":"nymphrover-security","name":"Nymphrover Security","priceMode":"range","priceMin":80000,"priceMax":150000,"priceLabel":"80 000 - 150 000 $","effect":"Transport protege corporatif","data":{"Places":"4-6","Str.":"25","Blind.":"5","Sec.":"21","Auto.":"18","Entretien/mois":"500 - 1 000 $","Notes":"Transport protege corporatif"},"_path":"entries / 7"},"vehicle":true,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'tactical-rover', 'Tactical Rover', NULL, '{"nature":"equipement","kind":"equipment","category":"Véhicules","sourceCategory":"Véhicules","price":null,"priceMin":null,"priceMax":null,"priceLabel":"","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Mercenaire / operationnel","lore":"Le Tactical Rover est un véhicule destiné à un emploi mercenaire ou opérationnel. Sa catégorie le place du côté des déplacements préparés pour une mission plutôt que de la mobilité civile quotidienne, ce qui en fait une plateforme cohérente pour une équipe travaillant sur le terrain.\n\nCette vocation opérationnelle n’autorise pas à lui attribuer gratuitement un armement ou un équipement particulier. Les capacités exactes dépendent de la configuration réellement retenue ; le véhicule fournit le cadre tactique, tandis que les systèmes embarqués doivent être définis par ce qui est effectivement installé.","data":{"id":"tactical-rover","name":"Tactical Rover","priceMode":"range","priceMin":80000,"priceMax":150000,"priceLabel":"80 000 - 150 000 $","effect":"Mercenaire / operationnel","data":{"Places":"4-8","Str.":"25","Blind.":"6","Sec.":"18","Auto.":"18","Entretien/mois":"500 - 1 500 $","Notes":"Mercenaire / operationnel"},"_path":"entries / 8"},"vehicle":true,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('equipement', 'equipement', 'apc-leger', 'APC léger', NULL, '{"nature":"equipement","kind":"equipment","category":"Véhicules","sourceCategory":"Véhicules","price":null,"priceMin":null,"priceMax":null,"priceLabel":"","generation":null,"charge":null,"stress":null,"slots":null,"effect":"Militaire/restreint ; blindage lourd","lore":"L’APC léger est un véhicule militaire ou restreint doté d’un blindage lourd. Il relève donc d’un niveau de protection et d’accès très différent des véhicules civils, sa présence elle-même indiquant un usage institutionnel, militaire ou exceptionnellement autorisé.\n\nLe blindage constitue sa caractéristique déterminante, mais il ne faut pas lui ajouter automatiquement des armes ou des systèmes qui ne sont pas décrits. Ce que l’APC peut faire au-delà du transport protégé dépend de son profil concret et des équipements réellement montés sur l’exemplaire utilisé.","data":{"id":"apc-leger","name":"APC leger","priceMode":"range","priceMin":150000,"priceMax":400000,"priceLabel":"150 000 - 400 000 $","effect":"Militaire/restreint ; blindage lourd","data":{"Places":"8-12","Str.":"35","Blind.":"10","Sec.":"21","Auto.":"18","Entretien/mois":"1 000 - 2 500 $+","Notes":"Militaire/restreint ; blindage lourd"},"_path":"entries / 9"},"vehicle":true,"neuro":false,"recurring":"durable_purchase","monthlyCost":0,"families":[]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'teinte_dermique_modulable', 'Teinte dermique modulable', NULL, '{"nature":"equipement","kind":"augmentation","category":"Esthétique / fonctionnel","sourceCategory":"Esthétique / fonctionnel","price":1500,"priceMin":null,"priceMax":null,"priceLabel":"1500 $","generation":null,"charge":0,"stress":0,"slots":0,"effect":"Peau technologique a couleur variable.","lore":"La Teinte dermique modulable emploie une couche technodermique capable de changer à volonté la pigmentation de la peau, sur tout le corps ou seulement certaines zones. Les réglages peuvent produire des transitions progressives, instantanées ou des couleurs manifestement artificielles.\n\nLe système sert à choisir et modifier une apparence corporelle plutôt qu’à analyser le décor. Il ne constitue donc pas un camouflage adaptatif : aucune teinte ne se recalcule automatiquement pour faire disparaître le porteur dans son environnement.","data":{"id":"teinte_dermique_modulable","name":"Teinte dermique modulable","family":"Esthétique / fonctionnel","priceLabel":"1 500 $","effect":"Peau technologique a couleur variable.","generation":null,"charge":0,"stress":0,"slots":0,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":1500,"priceMin":1500,"priceMax":1500,"_path":"entries / 0"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["dermal","aesthetic","utility","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'lentilles_polychromes', 'Lentilles polychromes', NULL, '{"nature":"equipement","kind":"augmentation","category":"Esthétique / fonctionnel","sourceCategory":"Esthétique / fonctionnel","price":750,"priceMin":null,"priceMax":null,"priceLabel":"750 $","generation":null,"charge":0,"stress":0,"slots":0,"effect":"Iris/couleur variable.","lore":"Les Lentilles polychromes sont des dispositifs oculaires cosmétiques permettant de modifier à volonté la couleur de l’iris. Les modèles compatibles peuvent également afficher des motifs ou des teintes artificielles impossibles à obtenir naturellement.\n\nElles transforment l’apparence du regard sans toucher aux capacités visuelles du porteur. Aucun zoom, spectre supplémentaire ou meilleure perception ne se cache derrière la couleur : leur fonction est esthétique, externe et volontairement distincte d’un CyberŒil.","data":{"id":"lentilles_polychromes","name":"Lentilles polychromes","family":"Esthétique / fonctionnel","priceLabel":"750 $","effect":"Iris/couleur variable.","generation":null,"charge":0,"stress":0,"slots":0,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":750,"priceMin":750,"priceMax":750,"_path":"entries / 1"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["aesthetic","utility","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'tatouage_lumineux', 'Tatouage lumineux', NULL, '{"nature":"equipement","kind":"augmentation","category":"Esthétique / fonctionnel","sourceCategory":"Esthétique / fonctionnel","price":null,"priceMin":null,"priceMax":null,"priceLabel":"","generation":null,"charge":0,"stress":0,"slots":0,"effect":"LED sous-cutanee, forme et luminosite selon implantation.","lore":"Le Tatouage lumineux implante sous la peau un réseau de points ou de lignes électroluminescentes qui dessinent un motif invisible, discret ou éclatant selon la conception. Contrairement au Bio-tatouage vivant, il revendique son caractère technologique : lumière nette, géométrie artificielle et parfois animation simple deviennent directement partie du corps.\n\nOn le retrouve dans la mode urbaine, les clubs, certaines scènes Neopunk et chez ceux qui veulent faire de leur augmentation un signe visible plutôt qu’un secret. La forme et la puissance lumineuse dépendent du réseau implanté ; un tatouage conçu comme un fin liseré ne se transforme pas ensuite en écran corporel complet sans nouvelle intervention.","data":{"id":"tatouage_lumineux","name":"Tatouage lumineux","family":"Esthétique / fonctionnel","priceLabel":"100 - 1 000 $","effect":"LED sous-cutanee, forme et luminosite selon implantation.","generation":null,"charge":0,"stress":0,"slots":0,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"range","priceMin":100,"priceMax":1000,"_path":"entries / 2"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["aesthetic","utility","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'cheveux_artificiels', 'Cheveux artificiels', NULL, '{"nature":"equipement","kind":"augmentation","category":"Esthétique / fonctionnel","sourceCategory":"Esthétique / fonctionnel","price":1000,"priceMin":null,"priceMax":null,"priceLabel":"1000 $","generation":null,"charge":0,"stress":0,"slots":0,"effect":"Fibre optique, coupe/couleur modulables.","lore":"Les cheveux artificiels remplacent la chevelure par des fibres synthétiques ou optiques implantées sur le cuir chevelu. Selon le modèle, leur couleur, leur coiffure et une partie de leur longueur peuvent être modifiées sans repousse biologique.\n\nDes fibres optiques peuvent également produire des effets lumineux manifestement artificiels. L’objectif est esthétique et contrôlable : le porteur choisit son apparence capillaire dans les possibilités du système au lieu d’attendre croissance, teinture ou coiffage conventionnel.","data":{"id":"cheveux_artificiels","name":"Cheveux artificiels","family":"Esthétique / fonctionnel","priceLabel":"1 000 $","effect":"Fibre optique, coupe/couleur modulables.","generation":null,"charge":0,"stress":0,"slots":0,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":1000,"priceMin":1000,"priceMax":1000,"_path":"entries / 3"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["optical","aesthetic","sensorial","utility","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'maillage_dermique_decoratif', 'Maillage dermique decoratif', NULL, '{"nature":"equipement","kind":"augmentation","category":"Esthétique / fonctionnel","sourceCategory":"Esthétique / fonctionnel","price":150,"priceMin":null,"priceMax":null,"priceLabel":"150 $","generation":null,"charge":0,"stress":0,"slots":0,"effect":"Circuits/filaments sous la peau.","lore":"Le Maillage dermique décoratif implante sous la peau de fins conducteurs ou fils métalliques formant des motifs de circuits visibles. Il donne au corps une esthétique technologique permanente sans exiger une fonction cybernétique lourde.\n\nDans sa version standard, le maillage est purement décoratif : il ne protège ni le corps ni les systèmes électroniques et ne fournit aucun blindage. L’ancien usage social du dispositif était précisément de paraître augmenté sans devoir porter un véritable chrome de performance.","data":{"id":"maillage_dermique_decoratif","name":"Maillage dermique decoratif","family":"Esthétique / fonctionnel","priceLabel":"150 $","effect":"Circuits/filaments sous la peau.","generation":null,"charge":0,"stress":0,"slots":0,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":150,"priceMin":150,"priceMax":150,"_path":"entries / 4"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["dermal","aesthetic","utility","combat","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'montre_sous_cutanee', 'Montre sous-cutanee', NULL, '{"nature":"equipement","kind":"augmentation","category":"Esthétique / fonctionnel","sourceCategory":"Esthétique / fonctionnel","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $","generation":null,"charge":0,"stress":0,"slots":0,"effect":"Affichage horaire/informations sur la peau.","lore":"La Montre sous-cutanée est un microafficheur implanté sous la peau de l’avant-bras ou du poignet. Il peut montrer l’heure, des notifications et des informations simples sans imposer au porteur un écran ou un terminal tenu en main.\n\nL’afficheur peut se synchroniser avec un Holophone ou un autre système compatible pour relayer les données utiles. Sa fonction reste celle d’une interface discrète de consultation : il ne remplace ni ordinateur complet ni système de réalité augmentée.","data":{"id":"montre_sous_cutanee","name":"Montre sous-cutanee","family":"Esthétique / fonctionnel","priceLabel":"500 $","effect":"Affichage horaire/informations sur la peau.","generation":null,"charge":0,"stress":0,"slots":0,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":500,"priceMin":500,"priceMax":500,"_path":"entries / 5"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["dermal","aesthetic","utility","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'implants_mammaires_modulaires', 'Implants mammaires modulaires', NULL, '{"nature":"equipement","kind":"augmentation","category":"Esthétique / fonctionnel","sourceCategory":"Esthétique / fonctionnel","price":2000,"priceMin":null,"priceMax":null,"priceLabel":"2000 $","generation":null,"charge":0,"stress":0,"slots":0,"effect":"Morphologie ajustable dans les limites de l''implant.","lore":"Les implants mammaires modulaires remplacent le volume fixe de la chirurgie esthétique classique par une structure dont la forme peut être ajustée dans une plage prévue lors de l’implantation. La technologie sert autant à la reconstruction qu’au choix esthétique, et permet de modifier une silhouette sans repasser systématiquement par une opération complète.\n\nDans une société habituée aux corps modifiés, ils appartiennent davantage à la médecine esthétique courante qu’au spectaculaire cyborg. La modularité n’est cependant pas une métamorphose illimitée : la peau, la cage thoracique, les ancrages et le volume de l’implant imposent toujours une enveloppe anatomique crédible que le réglage ne peut pas dépasser sans nouvelle chirurgie.","data":{"id":"implants_mammaires_modulaires","name":"Implants mammaires modulaires","family":"Esthétique / fonctionnel","priceLabel":"2 000 $","effect":"Morphologie ajustable dans les limites de l''implant.","generation":null,"charge":0,"stress":0,"slots":0,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":2000,"priceMin":2000,"priceMax":2000,"_path":"entries / 6"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["aesthetic","utility","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'implant_sexuel', 'Implant sexuel', NULL, '{"nature":"equipement","kind":"augmentation","category":"Esthétique / fonctionnel","sourceCategory":"Esthétique / fonctionnel","price":2000,"priceMin":null,"priceMax":null,"priceLabel":"2000 $","generation":null,"charge":0,"stress":0,"slots":0,"effect":"Modification/remplacement genital cybernetique.","lore":"Les implants sexuels permettent de remplacer, modifier ou ajouter des organes génitaux cybernétiques selon le modèle retenu. La technologie peut donc servir à une reconstruction, à une modification anatomique ou à un changement volontaire de configuration sexuelle.\n\nCette entrée décrit une fonction corporelle et esthétique, pas un bonus de séduction ou de Charisme. Toute capacité augmentée supplémentaire exige son propre dispositif spécialisé : l’implant de base ne transforme pas automatiquement l’intimité en avantage mécanique.","data":{"id":"implant_sexuel","name":"Implant sexuel","family":"Esthétique / fonctionnel","priceLabel":"2 000 $","effect":"Modification/remplacement genital cybernetique.","generation":null,"charge":0,"stress":0,"slots":0,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":2000,"priceMin":2000,"priceMax":2000,"_path":"entries / 7"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["aesthetic","medical","utility","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'implant_contraceptif', 'Implant contraceptif', NULL, '{"nature":"equipement","kind":"augmentation","category":"Esthétique / fonctionnel","sourceCategory":"Esthétique / fonctionnel","price":100,"priceMin":null,"priceMax":null,"priceLabel":"100 $","generation":null,"charge":0,"stress":0,"slots":0,"effect":"Contraception hautement fiable.","lore":"L’implant contraceptif est un dispositif autonome léger placé dans l’appareil reproductif. Tant qu’il fonctionne normalement, il assure une contraception pratiquement totale sans transformer le reste du corps ni demander de système cybernétique lourd.\n\nIl appartient aux augmentations fonctionnelles de la vie quotidienne plutôt qu’au chrome de performance. Son intérêt est la continuité d’une fonction contraceptive implantée ; il n’apporte ni capacité physique, ni avantage social, ni plateforme pour d’autres modules.","data":{"id":"implant_contraceptif","name":"Implant contraceptif","family":"Esthétique / fonctionnel","priceLabel":"100 $","effect":"Contraception hautement fiable.","generation":null,"charge":0,"stress":0,"slots":0,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":100,"priceMin":100,"priceMax":100,"_path":"entries / 8"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["aesthetic","utility","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'synthederm_de_couverture', 'SynthéDerm de couverture', NULL, '{"nature":"equipement","kind":"augmentation","category":"Esthétique / fonctionnel","sourceCategory":"Esthétique / fonctionnel","price":2500,"priceMin":null,"priceMax":null,"priceLabel":"2500 $","generation":null,"charge":0,"stress":0,"slots":0,"effect":"Masque visuellement une augmentation Gen2 compatible.","lore":"Le SynthéDerm de couverture est un revêtement synthétique appliqué sur une augmentation compatible de deuxième génération afin de lui rendre une apparence biologique crédible. Une prothèse correctement habillée peut ainsi cesser d’être immédiatement visible.\n\nLe revêtement ne modifie pourtant aucune performance de l’implant et ne le rend pas indétectable. Une inspection médicale ou technique et certains scanners peuvent toujours révéler la structure artificielle dissimulée sous cette peau synthétique.","data":{"id":"synthederm_de_couverture","name":"SynthéDerm de couverture","family":"Esthétique / fonctionnel","priceLabel":"2 500 $","effect":"Masque visuellement une augmentation Gen2 compatible.","generation":null,"charge":0,"stress":0,"slots":0,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":2500,"priceMin":2500,"priceMax":2500,"_path":"entries / 9"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["optical","dermal","sensorial","infiltration","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'radio_integree', 'Radio integree', NULL, '{"nature":"equipement","kind":"augmentation","category":"Esthétique / fonctionnel","sourceCategory":"Esthétique / fonctionnel","price":200,"priceMin":null,"priceMax":null,"priceLabel":"200 $","generation":null,"charge":0,"stress":0,"slots":0,"effect":"Audio/musique ; exige support CyberAudio compatible.","lore":"La Radio intégrée est un petit module CyberAudio qui envoie directement le son dans le système auditif du porteur. Elle réunit réception radio, lecture de musique ou fichiers audio et écoute de flux transmis par un appareil connecté.\n\nL’écoute reste privée et mains libres, sans devoir porter d’écouteurs externes. Cette fonction légère suppose toutefois un support auditif compatible : elle enrichit le CyberAudio existant au lieu de constituer un appareil autonome implantable n’importe où.","data":{"id":"radio_integree","name":"Radio integree","family":"Esthétique / fonctionnel","priceLabel":"200 $","effect":"Audio/musique ; exige support CyberAudio compatible.","generation":null,"charge":0,"stress":0,"slots":0,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":200,"priceMin":200,"priceMax":200,"_path":"entries / 10"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["audio","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'cablage_neuronal_g1', 'Cablage neuronal', NULL, '{"nature":"equipement","kind":"augmentation","category":"Neural","sourceCategory":"Neural","price":3000,"priceMin":null,"priceMax":null,"priceLabel":"3000 $","generation":1,"charge":1,"stress":3,"slots":null,"effect":"Support des NeuroWares ; interface de base. · Mécanique : Support 2 slots","lore":"Le Câblage neuronal forme l’infrastructure interne sur laquelle viennent se brancher les NeuroWares. Il ne constitue pas lui-même une compétence ou un programme : il aménage les connexions, relais et interfaces nécessaires pour que d’autres augmentations neurales disposent d’un support stable dans le système nerveux du porteur.\n\nLa Gen.1 fournit 2 slots de support pour 1 Charge et 3 Stress ; la Gen.2 porte ce support à 4 slots pour la même Charge avec seulement 1 Stress. Disposer de davantage de slots permet d’installer plus de NeuroWares compatibles, mais n’accorde aucun effet de ces modules tant qu’ils ne sont pas réellement implantés.","data":{"id":"cablage_neuronal_g1","name":"Cablage neuronal","family":"Neural","priceLabel":"3 000 $","effect":"Support des NeuroWares ; interface de base. · Mécanique : Support 2 slots","generation":1,"charge":1,"stress":3,"slots":null,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":3000,"priceMin":3000,"priceMax":3000,"_path":"entries / 11"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["neural","utility","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'cablage_neuronal_g2', 'Cablage neuronal', NULL, '{"nature":"equipement","kind":"augmentation","category":"Neural","sourceCategory":"Neural","price":8000,"priceMin":null,"priceMax":null,"priceLabel":"8000 $","generation":2,"charge":1,"stress":1,"slots":null,"effect":"Support des NeuroWares ; interface de base. · Mécanique : Support 4 slots","lore":"Le Câblage neuronal forme l’infrastructure interne sur laquelle viennent se brancher les NeuroWares. Il ne constitue pas lui-même une compétence ou un programme : il aménage les connexions, relais et interfaces nécessaires pour que d’autres augmentations neurales disposent d’un support stable dans le système nerveux du porteur.\n\nLa Gen.1 fournit 2 slots de support pour 1 Charge et 3 Stress ; la Gen.2 porte ce support à 4 slots pour la même Charge avec seulement 1 Stress. Disposer de davantage de slots permet d’installer plus de NeuroWares compatibles, mais n’accorde aucun effet de ces modules tant qu’ils ne sont pas réellement implantés.","data":{"id":"cablage_neuronal_g2","name":"Cablage neuronal","family":"Neural","priceLabel":"8 000 $","effect":"Support des NeuroWares ; interface de base. · Mécanique : Support 4 slots","generation":2,"charge":1,"stress":1,"slots":null,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":8000,"priceMin":8000,"priceMax":8000,"_path":"entries / 12"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["neural","utility","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'analyseur_chimique_g1', 'Analyseur chimique', NULL, '{"nature":"equipement","kind":"augmentation","category":"Neural","sourceCategory":"Neural","price":1500,"priceMin":null,"priceMax":null,"priceLabel":"1500 $","generation":1,"charge":0,"stress":1,"slots":1,"effect":"Analyse chimique par gout ; outil de Savoirs/Investigation. · Mécanique : +3 circonstanciel","lore":"L’Analyseur chimique ajoute au goût une couche d’interprétation instrumentale : une substance réellement mise en contact avec les récepteurs peut être comparée à des signatures connues et fournir des indices utiles à une analyse de Savoirs ou d’Investigation. L’implant est donc un laboratoire miniature de proximité, pas un scanner chimique à distance.\n\nLa Gen.1 apporte un +3 circonstanciel au travail pertinent mais impose 1 point de Stress ; la Gen.2 réduit cet avantage à +2 tout en supprimant ce Stress. Le résultat dépend toujours de l’échantillon et de ce que la base de connaissances permet d’identifier : goûter une matière inconnue ne garantit pas d’en comprendre automatiquement l’origine ou tous les effets.","data":{"id":"analyseur_chimique_g1","name":"Analyseur chimique","family":"Neural","priceLabel":"1 500 $","effect":"Analyse chimique par gout ; outil de Savoirs/Investigation. · Mécanique : +3 circonstanciel","generation":1,"charge":0,"stress":1,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":1500,"priceMin":1500,"priceMax":1500,"_path":"entries / 13"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["neural","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'analyseur_chimique_g2', 'Analyseur chimique', NULL, '{"nature":"equipement","kind":"augmentation","category":"Neural","sourceCategory":"Neural","price":3000,"priceMin":null,"priceMax":null,"priceLabel":"3000 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Analyse chimique par gout ; outil de Savoirs/Investigation. · Mécanique : +2","lore":"L’Analyseur chimique ajoute au goût une couche d’interprétation instrumentale : une substance réellement mise en contact avec les récepteurs peut être comparée à des signatures connues et fournir des indices utiles à une analyse de Savoirs ou d’Investigation. L’implant est donc un laboratoire miniature de proximité, pas un scanner chimique à distance.\n\nLa Gen.1 apporte un +3 circonstanciel au travail pertinent mais impose 1 point de Stress ; la Gen.2 réduit cet avantage à +2 tout en supprimant ce Stress. Le résultat dépend toujours de l’échantillon et de ce que la base de connaissances permet d’identifier : goûter une matière inconnue ne garantit pas d’en comprendre automatiquement l’origine ou tous les effets.","data":{"id":"analyseur_chimique_g2","name":"Analyseur chimique","family":"Neural","priceLabel":"3 000 $","effect":"Analyse chimique par gout ; outil de Savoirs/Investigation. · Mécanique : +2","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":3000,"priceMin":3000,"priceMax":3000,"_path":"entries / 14"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["neural","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fi