INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'bloqueur_de_douleur_g1', 'Bloqueur de douleur', NULL, '{"nature":"equipement","kind":"augmentation","category":"Neural","sourceCategory":"Neural","price":3500,"priceMin":null,"priceMax":null,"priceLabel":"3500 $","generation":1,"charge":0,"stress":1,"slots":1,"effect":"Reduit les consequences dues exclusivement a la douleur ; ne soigne aucune blessure. · Mécanique : blessures −2 états","lore":"Le Bloqueur de douleur agit sur les voies neurales qui transforment une lésion en sensation consciente. Il ne répare rien : il réduit la place que la douleur prend dans l’attention du porteur, ce qui permet de continuer à fonctionner là où un organisme non modifié serait surtout occupé à signaler qu’il vient d’être sérieusement malmené.\n\nCette distinction explique autant son intérêt que son danger culturel. Soldats, travailleurs augmentés ou combattants peuvent le considérer comme un outil de continuité opérationnelle, tandis que les médecins rappellent qu’un corps silencieux peut continuer à se dégrader. Un utilisateur expérimenté apprend donc à surveiller ses blessures au lieu de prendre l’absence de douleur pour une absence de dommages.","data":{"id":"bloqueur_de_douleur_g1","name":"Bloqueur de douleur","family":"Neural","priceLabel":"3 500 $","effect":"Reduit les consequences dues exclusivement a la douleur ; ne soigne aucune blessure. · Mécanique : blessures −2 états","generation":1,"charge":0,"stress":1,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":3500,"priceMin":3500,"priceMax":3500,"_path":"entries / 15"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["neural","medical","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'bloqueur_de_douleur_g2', 'Bloqueur de douleur', NULL, '{"nature":"equipement","kind":"augmentation","category":"Neural","sourceCategory":"Neural","price":7000,"priceMin":null,"priceMax":null,"priceLabel":"7000 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Reduit les consequences dues exclusivement a la douleur ; ne soigne aucune blessure. · Mécanique : blessures −1 état","lore":"Le Bloqueur de douleur agit sur les voies neurales qui transforment une lésion en sensation consciente. Il ne répare rien : il réduit la place que la douleur prend dans l’attention du porteur, ce qui permet de continuer à fonctionner là où un organisme non modifié serait surtout occupé à signaler qu’il vient d’être sérieusement malmené.\n\nCette distinction explique autant son intérêt que son danger culturel. Soldats, travailleurs augmentés ou combattants peuvent le considérer comme un outil de continuité opérationnelle, tandis que les médecins rappellent qu’un corps silencieux peut continuer à se dégrader. Un utilisateur expérimenté apprend donc à surveiller ses blessures au lieu de prendre l’absence de douleur pour une absence de dommages.","data":{"id":"bloqueur_de_douleur_g2","name":"Bloqueur de douleur","family":"Neural","priceLabel":"7 000 $","effect":"Reduit les consequences dues exclusivement a la douleur ; ne soigne aucune blessure. · Mécanique : blessures −1 état","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":7000,"priceMin":7000,"priceMax":7000,"_path":"entries / 16"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["neural","medical","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.field