INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'booster_d_adrenaline_g1', 'Booster d''adrenaline', NULL, '{"nature":"equipement","kind":"augmentation","category":"Neural","sourceCategory":"Neural","price":4500,"priceMin":null,"priceMax":null,"priceLabel":"4500 $","generation":1,"charge":0,"stress":2,"slots":2,"effect":"Gen2 : 2 Slots, Charge 0, Stress 1 ; 1/scène, +1 PA pendant 1 round (max 4 PA), puis +1 Stress temporaire. Gen1 : 2 Slots, Charge 0, Stress 2 ; +1 PA pendant 2 rounds (max 4 PA), puis +2 Stress temporaire. · Mécanique : +1 PA ×2 rounds","lore":"Le Booster d’adrénaline relie le système neural aux mécanismes endocriniens d’urgence afin de déclencher volontairement un état que le corps réserve normalement à la peur, au choc ou à la survie. La sensation décrite par les utilisateurs tient moins d’un simple stimulant que d’un organisme entier qui reçoit soudain l’ordre de traiter les prochaines secondes comme critiques.\n\nIl intéresse naturellement les métiers où une brève pointe de vitesse décisionnelle ou physique peut sauver une vie, mais personne de sérieux ne le considère comme un régime de fonctionnement normal. Après l’impulsion viennent fatigue, tremblements, chaleur et dette physiologique ; les modèles récents cherchent surtout à rendre cette transition plus contrôlable, pas à abolir le prix biologique d’une telle poussée.","data":{"id":"booster_d_adrenaline_g1","name":"Booster d''adrenaline","family":"Neural","priceLabel":"4 500 $","effect":"Gen2 : 2 Slots, Charge 0, Stress 1 ; 1/scène, +1 PA pendant 1 round (max 4 PA), puis +1 Stress temporaire. Gen1 : 2 Slots, Charge 0, Stress 2 ; +1 PA pendant 2 rounds (max 4 PA), puis +2 Stress temporaire. · Mécanique : +1 PA ×2 rounds","generation":1,"charge":0,"stress":2,"slots":2,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":4500,"priceMin":4500,"priceMax":4500,"_path":"entries / 17"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["neural","combat"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'booster_d_adrenaline_g2', 'Booster d''adrenaline', NULL, '{"nature":"equipement","kind":"augmentation","category":"Neural","sourceCategory":"Neural","price":8500,"priceMin":null,"priceMax":null,"priceLabel":"8500 $","generation":2,"charge":0,"stress":1,"slots":2,"effect":"Gen2 : 2 Slots, Charge 0, Stress 1 ; 1/scène, +1 PA pendant 1 round (max 4 PA), puis +1 Stress temporaire. Gen1 : 2 Slots, Charge 0, Stress 2 ; +1 PA pendant 2 rounds (max 4 PA), puis +2 Stress temporaire. · Mécanique : +1 PA ×1 round","lore":"Le Booster d’adrénaline relie le système neural aux mécanismes endocriniens d’urgence afin de déclencher volontairement un état que le corps réserve normalement à la peur, au choc ou à la survie. La sensation décrite par les utilisateurs tient moins d’un simple stimulant que d’un organisme entier qui reçoit soudain l’ordre de traiter les prochaines secondes comme critiques.\n\nIl intéresse naturellement les métiers où une brève pointe de vitesse décisionnelle ou physique peut sauver une vie, mais personne de sérieux ne le considère comme un régime de fonctionnement normal. Après l’impulsion viennent fatigue, tremblements, chaleur et dette physiologique ; les modèles récents cherchent surtout à rendre cette transition plus contrôlable, pas à abolir le prix biologique d’une telle poussée.","data":{"id":"booster_d_adrenaline_g2","name":"Booster d''adrenaline","family":"Neural","priceLabel":"8 500 $","effect":"Gen2 : 2 Slots, Charge 0, Stress 1 ; 1/scène, +1 PA pendant 1 round (max 4 PA), puis +1 Stress temporaire. Gen1 : 2 Slots, Charge 0, Stress 2 ; +1 PA pendant 2 rounds (max 4 PA), puis +2 Stress temporaire. · Mécanique : +1 PA ×1 round","generation":2,"charge":0,"stress":1,"slots":2,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":8500,"priceMin":8500,"priceMax":8500,"_path":"entries / 18"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["neural","combat"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'ports_d_interface_g1', 'Ports d''interface', NULL, '{"nature":"equipement","kind":"augmentation","category":"Neural","sourceCategory":"Neural","price":2500,"priceMin":null,"priceMax":null,"priceLabel":"2500 $","generation":1,"charge":0,"stress":1,"slots":1,"effect":"Connexion physique directe Neurodive ; applique +2 Intrusion/Contrôle au système exactement connecté. Un Unsinkable peut utiliser le port comme connectique ordinaire mais pas pour Neurodive. · Mécanique : accès direct +2","lore":"Les Ports d’interface offrent une connexion physique directe entre le système neural du porteur et une machine compatible. Ils permettent de travailler sans dépendre d’une liaison distante lorsqu’un accès câblé est disponible, ce qui réduit les intermédiaires entre le Neurodiver et le système effectivement branché.\n\nGen.1 comme Gen.2 appliquent +2 en Intrusion/Contrôle au système exactement connecté ; la première impose 1 Stress, la seconde aucun. Un Unsinkable peut utiliser le port comme connectique ordinaire, mais pas pour Neurodive. Le bonus ne se propage pas à tout un réseau simplement parce qu’un câble est branché sur l’un de ses équipements.","data":{"id":"ports_d_interface_g1","name":"Ports d''interface","family":"Neural","priceLabel":"2 500 $","effect":"Connexion physique directe Neurodive ; applique +2 Intrusion/Contrôle au système exactement connecté. Un Unsinkable peut utiliser le port comme connectique ordinaire mais pas pour Neurodive. · Mécanique : accès direct +2","generation":1,"charge":0,"stress":1,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":2500,"priceMin":2500,"priceMax":2500,"_path":"entries / 19"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["neural","utility","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'ports_d_interface_g2', 'Ports d''interface', NULL, '{"nature":"equipement","kind":"augmentation","category":"Neural","sourceCategory":"Neural","price":6000,"priceMin":null,"priceMax":null,"priceLabel":"6000 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Connexion physique directe Neurodive ; applique +2 Intrusion/Contrôle au système exactement connecté. Un Unsinkable peut utiliser le port comme connectique ordinaire mais pas pour Neurodive. · Mécanique : accès direct +2","lore":"Les Ports d’interface offrent une connexion physique directe entre le système neural du porteur et une machine compatible. Ils permettent de travailler sans dépendre d’une liaison distante lorsqu’un accès câblé est disponible, ce qui réduit les intermédiaires entre le Neurodiver et le système effectivement branché.\n\nGen.1 comme Gen.2 appliquent +2 en Intrusion/Contrôle au système exactement connecté ; la première impose 1 Stress, la seconde aucun. Un Unsinkable peut utiliser le port comme connectique ordinaire, mais pas pour Neurodive. Le bonus ne se propage pas à tout un réseau simplement parce qu’un câble est branché sur l’un de ses équipements.","data":{"id":"ports_d_interface_g2","name":"Ports d''interface","family":"Neural","priceLabel":"6 000 $","effect":"Connexion physique directe Neurodive ; applique +2 Intrusion/Contrôle au système exactement connecté. Un Unsinkable peut utiliser le port comme connectique ordinaire mais pas pour Neurodive. · Mécanique : accès direct +2","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":6000,"priceMin":6000,"priceMax":6000,"_path":"entries / 20"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["neural","utility","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'defense_electronique_g1', 'Defense electronique', NULL, '{"nature":"equipement","kind":"augmentation","category":"Neural","sourceCategory":"Neural","price":4000,"priceMin":null,"priceMax":null,"priceLabel":"4000 $","generation":1,"charge":0,"stress":1,"slots":2,"effect":"Protection Neuro intégrée : Gen1, 2 Slots, +2 Défense Neuro ; Gen2, 1 Slot, +1 Défense Neuro. Ne modifie ni Rang ni capacité de Neuroprogrammes. · Mécanique : +2 Défense Neuro","lore":"La Défense électronique est une couche de sécurité implantée au plus près du réseau neural et des bus de données augmentiques. Elle surveille les échanges anormaux, isole certaines requêtes et complique l’accès direct aux systèmes du porteur, comme un pare-feu matériel dont la machine protégée serait le corps lui-même.\n\nChez les Neurodivers et les augmentés lourdement connectés, elle fait partie des investissements qui deviennent évidents après le premier incident sérieux. Elle ne remplace ni l’expérience ni les logiciels spécialisés : son rôle est de rendre l’architecture personnelle moins accueillante à une intrusion, pas de transformer automatiquement son propriétaire en expert de cybersécurité ou en meilleur Neurodiver.","data":{"id":"defense_electronique_g1","name":"Defense electronique","family":"Neural","priceLabel":"4 000 $","effect":"Protection Neuro intégrée : Gen1, 2 Slots, +2 Défense Neuro ; Gen2, 1 Slot, +1 Défense Neuro. Ne modifie ni Rang ni capacité de Neuroprogrammes. · Mécanique : +2 Défense Neuro","generation":1,"charge":0,"stress":1,"slots":2,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":4000,"priceMin":4000,"priceMax":4000,"_path":"entries / 21"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["neural","combat","defensive"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT 