INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'defense_electronique_g2', 'Defense electronique', NULL, '{"nature":"equipement","kind":"augmentation","category":"Neural","sourceCategory":"Neural","price":8000,"priceMin":null,"priceMax":null,"priceLabel":"8000 $","generation":2,"charge":0,"stress":1,"slots":1,"effect":"Protection Neuro intégrée : Gen1, 2 Slots, +2 Défense Neuro ; Gen2, 1 Slot, +1 Défense Neuro. Ne modifie ni Rang ni capacité de Neuroprogrammes. · Mécanique : +1 Défense Neuro","lore":"La Défense électronique est une couche de sécurité implantée au plus près du réseau neural et des bus de données augmentiques. Elle surveille les échanges anormaux, isole certaines requêtes et complique l’accès direct aux systèmes du porteur, comme un pare-feu matériel dont la machine protégée serait le corps lui-même.\n\nChez les Neurodivers et les augmentés lourdement connectés, elle fait partie des investissements qui deviennent évidents après le premier incident sérieux. Elle ne remplace ni l’expérience ni les logiciels spécialisés : son rôle est de rendre l’architecture personnelle moins accueillante à une intrusion, pas de transformer automatiquement son propriétaire en expert de cybersécurité ou en meilleur Neurodiver.","data":{"id":"defense_electronique_g2","name":"Defense electronique","family":"Neural","priceLabel":"8 000 $","effect":"Protection Neuro intégrée : Gen1, 2 Slots, +2 Défense Neuro ; Gen2, 1 Slot, +1 Défense Neuro. Ne modifie ni Rang ni capacité de Neuroprogrammes. · Mécanique : +1 Défense Neuro","generation":2,"charge":0,"stress":1,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":8000,"priceMin":8000,"priceMax":8000,"_path":"entries / 22"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["neural","combat","defensive"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT 