INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'systeme_d_orientation_g2', 'Systeme d''orientation', NULL, '{"nature":"equipement","kind":"augmentation","category":"Neural","sourceCategory":"Neural","price":2000,"priceMin":null,"priceMax":null,"priceLabel":"2000 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Carte mentale des lieux explores, nord et orientation. · Mécanique : navigation intégrée","lore":"Le Système d’orientation entretient une représentation mentale des lieux déjà parcourus et une référence directionnelle constante. Il transforme les déplacements du porteur en carte interne, utile pour revenir sur ses pas, conserver le nord ou comprendre comment plusieurs passages explorés s’articulent entre eux.\n\nLa Gen.2 occupe 1 emplacement et n’impose aucun Stress. Elle offre cette navigation intégrée à partir des lieux effectivement explorés ; elle ne révèle pas une pièce jamais visitée, un passage secret inconnu ni une carte complète d’un bâtiment simplement parce que le porteur y est entré.","data":{"id":"systeme_d_orientation_g2","name":"Systeme d''orientation","family":"Neural","priceLabel":"2 000 $","effect":"Carte mentale des lieux explores, nord et orientation. · Mécanique : navigation intégrée","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":2000,"priceMin":2000,"priceMax":2000,"_path":"entries / 23"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["neural","utility","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'processeur_mathematique_g2', 'Processeur mathematique', NULL, '{"nature":"equipement","kind":"augmentation","category":"Neural","sourceCategory":"Neural","price":3000,"priceMin":null,"priceMax":null,"priceLabel":"3000 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Calcul/traitement mathematique et assistance technique theorique. · Mécanique : +2 spécialisé","lore":"Le Processeur mathématique déporte une partie des calculs et manipulations formelles vers un module neural spécialisé. Il sert aux problèmes où vitesse, précision numérique ou traitement de relations complexes comptent réellement, notamment comme assistance technique théorique lorsque la difficulté relève bien du calcul.\n\nLa Gen.2 occupe 1 emplacement, n’impose aucun Stress et apporte +2 dans ce domaine spécialisé. Elle ne remplace ni une compétence technique pratique ni les données nécessaires au problème : le processeur peut calculer vite, mais il ne sait pas automatiquement quelle formule, hypothèse ou information manque.","data":{"id":"processeur_mathematique_g2","name":"Processeur mathematique","family":"Neural","priceLabel":"3 000 $","effect":"Calcul/traitement mathematique et assistance technique theorique. · Mécanique : +2 spécialisé","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":3000,"priceMin":3000,"priceMax":3000,"_path":"entries / 24"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["neural","utility","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'enregistreur_neural_g2', 'Enregistreur neural', NULL, '{"nature":"equipement","kind":"augmentation","category":"Neural","sourceCategory":"Neural","price":4000,"priceMin":null,"priceMax":null,"priceLabel":"4000 $","generation":2,"charge":0,"stress":1,"slots":1,"effect":"Enregistre sensations et donnees sensorielles du porteur. · Mécanique : enregistrement sensoriel","lore":"L’Enregistreur neural va au-delà d’une simple caméra ou d’un microphone en capturant des données sensorielles issues directement de l’expérience du porteur. Il constitue ainsi une mémoire enregistrée des perceptions reçues pendant une séquence, avec une richesse qui dépend des systèmes sensoriels réellement connectés au dispositif.\n\nLa version Gen.2 occupe 1 emplacement et impose 1 Stress. Elle permet l’enregistrement sensoriel, mais ne crée pas de sens absent et ne garantit pas une interprétation parfaite après coup : ce qui n’a pas été perçu ou transmis au système ne peut pas être reconstruit arbitrairement par l’enregistreur.","data":{"id":"enregistreur_neural_g2","name":"Enregistreur neural","family":"Neural","priceLabel":"4 000 $","effect":"Enregistre sensations et donnees sensorielles du porteur. · Mécanique : enregistrement sensoriel","generation":2,"charge":0,"stress":1,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":4000,"priceMin":4000,"priceMax":4000,"_path":"entries / 25"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["neural","infiltration","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'cyberoeil_g1', 'CyberOeil', NULL, '{"nature":"equipement","kind":"augmentation","category":"Optique","sourceCategory":"Optique","price":2500,"priceMin":null,"priceMax":null,"priceLabel":"2500 $","generation":1,"charge":1,"stress":3,"slots":null,"effect":"Support des modules optiques. · Mécanique : Support 2 Slots","lore":"Le CyberOeil est une plateforme optique implantée destinée à recevoir des fonctions visuelles spécialisées. Il peut remplacer un œil biologique ou servir de base à une configuration cyberoptique plus large, mais son rôle fondamental reste celui d’un support : les véritables capacités viennent des modules installés dans ses emplacements.\n\nLa Gen.1 fournit 2 slots pour 1 Charge et 3 Stress ; la Gen.2 fournit 3 slots pour 1 Charge et 1 Stress. Zoom, UV/infrarouge, caméra, anti-éblouissement ou réalité augmentée doivent toujours être ajoutés séparément : le CyberOeil n’obtient pas gratuitement leurs effets parce qu’il peut les héberger.","data":{"id":"cyberoeil_g1","name":"CyberOeil","family":"Optique","priceLabel":"2 500 $","effect":"Support des modules optiques. · Mécanique : Support 2 Slots","generation":1,"charge":1,"stress":3,"slots":null,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":2500,"priceMin":2500,"priceMax":2500,"_path":"entries / 26"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["optical","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'cyberoeil_g2', 'CyberOeil', NULL, '{"nature":"equipement","kind":"augmentation","category":"Optique","sourceCategory":"Optique","price":6000,"priceMin":null,"priceMax":null,"priceLabel":"6000 $","generation":2,"charge":1,"stress":1,"slots":null,"effect":"Support des modules optiques. · Mécanique : Support 3 Slots","lore":"Le CyberOeil est une plateforme optique implantée destinée à recevoir des fonctions visuelles spécialisées. Il peut remplacer un œil biologique ou servir de base à une configuration cyberoptique plus large, mais son rôle fondamental reste celui d’un support : les véritables capacités viennent des modules installés dans ses emplacements.\n\nLa Gen.1 fournit 2 slots pour 1 Charge et 3 Stress ; la Gen.2 fournit 3 slots pour 1 Charge et 1 Stress. Zoom, UV/infrarouge, caméra, anti-éblouissement ou réalité augmentée doivent toujours être ajoutés séparément : le CyberOeil n’obtient pas gratuitement leurs effets parce qu’il peut les héberger.","data":{"id":"cyberoeil_g2","name":"CyberOeil","family":"Optique","priceLabel":"6 000 $","effect":"Support des modules optiques. · Mécanique : Support 3 Slots","generation":2,"charge":1,"stress":1,"slots":null,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":6000,"priceMin":6000,"priceMax":6000,"_path":"entries / 27"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["optical","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'detecteur_de_radiation_g1', 'Detecteur de radiation', NULL, '{"nature":"equipement","kind":"augmentation","category":"Optique","sourceCategory":"Optique","price":1000,"priceMin":null,"priceMax":null,"priceLabel":"1000 $","generation":1,"charge":0,"stress":1,"slots":1,"effect":"Detecte/mesure radiations ; facilite Perception pertinente. · Mécanique : +3 circonstanciel","lore":"Le Détecteur de radiation ajoute à une cyberoptique un capteur capable de repérer et mesurer des rayonnements dans son domaine de fonctionnement. Il sert à matérialiser un danger qu’un humain ne percevrait autrement qu’après exposition, ou à comparer plusieurs zones pour déterminer où le niveau mesuré change réellement.\n\nLa Gen.1 apporte +3 circonstanciel en Perception pertinente et impose 1 Stress ; la Gen.2 apporte +2 sans Stress. Le détecteur renseigne sur les radiations qu’il peut mesurer : il ne devient pas un analyseur universel de toxines, de magie ou d’autres menaces invisibles.","data":{"id":"detecteur_de_radiation_g1","name":"Detecteur de radiation","family":"Optique","priceLabel":"1 000 $","effect":"Detecte/mesure radiations ; facilite Perception pertinente. · Mécanique : +3 circonstanciel","generation":1,"charge":0,"stress":1,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":1000,"priceMin":1000,"priceMax":1000,"_path":"entries / 28"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["optical","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'detecteur_de_radiation_g2', 'Detecteur de radiation', NULL, '{"nature":"equipement","kind":"augmentation","category":"Optique","sourceCategory":"Optique","price":2000,"priceMin":null,"priceMax":null,"priceLabel":"2000 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Detecte/mesure radiations ; facilite Perception pertinente. · Mécanique : +2","lore":"Le Détecteur de radiation ajoute à une cyberoptique un capteur capable de repérer et mesurer des rayonnements dans son domaine de fonctionnement. Il sert à matérialiser un danger qu’un humain ne percevrait autrement qu’après exposition, ou à comparer plusieurs zones pour déterminer où le niveau mesuré change réellement.\n\nLa Gen.1 apporte +3 circonstanciel en Perception pertinente et impose 1 Stress ; la Gen.2 apporte +2 sans Stress. Le détecteur renseigne sur les radiations qu’il peut mesurer : il ne devient pas un analyseur universel de toxines, de magie ou d’autres menaces invisibles.","data":{"id":"detecteur_de_radiation_g2","name":"Detecteur de radiation","family":"Optique","priceLabel":"2 000 $","effect":"Detecte/mesure radiations ; facilite Perception pertinente. · Mécanique : +2","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":2000,"priceMin":2000,"priceMax":2000,"_path":"entries / 29"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["optical","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'dispositif_de_visee_g1', 'Dispositif de visee', NULL, '{"nature":"equipement","kind":"augmentation","category":"Optique","sourceCategory":"Optique","price":3000,"priceMin":null,"priceMax":null,"priceLabel":"3000 $","generation":1,"charge":0,"stress":1,"slots":2,"effect":"Interface Smartlink/arme intelligente ; n''empile pas un bonus universel de Tir. · Mécanique : +3 Tir Smartgun","lore":"Le Dispositif de visée relie la cyberoptique à une arme intelligente ou à un Smartlink compatible afin d’échanger les informations nécessaires au ciblage. Il permet au porteur de superposer la solution de tir à sa perception et de travailler avec le Verrouillage fourni par l’interface correspondante.\n\nLa Gen.1 occupe 2 emplacements, impose 1 Stress et fournit +3 au Tir Smartgun ; la Gen.2 n’occupe qu’un emplacement, n’impose plus de Stress et fournit +2. Ce bonus ne s’applique pas universellement à n’importe quelle arme : sans liaison Smartlink ou arme intelligente compatible, le dispositif n’a pas de solution de tir à exploiter.","data":{"id":"dispositif_de_visee_g1","name":"Dispositif de visee","family":"Optique","priceLabel":"3 000 $","effect":"Interface Smartlink/arme intelligente ; n''empile pas un bonus universel de Tir. · Mécanique : +3 Tir Smartgun","generation":1,"charge":0,"stress":1,"slots":2,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":3000,"priceMin":3000,"priceMax":3000,"_path":"entries / 30"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["optical","sensorial","utility","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN c