INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'dispositif_de_visee_g2', 'Dispositif de visee', NULL, '{"nature":"equipement","kind":"augmentation","category":"Optique","sourceCategory":"Optique","price":5500,"priceMin":null,"priceMax":null,"priceLabel":"5500 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Interface Smartlink/arme intelligente ; n''empile pas un bonus universel de Tir. · Mécanique : +2 Tir Smartgun","lore":"Le Dispositif de visée relie la cyberoptique à une arme intelligente ou à un Smartlink compatible afin d’échanger les informations nécessaires au ciblage. Il permet au porteur de superposer la solution de tir à sa perception et de travailler avec le Verrouillage fourni par l’interface correspondante.\n\nLa Gen.1 occupe 2 emplacements, impose 1 Stress et fournit +3 au Tir Smartgun ; la Gen.2 n’occupe qu’un emplacement, n’impose plus de Stress et fournit +2. Ce bonus ne s’applique pas universellement à n’importe quelle arme : sans liaison Smartlink ou arme intelligente compatible, le dispositif n’a pas de solution de tir à exploiter.","data":{"id":"dispositif_de_visee_g2","name":"Dispositif de visee","family":"Optique","priceLabel":"5 500 $","effect":"Interface Smartlink/arme intelligente ; n''empile pas un bonus universel de Tir. · Mécanique : +2 Tir Smartgun","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":5500,"priceMin":5500,"priceMax":5500,"_path":"entries / 31"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["optical","sensorial","utility","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN c