INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'zoom_optique_g1', 'Zoom optique', NULL, '{"nature":"equipement","kind":"augmentation","category":"Optique","sourceCategory":"Optique","price":1000,"priceMin":null,"priceMax":null,"priceLabel":"1000 $","generation":1,"charge":0,"stress":0,"slots":1,"effect":"Grossissement integre. · Mécanique : ×4, +3 distant","lore":"Le Zoom optique permet à la cyberoptique d’agrandir une portion du champ visuel sans appareil tenu en main. Il sert à examiner un détail distant, lire une inscription ou mieux suivre une cible éloignée lorsque la qualité du capteur et les conditions de visibilité fournissent encore une image exploitable.\n\nLa Gen.1 fournit un grossissement ×4 et +3 pour l’observation distante ; la Gen.2 fournit ×2 et +2. Le zoom agrandit l’image reçue mais n’ajoute pas de lumière, ne traverse pas les obstacles et ne modifie pas à lui seul la portée mécanique d’une arme dépourvue d’interface ou de capacité correspondante.","data":{"id":"zoom_optique_g1","name":"Zoom optique","family":"Optique","priceLabel":"1 000 $","effect":"Grossissement integre. · Mécanique : ×4, +3 distant","generation":1,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":1000,"priceMin":1000,"priceMax":1000,"_path":"entries / 32"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["optical","sensorial","infiltration","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'zoom_optique_g2', 'Zoom optique', NULL, '{"nature":"equipement","kind":"augmentation","category":"Optique","sourceCategory":"Optique","price":2000,"priceMin":null,"priceMax":null,"priceLabel":"2000 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Grossissement integre. · Mécanique : ×2, +2 distant","lore":"Le Zoom optique permet à la cyberoptique d’agrandir une portion du champ visuel sans appareil tenu en main. Il sert à examiner un détail distant, lire une inscription ou mieux suivre une cible éloignée lorsque la qualité du capteur et les conditions de visibilité fournissent encore une image exploitable.\n\nLa Gen.1 fournit un grossissement ×4 et +3 pour l’observation distante ; la Gen.2 fournit ×2 et +2. Le zoom agrandit l’image reçue mais n’ajoute pas de lumière, ne traverse pas les obstacles et ne modifie pas à lui seul la portée mécanique d’une arme dépourvue d’interface ou de capacité correspondante.","data":{"id":"zoom_optique_g2","name":"Zoom optique","family":"Optique","priceLabel":"2 000 $","effect":"Grossissement integre. · Mécanique : ×2, +2 distant","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":2000,"priceMin":2000,"priceMax":2000,"_path":"entries / 33"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["optical","sensorial","infiltration","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'anti_eblouissement_g2', 'Anti-eblouissement', NULL, '{"nature":"equipement","kind":"augmentation","category":"Optique","sourceCategory":"Optique","price":1500,"priceMin":null,"priceMax":null,"priceLabel":"1500 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Ferme l''iris/capteur contre flash lumineux adapte. · Mécanique : protection lumineuse","lore":"L’Anti-éblouissement protège une cyberoptique contre une montée lumineuse brutale en fermant ou atténuant automatiquement l’iris et le capteur avant que le flash adapté ne sature la vision. Son rôle est comparable à une protection réflexe intégrée au système visuel plutôt qu’à une paire de lunettes ajoutée après coup.\n\nLa Gen.2 fournit une protection lumineuse lorsque l’agression peut effectivement être détectée et compensée par le capteur. Elle ne rend pas la vision parfaite dans toutes les conditions : obscurité, fumée, capteur masqué ou phénomène extérieur au spectre traité restent des problèmes distincts.","data":{"id":"anti_eblouissement_g2","name":"Anti-eblouissement","family":"Optique","priceLabel":"1 500 $","effect":"Ferme l''iris/capteur contre flash lumineux adapte. · Mécanique : protection lumineuse","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":1500,"priceMin":1500,"priceMax":1500,"_path":"entries / 34"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["optical","sensorial","defensive","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'camera_integree_g1', 'Camera integree', NULL, '{"nature":"equipement","kind":"augmentation","category":"Optique","sourceCategory":"Optique","price":750,"priceMin":null,"priceMax":null,"priceLabel":"750 $","generation":1,"charge":0,"stress":0,"slots":1,"effect":"Enregistrement visuel. · Mécanique : enregistrement","lore":"La Caméra intégrée permet à une cyberoptique d’enregistrer directement ce qu’elle reçoit, sans obliger le porteur à sortir un appareil ni à détourner son regard vers un terminal. L’enregistrement suit ainsi naturellement la ligne de vision du système auquel le module est rattaché.\n\nGen.1 et Gen.2 assurent toutes deux l’enregistrement visuel, la seconde l’intégrant dans une architecture plus récente sans Stress supplémentaire. Le module ne donne aucun bonus de Perception par lui-même : il conserve une image ou une séquence, il n’améliore ni la résolution d’un autre capteur ni la capacité du porteur à comprendre ce qu’il voit.","data":{"id":"camera_integree_g1","name":"Camera integree","family":"Optique","priceLabel":"750 $","effect":"Enregistrement visuel. · Mécanique : enregistrement","generation":1,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":750,"priceMin":750,"priceMax":750,"_path":"entries / 35"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["optical","sensorial","infiltration","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'camera_integree_g2', 'Camera integree', NULL, '{"nature":"equipement","kind":"augmentation","category":"Optique","sourceCategory":"Optique","price":1500,"priceMin":null,"priceMax":null,"priceLabel":"1500 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Enregistrement visuel. · Mécanique : enregistrement intégré","lore":"La Caméra intégrée permet à une cyberoptique d’enregistrer directement ce qu’elle reçoit, sans obliger le porteur à sortir un appareil ni à détourner son regard vers un terminal. L’enregistrement suit ainsi naturellement la ligne de vision du système auquel le module est rattaché.\n\nGen.1 et Gen.2 assurent toutes deux l’enregistrement visuel, la seconde l’intégrant dans une architecture plus récente sans Stress supplémentaire. Le module ne donne aucun bonus de Perception par lui-même : il conserve une image ou une séquence, il n’améliore ni la résolution d’un autre capteur ni la capacité du porteur à comprendre ce qu’il voit.","data":{"id":"camera_integree_g2","name":"Camera integree","family":"Optique","priceLabel":"1 500 $","effect":"Enregistrement visuel. · Mécanique : enregistrement intégré","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":1500,"priceMin":1500,"priceMax":1500,"_path":"entries / 36"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["optical","sensorial","infiltration","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'realite_augmentee_holonet_g2', 'Realite augmentee / Holonet', NULL, '{"nature":"equipement","kind":"augmentation","category":"Optique","sourceCategory":"Optique","price":2500,"priceMin":null,"priceMax":null,"priceLabel":"2500 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Superposition Holonet et interfaces visuelles. · Mécanique : couche Holonet/AR","lore":"Réalité augmentée / Holonet ajoute à la cyberoptique une couche d’affichage capable de superposer interfaces, informations et services du Holonet au champ de vision. Le porteur peut ainsi consulter des données sans détourner son attention vers un écran externe, comme si l’environnement réel devenait le support de son interface personnelle.\n\nLa Gen.2 occupe 1 emplacement et n’impose aucun Stress. Cette couche affiche des informations ; elle ne modifie pas le corps, ne camoufle pas le porteur et ne transforme pas automatiquement ce qui est affiché en vérité fiable. Les données dépendent toujours des applications, connexions et sources auxquelles l’utilisateur a effectivement accès.","data":{"id":"realite_augmentee_holonet_g2","name":"Realite augmentee / Holonet","family":"Optique","priceLabel":"2 500 $","effect":"Superposition Holonet et interfaces visuelles. · Mécanique : couche Holonet/AR","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":2500,"priceMin":2500,"priceMax":2500,"_path":"entries / 37"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["optical","sensorial","utility","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'uv_infrarouge_g1', 'UV / Infrarouge', NULL, '{"nature":"equipement","kind":"augmentation","category":"Optique","sourceCategory":"Optique","price":1500,"priceMin":null,"priceMax":null,"priceLabel":"1500 $","generation":1,"charge":0,"stress":1,"slots":1,"effect":"Vision nocturne/spectres selon capteur. · Mécanique : 30 m, +3 pertinent","lore":"UV / Infrarouge étend la cyberoptique au-delà du spectre visible humain afin d’exploiter des informations qui resteraient autrement invisibles. Selon le capteur et la scène, cette capacité peut faire ressortir des contrastes thermiques ou des signatures ultraviolettes sans transformer pour autant chaque obscurité en image parfaite.\n\nLa Gen.1 est donnée pour 30 mètres avec +3 lorsque le spectre est pertinent et impose 1 Stress ; la Gen.2 est donnée pour 15 mètres avec +2 sans Stress. L’augmentation montre ce que son spectre peut capter : un obstacle opaque à ce rayonnement, un camouflage adapté ou l’absence de contraste restent pleinement pertinents.","data":{"id":"uv_infrarouge_g1","name":"UV / Infrarouge","family":"Optique","priceLabel":"1 500 $","effect":"Vision nocturne/spectres selon capteur. · Mécanique : 30 m, +3 pertinent","generation":1,"charge":0,"stress":1,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":1500,"priceMin":1500,"priceMax":1500,"_path":"entries / 38"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["optical","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'uv_infrarouge_g2', 'UV / Infrarouge', NULL, '{"nature":"equipement","kind":"augmentation","category":"Optique","sourceCategory":"Optique","price":3000,"priceMin":null,"priceMax":null,"priceLabel":"3000 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Vision nocturne/spectres selon capteur. · Mécanique : 15 m, +2 pertinent","lore":"UV / Infrarouge étend la cyberoptique au-delà du spectre visible humain afin d’exploiter des informations qui resteraient autrement invisibles. Selon le capteur et la scène, cette capacité peut faire ressortir des contrastes thermiques ou des signatures ultraviolettes sans transformer pour autant chaque obscurité en image parfaite.\n\nLa Gen.1 est donnée pour 30 mètres avec +3 lorsque le spectre est pertinent et impose 1 Stress ; la Gen.2 est donnée pour 15 mètres avec +2 sans Stress. L’augmentation montre ce que son spectre peut capter : un obstacle opaque à ce rayonnement, un camouflage adapté ou l’absence de contraste restent pleinement pertinents.","data":{"id":"uv_infrarouge_g2","name":"UV / Infrarouge","family":"Optique","priceLabel":"3 000 $","effect":"Vision nocturne/spectres selon capteur. · Mécanique : 15 m, +2 pertinent","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":3000,"priceMin":3000,"priceMax":3000,"_path":"entries / 39"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["optical","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'lampes_oculaires_g1', 'Lampes oculaires', NULL, '{"nature":"equipement","kind":"augmentation","category":"Optique","sourceCategory":"Optique","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $","generation":1,"charge":0,"stress":0,"slots":1,"effect":"Eclairage integre. · Mécanique : 30 m","lore":"Les Lampes oculaires intègrent une source d’éclairage directement à la cyberoptique, de sorte que le faisceau suit naturellement l’orientation du regard. Elles permettent au porteur d’éclairer sans occuper une main, mais restent une lumière émise : elles peuvent donc aussi révéler sa présence comme n’importe quelle lampe visible.\n\nLa Gen.1 éclaire jusqu’à 30 mètres, tandis que la Gen.2 est donnée pour 15 mètres ; les deux occupent 1 emplacement et n’imposent aucun Stress. Ces valeurs sont conservées telles quelles : aucune portée supplémentaire ni vision nocturne n’est ajoutée au-delà de l’éclairage réellement produit.","data":{"id":"lampes_oculaires_g1","name":"Lampes oculaires","family":"Optique","priceLabel":"500 $","effect":"Eclairage integre. · Mécanique : 30 m","generation":1,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":500,"priceMin":500,"priceMax":500,"_path":"entries / 40"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["optical","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'lampes_oculaires_g2', 'Lampes oculaires', NULL, '{"nature":"equipement","kind":"augmentation","category":"Optique","sourceCategory":"Optique","price":1000,"priceMin":null,"priceMax":null,"priceLabel":"1000 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Eclairage integre. · Mécanique : 15 m","lore":"Les Lampes oculaires intègrent une source d’éclairage directement à la cyberoptique, de sorte que le faisceau suit naturellement l’orientation du regard. Elles permettent au porteur d’éclairer sans occuper une main, mais restent une lumière émise : elles peuvent donc aussi révéler sa présence comme n’importe quelle lampe visible.\n\nLa Gen.1 éclaire jusqu’à 30 mètres, tandis que la Gen.2 est donnée pour 15 mètres ; les deux occupent 1 emplacement et n’imposent aucun Stress. Ces valeurs sont conservées telles quelles : aucune portée supplémentaire ni vision nocturne n’est ajoutée au-delà de l’éclairage réellement produit.","data":{"id":"lampes_oculaires_g2","name":"Lampes oculaires","family":"Optique","priceLabel":"1 000 $","effect":"Eclairage integre. · Mécanique : 15 m","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":1000,"priceMin":1000,"priceMax":1000,"_path":"entries / 41"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["optical","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'cyberaudio_g1', 'CyberAudio', NULL, '{"nature":"equipement","kind":"augmentation","category":"Audio","sourceCategory":"Audio","price":2000,"priceMin":null,"priceMax":null,"priceLabel":"2000 $","generation":1,"charge":1,"stress":3,"slots":null,"effect":"Support AudioWare. · Mécanique : Support 2 Slots","lore":"CyberAudio est le support cybernétique principal des AudioWares : il remplace ou complète la chaîne auditive par une architecture capable d’accueillir filtres, protections, traducteurs, amplificateurs et autres modules spécialisés. Sans ces modules, son intérêt tient d’abord à cette capacité d’intégration plutôt qu’à un bonus auditif gratuit.\n\nLa Gen.1 fournit 2 slots pour 1 Charge et 3 Stress ; la Gen.2 fournit 4 slots pour 1 Charge et 1 Stress. Les capacités concrètes du porteur dépendent ensuite de ce qu’il installe dans ces emplacements : un CyberAudio vide ne possède pas automatiquement amplification, traduction ou écholocation.","data":{"id":"cyberaudio_g1","name":"CyberAudio","family":"Audio","priceLabel":"2 000 $","effect":"Support AudioWare. · Mécanique : Support 2 Slots","generation":1,"charge":1,"stress":3,"slots":null,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":2000,"priceMin":2000,"priceMax":2000,"_path":"entries / 42"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["audio","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'cyberaudio_g2', 'CyberAudio', NULL, '{"nature":"equipement","kind":"augmentation","category":"Audio","sourceCategory":"Audio","price":5000,"priceMin":null,"priceMax":null,"priceLabel":"5000 $","generation":2,"charge":1,"stress":1,"slots":null,"effect":"Support AudioWare. · Mécanique : Support 4 Slots","lore":"CyberAudio est le support cybernétique principal des AudioWares : il remplace ou complète la chaîne auditive par une architecture capable d’accueillir filtres, protections, traducteurs, amplificateurs et autres modules spécialisés. Sans ces modules, son intérêt tient d’abord à cette capacité d’intégration plutôt qu’à un bonus auditif gratuit.\n\nLa Gen.1 fournit 2 slots pour 1 Charge et 3 Stress ; la Gen.2 fournit 4 slots pour 1 Charge et 1 Stress. Les capacités concrètes du porteur dépendent ensuite de ce qu’il installe dans ces emplacements : un CyberAudio vide ne possède pas automatiquement amplification, traduction ou écholocation.","data":{"id":"cyberaudio_g2","name":"CyberAudio","family":"Audio","priceLabel":"5 000 $","effect":"Support AudioWare. · Mécanique : Support 4 Slots","generation":2,"charge":1,"stress":1,"slots":null,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":5000,"priceMin":5000,"priceMax":5000,"_path":"entries / 43"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["audio","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'amplificateur_interne_g1', 'Amplificateur interne', NULL, '{"nature":"equipement","kind":"augmentation","category":"Audio","sourceCategory":"Audio","price":1500,"priceMin":null,"priceMax":null,"priceLabel":"1500 $","generation":1,"charge":0,"stress":1,"slots":1,"effect":"Portee auditive et sons faibles/lointains. · Mécanique : ×4, +3 circonstanciel","lore":"L’Amplificateur interne augmente directement la sensibilité et le traitement de l’audition implantée afin de faire ressortir des sons faibles ou lointains sans recourir à un appareil tenu en main. Il sert surtout à écouter au-delà de la portée confortable d’une audition ordinaire ou à distinguer un signal très discret dans un environnement exploitable.\n\nLa Gen.1 porte plus loin l’amplification, avec un facteur ×4 et un +3 circonstanciel, mais conserve 1 point de Stress ; la Gen.2 fonctionne à ×2 avec +2 et sans Stress. Dans les deux cas, l’implant améliore ce que l’oreille peut effectivement capter : il ne transforme pas un son absent ou totalement bloqué en information exploitable.","data":{"id":"amplificateur_interne_g1","name":"Amplificateur interne","family":"Audio","priceLabel":"1 500 $","effect":"Portee auditive et sons faibles/lointains. · Mécanique : ×4, +3 circonstanciel","generation":1,"charge":0,"stress":1,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":1500,"priceMin":1500,"priceMax":1500,"_path":"entries / 44"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["audio","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'amplificateur_interne_g2', 'Amplificateur interne', NULL, '{"nature":"equipement","kind":"augmentation","category":"Audio","sourceCategory":"Audio","price":3000,"priceMin":null,"priceMax":null,"priceLabel":"3000 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Portee auditive et sons faibles/lointains. · Mécanique : ×2, +2","lore":"L’Amplificateur interne augmente directement la sensibilité et le traitement de l’audition implantée afin de faire ressortir des sons faibles ou lointains sans recourir à un appareil tenu en main. Il sert surtout à écouter au-delà de la portée confortable d’une audition ordinaire ou à distinguer un signal très discret dans un environnement exploitable.\n\nLa Gen.1 porte plus loin l’amplification, avec un facteur ×4 et un +3 circonstanciel, mais conserve 1 point de Stress ; la Gen.2 fonctionne à ×2 avec +2 et sans Stress. Dans les deux cas, l’implant améliore ce que l’oreille peut effectivement capter : il ne transforme pas un son absent ou totalement bloqué en information exploitable.","data":{"id":"amplificateur_interne_g2","name":"Amplificateur interne","family":"Audio","priceLabel":"3 000 $","effect":"Portee auditive et sons faibles/lointains. · Mécanique : ×2, +2","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":3000,"priceMin":3000,"priceMax":3000,"_path":"entries / 45"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["audio","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'analyseur_de_stress_vocal_g2', 'Analyseur de stress vocal', NULL, '{"nature":"equipement","kind":"augmentation","category":"Audio","sourceCategory":"Audio","price":3000,"priceMin":null,"priceMax":null,"priceLabel":"3000 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Aide a lire le stress vocal ; ne detecte pas automatiquement le mensonge. · Mécanique : +2 Perception","lore":"L’Analyseur de stress vocal décompose une voix en micro-variations de rythme, tension, souffle et modulation afin de signaler des marqueurs compatibles avec le stress. Il complète l’écoute du porteur par une lecture instrumentale de la manière dont quelqu’un parle, ce qui peut aider à remarquer qu’une situation le met sous pression.\n\nLa version Gen.2 apporte +2 en Perception lorsque ces indices vocaux sont réellement pertinents. Elle ne détecte pas automatiquement le mensonge : une personne peut être stressée en disant vrai, rester calme en mentant ou présenter une voix difficile à interpréter pour d’autres raisons.","data":{"id":"analyseur_de_stress_vocal_g2","name":"Analyseur de stress vocal","family":"Audio","priceLabel":"3 000 $","effect":"Aide a lire le stress vocal ; ne detecte pas automatiquement le mensonge. · Mécanique : +2 Perception","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":3000,"priceMin":3000,"priceMax":3000,"_path":"entries / 46"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["audio","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'brouilleur_decrypteur_g1', 'Brouilleur / Decrypteur', NULL, '{"nature":"equipement","kind":"augmentation","category":"Audio","sourceCategory":"Audio","price":2500,"priceMin":null,"priceMax":null,"priceLabel":"2500 $","generation":1,"charge":0,"stress":1,"slots":2,"effect":"Brouillage/decryptage de communications compatibles. · Mécanique : +3 spécialisé","lore":"Le Brouilleur / Décrypteur est un module AudioWare consacré aux communications compatibles : il peut travailler sur un signal reçu pour en gêner l’exploitation ou assister son déchiffrement lorsqu’il existe réellement une transmission accessible à traiter. Il s’agit d’un outil spécialisé de guerre électronique légère, pas d’une ouverture universelle de tous les systèmes voisins.\n\nLa Gen.1 occupe 2 emplacements, impose 1 Stress et apporte +3 dans son domaine spécialisé ; la Gen.2 n’occupe plus qu’un emplacement, supprime le Stress et apporte +2. Une communication hors de portée, sur un protocole inaccessible ou protégée par des moyens que l’implant ne sait pas traiter ne devient pas automatiquement lisible.","data":{"id":"brouilleur_decrypteur_g1","name":"Brouilleur / Decrypteur","family":"Audio","priceLabel":"2 500 $","effect":"Brouillage/decryptage de communications compatibles. · Mécanique : +3 spécialisé","generation":1,"charge":0,"stress":1,"slots":2,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":2500,"priceMin":2500,"priceMax":2500,"_path":"entries / 47"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["audio","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'brouilleur_decrypteur_g2', 'Brouilleur / Decrypteur', NULL, '{"nature":"equipement","kind":"augmentation","category":"Audio","sourceCategory":"Audio","price":5000,"priceMin":null,"priceMax":null,"priceLabel":"5000 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Brouillage/decryptage de communications compatibles. · Mécanique : +2 spécialisé","lore":"Le Brouilleur / Décrypteur est un module AudioWare consacré aux communications compatibles : il peut travailler sur un signal reçu pour en gêner l’exploitation ou assister son déchiffrement lorsqu’il existe réellement une transmission accessible à traiter. Il s’agit d’un outil spécialisé de guerre électronique légère, pas d’une ouverture universelle de tous les systèmes voisins.\n\nLa Gen.1 occupe 2 emplacements, impose 1 Stress et apporte +3 dans son domaine spécialisé ; la Gen.2 n’occupe plus qu’un emplacement, supprime le Stress et apporte +2. Une communication hors de portée, sur un protocole inaccessible ou protégée par des moyens que l’implant ne sait pas traiter ne devient pas automatiquement lisible.","data":{"id":"brouilleur_decrypteur_g2","name":"Brouilleur / Decrypteur","family":"Audio","priceLabel":"5 000 $","effect":"Brouillage/decryptage de communications compatibles. · Mécanique : +2 spécialisé","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":5000,"priceMin":5000,"priceMax":5000,"_path":"entries / 48"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["audio","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'detecteur_echolocation_g2', 'Detecteur echolocation', NULL, '{"nature":"equipement","kind":"augmentation","category":"Audio","sourceCategory":"Audio","price":4000,"priceMin":null,"priceMax":null,"priceLabel":"4000 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Transforme echolocation compatible en carte mentale. · Mécanique : carte d''échos, +2","lore":"Le Détecteur écholocation interprète les retours d’une émission compatible pour les convertir en carte mentale exploitable par le porteur. Là où une oreille ordinaire ne recevrait qu’une succession d’échos, le module reconstruit distances relatives, volumes et obstacles à partir du signal réellement disponible.\n\nLa Gen.2 fournit cette carte d’échos et +2 lorsque son interprétation est pertinente. Le module n’est ni un camouflage ni une vision à travers les murs : il dépend d’une écholocation compatible et des retours physiques qu’elle peut effectivement produire dans l’environnement.","data":{"id":"detecteur_echolocation_g2","name":"Detecteur echolocation","family":"Audio","priceLabel":"4 000 $","effect":"Transforme echolocation compatible en carte mentale. · Mécanique : carte d''échos, +2","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":4000,"priceMin":4000,"priceMax":4000,"_path":"entries / 49"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["audio","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'enregistreur_audio_g1', 'Enregistreur audio', NULL, '{"nature":"equipement","kind":"augmentation","category":"Audio","sourceCategory":"Audio","price":500,"priceMin":null,"priceMax":null,"priceLabel":"500 $","generation":1,"charge":0,"stress":0,"slots":1,"effect":"Enregistrement sonore. · Mécanique : enregistrement","lore":"L’Enregistreur audio conserve directement le flux sonore traité par le système auditif implanté. Il sert à garder une conversation, un bruit de machine, une ambiance ou tout autre signal effectivement capté, sans obliger le porteur à disposer d’un enregistreur externe visible.\n\nGen.1 et Gen.2 fournissent toutes deux une fonction d’enregistrement sonore intégrée, sans bonus d’écoute associé. Le module ne rend pas un son plus net ni plus lointain par lui-même : amplification et filtrage relèvent d’autres AudioWares, qui peuvent ensuite améliorer le signal avant ou pendant son enregistrement si la configuration le permet.","data":{"id":"enregistreur_audio_g1","name":"Enregistreur audio","family":"Audio","priceLabel":"500 $","effect":"Enregistrement sonore. · Mécanique : enregistrement","generation":1,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":500,"priceMin":500,"priceMax":500,"_path":"entries / 50"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["audio","sensorial","infiltration","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'enregistreur_audio_g2', 'Enregistreur audio', NULL, '{"nature":"equipement","kind":"augmentation","category":"Audio","sourceCategory":"Audio","price":1000,"priceMin":null,"priceMax":null,"priceLabel":"1000 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Enregistrement sonore. · Mécanique : intégré","lore":"L’Enregistreur audio conserve directement le flux sonore traité par le système auditif implanté. Il sert à garder une conversation, un bruit de machine, une ambiance ou tout autre signal effectivement capté, sans obliger le porteur à disposer d’un enregistreur externe visible.\n\nGen.1 et Gen.2 fournissent toutes deux une fonction d’enregistrement sonore intégrée, sans bonus d’écoute associé. Le module ne rend pas un son plus net ni plus lointain par lui-même : amplification et filtrage relèvent d’autres AudioWares, qui peuvent ensuite améliorer le signal avant ou pendant son enregistrement si la configuration le permet.","data":{"id":"enregistreur_audio_g2","name":"Enregistreur audio","family":"Audio","priceLabel":"1 000 $","effect":"Enregistrement sonore. · Mécanique : intégré","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":1000,"priceMin":1000,"priceMax":1000,"_path":"entries / 51"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["audio","sensorial","infiltration","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'filtrage_audio_g1', 'Filtrage audio', NULL, '{"nature":"equipement","kind":"augmentation","category":"Audio","sourceCategory":"Audio","price":1500,"priceMin":null,"priceMax":null,"priceLabel":"1500 $","generation":1,"charge":0,"stress":1,"slots":1,"effect":"Isole un bruit ou bande sonore particuliere. · Mécanique : +3 circonstanciel","lore":"Le Filtrage audio sélectionne une bande, une signature ou une source sonore au sein du flux reçu afin de réduire ce qui la masque. Il est particulièrement utile pour suivre une voix dans un environnement bruyant, isoler un moteur précis ou examiner une fréquence sans augmenter indifféremment tous les sons alentour.\n\nLa Gen.1 apporte +3 circonstanciel et impose 1 Stress ; la Gen.2 apporte +2 sans Stress. Le filtre ne fabrique pas un signal qui n’a jamais atteint le capteur : si le son est totalement couvert, hors portée ou extérieur au spectre disponible, il n’existe rien à isoler.","data":{"id":"filtrage_audio_g1","name":"Filtrage audio","family":"Audio","priceLabel":"1 500 $","effect":"Isole un bruit ou bande sonore particuliere. · Mécanique : +3 circonstanciel","generation":1,"charge":0,"stress":1,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":1500,"priceMin":1500,"priceMax":1500,"_path":"entries / 52"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["audio","sensorial","infiltration","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'filtrage_audio_g2', 'Filtrage audio', NULL, '{"nature":"equipement","kind":"augmentation","category":"Audio","sourceCategory":"Audio","price":3000,"priceMin":null,"priceMax":null,"priceLabel":"3000 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Isole un bruit ou bande sonore particuliere. · Mécanique : +2","lore":"Le Filtrage audio sélectionne une bande, une signature ou une source sonore au sein du flux reçu afin de réduire ce qui la masque. Il est particulièrement utile pour suivre une voix dans un environnement bruyant, isoler un moteur précis ou examiner une fréquence sans augmenter indifféremment tous les sons alentour.\n\nLa Gen.1 apporte +3 circonstanciel et impose 1 Stress ; la Gen.2 apporte +2 sans Stress. Le filtre ne fabrique pas un signal qui n’a jamais atteint le capteur : si le son est totalement couvert, hors portée ou extérieur au spectre disponible, il n’existe rien à isoler.","data":{"id":"filtrage_audio_g2","name":"Filtrage audio","family":"Audio","priceLabel":"3 000 $","effect":"Isole un bruit ou bande sonore particuliere. · Mécanique : +2","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":3000,"priceMin":3000,"priceMax":3000,"_path":"entries / 53"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["audio","sensorial","infiltration","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'spectre_auditif_etendu_g2', 'Spectre auditif etendu', NULL, '{"nature":"equipement","kind":"augmentation","category":"Audio","sourceCategory":"Audio","price":2500,"priceMin":null,"priceMax":null,"priceLabel":"2500 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Infrasons/ultrasons. · Mécanique : infra/ultrasons","lore":"Le Spectre auditif étendu biogénétique repose sur une structure cochléaire cultivée pour dépasser la plage humaine normale. Le porteur peut entendre infrasons et ultrasons dans les limites physiologiques fixées lors de la conception.\n\nCette nouvelle plage ne rend pas automatiquement chaque son plus facile à identifier : l’intérêt vient d’abord de percevoir ce qui était auparavant inaudible. Contrairement au module CyberAudio, la capacité est intégrée au tissu vivant et ne peut pas être remplacée comme un capteur.","data":{"id":"spectre_auditif_etendu_g2","name":"Spectre auditif etendu","family":"Audio","priceLabel":"2 500 $","effect":"Infrasons/ultrasons. · Mécanique : infra/ultrasons","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":2500,"priceMin":2500,"priceMax":2500,"_path":"entries / 54"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["audio","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'traducteur_g1', 'Traducteur', NULL, '{"nature":"equipement","kind":"augmentation","category":"Audio","sourceCategory":"Audio","price":1500,"priceMin":null,"priceMax":null,"priceLabel":"1500 $","generation":1,"charge":0,"stress":1,"slots":1,"effect":"Traduction des langues connues du systeme ; ne remplace pas Langages & Argot pour nuances/codes. · Mécanique : langues, +3 spécialisé","lore":"Le Traducteur traite la parole reçue par le système auditif et restitue une traduction lorsque la langue ou le registre fait partie des modèles qu’il connaît. Il rend les échanges ordinaires beaucoup plus accessibles sans obliger le porteur à consulter un terminal distinct à chaque phrase.\n\nLa Gen.1 fournit +3 spécialisé et impose 1 Stress ; la Gen.2 fournit +2 sans Stress. L’implant ne remplace pas Langages & Argot pour les nuances, sous-entendus, codes sociaux ou vocabulaires clandestins : une traduction littérale peut transmettre les mots tout en laissant échapper ce qu’un locuteur initié comprendrait réellement.","data":{"id":"traducteur_g1","name":"Traducteur","family":"Audio","priceLabel":"1 500 $","effect":"Traduction des langues connues du systeme ; ne remplace pas Langages & Argot pour nuances/codes. · Mécanique : langues, +3 spécialisé","generation":1,"charge":0,"stress":1,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":1500,"priceMin":1500,"priceMax":1500,"_path":"entries / 55"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["audio","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'traducteur_g2', 'Traducteur', NULL, '{"nature":"equipement","kind":"augmentation","category":"Audio","sourceCategory":"Audio","price":3000,"priceMin":null,"priceMax":null,"priceLabel":"3000 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Traduction des langues connues du systeme ; ne remplace pas Langages & Argot pour nuances/codes. · Mécanique : langues/argots, +2","lore":"Le Traducteur traite la parole reçue par le système auditif et restitue une traduction lorsque la langue ou le registre fait partie des modèles qu’il connaît. Il rend les échanges ordinaires beaucoup plus accessibles sans obliger le porteur à consulter un terminal distinct à chaque phrase.\n\nLa Gen.1 fournit +3 spécialisé et impose 1 Stress ; la Gen.2 fournit +2 sans Stress. L’implant ne remplace pas Langages & Argot pour les nuances, sous-entendus, codes sociaux ou vocabulaires clandestins : une traduction littérale peut transmettre les mots tout en laissant échapper ce qu’un locuteur initié comprendrait réellement.","data":{"id":"traducteur_g2","name":"Traducteur","family":"Audio","priceLabel":"3 000 $","effect":"Traduction des langues connues du systeme ; ne remplace pas Langages & Argot pour nuances/codes. · Mécanique : langues/argots, +2","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":3000,"priceMin":3000,"priceMax":3000,"_path":"entries / 56"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["audio","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'protection_auditive_g2', 'Protection auditive', NULL, '{"nature":"equipement","kind":"augmentation","category":"Audio","sourceCategory":"Audio","price":1500,"priceMin":null,"priceMax":null,"priceLabel":"1500 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Bloque sons physiquement dangereux lorsqu''ils sont detectables. · Mécanique : protection acoustique","lore":"La Protection auditive surveille le niveau et la nature des sons reçus afin de couper ou atténuer ceux qui deviennent physiquement dangereux pour le système auditif. Son intérêt est d’agir assez vite pour éviter qu’un pic sonore détectable ne soit transmis à pleine puissance au porteur.\n\nLa Gen.2 fournit cette protection acoustique dans un seul emplacement sans Stress. Elle n’est pas une immunité générale à tout phénomène sonique : l’effet doit passer par un son que le système peut effectivement détecter et bloquer, tandis qu’une vibration ou un autre vecteur physique peut relever d’un problème différent.","data":{"id":"protection_auditive_g2","name":"Protection auditive","family":"Audio","priceLabel":"1 500 $","effect":"Bloque sons physiquement dangereux lorsqu''ils sont detectables. · Mécanique : protection acoustique","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":1500,"priceMin":1500,"priceMax":1500,"_path":"entries / 57"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["audio","sensorial","defensive","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'stabilite_gyroscopique_g2', 'Stabilite gyroscopique', NULL, '{"nature":"equipement","kind":"augmentation","category":"Audio","sourceCategory":"Audio","price":4000,"priceMin":null,"priceMax":null,"priceLabel":"4000 $","generation":2,"charge":0,"stress":0,"slots":1,"effect":"Compensation de l''oreille interne/equilibre. · Mécanique : équilibre amélioré","lore":"La Stabilité gyroscopique agit sur les informations d’équilibre issues de l’oreille interne et du système sensoriel pour réduire les pertes de repères provoquées par les mouvements du corps. Elle aide le porteur à conserver une référence stable lorsque rotation, tangage ou changement rapide d’appui brouilleraient normalement ses sensations.\n\nLa Gen.2 occupe 1 emplacement, n’impose aucun Stress et améliore l’équilibre lorsque cette compensation est réellement pertinente. Elle ne crée pas d’adhérence et n’annule pas une force extérieure : sur une surface sans prise ou face à un choc assez violent pour déplacer le corps, savoir où se trouve le haut ne suffit pas à rester en place.","data":{"id":"stabilite_gyroscopique_g2","name":"Stabilite gyroscopique","family":"Audio","priceLabel":"4 000 $","effect":"Compensation de l''oreille interne/equilibre. · Mécanique : équilibre amélioré","generation":2,"charge":0,"stress":0,"slots":1,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":4000,"priceMin":4000,"priceMax":4000,"_path":"entries / 58"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["audio","sensorial","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'anticorps_robotiques_g2', 'Anticorps robotiques', NULL, '{"nature":"equipement","kind":"augmentation","category":"Interne","sourceCategory":"Interne","price":7500,"priceMin":null,"priceMax":null,"priceLabel":"7500 $","generation":2,"charge":0,"stress":0,"slots":null,"effect":"Biomaintenance contre maladies/infections ordinaires.","lore":"","data":{"id":"anticorps_robotiques_g2","name":"Anticorps robotiques","family":"Interne","priceLabel":"7 500 $","effect":"Biomaintenance contre maladies/infections ordinaires.","generation":2,"charge":0,"stress":0,"slots":null,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":7500,"priceMin":7500,"priceMax":7500,"_path":"entries / 59"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["internal","medical","civil"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
INSERT INTO content_entry (type, scope, slug, title, summary, fields, status, legacy_ids, published_at) VALUES ('augmentation', 'equipement', 'audiovox_g1', 'Audiovox', NULL, '{"nature":"equipement","kind":"augmentation","category":"Interne","sourceCategory":"Interne","price":3000,"priceMin":null,"priceMax":null,"priceLabel":"3000 $","generation":1,"charge":1,"stress":3,"slots":null,"effect":"Vocalisation infrasons/ultrasons ; attaque sonique possible selon profil.","lore":"L’Audiovox modifie la chaîne de vocalisation du porteur pour produire des fréquences que la voix humaine ordinaire n’atteint pas, notamment infrasons et ultrasons. L’augmentation transforme donc le corps en émetteur acoustique spécialisé, utilisable pour communiquer ou produire certains effets lorsque le profil concerné le prévoit.\n\nLes deux générations permettent cette vocalisation étendue et peuvent servir de base à une attaque sonique lorsque son profil l’autorise. La Gen.1 impose 1 Charge et 3 Stress, contre 1 Charge et 1 Stress en Gen.2 ; aucune portée, puissance ou conséquence supplémentaire n’est présumée en dehors de l’effet réellement défini.","data":{"id":"audiovox_g1","name":"Audiovox","family":"Interne","priceLabel":"3 000 $","effect":"Vocalisation infrasons/ultrasons ; attaque sonique possible selon profil.","generation":1,"charge":1,"stress":3,"slots":null,"source":"TUC_Realite_Equipement_Services_V1_final_2026-09-08","priceMode":"exact","price":3000,"priceMin":3000,"priceMax":3000,"_path":"entries / 60"},"vehicle":false,"neuro":false,"recurring":"one_off","monthlyCost":0,"families":["audio","internal","sensorial","combat"]}'::jsonb, 'published', '{}'::text[], now()) ON CONFLICT (type, scope, slug) DO UPDATE SET title = EXCLUDED.title, summary = EXCLUDED.summary, fields = EXCLUDED.fields, status = EXCLUDED.status, legacy_ids = EXCLUDED.legacy_ids, version = content_entry.version + CASE WHEN content_entry.fields IS DISTINCT FROM EXCLUDED.fields OR content_entry.title IS DISTINCT FROM EXCLUDED.title THEN 1 ELSE 0 END, updated_at = now();
